const (
	aiDefaultPoll = time.Minute
	// aiMinPoll은 화면 갱신과 Codex 조회의 하한이다. Claude 사용량 API에는 별도 간격을 적용한다.
	aiMinPoll = 30 * time.Second
	// aiClaudeMinInterval은 Claude 사용량 API를 부르는 최소 간격이다. 시험에서 1-4분 간격의 호출은 429를 받았고
	// 7분 쉰 뒤에는 200을 받았다. 정상 조회는 5분마다 갱신하고, 429 뒤에만 backoff를 적용한다.
	aiClaudeMinInterval = 5 * time.Minute
	// aiMaxBackoff는 429를 받아 늘린 Claude 조회 간격의 상한이다.
	aiMaxBackoff = 30 * time.Minute
	// aiScanInterval은 대화 기록을 다시 읽는 간격이다. 새로 붙은 줄만 읽으므로 짧아도 부담이 작다.
	// Claude Code는 응답을 받은 뒤 1초 안에 기록하므로 진행 중인 행이 2초 안에 늘어난다.
	aiScanInterval = 2 * time.Second
	aiResetLogName = "ai-resets.jsonl"
	// aiClaudeStateName은 마지막으로 받은 Claude 사용량이다. token은 담지 않는다.
	aiClaudeStateName = "ai-claude.json"
)

func runAI(args []string, version string) int {
	if len(args) > 0 {
		switch args[0] {
		case "statusline":
			return runAIStatusline(args[1:])
		case "hook":
			return runAIHook(args[1:])
		case "hooks":
			return runAIHooksSetup(args[1:])
		case "sessions":
			return runAISessions(args[1:])
		}
	}
	set := newFlagSet("ai")
	set.SetOutput(os.Stderr)
	poll := set.Duration("poll", aiDefaultPoll, T("command.ai.option.poll"))
	count := set.Int("count", 0, T("command.ai.option.count"))
	jsonPath := set.String("json", configuredStringFallback(nil, activeConfig.Defaults.Common.JSON, ""), T("option.json"))
	if err := set.Parse(args); err != nil {
		return 2
	}
	if set.NArg() != 0 {
		fmt.Fprintln(os.Stderr, T("observe.ai.usage"))
		return 2
	}
	if *poll < aiMinPoll {
		fmt.Fprintln(os.Stderr, T("observe.ai.poll_minimum", aiMinPoll))
		return 2
	}
	if *count < 0 {
		fmt.Fprintln(os.Stderr, T("observe.ai.count_minimum"))
		return 2

	}
	collector, err := openAICollector()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 2
	}
	defer collector.close()

	var writer io.Writer = os.Stdout
	if *jsonPath != "" && *jsonPath != "-" {
		file, err := os.OpenFile(*jsonPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 2
		}
		defer file.Close()
		writer = file
	}
	jsonOutput := *jsonPath != ""
	if !jsonOutput && *count == 0 && liveTerminal() {
		return runAIDashboard(collector, *poll, version)
	}
	return runAIStream(writer, collector, *poll, *count, jsonOutput)
}

// openAICollector는 edc ai와 edc top의 AI 패널이 함께 쓰는 수집기를 연다. 상태 파일은 기록 DB 옆에 둔다.
func openAICollector() (*aiCollector, error) {
	historyPath, err := defaultHistoryPath()
	if err != nil {
		return nil, err
	}
	home, _ := os.UserHomeDir()
	collector := newAICollector(aiClaudeDir(home), aiCodexDir(home), filepath.Dir(historyPath), time.Now())
	// macOS의 Claude Code는 token을 Keychain에 둔다. Keychain을 열면 다른 프로그램에도 token을 내주는 허용을 묻게 되므로
	// Claude Code가 statusline에 넘긴 사용량을 읽는다.
	if runtime.GOOS == "darwin" {
		collector.claudeSnapshot = filepath.Join(filepath.Dir(historyPath), aiClaudeSnapshotName)
	}
	return collector, nil
}

// aiCollector는 한도 조회, 기록 scan, 리셋 기록을 맡는다.
// 대시보드는 poll과 scan을 각각 앞선 호출이 끝난 뒤에만 다시 부르므로 두 메서드가 각자의 필드를 겹쳐 쓰지 않는다.
type aiCollector struct {
	http      *http.Client
	claudeDir string
	codex     aiCodexSource
	scanner   *aiTokenScanner
	resetLog  string
	// claudeState는 마지막으로 성공한 Claude 조회를 남기는 파일이다. 다시 열 때 429를 기다리지 않고 바로 보인다.
	claudeState string
	last        map[string]aiProvider
	lastResets  map[string]aiResetEvent
	// shown은 도구마다 마지막으로 보인 값이다. Claude를 건너뛴 조회도 이 값을 다시 보인다.
	shown map[string]aiProvider
	// claudeNext 전에는 Claude를 부르지 않는다. claudeBackoff는 429를 받을 때마다 두 배로 늘린 간격이고 성공해도 줄지 않는다.
	// --poll 하한과 따로 둔다. 둘을 한 값에 담으면 다른 --poll로 다시 실행할 때 앞선 하한이 백오프처럼 남는다.
	claudeNext    time.Time
	claudeBackoff time.Duration
	// claudeSnapshot이 있으면 사용량 API 대신 이 파일을 읽는다. 로컬 파일이라 조회 간격과 429 백오프를 적용하지 않는다.
	claudeSnapshot string
}

func newAICollector(claudeDir, codexDir, stateDir string, now time.Time) *aiCollector {
	resetLog := filepath.Join(stateDir, aiResetLogName)
	collector := &aiCollector{
		http:        &http.Client{Timeout: aiRequestTimeout},
		claudeDir:   claudeDir,
		scanner:     newAITokenScanner(claudeDir, codexDir),
		resetLog:    resetLog,
		claudeState: filepath.Join(stateDir, aiClaudeStateName),
		last:        map[string]aiProvider{},
		lastResets:  loadAILastResets(resetLog),
		shown:       map[string]aiProvider{},
	}
	if state, ok := loadAIClaudeState(collector.claudeState); ok {
		if claude := state.aiProvider; !claude.FetchedAt.IsZero() {
			// 저장한 값을 앞선 조회로 삼는다. 꺼져 있는 동안 지난 리셋도 다음 조회에서 찾는다.
			collector.last["claude"], collector.shown["claude"] = claude, claude
			// 직전 실행이 조회한 지 최소 간격이 지나지 않았으면 그때까지 부르지 않는다. 시각이 미래면 믿지 않는다.
			if claude.FetchedAt.Before(now) {
				collector.claudeNext = claude.FetchedAt.Add(aiClaudeMinInterval)
			}
		}
		// 백오프는 직전 실행이 정한 다음 조회 시각에서 한 간격이 더 지날 때까지 이어진다. 그 안에 다시 실행하면
		// --count 1을 되풀이할 때처럼 같은 간격에서 다시 늘리고, 더 오래 쉬었으면 처음 간격으로 돌아간다.
		// 백오프 상한보다 먼 시각은 믿지 않는다.
		if backoff := min(state.Backoff, aiMaxBackoff); backoff > 0 && state.NextTry.Before(now.Add(aiMaxBackoff)) && now.Before(state.NextTry.Add(backoff)) {
			collector.claudeBackoff = backoff
			if state.NextTry.After(collector.claudeNext) {
				collector.claudeNext = state.NextTry
			}
			// 성공한 값 없이 429로 미룬 상태다. 상자가 빈 채로 기다리지 않게 미룬 이유와 다음 조회 시각을 보인다.
			if state.FetchedAt.IsZero() && state.NextTry.After(now) {
				collector.shown["claude"] = aiProvider{Name: "claude", Windows: []aiWindow{}, Err: "rate limited · next try " + state.NextTry.Local().Format("15:04:05")}

			}
		}
	}
	return collector
}

func (collector *aiCollector) poll(ctx context.Context, poll time.Duration) aiPollResult {
	now := time.Now()
	var codex aiProvider
	var wait sync.WaitGroup
	wait.Add(1)
	go func() {
		defer wait.Done()
		codex = collector.codex.fetch(now)
	}()
	var fetched []aiProvider
	var stateErr error
	// poll 간격과 조회 시간이 겹쳐 예정 시각보다 조금 일찍 깨도 이번 차례로 본다.
	if collector.claudeSnapshot != "" {
		fetched = append(fetched, readAIClaudeSnapshot(collector.claudeSnapshot))
	} else if !now.Add(time.Second).Before(collector.claudeNext) {
		claude := fetchAIClaude(ctx, collector.http, collector.claudeDir, now)
		collector.scheduleClaude(claude.rateLimited, now, poll)
		if claude.rateLimited {
			claude.Err += " · next try " + collector.claudeNext.Local().Format("15:04:05")
			// 다시 실행해도 미룬 시각 전에는 부르지 않도록 남긴다. 마지막으로 성공한 값은 그대로 둔다.
			stateErr = saveAIClaudeState(collector.claudeState, aiClaudeState{aiProvider: collector.last["claude"], NextTry: collector.claudeRetry(now), Backoff: collector.claudeBackoff})
		}
		fetched = append(fetched, claude)
	}
	wait.Wait()
	fetched = append(fetched, codex)

	var events []aiResetEvent
	for _, provider := range fetched {
		previous, known := collector.last[provider.Name]
		if provider.Err == "" {
			if known {

			events = append(events, detectAIResets(previous, provider, now)...)
		}
		collector.last[provider.Name], collector.shown[provider.Name] = provider, provider
		if provider.Name == "claude" && collector.claudeSnapshot == "" {
			// 429 뒤에 늘어난 백오프는 성공해도 줄지 않는다. 다시 실행해도 이어지도록 다음 조회 시각과 함께 남긴다.
			stateErr = saveAIClaudeState(collector.claudeState, aiClaudeState{aiProvider: provider, NextTry: collector.claudeRetry(now), Backoff: collector.claudeBackoff})
		}
		continue
	}
	// 실패한 조회는 마지막으로 성공한 값을 지우지 않는다. 상자는 그 값과 오류를 함께 보인다.
	if known {
		previous.Err = provider.Err
		provider = previous
	} else {
		provider.FetchedAt = time.Time{}
	}
	collector.shown[provider.Name] = provider
}
result := aiPollResult{lastResets: map[string]aiResetEvent{}, claudeInterval: collector.claudeEvery(poll), stateErr: stateErr}
if collector.claudeSnapshot != "" {
	result.claudeInterval = poll
}
for _, name := range []string{"claude", "codex"} {
	provider, ok := collector.shown[name]
	if !ok {
		provider = aiProvider{Name: name, Windows: []aiWindow{}}
	}
	result.providers = append(result.providers, provider)
}
result.logErr = appendAIResets(collector.resetLog, events)
for _, event := range events {
	collector.lastResets[event.Provider] = event

	}
	for name, event := range collector.lastResets {
		result.lastResets[name] = event
	}
	return result
}

// scheduleClaude는 다음 Claude 조회 시각을 정한다. 사용량 API의 요청 한도는 공개되지 않았고 같은 계정의
// Claude Code도 이 API를 부른다. 429를 받으면 간격을 두 배로 늘리고, 성공해도 한도에 닿았던 간격으로 돌아가지 않는다.
func (collector *aiCollector) scheduleClaude(rateLimited bool, now time.Time, poll time.Duration) {
	if rateLimited {
		collector.claudeBackoff = min(2*collector.claudeEvery(poll), aiMaxBackoff)
	}
	collector.claudeNext = now.Add(collector.claudeEvery(poll))
}

// claudeEvery는 지금 적용되는 Claude 조회 간격이다. 저장한 값으로 시작해 아직 부르지 않았어도 상태 줄이 같은 간격을 보인다.
func (collector *aiCollector) claudeEvery(poll time.Duration) time.Duration {
	every := collector.claudeBackoff
	for _, floor := range []time.Duration{aiClaudeMinInterval, poll} {
		if every < floor {
			every = floor
		}
	}
	return every
}

// claudeRetry는 상태 파일에 남길 다음 조회 시각이다. --poll 하한은 이 실행의 설정이라 다음 실행으로 넘기지 않는다.
// 하한이 섞이면 --poll이 백오프 상한보다 길 때 저장한 시각이 복원 범위를 벗어나 백오프가 사라진다.
func (collector *aiCollector) claudeRetry(now time.Time) time.Time {
	every := collector.claudeBackoff
	if every < aiClaudeMinInterval {
		every = aiClaudeMinInterval
	}
	return now.Add(every)
}

// newAISample은 최근 60분을 1분 행으로, 최근 24시간을 1시간 행으로 담는다. 마지막 행은 진행 중인 구간이다.
func newAISample(at time.Time, providers []aiProvider, usage aiUsageSnapshot) aiSample {
	return aiSample{
		At: at, Providers: providers, ScanError: usage.Err,
		Totals:  usage.totals(at),
		Minutes: usage.rows(at, time.Minute, 60),
		Hours:   usage.rows(at, time.Hour, 24),
	}
}

// runAIStream은 표나 JSON을 poll 간격마다 쓴다. count가 0이면 중단할 때까지 쓴다.
func runAIStream(writer io.Writer, collector *aiCollector, poll time.Duration, count int, jsonOutput bool) int {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	encoder := json.NewEncoder(writer)
	style := newTextStyle(!jsonOutput && writer == io.Writer(os.Stdout) && richEnabled(os.Stdout))
	for printed := 0; count == 0 || printed < count; printed++ {
		if printed > 0 {
			select {
			case <-ctx.Done():
				return 0
			case <-time.After(poll):
			}
		}
		result := collector.poll(ctx, poll)
		if result.logErr != nil {
			fmt.Fprintln(os.Stderr, T("observe.ai.error.reset_log", result.logErr))
		}
		if result.stateErr != nil {
			fmt.Fprintln(os.Stderr, T("observe.ai.error.state", result.stateErr))
		}
		sample := newAISample(time.Now(), result.providers, collector.scan())
		if jsonOutput {
			if err := encoder.Encode(sample); err != nil {
				fmt.Fprintln(os.Stderr, err)
				return 1
			}
			continue
		}
		fmt.Fprint(writer, formatAITable(sample, style))
	}
	return 0

// formatAITable은 --count와 파이프의 표다. 색을 쓰면 사용률은 대시보드와 같은 임계치로, 시각과 이름표는 회색으로 칠한다.
// 칸은 평문으로 채운 뒤 칠해 열이 맞는다.
func formatAITable(sample aiSample, style textStyle) string {
	var builder strings.Builder
	at := style.dim(sample.At.Local().Format("15:04:05"))
	nameWidth := len("updated")
	for _, provider := range sample.Providers {
		for _, window := range provider.Windows {
			nameWidth = max(nameWidth, len(window.Name))
		}
	}
	line := func(format string, values ...any) {
		builder.WriteString(style.fit(fmt.Sprintf(format, values...)) + "\n")
	}
	pad := func(text string, width int) string { return fmt.Sprintf("%-*s", width, text) }
	for _, provider := range sample.Providers {
		name := pad(provider.Name, 6)
		if provider.Err != "" {
			line("%s  %s  %s  %s", at, name, style.dim(pad("error", nameWidth)), style.bad(provider.Err))
		}
		// 저장한 값이나 실패 전에 받은 값은 지금 값이 아니다. 언제 받은 값인지 같이 쓴다.
		if !provider.FetchedAt.IsZero() && sample.At.Sub(provider.FetchedAt) >= time.Minute {
			line("%s  %s  %s  %s", at, name, style.dim(pad("updated", nameWidth)), style.dim(aiAgo(sample.At.Sub(provider.FetchedAt))+" ago"))
		}
		for _, window := range provider.Windows {
			line("%s  %s  %s  %s  %s", at, name, pad(window.Name, nameWidth), style.paint(fmt.Sprintf("%3.0f%%", window.Used), aiPercentColor(window.Used)), aiStyleReset(style, aiResetText(window.ResetsAt, sample.At)))
		}
	}
	for _, total := range sample.Totals {
		line("%s  %s  %s  %s %s %s %s %s %s %s %s %s %s", at, style.dim("tokens"), style.dim(pad(total.Window, nameWidth)),
			style.dim("claude"), aiCompact(total.Claude.total()), style.dim("hit"), total.Claude.cacheHitText(), style.dim("·"),
			style.dim("codex"), aiCompact(total.Codex.total()), style.dim("hit"), total.Codex.cacheHitText(), style.dim("· this host"))

	}
	if sample.ScanError != "" {
		line("%s  %s  %s", at, style.dim("scan    error"), style.bad(sample.ScanError))
	}
	return builder.String()
}

// aiStyleReset은 리셋 시각을 기본색으로, 남은 시간과 "reset due"를 회색으로 둔다. 시각이 없으면 모두 회색이다.
func aiStyleReset(style textStyle, text string) string {
	at, left, found := strings.Cut(text, "  ")
	if !found {
		return style.dim(text)
	}
	// 대시보드(aiPaintReset)와 같이 시각은 회색, 남은 시간은 기본색이다. 언제 풀리는지보다 얼마 남았는지를 먼저 본다.
	return style.dim(at) + "  " + left
}

func aiResetText(at, now time.Time) string {
	if at.IsZero() {
		return "no reset time"
	}
	if !now.Before(at) {
		return at.Local().Format("01-02 15:04:05") + "  reset due"
	}
	return at.Local().Format("01-02 15:04:05") + "  in " + aiCountdown(at.Sub(now))
}

// aiCountdown은 남은 시간을 초까지 보인다. 하루가 넘으면 앞에 일 수를 붙인다.
func aiCountdown(left time.Duration) string {
	if left < 0 {
		left = 0
	}
	total := int64(left / time.Second)
	days, hours, minutes, seconds := total/86400, total%86400/3600, total%3600/60, total%60
	if days > 0 {
		return fmt.Sprintf("%dd %02d:%02d:%02d", days, hours, minutes, seconds)
	}
	return fmt.Sprintf("%02d:%02d:%02d", hours, minutes, seconds)
}

// aiActivityTail은 활동을 찾으려고 읽는 대화 기록의 끝부분이다. 한 턴의 마지막 몇 단계가 들어가고,
// 파일 크기와 관계없이 2초마다 읽어도 부담이 작다.
const aiActivityTail int64 = 256 << 10

// aiActivity는 작업 중인 세션이 마지막으로 한 일이다. Running이면 결과가 아직 없는 도구 호출이다.
type aiActivity struct {
	Kind    string    `json:"kind"`
	Text    string    `json:"text,omitempty"`
	At      time.Time `json:"at"`
	Running bool      `json:"running,omitempty"`
}

// aiSessionInfo는 대화 기록 끝부분에 함께 있는 세션 정보다. 활동을 찾으려고 읽는 범위에서 얻는다.
// Claude의 누적 token만 파일 전체가 필요하므로 처음 한 번 전체를 읽고, 그 뒤에는 새로 붙은 줄만 읽는다.
type aiSessionInfo struct {
	Model  string `json:"model,omitempty"`
	Effort string `json:"effort,omitempty"`
	Branch string `json:"branch,omitempty"`
	// Mode는 Claude의 permissionMode, Codex의 approval_policy다.
	Mode    string `json:"mode,omitempty"`
	Sandbox string `json:"sandbox,omitempty"`
	// Context는 마지막 요청이 보낸 입력 token이다. cache에서 읽은 token도 들어간다.
	Context       int64   `json:"context,omitempty"`
	ContextWindow int64   `json:"context_window,omitempty"`
	Tokens        aiUsage `json:"tokens"`
	// Last는 마지막 요청의 token이다. Input은 cache에서 읽지 않은 입력이다.
	Last aiUsage `json:"last"`
	// TurnTools와 TurnFailed는 이번 턴의 도구 호출 수와 실패 수다. 턴 시작이 읽은 범위 밖이면 TurnPartial이고 값은 하한이다.
	TurnTools   int    `json:"turn_tools,omitempty"`
	TurnFailed  int    `json:"turn_failed,omitempty"`
	TurnPartial bool   `json:"turn_partial,omitempty"`
	LastError   string `json:"last_error,omitempty"`
	// Rate는 최근 aiRateWindow 동안의 분당 token이다. Fast는 세션 평균보다 확실히 빠르다는 뜻이다.
	Rate   int64 `json:"tokens_per_minute,omitempty"`
	Fast   bool  `json:"fast,omitempty"`
	points []aiTokenPoint
}

// aiTokenPoint는 그 시각까지의 누적 token이다.
type aiTokenPoint struct {
	at    time.Time
	total int64
}

const (
	aiRateWindow = 5 * time.Minute
	// aiFastRatio배를 넘고 aiFastMinimum 이상이어야 빠르다고 본다. 막 시작한 세션은 평균이 작아 쉽게 넘는다.
	aiFastRatio   = 1.5
	aiFastMinimum = 1000
	// aiClaudeSmallWindow를 넘은 Claude 세션은 1M 창으로 본다. Claude 기록에는 창 크기가 없다.
	aiClaudeSmallWindow = 200_000
	aiClaudeLargeWindow = 1_000_000
)

func (reader aiActivityReader) read(tool, path string) (aiActivity, bool, aiSessionInfo) {
	stat, err := os.Stat(path)
	if err != nil {
		return aiActivity{}, false, aiSessionInfo{}
	}
	cached := reader[path]
	if cached == nil || stat.Size() < cached.offset {
		cached = &aiActivityCache{seen: map[string]aiSeenMessage{}}
		reader[path] = cached
	} else if cached.size == stat.Size() && cached.modified.Equal(stat.ModTime()) {
		return cached.activity, cached.ok, cached.info
	}
	cached.size, cached.modified = stat.Size(), stat.ModTime()
	previous := cached.info
	cached.activity, cached.ok, cached.info = readAITranscriptActivity(tool, path, stat.Size())
	keepAISessionInfo(&cached.info, previous)
	if tool == "claude" {
		readAIClaudeTokens(path, cached)
		cached.info.Tokens, cached.info.points = cached.tokens, cached.points
	}
	return cached.activity, cached.ok, cached.info
}

// keepAISessionInfo는 끝부분에 없던 값을 앞서 읽은 값으로 채운다. 큰 도구 출력이 끝부분을 채우면 마지막 응답이 범위 밖으로 밀린다.
func keepAISessionInfo(info *aiSessionInfo, previous aiSessionInfo) {
	if info.Model == "" {
		info.Model, info.Context = previous.Model, previous.Context
	}
	if info.ContextWindow == 0 {
		info.ContextWindow = previous.ContextWindow
	}
	for _, pair := range []struct{ value, old *string }{{&info.Branch, &previous.Branch}, {&info.Mode, &previous.Mode}, {&info.Effort, &previous.Effort}, {&info.Sandbox, &previous.Sandbox}} {
		if *pair.value == "" {
			*pair.value = *pair.old
		}
	}
	if info.Last.empty() {
		info.Last = previous.Last
	}
}

// readAIClaudeTokens는 읽은 위치부터 끝난 줄의 token을 더한다. 처음에는 파일 전체를 읽는다.
func readAIClaudeTokens(path string, cached *aiActivityCache) {
	file, err := os.Open(path)
	if err != nil {
		return
	}
	defer file.Close()
	if _, err := file.Seek(cached.offset, io.SeekStart); err != nil {
		return
	}
	reader := bufio.NewReaderSize(file, 256<<10)
	for {
		line, err := reader.ReadBytes('\n')
		if err != nil {
			return
		}
		cached.offset += int64(len(line))
		if at, usage, ok := aiClaudeUsageDelta(line, cached.seen); ok {
			cached.tokens.add(usage)
			cached.points = append(cached.points, aiTokenPoint{at: at, total: cached.tokens.total()})
		}
	}
}

// aiTokenRate는 최근 aiRateWindow의 분당 token과, 그 값이 세션 평균보다 빠른지 돌려준다.
// 창 앞의 마지막 점을 기준으로 삼는다. 그런 점이 없으면 세션이 창 안에서 시작했으므로 0에서 센다.
func aiTokenRate(points []aiTokenPoint, now time.Time) (int64, bool) {
	if len(points) == 0 {
		return 0, false
	}
	last := points[len(points)-1]
	from := now.Add(-aiRateWindow)
	var base int64
	for _, point := range points {
		if point.at.After(from) {
			break
		}
		base = point.total
	}
	rate := (last.total - base) * int64(time.Minute) / int64(aiRateWindow)
	span := last.at.Sub(points[0].at)
	if span < aiRateWindow {
		return rate, false
	}
	average := float64(last.total) / span.Minutes()
	return rate, rate >= aiFastMinimum && float64(rate) > average*aiFastRatio
}

// annotate는 세션 정보를 붙이고, 작업 중인 세션에만 활동을 붙인다. 다른 상태는 hook이 남긴 설명이 더 정확하다.
func (reader aiActivityReader) annotate(sessions []aiSession, now time.Time) {
	for index := range sessions {
		session := &sessions[index]
		if session.State == aiStateEnded || session.Transcript == "" {
			continue
		}
		activity, ok, info := reader.read(session.Tool, session.Transcript)
		info.Rate, info.Fast = aiTokenRate(info.points, now)
		session.Info = &info
		if ok && session.State == aiStateWorking {
			session.Activity = &activity
		}
	}
}

func readAITranscriptActivity(tool, path string, size int64) (aiActivity, bool, aiSessionInfo) {
	var info aiSessionInfo
	file, err := os.Open(path)
	if err != nil {
		return aiActivity{}, false, info
	}
	defer file.Close()
	start := size - aiActivityTail
	if start < 0 {
		start = 0
	}
	if _, err := file.Seek(start, io.SeekStart); err != nil {
		return aiActivity{}, false, info
	}
	data, err := io.ReadAll(io.LimitReader(file, aiActivityTail))
	if err != nil {
		return aiActivity{}, false, info
	}
	if start > 0 {
		// 중간에서 시작한 첫 줄은 잘린 JSON이다.
		if cut := bytes.IndexByte(data, '\n'); cut >= 0 {
			data = data[cut+1:]
		}
	}
	var activity aiActivity
	var ok bool
	if tool == "codex" {
		activity, ok = parseAICodexActivity(data, &info)
	} else {
		activity, ok = parseAIClaudeActivity(data, &info)
	}
	return activity, ok, info

// aiClaudeResultText는 도구 결과의 글자만 꺼낸다. 결과는 문자열이거나 text 조각의 배열이다.
func aiClaudeResultText(raw json.RawMessage) string {
	var text string
	if json.Unmarshal(raw, &text) == nil {
		return text
	}
	var parts []struct {
		Text string `json:"text"`
	}
	_ = json.Unmarshal(raw, &parts)
	var builder strings.Builder
	for _, part := range parts {
		builder.WriteString(part.Text + " ")
	}
	return builder.String()
}

// parseAIClaudeActivity는 마지막 활동을 고른다. 결과가 온 도구 호출은 끝난 것으로 표시한다.
func parseAIClaudeActivity(data []byte, info *aiSessionInfo) (aiActivity, bool) {
	// 턴 시작을 만나기 전까지 센 값은 읽은 범위 안의 하한이다.
	info.TurnPartial = true
	var last aiActivity
	found := false
	pending := map[string]bool{}
	for _, line := range bytes.Split(data, []byte{'\n'}) {
		var entry struct {
			Type           string    `json:"type"`
			Timestamp      time.Time `json:"timestamp"`
			GitBranch      string    `json:"gitBranch"`
			PermissionMode string    `json:"permissionMode"`
			IsMeta         bool      `json:"isMeta"`
			Message        struct {
				Model   string          `json:"model"`
				Content json.RawMessage `json:"content"`
				Usage   *struct {
					Input         int64 `json:"input_tokens"`
					CacheCreation int64 `json:"cache_creation_input_tokens"`
					CacheRead     int64 `json:"cache_read_input_tokens"`
					Output        int64 `json:"output_tokens"`
				} `json:"usage"`
			} `json:"message"`
		}
		if json.Unmarshal(line, &entry) != nil || entry.Type != "assistant" && entry.Type != "user" {
			continue
		}
		if entry.GitBranch != "" {
			info.Branch = entry.GitBranch
		}
		if entry.PermissionMode != "" {

	info.Mode = entry.PermissionMode
}
// <synthetic>은 Claude Code가 API 없이 만든 응답이다. 모델과 컨텍스트가 없다.
if entry.Message.Model != "" && entry.Message.Model != "<synthetic>" {
	info.Model = entry.Message.Model
	if usage := entry.Message.Usage; usage != nil {
		info.Context = usage.Input + usage.CacheCreation + usage.CacheRead
		info.Last = aiUsage{Requests: 1, Input: usage.Input + usage.CacheCreation, Output: usage.Output, Cache: usage.CacheRead}
	}
}
// 문자열 content는 사용자가 친 프롬프트다. 도구 결과는 배열로 온다.
var prompt string
if entry.Type == "user" && !entry.IsMeta && json.Unmarshal(entry.Message.Content, &prompt) == nil {
	info.TurnTools, info.TurnFailed, info.LastError, info.TurnPartial = 0, 0, "", false
	continue
}
var parts []struct {
	Type      string          `json:"type"`
	ID        string          `json:"id"`
	ToolUseID string          `json:"tool_use_id"`
	Name      string          `json:"name"`
	Input     json.RawMessage `json:"input"`
	Text      string          `json:"text"`
	IsError   bool            `json:"is_error"`
	Content   json.RawMessage `json:"content"`
}
if json.Unmarshal(entry.Message.Content, &parts) != nil {
	continue
}
for _, part := range parts {
	switch {
	case part.Type == "tool_use":

				pending[part.ID] = true
				info.TurnTools++
				last, found = aiActivity{Kind: "tool", Text: aiHookToolDetail(part.Name, part.Input), At: entry.Timestamp, Running: true}, true
			case part.Type == "tool_result":
				delete(pending, part.ToolUseID)
				if part.IsError {
					info.TurnFailed++
					info.LastError = aiHookClip(aiClaudeResultText(part.Content), false)
				}
			case part.Type == "text" && entry.Type == "assistant" && strings.TrimSpace(part.Text) != "":
				last, found = aiActivity{Kind: "text", Text: aiHookClip(part.Text, true), At: entry.Timestamp}, true
			case part.Type == "thinking":
				last, found = aiActivity{Kind: "thinking", At: entry.Timestamp}, true
			}
		}
	}
	// 병렬 호출 가운데 하나라도 결과가 없으면 아직 실행 중이다.
	last.Running = last.Kind == "tool" && len(pending) > 0
	return last, found
}

func parseAICodexActivity(data []byte, info *aiSessionInfo) (aiActivity, bool) {
	info.TurnPartial = true
	var last aiActivity
	found := false
	pending := map[string]bool{}
	for _, line := range bytes.Split(data, []byte{'\n'}) {
		var entry struct {
			Type      string    `json:"type"`
			Timestamp time.Time `json:"timestamp"`
			Payload   struct {
				Type           string `json:"type"`
				Model          string `json:"model"`
				Effort         string `json:"effort"`
				ApprovalPolicy string `json:"approval_policy"`
				SandboxPolicy  struct {
					Type string `json:"type"`
				} `json:"sandbox_policy"`
				Info *struct {
					Total  aiCodexTotals `json:"total_token_usage"`
					Last   aiCodexTotals `json:"last_token_usage"`
					Window int64         `json:"model_context_window"`
				} `json:"info"`
				Window    int64           `json:"model_context_window"`
				Output    json.RawMessage `json:"output"`
				Role      string          `json:"role"`
				Name      string          `json:"name"`
				CallID    string          `json:"call_id"`
				Arguments string          `json:"arguments"`
				Input     string          `json:"input"`
				Content   []struct {
					Text string `json:"text"`
				} `json:"content"`

	} `json:"payload"`
}
if json.Unmarshal(line, &entry) != nil {
	continue
}
payload := entry.Payload
switch {
case entry.Type == "turn_context":
	info.Model, info.Effort, info.Mode, info.Sandbox = payload.Model, payload.Effort, payload.ApprovalPolicy, payload.SandboxPolicy.Type
	continue
case entry.Type == "event_msg" && payload.Type == "task_started":
	info.TurnTools, info.TurnFailed, info.LastError, info.TurnPartial = 0, 0, "", false
	if payload.Window > 0 {
		info.ContextWindow = payload.Window
	}
	continue
case entry.Type == "event_msg" && payload.Type == "token_count" && payload.Info != nil:
	// 누적값이므로 마지막 이벤트가 세션 전체다. cached_input_tokens는 input_tokens에 들어 있다.
	total, latest := payload.Info.Total, payload.Info.Last
	info.Tokens = aiUsage{Input: aiGrowth(total.Cached, total.Input), Output: total.Output, Cache: total.Cached}
	info.Last = aiUsage{Requests: 1, Input: aiGrowth(latest.Cached, latest.Input), Output: latest.Output, Cache: latest.Cached}
	info.Context, info.ContextWindow = latest.Input, payload.Info.Window
	info.points = append(info.points, aiTokenPoint{at: entry.Timestamp, total: info.Tokens.total()})
	continue
case entry.Type != "response_item":
	continue
}
switch payload.Type {
case "function_call", "custom_tool_call":
	pending[payload.CallID] = true
	info.TurnTools++
	last, found = aiActivity{Kind: "tool", Text: aiCodexToolDetail(payload.Name, payload.Arguments+payload.Input), At: entry.Timestamp, Running: true}, true

		case "function_call_output", "custom_tool_call_output":
			delete(pending, payload.CallID)
			if text, failed := aiCodexFailure(payload.Output); failed {
				info.TurnFailed++
				info.LastError = text
			}
		case "reasoning":
			last, found = aiActivity{Kind: "thinking", At: entry.Timestamp}, true
		case "message":
			if payload.Role != "assistant" {
				continue
			}
			var text strings.Builder
			for _, content := range payload.Content {
				text.WriteString(content.Text)
			}
			if strings.TrimSpace(text.String()) != "" {
				last, found = aiActivity{Kind: "text", Text: aiHookClip(text.String(), true), At: entry.Timestamp}, true
			}
		}
	}
	last.Running = last.Kind == "tool" && len(pending) > 0
	return last, found
}

// aiCodexFailure는 exec_command 결과의 종료 코드가 0이 아니면 그 코드와 출력 앞부분을 돌려준다.
func aiCodexFailure(raw json.RawMessage) (string, bool) {
	text := string(raw)
	match := aiCodexExitCode.FindStringSubmatch(text)
	if match == nil || match[1] == "0" {
		return "", false
	}
	detail := "exit " + match[1]
	if output := aiCodexOutput.FindStringSubmatch(text); output != nil {
		unescaped := strings.NewReplacer(`\\n`, " ", `\n`, " ", `\\"`, `"`, `\"`, `"`).Replace(output[1])
		detail += " · " + unescaped
	}
	return aiHookClip(detail, false), true
}

// aiCodexToolDetail은 Codex 도구 호출을 Claude와 같은 "도구: 대상" 형태로 줄인다.
func aiCodexToolDetail(name, input string) string {
	if match := aiCodexCommand.FindStringSubmatch(input); match != nil {
		command := match[1]
		if unquoted, err := strconv.Unquote(`"` + command + `"`); err == nil {
			command = unquoted
		}
		return aiHookClip("exec_command: "+command, false)
	}
	if match := aiCodexPatch.FindStringSubmatch(input); match != nil {
		return aiHookClip("apply_patch: "+match[1], false)
	}
	var arguments map[string]any
	if json.Unmarshal([]byte(input), &arguments) == nil {
		raw, _ := json.Marshal(arguments)
		return aiHookToolDetail(name, raw)
	}
	return aiHookClip(name, false)
}

// aiActivityText는 목록 한 줄에 넣을 활동이다. 실행 중인 도구는 걸린 시간을 앞에 둔다. 좁은 칸에서 설명 끝이 잘려도 시간은 남는다.
func aiActivityText(activity *aiActivity, now time.Time) string {
	if activity == nil {
		return ""
	}
	switch {
	case activity.Kind == "tool" && activity.Running:
		return formatTopEventDuration(now.Sub(activity.At)) + " · " + activity.Text
	case activity.Kind == "tool":
		return "thinking · after " + activity.Text
	case activity.Kind == "thinking":
		return "thinking"
	}
	return activity.Text
}

func TestAIActivityReaderSkipsACutFirstLineAndCaches(t *testing.T) {
	path := filepath.Join(t.TempDir(), "t.jsonl")
	padding := strings.Repeat("x", int(aiActivityTail))
	line := `{"type":"assistant","timestamp":"2026-10-29T06:40:20Z","message":{"content":[{"type":"tool_use","id":"t1","name":"Read","input":{"file_path":"/w/a.go"}}]}}`
	if err := os.WriteFile(path, []byte(padding+"\n"+line+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	reader := aiActivityReader{}
	sessions := []aiSession{{Tool: "claude", State: aiStateWorking, Transcript: path, Task: "fix the bug"}, {Tool: "claude", State: aiStateWaiting, Transcript: path}}
	reader.annotate(sessions, time.Now())
	if sessions[0].Activity == nil || sessions[0].Activity.Text != "Read: /w/a.go" || sessions[1].Activity != nil {
		t.Fatalf("annotate %+v", sessions)
	}
	if _, ok := reader[path]; !ok {
		t.Fatal("the reader must cache the transcript")
	}
	sessions[0].Activity = nil
	if aiSessionDetail(sessions[0], time.Now()) != "fix the bug" {
		t.Fatal("a working session without activity shows its task")
	}
}

func TestAIActivityReaderCountsClaudeTokensOnceAndKeepsCounting(t *testing.T) {
	path := filepath.Join(t.TempDir(), "c.jsonl")
	first := `{"type":"assistant","timestamp":"2026-10-29T06:40:20Z","gitBranch":"develop","requestId":"r1","message":{"id":"m1","model":"claude-opus-5-5",` +
		`"content":[{"type":"text","text":"a"}],"usage":{"input_tokens":10,"cache_creation_input_tokens":100,"cache_read_input_tokens":1000,"output_tokens":5}}}`
	// 같은 응답의 다음 줄은 output만 늘어난 값을 다시 적는다.
	again := strings.Replace(first, `"output_tokens":5`, `"output_tokens":50`, 1)
	mode := `{"type":"user","timestamp":"2026-10-29T06:40:21Z","permissionMode":"bypassPermissions","message":{"content":"next"}}`
	if err := os.WriteFile(path, []byte(first+"\n"+again+"\n"+mode+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	reader := aiActivityReader{}
	_, _, info := reader.read("claude", path)
	if info.Model != "claude-opus-5-5" || info.Branch != "develop" || info.Mode != "bypassPermissions" || info.Context != 1110 {
		t.Fatalf("info %+v", info)
	}
	if info.Tokens.Input != 110 || info.Tokens.Output != 50 || info.Tokens.Cache != 1000 || info.Tokens.Requests != 1 {
		t.Fatalf("one response must count once: %+v", info.Tokens)
	}
	second := strings.NewReplacer(`"m1"`, `"m2"`, `"r1"`, `"r2"`).Replace(first)
	appendAIFixture(t, path, second+"\n")
	if _, _, info = reader.read("claude", path); info.Tokens.Requests != 2 || info.Tokens.Output != 55 {
		t.Fatalf("new lines must add to the total: %+v", info.Tokens)
	}
}

