	for _, want := range []string{"source <(edc alias zsh)' >> ~/.zshrc", "_edc_alias() {", "# logs", "_edc_alias eg 'edc grep'", "# diagnose", "# observe", "# record and remote", "unset -f _edc_alias", "# eg timeout /var/log/app/"} {
