	}
	// banner가 버전을 보여 주므로 머리말의 Version 줄은 중복이다.
	if strings.Contains(text, "Version     :") {
		t.Fatalf("the version line duplicates the banner: %q", text)
	}
	if strings.Contains(text, "\033[") {
		t.Fatalf("색을 끄면 escape가 없어야 한다: %q", text)
	}
}

