// h2c 연결은 HTTP2_PREFACE_LEN byte 머리로 시작한다. 짧은 조각은 HTTP/1 서버가 몇 byte씩 엿보는 경우와 구별할 수 없다.
int http2_start = readable && peek[0] == 'P' && peek[1] == 'R' && peek[2] == 'I' && peek[3] == ' ' && h2c_preface(buffer, limit, size);
// TCP Fast Open은 송신 호출 안에서 SYN과 첫 순번을 정하므로 시작할 때의 write_seq가 첫 data의 순번이 아니다. 이런
// 연결은 client 쪽 h2c를 따라가지 않는다. 위치를 틀리게 잡으면 첫 쓰기 뒤의 frame을 모두 버리게 된다. http_start는
// "PRI "도 시작으로 보므로 start도 지워서, preface만 HTTP/1 레코드로 나가 반쪽 상태가 생기지 않게 한다.
if (http2_start && direction == HTTP_SENT) {
	__u8 state = BPF_CORE_READ(sk, __sk_common.skc_state);
	if (state == TCP_CLOSE || state == TCP_SYN_SENT) {
		http2_start = 0;
		start = 0;
	}
}
// 모든 TCP 송수신이 여기를 지나므로 이어 받을 조각이 있는 socket에서만 map에 값이 있다. 이어 받는 조각을 TLS 판별보다
// 먼저 보므로, 0x16 0x03으로 시작하는 HTTP body 조각을 TLS로 읽지 않는다. h2c 연결의 frame 안에서 "GET "처럼 보이는
// 조각이 와도 HTTP/1 message로 보지 않도록 HTTP 시작보다 먼저 확인한다.
__u64 *seen = bpf_map_lookup_elem(&http_streams, &key);
int http2_going = seen && (*seen & HTTP2_STREAM);
int http2 = http2_going || http2_start;
start = !http2_going && (start || http2_start);
__u8 kind = start ? HTTP_START : HTTP_CONTINUATION;
__u64 offset = 0;
__u64 budget = http_payload_limit;
__u8 tls_handshake[TLS_HANDSHAKE_HEADER_SIZE] = {};
int tls_synthetic = 0;
__u64 segment = 0;
int dropped = 0;
struct http_stream_key peer = {.skaddr = (__u64)sk, .direction = direction == HTTP_SENT ? HTTP_RECEIVED : HTTP_SENT};
int peer_marked = 0;
if (!start && !seen) {
	__u64 tls_offset = 0;
	__u64 tls_captured = 0;
	struct tls_segments segments = {.base = {buffer}, .len = {limit}};

	__u64 tail = mysql_tail_size < avail ? mysql_tail_size : avail;
	if (tail > MYSQL_TAIL_MAX) {
		tail = MYSQL_TAIL_MAX;
	}
	if (tail == 0 || bpf_probe_read_user(record->payload, tail, (void *)(end - tail))) {
		return;
	}
	record->event_type = MYSQL_TAIL_RECORD;
	record->len = tail;
	if (bpf_ringbuf_output(&events, record, __builtin_offsetof(struct http_record, payload) + tail, 0)) {
		__u32 zero = 0;
		__u64 *lost = bpf_map_lookup_elem(&lost_events, &zero);
		if (lost) {
			__sync_fetch_and_add(lost, 1);
		}
	}
}

static __always_inline void emit_mysql_iov(struct sock *sk, __u64 buffer, __u64 limit, const struct iovec *iov, __u64 nr_segs, __u64 size, __u8 direction, __u8 server) {
	if (!buffer || size == 0) {
		return;
	}
	__u32 zero = 0;
	struct http_record *record = bpf_map_lookup_elem(&http_scratch, &zero);
	if (!record) {
		return;
	}
	__u32 cap = server != (direction == HTTP_SENT) ? MYSQL_REQUEST_SIZE : (mysql_response_size ? mysql_response_size : MYSQL_RESPONSE_SIZE);
	if (cap >= MYSQL_REQUEST_SIZE) {
		cap = MYSQL_REQUEST_SIZE - 1;
	}
	struct http_cursor *cursor = bpf_map_lookup_elem(&http_cursors, &zero);

if (!buffer || size == 0) {
	return;
}
__u32 zero = 0;
struct http_record *record = bpf_map_lookup_elem(&http_scratch, &zero);
if (!record) {
	return;
}
__u64 cap = server != (direction == HTTP_SENT) ? MYSQL_REQUEST_SIZE : (mysql_response_size ? mysql_response_size : MYSQL_RESPONSE_SIZE);
__u64 len = size < limit ? size : limit;
if (len > cap) {
	len = cap;
}
if (len > MYSQL_REQUEST_SIZE) {
	len = MYSQL_REQUEST_SIZE;
}
if (len == 0 || bpf_probe_read_user(record->payload, len, (void *)buffer)) {
	return;
}
if (len >= 3 && record->payload[0] >= 0x14 && record->payload[0] <= 0x17 && record->payload[1] == 0x03 && (record->payload[2] == 0x01 || record->payload[2] == 0x03)) {
	return;
}
http_fill_record(record, sk, direction);
record->event_type = 11;
record->timestamp_ns = bpf_ktime_get_ns();
record->len = len;
record->kind = server;
record->offset = (__u32)size;
if (bpf_ringbuf_output(&events, record, __builtin_offsetof(struct http_record, payload) + len, 0)) {
	__u64 *lost = bpf_map_lookup_elem(&lost_events, &zero);
	if (lost) {
		__sync_fetch_and_add(lost, 1);

		}
		return;
	}
	// readv처럼 받은 byte가 첫 버퍼를 넘으면 끝이 다른 버퍼에 있어 끝부분을 넘기지 않는다.
	if (mysql_tail_size && server == (direction == HTTP_SENT) && size > len && size <= limit) {
		emit_mysql_tail(record, buffer + size, size);
	}
}

// DNS over TCP는 로컬이나 상대 port 53의 연결이다. 로컬 53은 이 host의 DNS 서버라서 --side server일 때만 본다.
static __always_inline int dns_tcp_socket(struct sock *sk) {
	__u16 local = BPF_CORE_READ(sk, __sk_common.skc_num);
	__u16 remote = bpf_ntohs(BPF_CORE_READ(sk, __sk_common.skc_dport));
	return remote == 53 || (emit_dns_server && local == 53);
}

// emit_dns_tcp는 TCP로 주고받은 조각의 앞부분을 DNS 레코드로 넘긴다. 조각 앞의 2바이트 길이는 그대로 두고, 사용자 공간이
// 연결마다 길이와 message를 맞춘다.
static __always_inline void emit_dns_tcp(struct sock *sk, const void *buffer, __u64 size, __u8 direction) {
	if (!sk || !buffer || size == 0) {
		return;
	}
	struct dns_record *record = bpf_ringbuf_reserve(&events, sizeof(*record), 0);
	if (!record) {
		__u32 key = 0;
		__u64 *lost = bpf_map_lookup_elem(&lost_events, &key);
		if (lost) {
			__sync_fetch_and_add(lost, 1);
		}
		return;
	}
	__u32 len = size;

			emit_mysql_iov((struct sock *)pending.send.skaddr, pending.send.buffer, pending.send.limit, (const struct iovec *)pending.send.iov, pending.send.nr_segs, sent, HTTP_SENT, pending.server);
		}
		return 0;
	}
	struct http_send_pending *stored = bpf_map_lookup_elem(&http_send_pending, &key);
	if (!stored) {
		return 0;
	}
	struct http_send_pending pending = *stored;
	bpf_map_delete_elem(&http_send_pending, &key);
	int sent = (int)ctx[3];
	if (sent > 0) {
		// 끝날 때 write_seq는 보낸 만큼 앞서 있다. BPF_CORE_READ 안에서 pending을 읽으면 그 접근도 kernel 타입으로
		// 옮기려다 실패하므로 pointer를 먼저 꺼낸다.
		struct tcp_sock *tcp = (struct tcp_sock *)pending.skaddr;
		__u32 seq = BPF_CORE_READ(tcp, write_seq) - sent;
		http_capture((struct sock *)pending.skaddr, pending.buffer, pending.limit, (const struct iovec *)pending.iov, pending.nr_segs, sent, HTTP_SENT, seq);
	}
	return 0;
}

SEC("fentry/tcp_cleanup_rbuf")
int tcp_cleanup_rbuf_entry(__u64 *ctx) {
	return emit_tcp_length_fallback((struct sock *)ctx[0], (int)ctx[1], 7);
}

// tcp_recvmsg가 끝나야 사용자 버퍼에 data가 있다. 시작할 때 버퍼 위치를 thread별로 두고 끝날 때 읽는다.
struct http_recv_pending {
	__u64 skaddr;
	__u64 buffer;
	__u64 limit;
	__u64 iov;

	__u64 nr_segs;
};

struct {
	__uint(type, BPF_MAP_TYPE_HASH);
	__uint(max_entries, 10240);
	__type(key, __u64);
	__type(value, struct http_recv_pending);
} http_recv_pending SEC(".maps");

SEC("fentry/tcp_recvmsg")
int tcp_recvmsg_entry(__u64 *ctx) {
	struct sock *sk = (struct sock *)ctx[0];
	// SSL_read 안의 수신이면 그 SSL 객체에 socket을 적는다. MSG_PEEK와 port 확인보다 먼저 해야 한다.
	if (emit_tls_plaintext && sk) {
		ssl_learn(sk);
	}
	// MSG_PEEK로 읽은 data는 다음 recv가 다시 읽는다. 같은 message를 두 번 내지 않는다.
	if ((int)ctx[3] & MSG_PEEK) {
		return 0;
	}
	// 끝날 때 쓰지 않을 socket이면 버퍼 위치를 기록하지 않는다. recv마다 map을 갱신하는 비용이 크다.
	if (!sk || !((emit_dns_tcp_messages && dns_tcp_socket(sk)) || (emit_http_messages && http_socket(sk)) || (mysql_port && mysql_socket(sk)))) {
		return 0;
	}
	struct http_recv_pending pending = {.skaddr = ctx[0], .nr_segs = 1};
	void *buffer = http_user_buffer((struct msghdr *)ctx[1], &pending.limit);
	if (!buffer) {
		return 0;
	}
	pending.buffer = (__u64)buffer;
	// readv와 recvmsg는 받은 byte를 여러 iovec에 나눠 담는다. 첫 iovec만 읽으면 그 뒤의 byte를 놓친다.

// rootCommand는 지금 명령을 sudo로 다시 실행하는 줄이다. Ubuntu의 sudo는 secure_path만 PATH로 써서 ~/.local/bin의
// edc를 찾지 못하므로 실행 파일의 전체 경로를 쓴다.
func rootCommand(executable string, args []string) string {
	words := []string{"sudo", shellWord(executable)}
	for _, arg := range args {
		words = append(words, shellWord(arg))
	}
	return strings.Join(words, " ")
}

// shellWord는 셸에 그대로 붙여 넣을 수 있게, 특수 문자가 있을 때만 작은따옴표로 감싼다.
func shellWord(word string) string {
	plain := func(r rune) bool {
		return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("/-_.=:,@+%", r)
	}
	if word != "" && strings.IndexFunc(word, func(r rune) bool { return !plain(r) }) < 0 {
		return word
	}
	return "'" + strings.ReplaceAll(word, "'", `'\''`) + "'"
}

// traceTLSAttachGone은 탐색한 뒤 그 process가 끝나 경로가 사라져서 아무것도 붙이지 못한 경우다. 그 파일은 같은 파일을
// 적재한 다른 process에서 다시 고른다. 일부라도 붙었으면 다시 고르지 않아 같은 함수에 두 번 붙지 않는다.
func traceTLSAttachGone(attached []link.Link, err error) bool {
	return len(attached) == 0 && (err == nil || errors.Is(err, fs.ErrNotExist))
}

// postgresResponseCapture는 trace postgres가 응답 방향에서 읽는 byte 수다. 서버는 결과를 8192 byte씩 보내므로 이 값으로도 큰
// 결과의 경계는 잃지만, 작은 결과의 마지막 쓰기(CommandComplete와 ReadyForQuery)는 담는다(testdata/postgres/boundaries.txt).
const postgresResponseCapture = 4096

type captureEventFilter struct {
	udpEvents    bool
	dnsSent      bool
	server       bool
	tcpStatePort uint16
	httpMessages bool
	dnsTCP       bool
	// httpPayload는 HTTP message를 httpPayloadHead까지 읽는다. 끄면 BPF 기본값인 512바이트만 읽는다.
	httpPayload bool
	// httpPort가 0이 아니면 로컬이나 상대 port가 이 값인 socket의 HTTP message만 본다.
	httpPort uint16
	// httpMessageLimit가 0이 아니면 HTTP message 하나를 이 byte 수까지 조각으로 따라간다.
	httpMessageLimit uint32
	// mysqlPort가 0이 아니면 로컬이나 상대 port가 이 값인 socket의 MySQL packet을 읽는다. trace clickhouse도 같은 BPF
	// 경로를 쓰므로 ClickHouse port를 이 변수에 넣는다.
	mysqlPort uint16
	// mysqlResponseSize가 0이 아니면 응답 방향을 이 byte 수까지 읽는다. 0이면 BPF 기본값인 1024를 쓴다.
	mysqlResponseSize uint32
	// mysqlTailSize가 0이 아니면 응답 방향에서 앞부분보다 긴 쓰기나 읽기의 끝 이 byte 수를 끝부분 레코드로 더 읽는다.
	mysqlTailSize uint32
	// allTCPDestroys는 끝난 socket을 port와 관계없이 알린다. 서버 쪽 socket은 닫힐 때 port를 놓아 port로 고를 수 없다.
	allTCPDestroys bool
	// clickHouseHTTPPort가 0이 아니면 trace clickhouse가 이 port의 socket도 mysqlPort와 같은 경로로 읽는다.
	clickHouseHTTPPort uint16
	// tlsPlaintext는 trace http --tls다. OpenSSL uprobe가 넘기는 평문 레코드를 낸다.
	tlsPlaintext bool
}

func captureEventFilterFor(scope traceScope) captureEventFilter {
	filter := captureEventFilter{udpEvents: true, dnsSent: true}
	switch scope.protocol {
	case "tcp":
		// skb_consume_udp는 target 이름을 지을 DNS 응답만 보낸다.
		filter.udpEvents = false
	case "udp":
		filter.dnsSent = false
	case "dns":
		filter.udpEvents, filter.server, filter.tcpStatePort, filter.dnsTCP = false, scope.server, 53, true
	case "http":
		filter.udpEvents, filter.httpMessages, filter.httpPayload, filter.httpPort, filter.tlsPlaintext = false, true, scope.payload, scope.port, scope.tls != ""
		if scope.payloadAll {
			filter.httpMessageLimit = httpMessageMax
		}
	case "mysql":
		filter.udpEvents, filter.mysqlPort = false, cmp.Or(scope.port, traceMySQLDefaultPort)
	case "clickhouse":
		filter.udpEvents, filter.mysqlPort = false, cmp.Or(scope.port, traceClickHouseDefaultPort)
		filter.mysqlResponseSize = clickHouseResponseCapture
		filter.clickHouseHTTPPort = cmp.Or(scope.httpPort, traceClickHouseDefaultHTTPPort)
	case "postgres":
		filter.udpEvents, filter.mysqlPort = false, cmp.Or(scope.port, tracePostgresDefaultPort)
		filter.mysqlResponseSize, filter.mysqlTailSize, filter.allTCPDestroys = postgresResponseCapture, postgresTailCapture, true
	case "redis":
		// 작은 응답은 모두 쓰기의 앞 1024 byte 안에서 끝나고, 4095로 늘려도 경계를 잃는 큰 array 응답은 그대로다
		// (testdata/redis/capture.txt Findings 3, 4). 그래서 BPF 기본값을 쓴다.
		filter.udpEvents, filter.mysqlPort, filter.allTCPDestroys = false, cmp.Or(scope.port, traceRedisDefaultPort), true
	}
	return filter
}

func collectCaptureEventsFor(scope traceScope, duration time.Duration, onEvent func(captureEvent) error, stop <-chan struct{}) (captureSummary, error) {
	protocol := scope.protocol
	tlsNotices := newTraceTLSNoticeBuffer()
	queueTLSNotice := tlsNotices.offer
	if scope.tlsFinder != nil {
		for _, notice := range scope.tlsFinder.notices {
			tlsNotices.record(notice)
		}
	}
	if err := rlimit.RemoveMemlock(); err != nil {
		return captureSummary{}, fmt.Errorf("remove memlock limit: %w", err)
	}
	// 프로그램을 붙이기 전에 채워서, 붙인 뒤 첫 event를 읽는 시점을 늦추지 않는다.
	names := newDNSNameCache()
	seedResolverCache(names)
	objects := captureEventsObjects{}
	if err := loadCaptureEventsFor(scope, &objects); err != nil {
		return captureSummary{}, fmt.Errorf("load eBPF objects: %w", err)
	}
	defer objects.Close()

	attachments, tracing := captureAttachmentsFor(&objects, scope)
	links := make([]link.Link, 0, len(attachments)+len(tracing))
	tlsExecProblem := ""
	closeLinks := func() { closeCaptureLinks(links) }
	for _, attachment := range attachments {
		attached, err := link.Tracepoint(attachment.group, attachment.name, attachment.prog, nil)
		if err != nil {
			closeLinks()
			return captureSummary{}, fmt.Errorf("attach %s/%s: %w", attachment.group, attachment.name, err)
		}
		links = append(links, attached)

func TestCaptureEventFiltersFollowTheProtocol(t *testing.T) {
	for _, test := range []struct {
		scope traceScope
		want  captureEventFilter
	}{
		{traceScope{}, captureEventFilter{udpEvents: true, dnsSent: true}},
		{traceScope{protocol: "tcp"}, captureEventFilter{dnsSent: true}},
		{traceScope{protocol: "udp"}, captureEventFilter{udpEvents: true}},
		{traceScope{protocol: "dns"}, captureEventFilter{dnsSent: true, tcpStatePort: 53, dnsTCP: true}},
		{traceScope{protocol: "dns", server: true}, captureEventFilter{dnsSent: true, server: true, tcpStatePort: 53, dnsTCP: true}},
		{traceScope{protocol: "http"}, captureEventFilter{dnsSent: true, httpMessages: true}},
		{traceScope{protocol: "http", payload: true}, captureEventFilter{dnsSent: true, httpMessages: true, httpPayload: true}},
		{traceScope{protocol: "http", server: true, port: 8080}, captureEventFilter{dnsSent: true, httpMessages: true, httpPort: 8080}},
		{traceScope{protocol: "http", payload: true, payloadAll: true}, captureEventFilter{dnsSent: true, httpMessages: true, httpPayload: true, httpMessageLimit: httpMessageMax}},
		{traceScope{protocol: "http", tls: traceTLSAuto}, captureEventFilter{dnsSent: true, httpMessages: true, tlsPlaintext: true}},
		{traceScope{protocol: "http", tls: "/usr/lib/libssl.so.3", port: 443}, captureEventFilter{dnsSent: true, httpMessages: true, httpPort: 443, tlsPlaintext: true}},
		{traceScope{protocol: "mysql"}, captureEventFilter{dnsSent: true, mysqlPort: 3306}},
		{traceScope{protocol: "mysql", port: 3307}, captureEventFilter{dnsSent: true, mysqlPort: 3307}},
		{traceScope{protocol: "clickhouse"}, captureEventFilter{dnsSent: true, mysqlPort: 9000, mysqlResponseSize: 4096, clickHouseHTTPPort: 8123}},
		{traceScope{protocol: "clickhouse", port: 9440, httpPort: 18123}, captureEventFilter{dnsSent: true, mysqlPort: 9440, mysqlResponseSize: 4096, clickHouseHTTPPort: 18123}},
		{traceScope{protocol: "postgres"}, captureEventFilter{dnsSent: true, mysqlPort: 5432, mysqlResponseSize: 4096, mysqlTailSize: postgresTailCapture, allTCPDestroys: true}},
		{traceScope{protocol: "postgres", port: 6432}, captureEventFilter{dnsSent: true, mysqlPort: 6432, mysqlResponseSize: 4096, mysqlTailSize: postgresTailCapture, allTCPDestroys: true}},
		{traceScope{protocol: "redis"}, captureEventFilter{dnsSent: true, mysqlPort: 6379, allTCPDestroys: true}},
		{traceScope{protocol: "redis", port: 6380}, captureEventFilter{dnsSent: true, mysqlPort: 6380, allTCPDestroys: true}},
	} {
		if got := captureEventFilterFor(test.scope); got != test.want {
			t.Fatalf("scope %+v filter = %+v, want %+v", test.scope, got, test.want)
		}
	}
	defaultHTTP := tcpTraceOptions{}
	applyTraceHTTPDefaults(&defaultHTTP)
	defaultFilter := captureEventFilterFor(defaultHTTP.scope("http"))

	if err := errors.Join(variables.EmitUdpEvents.Get(&udpEvents), variables.EmitDnsSent.Get(&dnsSent), variables.EmitDnsServer.Get(&server), variables.TcpStatePort.Get(&tcpStatePort), variables.HttpPayloadLimit.Get(&httpPayloadLimit), variables.HttpPort.Get(&httpPort), variables.HttpMessageLimit.Get(&httpMessageLimit), variables.MysqlPort.Get(&mysqlPort), variables.MysqlResponseSize.Get(&mysqlResponseSize), variables.ClickhouseHttpPort.Get(&clickHouseHTTPPort),
		variables.EmitTlsPlaintext.Get(&tlsPlaintext), variables.UprobeArch.Get(&uprobeArch)); err != nil {
		t.Fatal(err)
	}
	// uprobe program은 모든 trace가 함께 불러오므로, --tls가 아니면 첫 명령에서 돌아가도록 꺼져 있어야 한다.
	if tlsPlaintext != 0 || uprobeArch != 0 {
		t.Fatalf("TLS BPF defaults = %d, %d", tlsPlaintext, uprobeArch)
	}
	// capture는 모든 event와 client 쪽 DNS 레코드를 받는다. 서버 쪽 레코드는 trace dns --side server만 켠다.
	// HTTP message는 --payload가 아니면 요청 줄과 Host가 들어가는 512바이트만 읽는다.
	if udpEvents != 1 || dnsSent != 1 || server != 0 || tcpStatePort != 0 || httpPayloadLimit != 512 || httpPort != 0 || httpMessageLimit != 0 || mysqlPort != 0 || mysqlResponseSize != 0 || clickHouseHTTPPort != 0 {
		t.Fatalf("BPF defaults = %d, %d, %d, %d, %d, %d, %d, %d, %d, %d", udpEvents, dnsSent, server, tcpStatePort, httpPayloadLimit, httpPort, httpMessageLimit, mysqlPort, mysqlResponseSize, clickHouseHTTPPort)
	}
}

func dnsRecordSample(t *testing.T, pid uint32, message *dns.Msg) []byte {
	t.Helper()
	payload, err := message.Pack()
	if err != nil {
		t.Fatal(err)
	}
	sample := make([]byte, dnsRecordPayloadOffset+1024)
	binary.LittleEndian.PutUint32(sample[8:12], dnsRecordType)
	binary.LittleEndian.PutUint32(sample[12:16], pid)
	binary.LittleEndian.PutUint32(sample[40:44], uint32(len(payload)))
	copy(sample[dnsRecordPayloadOffset:], payload)
	return sample
}

// dnsRecordPayloadOffset과 parseDNSRecord의 offset은 BPF의 struct dns_record를 따른다. bpf2go가 만든 Go 구조체와
// 비교해 C 구조체를 바꾸고 이쪽을 고치지 않으면 여기서 실패한다.
func TestDNSRecordOffsetsMatchTheBPFStruct(t *testing.T) {
	var record captureEventsDnsRecord
	for name, offsets := range map[string][2]uintptr{
		"event_type":  {unsafe.Offsetof(record.EventType), 8},
		"pid":         {unsafe.Offsetof(record.Pid), 12},
		"cgroup_id":   {unsafe.Offsetof(record.CgroupId), 16},
		"arrival_ns":  {unsafe.Offsetof(record.ArrivalNs), 24},
		"skaddr":      {unsafe.Offsetof(record.Skaddr), 32},
		"len":         {unsafe.Offsetof(record.Len), 40},
		"family":      {unsafe.Offsetof(record.Family), 44},
		"direction":   {unsafe.Offsetof(record.Direction), 46},
		"transport":   {unsafe.Offsetof(record.Transport), 47},
		"sport":       {unsafe.Offsetof(record.Sport), 48},
		"dport":       {unsafe.Offsetof(record.Dport), 50},
		"source":      {unsafe.Offsetof(record.Source), 52},
		"destination": {unsafe.Offsetof(record.Destination), 68},
		"comm":        {unsafe.Offsetof(record.Comm), 84},
		"payload":     {unsafe.Offsetof(record.Payload), dnsRecordPayloadOffset},
	} {
		if offsets[0] != offsets[1] {
			t.Fatalf("%s is at %d in the BPF struct, parseDNSRecord reads %d", name, offsets[0], offsets[1])
		}
	}
}

