		// 원격 호스트의 clean은 그 호스트의 홈과 프로젝트를 잰다. 이 컴퓨터의 --project는 넘기지 않는다.
		if len(projects) > 0 {
			fmt.Fprintln(os.Stderr, T("clean.group.error.project"))
			return 2
		}
		return runCleanGroup(options, *group, *inventory, version, deps.remote, stdout)
	}

