const (
	// logrotate 설정 한 파일에서 읽는 크기의 상한과, include를 따라가며 읽는 파일 수와 깊이의 상한이다.
	cleanLogrotateFileMax  = 1 << 20
	cleanLogrotateFiles    = 500
	cleanLogrotateIncluded = 8
)

// cleanLogrotatePatterns는 logrotate 설정에서 규칙의 로그 경로 패턴을 모은다. 주 설정 파일과 설정 디렉터리에서 시작해
// include 줄을 절대 경로일 때만 따라간다. 설정을 하나도 읽지 못하면 known이 false다.
func cleanLogrotatePatterns(ctx context.Context, paths cleanSystemPaths) (patterns []cleanLogrotatePattern, known bool) {
	type pending struct {
		path  string
		depth int
	}
	var queue []pending
	for _, file := range cleanConfigFilesAny(paths.logrotateConf) {
		queue = append(queue, pending{file, 0})
	}
	for _, file := range cleanLogrotateDirFiles(paths.logrotateDir) {
		queue = append(queue, pending{file, 0})
	}
	visited := map[string]bool{}
	for len(queue) > 0 && len(visited) < cleanLogrotateFiles && ctx.Err() == nil {
		current := queue[0]
		queue = queue[1:]
		if visited[current.path] {
			continue
		}
		visited[current.path] = true
		text, ok := cleanReadLimited(current.path, cleanLogrotateFileMax)
		if !ok {
			continue
		}
		known = true
		patterns = append(patterns, cleanParseLogrotate(text, current.path)...)
		if current.depth >= cleanLogrotateIncluded {
			continue
		}
		for _, include := range cleanLogrotateIncludes(text) {

			info, err := os.Stat(include)
			switch {
			case err != nil:
			case info.IsDir():
				for _, file := range cleanLogrotateDirFiles(include) {
					queue = append(queue, pending{file, current.depth + 1})
				}
			default:
				queue = append(queue, pending{include, current.depth + 1})
			}
		}
	}
	return patterns, known
}

// cleanReadLimited는 max를 넘는 파일을 읽지 않는다. 설정 파일 하나가 메모리를 크게 쓰지 못하게 한다.
func cleanReadLimited(path string, max int64) (string, bool) {
	info, err := os.Stat(path)
	if err != nil || !info.Mode().IsRegular() || info.Size() > max {
		return "", false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", false
	}
	return string(data), true
}

func cleanConfigFilesAny(path string) []string {
	if info, err := os.Stat(path); err == nil && !info.IsDir() {
		return []string{path}
	}
	return nil
}

// cleanOpenCounts는 paths 각각을 열고 있는 fd 수를 한 번의 /proc 순회로 센다.
func cleanOpenCounts(ctx context.Context, procDir string, logs []cleanLargeLog) (counts map[string]int, complete, readable bool) {
	entries, err := os.ReadDir(procDir)
	if err != nil {
		return nil, false, false
	}
	wanted := make(map[string]bool, len(logs))
	for _, log := range logs {
		wanted[log.Path] = true
	}
	counts, complete = map[string]int{}, true
	for _, entry := range entries {
		if ctx.Err() != nil {
			return counts, false, true
		}
		if !entry.IsDir() || !cleanNumeric(entry.Name()) {
			continue
		}
		fdDir := filepath.Join(procDir, entry.Name(), "fd")
		fds, err := os.ReadDir(fdDir)
		if err != nil {
			if !os.IsNotExist(err) {
				complete = false
			}
			continue
		}
		for _, fd := range fds {
			if target, err := os.Readlink(filepath.Join(fdDir, fd.Name())); err == nil {
				target = strings.TrimSuffix(target, " (deleted)")
				if wanted[target] {
					counts[target]++
				}

// cleanDescribeBuildCaches는 보일 캐시에만 마지막 쓰기와 열린 파일을 채운다. 열린 파일이 없을 때만 명령을 둔다.
func cleanDescribeBuildCaches(ctx context.Context, caches []cleanBuildCache) {
	for index := range caches {
		cache := &caches[index]
		newest, partial := cleanNewestWrite(ctx, cache.Path)
		if !newest.IsZero() {
			utc := newest.UTC()
			cache.NewestWrite = &utc
		}
		cache.NewestPartial = partial
		count, complete, readable := cleanOpenUnder(ctx, cleanProcDir, cache.Path)
		if !readable {
			continue
		}
		cache.OpenFiles, cache.OpenFilesComplete = &count, complete
		// /proc을 모두 읽어 열린 파일이 없다고 확인한 경우에만 명령을 둔다. 읽지 못한 process가 있으면 쓰는 중일 수 있다.
		if count == 0 && complete {
			cache.Cleanup = "rm -rf " + cleanShellQuote(cache.Path)
		}
	}
}

		if current == revision {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			continue
		}
		modified := info.ModTime().UTC()
		revisions = append(revisions, cleanSnapRevision{Name: name, Revision: revision, Current: current, Bytes: uint64(info.Size()),
			Modified: &modified, Cleanup: fmt.Sprintf("snap remove %s --revision=%s", name, revision)})
	}
	sort.Slice(revisions, func(i, j int) bool {
		if revisions[i].Bytes != revisions[j].Bytes {
			return revisions[i].Bytes > revisions[j].Bytes
		}
		return revisions[i].Name+revisions[i].Revision < revisions[j].Name+revisions[j].Revision
	})
	return revisions, unknown
}

func cleanTestSparse(t *testing.T, path string, size int64) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	file, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := file.Truncate(size); err != nil {
		t.Fatal(err)
	}
}

func TestCleanJournaldDetailFollowsTheSystemdPrecedence(t *testing.T) {
	root := t.TempDir()
	etcMain := filepath.Join(root, "etc/journald.conf")
	vendorMain := filepath.Join(root, "usr/journald.conf")
	etcDrop, runDrop, vendorDrop := filepath.Join(root, "etc/journald.conf.d"), filepath.Join(root, "run/journald.conf.d"), filepath.Join(root, "usr/journald.conf.d")
	now := time.Now()
	cleanTestWriteFile(t, etcMain, "[Journal]\n#SystemMaxUse=\nSystemMaxUse=2G\nSystemKeepFree=1G\nStorage=persistent\n[Other]\nMaxRetentionSec=1\n", now)
	cleanTestWriteFile(t, vendorMain, "[Journal]\nSystemMaxUse=9G\nMaxRetentionSec=9\n", now)
	// 같은 이름은 /etc가 /usr/lib을 가린다. 남은 파일은 디렉터리와 상관없이 이름 순으로 적용된다.
	cleanTestWriteFile(t, filepath.Join(vendorDrop, "50-limit.conf"), "[Journal]\nSystemMaxUse=1G\n", now)
	cleanTestWriteFile(t, filepath.Join(etcDrop, "50-limit.conf"), "[Journal]\nSystemMaxUse=500M\n", now)
	cleanTestWriteFile(t, filepath.Join(vendorDrop, "10-first.conf"), "[Journal]\nSystemMaxUse=300M\nMaxRetentionSec=1month\n", now)
	cleanTestWriteFile(t, filepath.Join(runDrop, "90-last.conf"), "[Journal]\nSystemKeepFree=\n", now)
	cleanTestWriteFile(t, filepath.Join(etcDrop, "ignored.txt"), "[Journal]\nSystemMaxFileSize=9G\n", now)
	// 50-limit.conf(/etc)가 SystemMaxUse=500M으로 최종 값을 정하고, 90-last.conf가 SystemKeepFree를 비워 되돌린다.
	got := cleanJournaldDetail([]string{etcMain, vendorMain}, []string{etcDrop, runDrop, vendorDrop})()
	if got != "journald.conf sets SystemMaxUse=500M, MaxRetentionSec=1month" {
		t.Fatalf("detail = %q", got)
	}
	// /etc에 주 설정이 없으면 /usr/lib의 주 설정을 읽고, drop-in이 그 위에 덮인다.
	got = cleanJournaldDetail([]string{filepath.Join(root, "missing.conf"), vendorMain}, []string{vendorDrop})()
	if got != "journald.conf sets SystemMaxUse=1G, MaxRetentionSec=1month" {
		t.Fatalf("vendor main = %q", got)
	}
}

