		}
		result := svcResultFor(ctrProbeID, "state", StatusFail, T("ctr.state.inspect_failed", infoSingleLine(firstLine(detail))))
		result.Error = &DiagnosticError{Kind: "command", Message: detail}
		return []Result{result}
