func ctrStateText(inspect ctrInspect) string {
	state := inspect.Status
	if inspect.Health != "" {
		state += " (" + inspect.Health + ")"
	}
	if inspect.Status != "running" && !inspect.FinishedAt.IsZero() {
		state += fmt.Sprintf(", exit code %d", inspect.ExitCode)
	}
