	case inspect.RestartPolicy == "no":
		return T("ctr.state.no_policy")
	case inspect.RestartPolicy == "on-failure" && inspect.RestartMax > 0:
		return fmt.Sprintf("on-failure:%d", inspect.RestartMax)
	}
	return inspect.RestartPolicy
