func ctrPhaseTwoSampleReason(metric, latest, requestErr string, ctxErr error) string {
	cause := latest
	if cause == "" {
		cause = requestErr
	}
	if cause == "" && ctxErr != nil {
		cause = ctxErr.Error()
	}
	if cause == "" {
		cause = "value is missing"
	}
	return "phase-two sample unavailable for " + metric + ": " + cause
}

