const (
	diskProbeCheck = "disk.check"
	diskProbeGrow  = "disk.grow"
	diskSectorSize = 512
	// diskGrowMinGap보다 작은 차이는 정렬과 메타데이터의 몫이다. 이것까지 늘릴 공간으로 보면
	// 이미 다 늘린 디스크에서도 매번 할 일이 남았다고 말한다.
	diskGrowMinGap = 1 << 20
	// GPT는 디스크 끝 33 섹터에 백업 헤더를 둔다. 파티션은 그 앞까지만 늘어난다.
	diskGPTTailBytes = 34 * diskSectorSize
	// MBR은 섹터 번호를 32비트로 적으므로 파티션 끝이 2 TiB를 넘지 못한다.
	diskMBRLimitBytes = (1 << 32) * diskSectorSize
	// diskMaxSteps는 rescan을 뺀 단계 수(partition, pv, lv, filesystem)보다 넉넉하다.
	// 단계가 크기를 바꾸지 못하면 같은 단계를 되풀이하지 않고 멈추므로 실제로는 닿지 않는다.
	diskMaxSteps = 6
)

// checkDiskMount는 check의 마운트 하나다. 늘릴 공간이 남았으면 warn으로 눈에 띄게 한다. 장치가 커널보다
// 크다고 답했으면 rescan한 뒤의 크기로 계획한다. 그래야 콘솔에서 늘린 볼륨을 grow 전에 보여 준다.
func checkDiskMount(ctx context.Context, system diskSystem, mount diskMount) Result {
	started := time.Now()
	chain, err := system.readChain(ctx, mount)
	if err != nil {
		return resultFromError(diskProbeCheck, started, "disk", fmt.Errorf("%s: %w", mount.Point, err))
	}
	result := Result{Probe: diskProbeCheck, Status: StatusPass, StartedAt: started.UTC()}
	if !diskGrowFSTypes[mount.FSType] {
		result.Status, result.Summary = StatusSkip, mount.Point+": "+chain.Blocked
		return finishDiskResult(result, started)
	}
	planned := chain.afterRescan()
	steps, blocked := planDiskGrow(planned)
	result.Evidence = diskEvidence(chain, steps)
	// 파티션 순서 때문에 막힌 경우만 본다. readChain이 다른 이유(논리 파티션 등)로 막았다면 그 이유를 그대로 보인다.
	owner := ""
	if blocked != "" && chain.Blocked == "" && planned.freeAfterLast() {
		owner = system.partitionMount(planned.LastPart)
	}
	switch {
	case owner != "":
		// 빈 공간은 마지막 파티션의 몫이다. 그 파일시스템의 줄이 grow를 제안하므로 여기서 다시 경고하지 않는다.
		result.Summary = T("disk.check.space_for", mount.Point, formatBytes(chain.Part.Size), chain.Disk.Name, owner)
		return finishDiskResult(result, started)
	case blocked != "":
		result.Status, result.Summary = StatusWarn, mount.Point+": "+blocked
	case len(steps) > 0:
		result.Status = StatusWarn
		from, to := diskGrowRange(steps)
		result.Summary = T("disk.check.growable", mount.Point, formatBytes(from), formatBytes(to), formatBytes(diskGrowth(steps)))

		result.Next = "edc disk grow " + quoteLocalShellWord(mount.Point)
	case chain.FSSizeErr != nil:
		result.Status = StatusWarn
		result.Summary = T("disk.check.unknown", mount.Point)
	default:
		result.Summary = T("disk.check.full", mount.Point, formatBytes(chain.FSSize))
	}
	if blocked == "" {
		result.Warnings = append(result.Warnings, diskRescanWarnings(chain)...)
	}
	return finishDiskResult(result, started)
}

// diskRescanWarnings는 SCSI 디스크의 크기를 설명한다. 장치에 물어 커널보다 크다는 답을 받았으면 그 크기를,
// 묻지 못했으면 grow가 rescan하면서 더 찾을 수도 있다는 것을 알린다. 같은 크기라는 답을 받았으면 말하지 않는다.
func diskRescanWarnings(chain diskChain) []string {
	switch {
	case chain.grownVolume() > 0:
		return []string{T("disk.check.volume_grew", chain.Disk.Name, formatBytes(chain.grownVolume()), formatBytes(chain.Disk.Size))}
	case chain.Disk.Rescan && chain.DeviceSize == 0:
		return []string{T("disk.check.rescan_note", chain.Disk.Name)}
	}
	return nil
}

// checkDiskMounts는 인자가 없을 때 블록 디바이스 위의 마운트를 한 번씩만 본다. bind 마운트는
// root 필드가 "/"가 아니므로 건너뛴다.
func checkDiskMounts(ctx context.Context, system diskSystem, path string) []Result {
	mounts, err := system.mounts()
	if err != nil {
		return []Result{resultFromError(diskProbeCheck, time.Now(), "disk", err)}
	}
	if path != "" {
		mount, ok := findDiskMount(mounts, path)
		if !ok {
			return []Result{resultFromError(diskProbeCheck, time.Now(), "disk", errors.New(T("disk.error.no_mount", path)))}
		}
		return []Result{checkDiskMount(ctx, system, mount)}
	}
	seen := map[string]bool{}
	var results []Result
	for _, mount := range mounts {
		key := fmt.Sprintf("%d:%d", mount.Major, mount.Minor)
		// 이름을 주지 않았을 때는 늘릴 수 있는 파일시스템만 본다. vfat인 /boot/efi 같은 줄은 매번 skip으로 남아 소음이 된다.
		if mount.Major == 0 || mount.Root != "/" || !strings.HasPrefix(mount.Source, "/dev/") || !diskGrowFSTypes[mount.FSType] || seen[key] {
			continue
		}
		seen[key] = true
		results = append(results, checkDiskMount(ctx, system, mount))
	}
	if len(results) == 0 {
		return []Result{unsupported(diskProbeCheck, T("disk.check.none"))}
	}
	return results
}

// executeDiskGrow는 rescan → 계획 → 확인 → 단계 실행 순서로 돈다. 단계마다 층을 다시 읽어 그 층이
// 실제로 늘었는지 본다. 같은 명령을 다시 실행하면 이미 늘어난 층은 계획에서 빠지므로 중간에 끊긴
// 실행을 이어 간다.
func executeDiskGrow(ctx context.Context, system diskSystem, input diskGrowInput) diskGrowOutcome {
	started := time.Now()
	fail := func(kind string, err error) diskGrowOutcome {
		return diskGrowOutcome{Result: resultFromError(diskProbeGrow, started, kind, err)}
	}
	mounts, err := system.mounts()
	if err != nil {
		return fail("disk", err)
	}
	mount, ok := findDiskMount(mounts, input.path)
	if !ok {
		return fail("disk", errors.New(T("disk.error.no_mount", input.path)))
	}
	chain, err := system.readChain(ctx, mount)
	if err != nil {
		return fail("disk", err)
	}
	// 디스크를 바꾸는 명령은 시간 제한으로 끊지 않는다. resize2fs를 죽여도 커널은 확장을 끝까지
	// 하므로, 끊으면 실제로는 늘어난 디스크를 실패로 보고한다. 시간 제한은 계획을 세우는 읽기에만 건다.
	changeCtx := context.WithoutCancel(ctx)
	var done []Evidence
	if chain.Disk.Rescan && !input.dryRun {
		if err := system.rescan(changeCtx, chain.Disk.Name); err != nil {
			return fail("rescan", fmt.Errorf("rescan %s: %w", chain.Disk.Name, err))
		}
		done = append(done, Evidence{Label: T("disk.evidence.done"), Value: "rescan " + chain.Disk.Name})
		if chain, err = system.readChain(changeCtx, mount); err != nil {
			return fail("disk", err)
		}

	// 장치가 여전히 커널보다 크다고 답하면 rescan이 듣지 않은 것이다. 옛 크기로 "다 씀"이라 말하지 않는다.
	if volume := chain.grownVolume(); volume > 0 {
		result := fail("rescan", errors.New(T("disk.grow.error.rescan_stale", chain.Disk.Name, formatBytes(chain.Disk.Size), formatBytes(volume))))
		result.Result.Evidence = append(done, diskEvidence(chain, nil)...)
		return result
	}
}
// 계획만 볼 때는 rescan하지 않으므로, 장치가 알려 준 크기로 rescan한 뒤의 계획을 보인다.
planned := chain
if input.dryRun {
	planned = chain.afterRescan()
}
steps, blocked := planDiskGrow(planned)
if blocked == "" {
	blocked = system.missingTool(steps)
}
if blocked != "" {
	result := fail("plan", errors.New(mount.Point+": "+blocked))
	result.Result.Evidence = diskEvidence(chain, nil)
	return result
}
if len(steps) == 0 {
	if chain.FSSizeErr != nil {
		return fail("disk", fmt.Errorf("%s: %w", mount.Point, chain.FSSizeErr))
	}
	return diskGrowOutcome{Result: finishDiskResult(Result{
		Probe: diskProbeGrow, Status: StatusPass, StartedAt: started.UTC(),
		Summary: T("disk.check.full", mount.Point, formatBytes(chain.FSSize)), Evidence: append(done, diskEvidence(chain, nil)...),
	}, started)}
}
if input.dryRun {
	from, to := diskGrowRange(steps)

// diskNotifySignals는 단계 중의 Ctrl+C와 종료 신호를 잡아 edc가 지금 단계를 끝낸 뒤 멈추게 한다.
// 단계 명령은 자기 프로세스 그룹에서 돌므로 터미널의 Ctrl+C를 받지 않는다.
func diskNotifySignals() (<-chan os.Signal, func()) {
	signals := make(chan os.Signal, 1)
	signal.Notify(signals, os.Interrupt, syscall.SIGTERM, syscall.SIGHUP)
	return signals, func() { signal.Stop(signals) }
}

// diskCommandMessage는 실패한 명령의 출력에서 마지막 의미 있는 줄을 고른다. resize2fs처럼 첫 줄에
// 버전을 쓰는 명령은 첫 줄로 이유를 알 수 없다. stderr가 비면 stdout을 본다. growpart는 이유를
// stdout에 쓴다.
func diskCommandMessage(stderr, stdout string) string {
	for _, output := range []string{stderr, stdout} {
		lines := strings.Split(strings.TrimSpace(output), "\n")
		for index := len(lines) - 1; index >= 0; index-- {
			if line := strings.TrimSpace(lines[index]); line != "" {
				return line
			}
		}
	}
	return ""
}

func runDisk(args []string, version string) int {
	usage := T("cli.usage", subcommandUsage("disk")+" ...")
	if len(args) == 0 {
		choice, ok := promptMissingSubcommand("disk")
		if !ok {
			fmt.Fprintln(os.Stderr, usage)
			return 2
		}
		args = []string{choice}
	}
	switch args[0] {
	case "check":
		return runDiskCheck(args[1:], version)
	case "grow":
		return runDiskGrow(args[1:], version)
	default:
		fmt.Fprintln(os.Stderr, usage)
		return 2
	}
}

func runDiskCheck(args []string, version string) int {
	options := configuredCommon(15 * time.Second)
	set := newFlagSet("disk check")
	set.SetOutput(os.Stderr)
	bindCommon(set, &options)
	if err := set.Parse(args); err != nil {
		return 2
	}
	if set.NArg() > 1 {
		fmt.Fprintln(os.Stderr, T("cli.usage", "edc disk check [mount]"))
		return 2
	}
	started := time.Now()
	ctx, cancel, deadline := probeContext(options.timeout)
	defer cancel()
	defer deadline()
	system, ok := newDiskSystem()
	if !ok {
		return emit(options, buildReport(version, started, nil, []Result{unsupported(diskProbeCheck, T("disk.skip.linux_only"))}, options.redact))
	}
	return emit(options, buildReport(version, started, nil, checkDiskMounts(ctx, system, set.Arg(0)), options.redact))
}

func runDiskGrow(args []string, version string) int {
	options := configuredCommon(5 * time.Minute)
	set := newFlagSet("disk grow")
	set.SetOutput(os.Stderr)
	bindCommon(set, &options)
	yes := set.Bool("yes", false, T("disk.flag.yes"))
	dryRun := set.Bool("dry-run", false, T("disk.flag.dry_run"))
	set.BoolVar(dryRun, "n", false, T("disk.flag.dry_run"))
	// `edc disk grow / -n`처럼 마운트 뒤에 온 flag도 받는다. flag 패키지는 첫 위치 인자에서 멈춘다.
	if err := parseReordered(set, args); err != nil {
		return 2
	}
	if set.NArg() != 1 {
		fmt.Fprintln(os.Stderr, T("cli.usage", "edc disk grow <mount> [-n] [--yes]"))
		return 2
	}
	// 내부에서 sudo를 붙이지 않는다. --dry-run은 읽기만 하므로 root 없이도 계획을 볼 수 있다.
	if os.Geteuid() != 0 && !*dryRun {
		fmt.Fprintln(os.Stderr, T("disk.grow.error.root_required"))
		return 3
	}
	started := time.Now()
	ctx, cancel, deadline := probeContext(options.timeout)
	defer cancel()
	defer deadline()
	system, ok := newDiskSystem()
	if !ok {
		return emit(options, buildReport(version, started, nil, []Result{unsupported(diskProbeGrow, T("disk.skip.linux_only"))}, options.redact))
	}
	input := diskGrowInput{path: set.Arg(0), dryRun: *dryRun, confirm: diskTerminalConfirm, notify: diskNotifySignals}
	if *yes {
		input.confirm = diskAutoConfirm

	}
	outcome := executeDiskGrow(ctx, system, input)
	if outcome.Cancelled {
		fmt.Fprintln(os.Stderr, T("disk.grow.cancelled"))
		return 4
	}
	return emit(options, buildReport(version, started, nil, []Result{outcome.Result}, options.redact))
}

// scsiCapacityFrom은 READ CAPACITY(16)을 묻고, 장치가 받지 않으면 (10)으로 다시 묻는다. 각 명령은 UNIT ATTENTION이면
// 한 번 더 보낸다. 둘 다 실패하면 (16)의 오류를 돌려준다.
func scsiCapacityFrom(read16, read10 func() (uint64, error)) (uint64, error) {
	size, err := scsiRetry(read16)
	if err == nil {
		return size, nil
	}
	if size, err10 := scsiRetry(read10); err10 == nil {
		return size, nil
	}
	return 0, err
}

// scsiCapacity는 SCSI 디스크에 지금 크기를 묻는다. 커널이 기억하는 크기(sysfs size)는 rescan 전까지 옛 값이라,
// 클라우드 콘솔에서 늘린 볼륨은 장치에 직접 물어야 보인다. rescan과 달리 커널 상태를 바꾸지 않는다.
func scsiCapacity(disk string) (uint64, error) {
	file, err := os.OpenFile("/dev/"+disk, os.O_RDONLY|unix.O_NONBLOCK, 0)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	read := func(command []byte, length int, parse func([]byte) (uint64, error)) func() (uint64, error) {
		return func() (uint64, error) {
			data := make([]byte, length)
			if err := scsiCommand(file, command, data); err != nil {
				return 0, fmt.Errorf("%s: %w", file.Name(), err)
			}
			return parse(data)
		}
	}
	return scsiCapacityFrom(
		read(scsiReadCapacity16Command(), scsiReadCapacity16Length, parseReadCapacity16),
		read(scsiReadCapacity10Command(), scsiReadCapacity10Length, parseReadCapacity10),
	)
}

// xfsIocFSGeometryV1은 _IOR('X', 100, struct xfs_fsop_geom_v1)이다. 구조체는 112 바이트다.
// v1은 오래된 커널부터 지금 커널까지 모두 받는다.
const (
	xfsIocFSGeometryV1  = 0x80705864
	xfsGeometryV1Length = 112
)

// diskCommand는 stdout만 돌려준다. lvs와 pvs는 경고를 stderr에 쓰므로 섞으면 JSON이 깨진다.
// 명령은 자기 프로세스 그룹에서 돈다. 터미널의 Ctrl+C가 resize2fs 같은 단계를 중간에 죽이지 않는다.
func diskCommand(ctx context.Context, name string, args ...string) (string, error) {
	command := exec.CommandContext(ctx, name, args...)
	command.Env = append(os.Environ(), "LC_ALL=C", "LVM_SUPPRESS_FD_WARNINGS=1")
	command.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	var stdout, stderr bytes.Buffer
	command.Stdout, command.Stderr = &stdout, &stderr
	if err := command.Run(); err != nil {
		if message := diskCommandMessage(stderr.String(), stdout.String()); message != "" {
			return stdout.String(), fmt.Errorf("%w: %s", err, message)
		}
		return stdout.String(), err
	}
	return stdout.String(), nil
}

// xfsDataSize는 마운트된 xfs의 데이터 영역 크기를 커널에 묻는다. xfs는 자체 버퍼 캐시를 쓰므로
// 디바이스의 슈퍼블록은 늘린 직후에도 옛 값일 수 있다.
func xfsDataSize(mount string) (uint64, error) {
	file, err := os.Open(mount)
	if err != nil {
		return 0, err
	}
	defer file.Close()
	var geometry [xfsGeometryV1Length]byte
	if _, _, errno := unix.Syscall(unix.SYS_IOCTL, file.Fd(), xfsIocFSGeometryV1, uintptr(unsafe.Pointer(&geometry[0]))); errno != 0 {
		return 0, fmt.Errorf("XFS_IOC_FSGEOMETRY_V1 %s: %w", mount, errno)
	}
	blockSize := binary.NativeEndian.Uint32(geometry[0:4])
	dataBlocks := binary.NativeEndian.Uint64(geometry[32:40])
	return uint64(blockSize) * dataBlocks, nil
}

// EDC_SCSI_DISK=sda처럼 SCSI 디스크를 주면 READ CAPACITY 답을 커널의 크기와 비교한다. 파싱이 틀리면 늘어난 볼륨을
// 못 보고도 같은 크기라고 판단하므로, 실제 장치에서 한 번 맞춰 본다. rescan하지 않으므로 커널 크기가 옛 값이면 다를 수 있다.
func TestSCSICapacityMatchesTheKernelSize(t *testing.T) {
	disk := os.Getenv("EDC_SCSI_DISK")
	if disk == "" {
		t.Skip("set EDC_SCSI_DISK to a SCSI disk to compare READ CAPACITY with sysfs")
	}
	size, err := scsiCapacity(disk)
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile("/sys/block/" + disk + "/size")
	if err != nil {
		t.Fatal(err)
	}
	sectors, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("READ CAPACITY %d bytes, sysfs %d bytes", size, sectors*diskSectorSize)
	if size != sectors*diskSectorSize {
		t.Fatalf("READ CAPACITY %d, sysfs %d", size, sectors*diskSectorSize)
	}
}

func (system diskSystem) readUint(path string) (uint64, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	return strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
}

// blockAt은 sysfs의 디바이스 디렉터리 하나를 읽는다. size와 start는 디바이스의 섹터 크기와 관계없이
// 늘 512 바이트 단위다.
func (system diskSystem) blockAt(dir string) (diskBlock, error) {
	block := diskBlock{Name: filepath.Base(dir), dir: dir}
	sectors, err := system.readUint(filepath.Join(dir, "size"))
	if err != nil {
		return diskBlock{}, err
	}
	block.Size = sectors * diskSectorSize
	if number, err := system.readUint(filepath.Join(dir, "partition")); err == nil {
		start, err := system.readUint(filepath.Join(dir, "start"))
		if err != nil {
			return diskBlock{}, err
		}
		block.Partition, block.Start = int(number), start*diskSectorSize
		block.Parent = filepath.Base(filepath.Dir(dir))
	}
	if data, err := os.ReadFile(filepath.Join(dir, "dm", "name")); err == nil {
		block.DMName = strings.TrimSpace(string(data))
	}
	if data, err := os.ReadFile(filepath.Join(dir, "dm", "uuid")); err == nil {
		block.DMUUID = strings.TrimSpace(string(data))
	}
	if entries, err := os.ReadDir(filepath.Join(dir, "slaves")); err == nil {
		for _, entry := range entries {
			block.Slaves = append(block.Slaves, entry.Name())
		}
	}
	if _, err := os.Stat(filepath.Join(dir, "device", "rescan")); err == nil && block.Partition == 0 {
		block.Rescan = true
	}
	return block, nil

// partitionTable은 디스크 앞 1 KiB에서 GPT 헤더나 MBR 서명을 찾는다. 읽지 못하면 빈 문자열이다.
func (system diskSystem) partitionTable(disk string) string {
	file, err := os.Open(system.path("dev", disk))
	if err != nil {
		return ""
	}
	defer file.Close()
	head := make([]byte, 2*diskSectorSize)
	if _, err := file.ReadAt(head, 0); err != nil {
		return ""
	}
	if string(head[diskSectorSize:diskSectorSize+8]) == "EFI PART" {
		return "gpt"
	}
	if head[510] == 0x55 && head[511] == 0xAA {
		return "dos"
	}
	return ""
}

func (system diskSystem) fsSize(mount diskMount, device string) (uint64, error) {
	if mount.FSType == "xfs" {
		return system.xfsSize(mount.Point)
	}
	file, err := os.Open(system.path("dev", device))
	if err != nil {
		return 0, err
	}
	defer file.Close()
	superblock := make([]byte, 1024)
	if _, err := file.ReadAt(superblock, 1024); err != nil {
		return 0, err
	}
	return ext4SuperblockSize(superblock)
}

func (system diskSystem) mounts() ([]diskMount, error) {
	data, err := os.ReadFile(system.path("proc/self/mountinfo"))
	if err != nil {
		return nil, err
	}
	return parseMountInfo(string(data)), nil
}

