	host.ext4("sdb1", 10*gib)
	host.mountinfo(`40 1 8:17 / /mnt\040data rw - ext4 /dev/sdb1 rw`)
	results := checkDiskMounts(context.Background(), host.system(), "/mnt data")
	if len(results) != 1 || results[0].Next != "edc disk grow '/mnt data'" {
		t.Fatalf("results = %#v", results)
	}
	var plain, colored strings.Builder
	printTerminalWithColor(&plain, results, false, false)
	printTerminalWithColor(&colored, results, false, true)
	if !strings.Contains(plain.String(), "\n      next: edc disk grow '/mnt data'\n") {
		t.Fatalf("plain = %q", plain.String())
	}
	if !strings.Contains(colored.String(), richExpect("next:\033[0m \033[1;36medc disk grow '/mnt data'\033[0m")) {
		t.Fatalf("colored = %q", colored.String())
	}
}

func (flags *resolverFlags) Set(value string) error {
	address := value
	if host, _, err := net.SplitHostPort(value); err == nil {
		address = host
	}
	if net.ParseIP(address) == nil {
		return fmt.Errorf("%s", T("observe.dns_compare.resolver_ip", value))
	}
	*flags = append(*flags, value)
	return nil
}

func runDNSCompare(args []string, version string) int {
	options := configuredCommon(15 * time.Second)
	set := newFlagSet("dns compare")
	set.SetOutput(os.Stderr)
	bindCommon(set, &options)
	var resolvers resolverFlags
	set.Var(&resolvers, "resolver", T("command.dns.option.resolver"))
	if err := set.Parse(args); err != nil {
		return 2
	}
	if set.NArg() != 1 {
		fmt.Fprintln(os.Stderr, T("cli.usage", "edc dns compare [--resolver IP[:port]] [options] <host>"))
		return 2
	}
	if len(resolvers) == 0 {
		resolvers = resolverFlags{"1.1.1.1"}
	}
	started := time.Now()
	ctx, cancel := context.WithTimeout(context.Background(), options.timeout)
	defer cancel()
	result := probeDNSCompare(ctx, set.Arg(0), resolvers)
	return emit(options, buildReport(version, started, map[string]interface{}{"host": set.Arg(0), "resolvers": []string(resolvers)}, []Result{result}, options.redact))
}

func probeDNSCompare(ctx context.Context, host string, resolvers []string) Result {
	started := time.Now()
	rows := make([]dnsCompareRow, len(resolvers)+1)
	var workers sync.WaitGroup
	workers.Add(len(rows))
	go func() {
		defer workers.Done()
		rows[0] = systemDNSRow(ctx, host)
	}()
	for index, resolver := range resolvers {
		go func() {
			defer workers.Done()
			rows[index+1] = directDNSRow(ctx, host, resolver)
		}()
	}
	workers.Wait()
	matched := true
	for _, row := range rows[1:] {
		if dnsRowSignature(row) != dnsRowSignature(rows[0]) {
			matched = false
		}
	}
	status := StatusPass
	if rows[0].Status != "ok" {
		status = StatusFail
	} else if !matched {
		status = StatusWarn
	}
	summary := T("observe.dns_compare.summary", len(rows), matched)
	result := Result{Probe: "dns.compare", Status: status, StartedAt: started.UTC(), DurationMS: time.Since(started).Milliseconds(), Summary: summary,
		Metrics: map[string]interface{}{"rows": rows, "matched": matched}, Evidence: []Evidence{{Label: T("observe.dns_compare.details"), Value: dnsCompareTable(rows)}}}
	if status == StatusFail {

		result.Error = &DiagnosticError{Kind: "dns", Message: rows[0].Error}
		if result.Error.Message == "" {
			result.Error.Message = rows[0].Status
		}
	}
	return result
}

func systemDNSRow(ctx context.Context, host string) dnsCompareRow {
	row := dnsCompareRow{Resolver: "system", IPv4: []string{}, IPv6: []string{}, Status: "ok"}
	addresses, err := net.DefaultResolver.LookupIPAddr(ctx, host)
	if err != nil {
		row.Status, row.Error = dnsLookupError(err)
		return row
	}
	for _, address := range addresses {
		if address.IP.To4() != nil {
			row.IPv4 = append(row.IPv4, address.IP.String())
		} else {
			row.IPv6 = append(row.IPv6, address.IP.String())
		}
	}
	row.CNAME, _ = net.DefaultResolver.LookupCNAME(ctx, host)
	row.CNAME = normalizeCNAME(row.CNAME, host)
	sort.Strings(row.IPv4)
	sort.Strings(row.IPv6)
	return row
}

func directDNSRow(ctx context.Context, host, resolver string) dnsCompareRow {
	row := dnsCompareRow{Resolver: resolver, IPv4: []string{}, IPv6: []string{}, Status: "ok"}
	address := resolver
	if _, _, err := net.SplitHostPort(resolver); err != nil {
		address = net.JoinHostPort(resolver, "53")
	}
	for _, recordType := range []uint16{dns.TypeA, dns.TypeAAAA} {
		message := new(dns.Msg)
		message.SetQuestion(dns.Fqdn(host), recordType)
		message.SetEdns0(1232, false)
		client := &dns.Client{Net: "udp", Timeout: 3 * time.Second}
		response, _, err := client.ExchangeContext(ctx, message, address)
		if err != nil {
			row.Status, row.Error = dnsLookupError(err)
			return row
		}
		if response.Truncated {
			client.Net = "tcp"
			response, _, err = client.ExchangeContext(ctx, message, address)
			if err != nil {
				row.Status, row.Error = dnsLookupError(err)
				return row
			}
		}
		if response.Rcode != dns.RcodeSuccess {
			row.Status = dns.RcodeToString[response.Rcode]
			row.Error = row.Status
			return row
		}
		readDNSAnswers(&row, response, host)
	}
	sort.Strings(row.IPv4)

	sort.Strings(row.IPv6)
	return row
}

func readDNSAnswers(row *dnsCompareRow, response *dns.Msg, host string) {
	for _, answer := range response.Answer {
		switch record := answer.(type) {
		case *dns.A:
			row.IPv4 = append(row.IPv4, record.A.String())
		case *dns.AAAA:
			row.IPv6 = append(row.IPv6, record.AAAA.String())
		case *dns.CNAME:
			row.CNAME = normalizeCNAME(record.Target, host)
		}
		ttl := answer.Header().Ttl
		if row.TTLSeconds == nil || ttl < *row.TTLSeconds {
			row.TTLSeconds = &ttl
		}
	}
}

func dnsLookupError(err error) (string, string) {
	var dnsError *net.DNSError
	if errors.As(err, &dnsError) && dnsError.IsNotFound {
		return "NXDOMAIN", err.Error()
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return "timeout", err.Error()
	}
	return "error", err.Error()
}

func normalizeCNAME(cname, host string) string {
	if strings.EqualFold(strings.TrimSuffix(cname, "."), strings.TrimSuffix(host, ".")) {
		return ""
	}
	return strings.TrimSuffix(strings.ToLower(cname), ".")
}

func dnsRowSignature(row dnsCompareRow) string {
	return row.Status + "|" + strings.Join(row.IPv4, ",") + "|" + strings.Join(row.IPv6, ",") + "|" + row.CNAME
}

func dnsCompareTable(rows []dnsCompareRow) string {
	var table strings.Builder
	for _, row := range rows {
		ttl := "—"
		if row.TTLSeconds != nil {
			ttl = fmt.Sprintf("%ds", *row.TTLSeconds)
		}
		fmt.Fprintf(&table, "%s  %s  TTL %s\n", row.Resolver, row.Status, ttl)
		fmt.Fprintf(&table, "  A %s\n  AAAA %s\n", strings.Join(row.IPv4, ", "), strings.Join(row.IPv6, ", "))
		if row.CNAME != "" {
			fmt.Fprintf(&table, "  CNAME %s\n", row.CNAME)
		}
		if row.Error != "" && row.Status != "NXDOMAIN" {
			fmt.Fprintf(&table, "  %s\n", firstLine(row.Error))
		}
	}
	return strings.TrimRight(table.String(), "\n")
}

func probeAllIPsWithOptions(ctx context.Context, dns Result, host, port, rawURL string, options endpointOptions) Result {
	started := time.Now()
	if options.ownerLookup == nil {
		options.ownerLookup = newEndpointOwnerResolver(ripeStatURL).lookup
	}
	if dns.Status != StatusPass {
		return unsupported(endpointProbeID, T("observe.probe.endpoints_dns_failed"))
	}
	addresses, ok := dns.Metrics["addresses"].([]string)
	if !ok || len(addresses) == 0 {
		return unsupported(endpointProbeID, T("observe.probe.endpoints_empty"))
	}
	checks := make([]endpointCheck, len(addresses))
	jobs := make(chan int)
	var workers sync.WaitGroup
	for range min(len(addresses), endpointConcurrency) {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for index := range jobs {
				checks[index] = checkEndpoint(ctx, addresses[index], host, port, rawURL, options)
			}
		}()
	}
	for index := range addresses {
		select {
		case jobs <- index:
		case <-ctx.Done():
			for skipped := index; skipped < len(addresses); skipped++ {
				checks[skipped] = endpointCheck{IP: addresses[skipped], TCP: StatusSkip, TLS: StatusSkip, HTTP: StatusSkip, Detail: ctx.Err().Error()}
			}
			close(jobs)

func checkEndpoint(ctx context.Context, ip, host, port, rawURL string, options endpointOptions) (check endpointCheck) {
	address := net.JoinHostPort(ip, port)
	check = endpointCheck{IP: ip, TLS: StatusSkip, HTTP: StatusSkip}
	defer func() { check.Network = options.ownerLookup(ctx, ip) }()
	tcp := probeTCP(ctx, address)
	check.TCP = tcp.Status
	if value, ok := tcp.Metrics["connect_ms"].(int64); ok {
		check.ConnectMS = value
	}
	if tcp.Status == StatusFail {
		check.Detail = firstLine(tcp.Summary)
		return check
	}
	if strings.HasPrefix(rawURL, "https://") {
		tls := probeTLSWithOptions(ctx, address, host, tlsCheckOptions{rootCAs: options.rootCAs})
		check.TLS = tls.Status
		if value, ok := tls.Metrics["version"].(string); ok {
			check.TLSVersion = value
		}
		if tls.Status == StatusFail {
			check.Detail = firstLine(tls.Summary)
			return check
		}
	}
	http := probeHTTPWithOptions(ctx, rawURL, httpCheckOptions{dialAddress: address, noRedirect: true, rootCAs: options.rootCAs, headersOnly: true})
	check.HTTP = http.Status
	if value, ok := http.Metrics["status_code"].(int); ok {
		check.HTTPCode = value
	}
	if http.Status == StatusFail {
		check.Detail = firstLine(http.Summary)
	}

func endpointStatus(check endpointCheck) Status {
	if check.TCP == StatusFail || check.TLS == StatusFail || check.HTTP == StatusFail {
		return StatusFail
	}
	if check.TCP == StatusSkip {
		return StatusSkip
	}
	if check.TCP == StatusWarn || check.TLS == StatusWarn || check.HTTP == StatusWarn {
		return StatusWarn
	}
	return StatusPass
}

func endpointTable(checks []endpointCheck) string {
	var table strings.Builder
	table.WriteString("IP                               TCP       TLS       HTTP  ASN       OWNER / DETAIL\n")
	for _, check := range checks {
		tcp := strings.ToUpper(string(check.TCP))
		if check.TCP == StatusPass || check.TCP == StatusWarn {
			tcp = fmt.Sprintf("%dms", check.ConnectMS)
		}
		tls := strings.ToUpper(string(check.TLS))
		if check.TLSVersion != "" {
			tls = check.TLSVersion
		}
		http := strings.ToUpper(string(check.HTTP))
		if check.HTTPCode != 0 {
			http = fmt.Sprint(check.HTTPCode)
		}
		asns := make([]string, 0, len(check.Network.ASNs))
		for _, asn := range check.Network.ASNs {
			asns = append(asns, "AS"+asn)
		}
		owner := endpointOwnerLabel(check.Network)
		if check.Detail != "" {
			owner += " · " + check.Detail
		}
		fmt.Fprintf(&table, "%-32s %-9s %-9s %-5s %-9s %s\n", check.IP, tcp, tls, http, strings.Join(asns, ","), owner)
	}
	table.WriteString(T("observe.probe.owner_source") + "\n")
	table.WriteString(T("observe.probe.lb_unknown"))
	return strings.TrimRight(table.String(), "\n")
}

func printDoctorGuidance(writer io.Writer, report Report, color bool) {
	style := newTextStyle(color)
	stages := []struct{ probe, command string }{
		{"dns.lookup", "edc dns lookup 'HOST'"},
		{"tcp.check", "edc tcp check 'HOST:PORT'"},
		{"tls.check", "edc tls check 'HOST:PORT'"},
		{"http.check", "edc http check 'URL'"},
	}
	heading := false
	for _, stage := range stages {
		for _, result := range report.Results {
			if result.Probe != stage.probe || (result.Status != StatusFail && result.Status != StatusWarn) {
				continue
			}
			if !heading {
				fmt.Fprintln(writer)
				style.line(writer, style.heading(T("observe.doctor.guidance_heading")))
				style.line(writer, style.dim(T("observe.doctor.guidance_manual")))
				heading = true
			}
			kind := ""
			if result.Error != nil && result.Error.Kind != "" {
				kind = " · " + doctorGuidanceExcerpt(result.Error.Kind)
			}
			excerpt := result.Summary
			if len(result.Evidence) > 0 {
				evidence := result.Evidence[0]
				excerpt += " · " + evidence.Label + ": " + evidence.Value
			}
			style.line(writer, doctorGuidanceStage(style, stage.probe, result.Status, kind))
			fmt.Fprintln(writer, doctorGuidanceEvidence(style, doctorGuidanceExcerpt(excerpt)))
			style.line(writer, "  "+style.command(stage.command))

func printDoctorTail(writer io.Writer, report Report, verbose, color bool) {
	printResultTail(writer, report.Results, verbose, color)
	printDoctorGuidance(writer, report, color)
}

func TestDoctorGuidanceObservedStages(t *testing.T) {
	for _, tc := range []struct {
		name     string
		results  []Result
		commands []string
	}{
		{"mixed", []Result{{Probe: "http.check", Status: StatusFail, Summary: "http"}, {Probe: "dns.lookup", Status: StatusFail, Summary: "dns"}, {Probe: "tcp.check", Status: StatusPass}, {Probe: "tls.check", Status: StatusWarn, Summary: "expiry"}}, []string{"edc dns", "edc tls", "edc http"}},
		{"timeout", []Result{{Probe: "tcp.check", Status: StatusFail, Error: &DiagnosticError{Kind: "timeout"}, Summary: "deadline exceeded"}}, []string{"edc tcp"}},
		{"cancelled", []Result{{Probe: "dns.lookup", Status: StatusFail, Error: &DiagnosticError{Kind: "cancelled"}, Summary: "cancelled"}}, []string{"edc dns"}},
		{"http skip", []Result{{Probe: "tls.check", Status: StatusSkip}, {Probe: "http.check", Status: StatusPass}}, nil},
		{"extra", []Result{{Probe: "net.quality", Status: StatusFail}, {Probe: "endpoints.check", Status: StatusWarn}}, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			report := Report{Results: tc.results, Summary: summarize(tc.results)}
			before, _ := json.Marshal(report)
			var out bytes.Buffer
			printDoctorGuidance(&out, report, false)
			after, _ := json.Marshal(report)
			if !bytes.Equal(before, after) {
				t.Fatal("report mutated")
			}
			if len(tc.commands) == 0 && out.Len() != 0 {
				t.Fatalf("unexpected guidance: %s", out.String())
			}
			previous := -1
			for _, command := range tc.commands {
				index := strings.Index(out.String(), command)
				if index <= previous {
					t.Fatalf("missing or unordered %s: %s", command, out.String())
				}
				previous = index
			}

func TestDoctorCompletionGuidanceAndJSON(t *testing.T) {
	report := buildReport("fixture", time.Now(), map[string]interface{}{"input": "192.0.2.10;secret"}, []Result{
		{Probe: "dns.lookup", Status: StatusFail, Summary: "lookup 192.0.2.10\nfailed", Evidence: []Evidence{{Label: "address", Value: "2001:db8::1"}}},
		{Probe: "net.quality", Status: StatusSkip}, {Probe: "endpoints.check", Status: StatusWarn},
	}, true)
	before, _ := json.Marshal(report)
	var guidance, tail bytes.Buffer
	printDoctorGuidance(&guidance, report, false)
	printDoctorTail(&tail, report, false, false)
	var code int
	plain := traceCaptureOutput(t, &os.Stdout, func() { code = emitDoctor(commonOptions{}, report) })
	if code != 1 || !strings.HasSuffix(plain, guidance.String()) || !strings.HasSuffix(tail.String(), guidance.String()) {
		t.Fatalf("completion mismatch: code=%d plain=%q tail=%q", code, plain, tail.String())
	}
	if strings.Contains(guidance.String(), "192.0.2.10") || strings.Contains(guidance.String(), "2001:db8::1") || strings.Contains(guidance.String(), "secret") {
		t.Fatalf("guidance leaked target: %s", guidance.String())
	}
	for _, path := range []string{"-", filepath.Join(t.TempDir(), "report.json")} {
		output := traceCaptureOutput(t, &os.Stdout, func() { code = emitDoctor(commonOptions{jsonPath: path}, report) })
		if code != 1 {
			t.Fatalf("JSON exit=%d", code)
		}
		if path != "-" {
			if output != "" {
				t.Fatalf("JSON file stdout=%q", output)
			}
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			output = string(data)
		}

		var got Report
		if err := json.Unmarshal([]byte(output), &got); err != nil {
			t.Fatalf("JSON invalid: %v: %q", err, output)
		}
		marshaled, _ := json.Marshal(got)
		if !bytes.Equal(before, marshaled) {
			t.Fatalf("JSON report changed: %s", marshaled)
		}
	}
	after, _ := json.Marshal(report)
	if !bytes.Equal(before, after) {
		t.Fatal("completion mutated report")
	}
}

const (
	duProbeID = "du.scan"
	// 캐시가 빈 회전 디스크에서는 큰 트리를 읽는 데 오래 걸린다. 시간이 다 되면 그때까지 센 값을 partial로 보인다.
	duDefaultTimeout = 60 * time.Second
	duPipedRows      = 20
	// duMountRows는 터미널에 보이는 건너뛴 마운트 수다. container가 많은 호스트는 overlay 마운트가 수십 개다.
	duMountRows = 10
	// duUnreadableKeep은 읽지 못한 경로를 담는 상한이다. 개수는 모두 센다.
	duUnreadableKeep = 1000
	// duLargestDirs는 report diff가 두 시점을 맞춰 보도록 JSON에 남기는 큰 디렉터리 수다. 화면용 rows는 고른
	// 줄이라 두 시점의 줄이 서로 맞지 않는다.
	duLargestDirs = 200
	// duDiffDirs는 report diff가 보여 주는 디렉터리 변화 수다.
	duDiffDirs = 10
	// duBrowseFiles는 탐색 화면을 열 때 남기는 큰 파일 수다. 화면은 디렉터리마다 그 안의 큰 파일을 보여야 하므로
	// 출력 줄 수보다 많이 남긴다. 나머지 파일은 디렉터리마다 한 줄로 합친다.
	duBrowseFiles = 10000
)

type duOptions struct {
	root        string
	workers     int
	rows        int
	crossMounts bool
	// keepFiles는 남길 큰 파일 수다. rows보다 작으면 rows를 쓴다.
	keepFiles int
	// progress는 읽은 디렉터리 수를 탐색 중에 바깥에서 읽게 한다. nil이면 탐색기가 따로 센다.
	progress *atomic.Int64
	// activity는 끝난 시스템 호출 수다. 값이 오래 그대로면 호출 하나가 커널 안에서 돌아오지 않는 것이다.
	activity *atomic.Int64
}

// duNode는 디렉터리 하나, 또는 화면에 오를 수 있는 큰 파일 하나다. bytes와 entries는 자기 자신과
// children으로 따로 두지 않은 파일의 합이다. total과 count는 탐색이 끝난 뒤 하위 전체를 더한 값이다.
type duNode struct {
	name     string
	parent   *duNode
	dir      bool
	bytes    uint64
	entries  int64
	children []*duNode
	total    uint64
	count    int64
	// own은 디렉터리 자신의 block이다. bytes에서 빼면 children으로 따로 두지 않은 파일의 합이 남는다.
	own        uint64
	unreadable bool
	// base는 탐색이 끝났을 때의 total이다. 화면이 다시 읽은 뒤 늘어난 양을 보인다. known은 탐색 때 있던 항목이다.
	base  uint64
	known bool
}

type duMount struct {
	Path      string `json:"path"`
	FSType    string `json:"fstype"`
	UsedBytes uint64 `json:"used_bytes,omitempty"`
	// Shared는 statfs가 이 마운트가 아니라 밑에 있는 파일 시스템 전체를 답하는 경우다. bind mount와 overlay가 그렇다.
	// 그 값을 마운트의 크기처럼 보이면 같은 숫자가 마운트마다 되풀이된다.
	Shared bool `json:"shared,omitempty"`
	// Label은 이 경로를 쓰는 container다. docker가 있을 때만 붙는다.
	Label string `json:"label,omitempty"`
}

type duScan struct {
	root            *duNode
	directories     int64
	mounts          []duMount
	unreadable      []string
	unreadableCount int64
	partial         bool
	warnings        []string
	filesystem      duFilesystem
	deleted         duDeletedOpen
	// deletedChecked는 지워졌지만 열린 파일을 찾았다는 뜻이다. Linux는 경로의 파일 시스템을 찾았을 때만 찾고, macOS는
	// 찾지 않는다. 찾지 않았으면 JSON에서 deleted_open을 빼서 0건과 구분한다.
	deletedChecked bool
	// notFound는 filesystem.Whole일 때만 뜻이 있다. df의 사용량에서 센 크기와 지워졌지만 열린 파일을 뺀 값이다.
	notFound uint64
	// labels는 절대 경로마다 그 경로를 쓰는 container다. docker가 없으면 비어 있다.
	labels map[string]string
	// elapsed는 탐색에 걸린 시간이다. 화면을 닫은 뒤 결과를 만들므로 화면을 본 시간을 넣지 않으려고 따로 잰다.
	elapsed time.Duration
	// walker는 탐색을 마친 탐색기다. 화면이 디렉터리를 다시 읽을 때 hard link 기록과 마운트 경계를 그대로 쓴다.
	walker *duWalker
}

// duFilesystem은 경로가 속한 파일 시스템이다. 크기와 사용량은 df와 같이 statfs에서 읽는다.
type duFilesystem struct {
	Mount  string `json:"mount"`
	FSType string `json:"fstype"`
	// Source와 Root는 mountinfo의 장치와, 그 장치에서 이 마운트에 붙인 디렉터리다. Root가 /가 아니면 bind mount라
	// 크기와 사용량이 마운트가 아니라 장치 전체의 값이다.
	Source    string `json:"source"`
	Root      string `json:"root"`
	SizeBytes uint64 `json:"size_bytes"`
	UsedBytes uint64 `json:"used_bytes"`
	// Whole은 경로가 파일 시스템의 root를 붙인 마운트 지점이고 모두 읽었다는 뜻이다. 그때만 사용량과 센 크기의
	// 차이가 "찾지 못한 공간"이 된다. 하위 디렉터리나 bind mount를 재면 차이는 당연히 크다.
	Whole bool `json:"whole"`
}

// duDeletedOpen은 같은 파일 시스템에서 지워졌지만 process가 아직 열고 있는 파일이다. 경로 아래만이 아니라
// 파일 시스템 전체의 값이다. Partial이면 다른 사용자의 process를 읽지 못해 값이 하한이다.
type duDeletedOpen struct {
	Bytes   uint64          `json:"bytes"`
	Files   uint64          `json:"files"`
	Partial bool            `json:"partial"`
	Top     []duDeletedFile `json:"top,omitempty"`
}

type duDeletedFile struct {
	Path  string `json:"path"`
	Bytes uint64 `json:"bytes"`
	PID   int    `json:"pid"`
	Comm  string `json:"comm"`
}

type duOther struct {
	Bytes   uint64 `json:"bytes"`
	Entries int64  `json:"entries"`
}

// duSources는 탐색이 읽는 호스트 원천이다. 테스트는 마운트 표를 가짜로 넣어 실제 마운트를 만들지 않는다.
type duSources struct {
	mountinfo func() (string, error)
	statfs    func(path string) (duUsage, bool)
	// deletedOpen의 bool은 다른 사용자의 process를 읽지 못해 값이 하한이라는 뜻이다.
	deletedOpen func() (map[uint64]*deletedOpenSummary, bool)
	// containerLabels는 docker 저장 경로의 이름표다. nil이면 이름표를 붙이지 않는다.
	containerLabels func(ctx context.Context) map[string]string
}

func runDu(args []string, version string) int {
	sources, ok := hostDuSources()
	return runDuWith(args, version, sources, ok, os.Stdout)
}

target := map[string]interface{}{"path": path}
if !ok {
	return emit(options, buildReport(version, started, target, []Result{unsupported(duProbeID, T("du.skip.unsupported"))}, options.redact))
}
terminal := options.jsonPath == "" && isTerminal(stdout)
// svc, ctr과 같이 사람이 보는 터미널에서만 화면을 연다. pipe, --json, NO_COLOR는 그대로 출력한다.
live := terminal && liveTerminal()
browse := live && !*noBrowse
// 출력 모드의 결과는 한 시점의 값이어야 한다. 받고 무시하면 켠 줄 알고 기다리게 된다.
if refresh.explicit && !browse {
	fmt.Fprintln(os.Stderr, T("du.error.refresh_needs_browse"))
	return 2
}
scanOptions := duOptions{workers: *workers, rows: *rows, crossMounts: *crossMounts}
if scanOptions.rows == 0 {
	scanOptions.rows = duDefaultRows(stdout, terminal)
}
if browse {
	scanOptions.keepFiles = duBrowseFiles
}
ctx, cancel, deadline := probeContext(options.timeout)
defer cancel()
defer deadline()
result := Result{Probe: duProbeID, StartedAt: started.UTC()}
// 넘긴 경로가 symlink면 링크 자체가 아니라 가리키는 디렉터리를 잰다. 링크 하나의 크기는 쓸모가 없다.
scanOptions.root, err = duResolveRoot(path)
var scan duScan
if err == nil && live {
	scan, err = duBrowse(ctx, cancel, scanOptions, sources, started, *noBrowse, refresh)
} else if err == nil {
	scan, err = duWalk(ctx, scanOptions, sources)
}

	if err != nil {
		result = duPathFailure(result, path, err)
	} else {
		// 화면에서 q로 멈추면 base context가 취소된다. 시간 초과와 구분해 다음 명령을 권하지 않는다.
		stopped := scan.partial && errors.Is(ctx.Err(), context.Canceled)
		result = duResult(result, scanOptions, scan, options.timeout, stopped)
	}
	result.DurationMS = time.Since(started).Milliseconds()
	if options.jsonPath != "" {
		return emit(options, buildReport(version, started, target, []Result{result}, options.redact))
	}
	// pipe로 넘기는 출력은 자르지 않는다. 받는 쪽이 경로 전체를 읽어야 한다.
	width := 0
	if terminal {
		width = terminalWidth()
	}
	return duPrint(stdout, options, result, terminal && os.Getenv("NO_COLOR") == "", live && *noBrowse, width)
}

func duResolveRoot(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(absolute)
}

// duDefaultRows는 결과 줄, 나머지 줄, 건너뛴 마운트 몇 줄, 파일 시스템 줄이 화면에 함께 들어가게 남긴다.
func duDefaultRows(stdout *os.File, terminal bool) int {
	if !terminal {
		return duPipedRows
	}
	_, height, err := term.GetSize(int(stdout.Fd()))
	if err != nil || height <= 0 {
		return duPipedRows
	}
	return max(5, height-12)
}

func duResult(result Result, options duOptions, scan duScan, timeout time.Duration, stopped bool) Result {
	root := scan.root
	rows, other := duSelect(root, options.rows)
	elapsed := scan.elapsed.Round(time.Millisecond)
	result.Status = StatusPass
	result.Summary = T("du.summary", formatSizeShort(root.total), options.root, root.count, elapsed, options.workers)
	result.Warnings = append(result.Warnings, scan.warnings...)
	if scan.partial && stopped {
		result.Status = StatusWarn
		result.Summary = T("du.summary_stopped", formatSizeShort(root.total), options.root, root.count)
		result.Warnings = append(result.Warnings, T("du.warning.stopped"))
	} else if scan.partial {
		result.Status = StatusWarn
		result.Summary = T("du.summary_partial", formatSizeShort(root.total), options.root, root.count, timeout)
		result.Warnings = append(result.Warnings, T("du.warning.partial"))
		next := 4 * timeout
		if next < duDefaultTimeout {
			next = duDefaultTimeout
		}
		result.Next = fmt.Sprintf("edc du --timeout %s %s", next, quoteLocalShellWord(options.root))
	}
	if scan.unreadableCount > 0 {
		result.Status = StatusWarn
		if os.Geteuid() != 0 {
			result.Warnings = append(result.Warnings, T("du.warning.unreadable_root", scan.unreadableCount))
		} else {
			result.Warnings = append(result.Warnings, T("du.warning.unreadable", scan.unreadableCount))
		}
		result.Evidence = append(result.Evidence, Evidence{Label: T("du.evidence.unreadable"), Value: strings.Join(scan.unreadable, "\n")})
	}
	// info.disk와 snapshot과 같은 기준이다. 읽지 못한 fd가 있어 하한이어도 그것만으로는 warn하지 않는다.
	// root가 아니면 늘 하한이라 모든 실행이 warn이 된다.

	filesystem, deleted := scan.filesystem, scan.deleted
	if filesystem.SizeBytes > 0 && len(deleted.Top) > 0 && deleted.Bytes*100 >= filesystem.SizeBytes*infoDeletedOpenWarnPercent {
		result.Status = StatusWarn
		top := deleted.Top[0]
		result.Warnings = append(result.Warnings, T("du.warning.deleted_open", formatSizeShort(deleted.Bytes), filesystem.Mount, top.Comm, top.PID))
	}
	largest := duLargest(root, duLargestDirs)
	if len(scan.labels) > 0 {
		for index := range rows {
			rows[index].Label = scan.labels[filepath.Join(options.root, rows[index].Path)]
		}
		for index := range scan.mounts {
			scan.mounts[index].Label = scan.labels[scan.mounts[index].Path]
		}
		for index := range largest.Dirs {
			largest.Dirs[index].Label = scan.labels[filepath.Join(options.root, largest.Dirs[index].Path)]
		}
	}
	result.Metrics = map[string]interface{}{
		"path": options.root, "bytes": root.total, "entries": root.count, "directories": scan.directories,
		"workers": options.workers, "partial": scan.partial, "unreadable": scan.unreadableCount,
		"rows": rows, "other": other, "skipped_mounts": scan.mounts,
		"filesystem": filesystem, "largest_dirs": largest,
	}
	if scan.deletedChecked {
		result.Metrics["deleted_open"] = deleted
	}
	if filesystem.Whole {
		result.Metrics["not_found_bytes"] = scan.notFound
	}
	return result
}

func duPrint(stdout io.Writer, options commonOptions, result Result, color, graph bool, width int) int {
	var output io.Writer = stdout
	var buffer strings.Builder
	if options.redact {
		output = &buffer
	}
	fmt.Fprint(output, formatResultLine(result, color))
	printResultDetail(output, result, options.verbose, color)
	if result.Status != StatusFail {
		rows, _ := result.Metrics["rows"].([]duRow)
		other, _ := result.Metrics["other"].(duOther)
		counted, _ := result.Metrics["bytes"].(uint64)
		mounts, _ := result.Metrics["skipped_mounts"].([]duMount)
		filesystem, _ := result.Metrics["filesystem"].(duFilesystem)
		deleted, _ := result.Metrics["deleted_open"].(duDeletedOpen)
		notFound, _ := result.Metrics["not_found_bytes"].(uint64)
		if color {
			fmt.Fprint(output, "\n"+richDuRows(rows, other, width, graph))
			fmt.Fprint(output, richDuMounts(mounts, options.verbose, width))
			fmt.Fprint(output, richDuFilesystem(filesystem, deleted, counted, notFound, width))
		} else {
			fmt.Fprint(output, "\n"+formatDuRows(rows, other, width))
			fmt.Fprint(output, formatDuMounts(mounts, options.verbose, width))
			fmt.Fprint(output, formatDuFilesystem(filesystem, deleted, counted, notFound, width))
		}
		fmt.Fprint(output, formatDuPartial(result, options.timeout, color, width))
	}
	if options.redact {
		fmt.Fprint(stdout, redactIPAddresses(buffer.String()))
	}
	return exitCode([]Result{result})
}

// formatDuPartial은 부분 결과임을 출력 끝에 다시 알린다. 맨 위의 경고는 긴 트리에 밀려 화면 밖으로 나가고,
// 바로 위의 파일 시스템 사용량이 읽은 부분만 센 크기와 나란히 보여 빠진 파일이 있는 것처럼 읽힌다.
func formatDuPartial(result Result, timeout time.Duration, color bool, width int) string {
	if partial, _ := result.Metrics["partial"].(bool); !partial {
		return ""
	}
	counted, _ := result.Metrics["bytes"].(uint64)
	// Next는 시간 초과일 때만 채운다. 사용자가 멈췄으면 더 긴 제한 시간을 권하지 않는다.
	line := T("du.partial.stopped", formatSizeShort(counted))
	if result.Next != "" {
		line = T("du.partial.timeout", timeout, formatSizeShort(counted))
	}
	if color {
		return richDuPartial(line, result.Next, width)
	}
	text := "\n" + line + "\n"
	if result.Next != "" {
		text += "  " + T("du.partial.next", result.Next) + "\n"
	}
	return text
}

// richDuPartial은 en, ko, ja가 모두 쓰는 "머리: 본문" 꼴에서 머리를 노란 배지로 바꾸고, 본문은 배지 뒤에 맞춰
// 줄을 바꾼다. 다시 실행할 명령은 자르거나 접지 않는다. 복사한 글자가 그대로 실행되어야 한다. 안내와 함께 폭을 넘으면
// 명령만 다음 줄에 둔다.
func richDuPartial(line, next string, width int) string {
	badge := ""
	if head, body, ok := strings.Cut(line, ": "); ok {
		badge, line = richBadge(head, richYellow)+" ", body
	}
	lead := liveWidth(badge)
	if room := width - lead; width > 0 && room >= 20 {
		line = strings.ReplaceAll(ansi.Wrap(line, room, ""), "\n", "\n"+strings.Repeat(" ", lead))
	}
	text := "\n" + badge + line + "\n"
	if next != "" {
		command := richPaint(next, richCyan, true)
		hint := "  " + duPhrase(T("du.partial.next", "\x00"), richDim, command)
		if width > 0 && liveWidth(hint) > width {
			before, after, _ := strings.Cut(T("du.partial.next", "\x00"), "\x00")
			hint = "  " + richDim(strings.TrimRight(before, " ")) + "\n  " + command + richDim(after)
		}
		text += hint + "\n"
	}
	return text
}

// duPhrase는 \x00, \x01 같은 표지를 넣어 만든 문장에서 표지 자리에 values의 칠한 값을 넣고 나머지 글자는 base로
// 칠한다. 문장 전체를 칠하면 값 뒤의 reset이 나머지 글자의 색을 지운다. 표지의 순서는 언어마다 달라도 된다.
func duPhrase(text string, base func(string) string, values ...string) string {
	var builder strings.Builder
	start := 0
	for index, char := range text {
		if int(char) >= len(values) {
			continue
		}
		if index > start {
			builder.WriteString(base(text[start:index]))
		}
		builder.WriteString(values[char])
		start = index + 1
	}
	if start < len(text) {
		builder.WriteString(base(text[start:]))
	}
	return builder.String()
}

// duSelect는 큰 항목부터 골라 펼친다. 디렉터리를 고르면 그 안의 항목이 후보에 오른다. 조상은 언제나 자손보다
// 먼저 뽑히므로, 보이는 파일보다 큰 파일은 모두 보인다. 그래서 탐색은 전체에서 큰 파일 limit개만 남기면 된다.
// 크기가 0인 항목은 /dev처럼 줄만 차지하므로 나머지 줄에 넣는다.
func duSelect(root *duNode, limit int) ([]duRow, duOther) {
	chosen := map[*duNode]bool{}
	candidates := &duHeap{}
	push := func(node *duNode) {
		for _, child := range node.children {
			if child.total > 0 {
				heap.Push(candidates, child)
			}
		}
	}
	push(root)
	for candidates.Len() > 0 && len(chosen) < limit {
		node := heap.Pop(candidates).(*duNode)
		chosen[node] = true
		push(node)
	}
	var rows []duRow
	other := duOther{Bytes: root.total, Entries: root.count - 1}
	var visit func(node *duNode, prefix string, depth int)
	visit = func(node *duNode, prefix string, depth int) {
		children := append([]*duNode(nil), node.children...)
		sort.Slice(children, func(i, j int) bool { return duLarger(children[i], children[j]) })
		for _, child := range children {
			if !chosen[child] {
				continue
			}
			path := prefix + child.name
			rows = append(rows, duRow{Path: path, Bytes: child.total, Entries: child.count, Dir: child.dir, Depth: depth})
			if depth == 0 {

				other.Bytes -= child.total
				other.Entries -= child.count
			}
			visit(child, path+"/", depth+1)
		}
	}
	visit(root, "", 0)
	return rows, other
}

func duLarger(left, right *duNode) bool {
	if left.total != right.total {
		return left.total > right.total
	}
	return left.name < right.name
}

func (h *duHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

// duFit는 width가 0이면 자르지 않는다.
func duFit(text string, width int) string {
	if width <= 0 {
		return text
	}
	return ansi.Truncate(text, width, "…")
}

func formatDuRows(rows []duRow, other duOther, width int) string {
	var builder strings.Builder
	line := func(bytes uint64, label string) {
		builder.WriteString(duFit(fmt.Sprintf("  %9s  %s", formatSizeShort(bytes), label), width))
		builder.WriteString("\n")
	}
	for _, row := range rows {
		name := duRowName(row)
		if row.Label != "" {
			name += "  " + row.Label
		}
		line(row.Bytes, strings.Repeat("  ", row.Depth)+name)
	}
	if other.Entries > 0 {
		line(other.Bytes, T("du.other", other.Entries))
	}
	return builder.String()
}

func duRowName(row duRow) string {
	name := row.Path[strings.LastIndex(row.Path, "/")+1:]
	if row.Dir {
		name += "/"
	}
	return name
}

// richDuRows는 색을 쓰는 터미널의 트리다. 크기는 크기 색으로 칠하고 맨 위 단계는 굵게 한다. graph면 크기 옆에
// 가장 큰 줄에 맞춘 막대를 둔다. 막대를 둘 줄이 하나뿐이면 늘 가득 차므로 뺀다.
func richDuRows(rows []duRow, other duOther, width int, graph bool) string {
	var largest uint64
	bars := len(rows)
	for _, row := range rows {
		if row.Bytes > largest {
			largest = row.Bytes
		}
	}
	if other.Entries > 0 {
		if other.Bytes > largest {
			largest = other.Bytes
		}
		bars++
	}
	graph = graph && bars > 1
	bar := func(bytes uint64, color string) string {
		if !graph {
			return ""
		}
		return richFill(richBar(float64(bytes), float64(largest), duBarWidth), color) + "  "
	}
	var builder strings.Builder
	write := func(text string) { builder.WriteString(duFit(text, width) + "\n") }
	for _, row := range rows {
		color := richSizeColor(int64(row.Bytes))
		text := "  " + richPaint(fmt.Sprintf("%9s", formatSizeShort(row.Bytes)), color, row.Depth == 0) + "  " +
			bar(row.Bytes, color) + strings.Repeat("  ", row.Depth) + duRowName(row)
		if row.Label != "" {
			text += "  " + richDim(row.Label)
		}

		write(text)
	}
	if other.Entries > 0 {
		write("  " + richDim(fmt.Sprintf("%9s", formatSizeShort(other.Bytes))) + "  " + bar(other.Bytes, richGray) + richDim(T("du.other", other.Entries)))
	}
	return builder.String()
}

func formatDuMounts(mounts []duMount, verbose bool, width int) string {
	if len(mounts) == 0 {
		return ""
	}
	shown, pathWidth, typeWidth := duShownMounts(mounts, verbose)
	var builder strings.Builder
	builder.WriteString("\n" + T("du.mounts.title") + "\n")
	for _, mount := range shown {
		used := "-"
		if !mount.Shared {
			used = T("du.mounts.used", formatSizeShort(mount.UsedBytes))
		}
		text := "  " + liveCell(mount.Path, pathWidth+2) + liveCell(mount.FSType, typeWidth+2) + used
		if mount.Label != "" {
			text += "  " + mount.Label
		}
		builder.WriteString(duFit(text, width) + "\n")
	}
	if hidden := len(mounts) - len(shown); hidden > 0 {
		builder.WriteString("  " + T("du.mounts.more", hidden) + "\n")
	}
	return builder.String()
}

func duShownMounts(mounts []duMount, verbose bool) (shown []duMount, pathWidth, typeWidth int) {
	shown = mounts
	if !verbose && len(shown) > duMountRows {
		shown = shown[:duMountRows]
	}
	for _, mount := range shown {
		pathWidth = max(pathWidth, liveWidth(mount.Path))
		typeWidth = max(typeWidth, liveWidth(mount.FSType))
	}
	return shown, pathWidth, typeWidth
}

// richDuMounts는 건너뛴 마운트를 회색 패널로 그린다. 경로는 기본 색, 파일 시스템 종류와 이름표는 회색이다.
func richDuMounts(mounts []duMount, verbose bool, width int) string {
	if len(mounts) == 0 {
		return ""
	}
	shown, pathWidth, typeWidth := duShownMounts(mounts, verbose)
	var builder strings.Builder
	write := func(text string) { builder.WriteString(duFit(text, width) + "\n") }
	builder.WriteString("\n")
	write(richPanelTop(T("du.mounts.title"), "", ""))
	for _, mount := range shown {
		used := richDim("-")
		if !mount.Shared {
			used = duPhrase(T("du.mounts.used", "\x00"), richDim, richPaint(formatSizeShort(mount.UsedBytes), richSizeColor(int64(mount.UsedBytes)), false))
		}
		text := liveCell(mount.Path, pathWidth+2) + richDim(liveCell(mount.FSType, typeWidth+2)) + used
		if mount.Label != "" {
			text += "  " + richDim(mount.Label)
		}
		write(richPanelLine(text, ""))
	}
	if hidden := len(mounts) - len(shown); hidden > 0 {
		more := strings.Replace(T("du.mounts.more", hidden), "-v", "\x00", 1)
		write(richPanelLine(duPhrase(more, richDim, richPaint("-v", richCyan, true)), ""))
	}
	write(richPanelBottom(""))
	return builder.String()
}

// duMountLabel은 bind mount를 findmnt처럼 장치[디렉터리]로 적어 사용량이 마운트가 아니라 장치 전체의 값임을 보인다.
func duMountLabel(filesystem duFilesystem) string {
	if filesystem.Root != "" && filesystem.Root != "/" {
		return fmt.Sprintf("%s (%s[%s])", filesystem.Mount, filesystem.Source, filesystem.Root)
	}
	return filesystem.Mount
}

// formatDuFilesystem은 경로가 속한 파일 시스템을 보인다. 경로가 파일 시스템 전체일 때만 df의 사용량과 센 크기를
// 맞춰 보고, 하위 디렉터리를 쟀으면 지워졌지만 열린 파일이 있을 때만 그 줄을 보인다.
func formatDuFilesystem(filesystem duFilesystem, deleted duDeletedOpen, counted, notFound uint64, width int) string {
	if filesystem.Mount == "" {
		return ""
	}
	var builder strings.Builder
	title := T("du.fs.title", duMountLabel(filesystem), filesystem.FSType, formatSizeShort(filesystem.UsedBytes), formatSizeShort(filesystem.SizeBytes))
	builder.WriteString("\n" + duFit(title, width) + "\n")
	rows, labelWidth := duFilesystemRows(filesystem, deleted, counted, notFound)
	for _, row := range rows {
		value := row.size
		if row.files != "" {
			value += " " + row.files
		}
		if row.hint != "" {
			value += "  " + row.hint
		}
		builder.WriteString(duFit("  "+liveCell(row.label, labelWidth+2)+value, width) + "\n")
	}
	for _, file := range deleted.Top {
		builder.WriteString(duFit(fmt.Sprintf("    %9s  pid %d %s  %s", formatSizeShort(file.Bytes), file.PID, file.Comm, file.Path), width) + "\n")
	}
	return builder.String()
}

// duFilesystemRow는 파일 시스템 아래의 한 줄이다. 값은 크기, 파일 수, 안내 순서로 붙인다.
type duFilesystemRow struct {
	label, size, files, hint string
	bytes                    uint64
}

func duFilesystemRows(filesystem duFilesystem, deleted duDeletedOpen, counted, notFound uint64) ([]duFilesystemRow, int) {
	var rows []duFilesystemRow
	if filesystem.Whole {
		rows = append(rows, duFilesystemRow{label: T("du.fs.counted"), size: formatSizeShort(counted), bytes: counted})
	}
	// 하나도 찾지 못했어도 하한이면 줄을 남긴다. 줄이 없으면 지워진 파일이 없다고 읽힌다.
	if filesystem.Whole || deleted.Files > 0 || deleted.Partial {
		row := duFilesystemRow{label: T("du.fs.deleted"), size: formatSizeShort(deleted.Bytes), bytes: deleted.Bytes}
		if deleted.Partial {
			row.size = "≥" + row.size
			row.hint = T("du.fs.partial_hint")
		}
		if deleted.Files > 0 {
			row.files = T("du.fs.files", deleted.Files)
		}
		rows = append(rows, row)
	}
	if filesystem.Whole {
		rows = append(rows, duFilesystemRow{label: T("du.fs.not_found"), size: formatSizeShort(notFound), bytes: notFound, hint: T("du.fs.not_found_hint")})
	}
	labelWidth := 0
	for _, row := range rows {
		labelWidth = max(labelWidth, liveWidth(row.label))
	}
	return rows, labelWidth
}

// richDuFilesystem은 clean의 파일 시스템 줄처럼 chip 이름표 뒤에 마운트와 사용량을 둔다. 아래 줄의 이름표와 안내는
// 회색이고 크기는 크기 색이다.
func richDuFilesystem(filesystem duFilesystem, deleted duDeletedOpen, counted, notFound uint64, width int) string {
	if filesystem.Mount == "" {
		return ""
	}
	var builder strings.Builder
	write := func(text string) { builder.WriteString(duFit(text, width) + "\n") }
	usage := duPhrase(T("du.fs.usage", "\x00", "\x01"), richDim, richBold(formatSizeShort(filesystem.UsedBytes)), formatSizeShort(filesystem.SizeBytes))
	builder.WriteString("\n")
	write(richChip(T("du.fs.label")) + " " + richBold(duMountLabel(filesystem)) + "  " + richDim(filesystem.FSType) + "  " + usage)
	rows, labelWidth := duFilesystemRows(filesystem, deleted, counted, notFound)
	for _, row := range rows {
		text := "  " + richDim(liveCell(row.label, labelWidth+2)) + richPaint(row.size, richSizeColor(int64(row.bytes)), false)
		if row.files != "" {
			text += " " + richDim(row.files)
		}
		if row.hint != "" {
			text += "  " + richDim(row.hint)
		}
		write(text)
	}
	for _, file := range deleted.Top {
		write("    " + richPaint(fmt.Sprintf("%9s", formatSizeShort(file.Bytes)), richSizeColor(int64(file.Bytes)), false) +
			fmt.Sprintf("  pid %d %s  ", file.PID, file.Comm) + richDim(file.Path))
	}
	return builder.String()
}

// duFiles는 전체에서 가장 큰 파일 limit개만 남긴다. 나머지 파일은 부모 디렉터리의 합에만 들어간다.
// 그래서 메모리는 파일 수가 아니라 디렉터리 수를 따라 는다.
type duFiles struct {
	limit int
	// floor는 가득 찬 heap의 가장 작은 값이다. 대부분의 파일은 lock 없이 여기서 걸러진다.
	floor atomic.Uint64
	mu    sync.Mutex
	heap  duFileHeap
}

// reset은 화면이 디렉터리를 다시 읽을 때 쓴다. floor는 탐색이 남긴 가장 작은 큰 파일이라, 다시 읽은 파일 중 그보다 큰
// 것만 줄로 올린다.
func (files *duFiles) reset(limit int, floor uint64) {
	files.limit, files.heap = limit, nil
	files.floor.Store(floor)
}

type duFile struct {
	parent *duNode
	name   string
	bytes  uint64
}

func (files *duFiles) offer(parent *duNode, name string, bytes uint64) {
	if files.limit <= 0 || bytes == 0 || bytes <= files.floor.Load() {
		return
	}
	files.mu.Lock()
	defer files.mu.Unlock()
	heap.Push(&files.heap, duFile{parent: parent, name: name, bytes: bytes})
	if files.heap.Len() > files.limit {
		heap.Pop(&files.heap)
	}
	if files.heap.Len() == files.limit {
		files.floor.Store(files.heap[0].bytes)
	}
}

func (h *duFileHeap) Pop() any {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}

// duFinish는 남긴 큰 파일을 부모의 children으로 옮기고 하위 합을 계산한다.
func duFinish(root *duNode, files []duFile) {
	for _, file := range files {
		file.parent.bytes -= file.bytes
		file.parent.entries--
		file.parent.children = append(file.parent.children, &duNode{name: file.name, parent: file.parent, bytes: file.bytes, entries: 1})
	}
	duTotal(root)
}

func duTotal(node *duNode) {
	node.total, node.count = node.bytes, node.entries
	for _, child := range node.children {
		duTotal(child)
		node.total += child.total
		node.count += child.count
	}
}

// duLargestList는 깊이와 관계없이 가장 큰 디렉터리다. Complete면 모든 디렉터리가 들어 있어, 목록에 없는 디렉터리는
// 없던 것이다. 아니면 목록에 없는 디렉터리는 가장 작은 항목 이하다.
type duLargestList struct {
	Complete bool         `json:"complete"`
	Dirs     []duLargeDir `json:"dirs"`
}

type duLargeDir struct {
	Path    string `json:"path"`
	Bytes   uint64 `json:"bytes"`
	Entries int64  `json:"entries"`
	Label   string `json:"label,omitempty"`
}

// duLargest는 root를 뺀 디렉터리 가운데 큰 것 limit개를 크기순으로 고른다. 경로는 root 기준이다.
func duLargest(root *duNode, limit int) duLargestList {
	var dirs []duLargeDir
	count := 0
	offer := func(candidate duLargeDir) {
		if limit == 0 {
			return
		}
		if len(dirs) < limit {
			if dirs == nil {
				dirs = make([]duLargeDir, 0, limit)
			}
			dirs = append(dirs, candidate)
			for index := len(dirs) - 1; index > 0; {
				parent := (index - 1) / 2
				if !duLargeBefore(dirs[parent], dirs[index]) {
					break
				}
				dirs[parent], dirs[index] = dirs[index], dirs[parent]
				index = parent
			}
			return
		}
		if !duLargeBefore(candidate, dirs[0]) {
			return
		}
		dirs[0] = candidate
		for index := 0; ; {
			child := 2*index + 1
			if child >= len(dirs) {
				break
			}

			if child+1 < len(dirs) && duLargeBefore(dirs[child], dirs[child+1]) {
				child++
			}
			if !duLargeBefore(dirs[index], dirs[child]) {
				break
			}
			dirs[index], dirs[child] = dirs[child], dirs[index]
			index = child
		}
	}
	var visit func(node *duNode, prefix string)
	visit = func(node *duNode, prefix string) {
		for _, child := range node.children {
			if !child.dir {
				continue
			}
			count++
			path := prefix + child.name
			offer(duLargeDir{Path: path, Bytes: child.total, Entries: child.count})
			visit(child, path+"/")
		}
	}
	visit(root, "")
	if limit == 0 && count > 0 {
		dirs = []duLargeDir{}
	}
	sort.Slice(dirs, func(i, j int) bool { return duLargeBefore(dirs[i], dirs[j]) })
	return duLargestList{Complete: count <= limit, Dirs: dirs}
}

func duLargeBefore(a, b duLargeDir) bool {
	if a.Bytes != b.Bytes {
		return a.Bytes > b.Bytes
	}
	return a.Path < b.Path
}

// duDirDelta는 report diff의 디렉터리 하나다. Bound가 있으면 그쪽 report의 목록에 이 디렉터리가 없어, 그쪽 값은
// 그 목록의 가장 작은 크기 이하라는 상한이다. 그때 Delta는 변화의 하한이다.
type duDirDelta struct {
	Path   string `json:"path"`
	Before uint64 `json:"before_bytes"`
	After  uint64 `json:"after_bytes"`
	Delta  int64  `json:"delta_bytes"`
	Bound  string `json:"bound,omitempty"`
	Label  string `json:"label,omitempty"`
}

// duCompareDirs는 두 du.scan 결과의 큰 디렉터리 목록을 경로로 맞춘다. 비교하지 않으면 그 이유를 돌려준다.
// 목록이 없는 이전 report는 이유 없이 건너뛴다.
func duCompareDirs(before, after map[string]interface{}) ([]duDirDelta, string) {
	old, oldOK := duLargestOf(before)
	current, currentOK := duLargestOf(after)
	if !oldOK || !currentOK {
		return nil, ""
	}
	oldPath, _ := before["path"].(string)
	currentPath, _ := after["path"].(string)
	if oldPath != currentPath {
		return nil, T("du.diff.path_differs", oldPath, currentPath)
	}
	// 일부만 센 쪽은 빠진 디렉터리가 줄어든 것처럼 보인다.
	if partial, _ := before["partial"].(bool); partial {
		return nil, T("du.diff.partial")
	}
	if partial, _ := after["partial"].(bool); partial {
		return nil, T("du.diff.partial")
	}
	oldBytes, oldBound := duLargestIndex(old)
	currentBytes, currentBound := duLargestIndex(current)
	// 이름표는 나중 report의 것을 쓴다. 지운 디렉터리는 앞 report에만 이름표가 있다.
	labels := map[string]string{}
	for _, list := range []duLargestList{old, current} {
		for _, dir := range list.Dirs {
			if dir.Label != "" {
				labels[dir.Path] = dir.Label
			}
		}
	}
	var deltas []duDirDelta

	for path := range duPathUnion(oldBytes, currentBytes) {
		delta := duDirDelta{Path: path, Label: labels[path]}
		var hadBefore, hasAfter bool
		delta.Before, hadBefore = oldBytes[path]
		delta.After, hasAfter = currentBytes[path]
		if !hadBefore {
			delta.Before = oldBound
			if !old.Complete {
				delta.Bound = "before"
			}
		}
		if !hasAfter {
			delta.After = currentBound
			if !current.Complete {
				delta.Bound = "after"
			}
		}
		delta.Delta = int64(delta.After) - int64(delta.Before)
		// 상한과 비교해 변화가 없거나 반대로 나오면 실제 변화의 방향을 알 수 없다.
		if delta.Delta == 0 || (delta.Bound == "before" && delta.Delta < 0) || (delta.Bound == "after" && delta.Delta > 0) {
			continue
		}
		deltas = append(deltas, delta)
	}
	return duTopDeltas(duFoldAncestors(deltas), duDiffDirs), ""
}

func duLargestOf(metrics map[string]interface{}) (duLargestList, bool) {
	value, ok := metrics["largest_dirs"]
	if !ok {
		return duLargestList{}, false
	}
	// 파일에서 읽은 report는 map이고, 같은 process에서 만든 결과는 duLargestList다. JSON으로 한 번 맞춘다.
	data, err := json.Marshal(value)
	if err != nil {
		return duLargestList{}, false
	}
	var list duLargestList
	if err := json.Unmarshal(data, &list); err != nil {
		return duLargestList{}, false
	}
	return list, true
}

// duLargestIndex는 경로별 크기와, 목록에 없는 디렉터리의 크기를 돌려준다. 목록이 완전하면 없는 디렉터리는 0이다.
func duLargestIndex(list duLargestList) (map[string]uint64, uint64) {
	index := make(map[string]uint64, len(list.Dirs))
	var smallest uint64
	for position, dir := range list.Dirs {
		index[dir.Path] = dir.Bytes
		if position == 0 || dir.Bytes < smallest {
			smallest = dir.Bytes
		}
	}
	if list.Complete {
		return index, 0
	}
	return index, smallest
}

func duPathUnion(first, second map[string]uint64) map[string]struct{} {
	union := make(map[string]struct{}, len(first)+len(second))
	for path := range first {
		union[path] = struct{}{}
	}
	for path := range second {
		union[path] = struct{}{}
	}
	return union
}

// duFoldAncestors는 같은 방향의 변화를 90% 이상 설명하는 하위 디렉터리가 있으면 상위 디렉터리를 뺀다.
// 그대로 두면 /var, /var/lib, /var/lib/docker가 같은 증가로 줄을 모두 차지한다.
func duFoldAncestors(deltas []duDirDelta) []duDirDelta {
	var kept []duDirDelta
	for _, delta := range deltas {
		explained := false
		for _, other := range deltas {
			if strings.HasPrefix(other.Path, delta.Path+"/") && (other.Delta > 0) == (delta.Delta > 0) &&
				duAbs(other.Delta)*10 >= duAbs(delta.Delta)*9 {
				explained = true
				break
			}
		}
		if !explained {
			kept = append(kept, delta)
		}
	}
	return kept
}

func duTopDeltas(deltas []duDirDelta, limit int) []duDirDelta {
	sort.Slice(deltas, func(i, j int) bool {
		if duAbs(deltas[i].Delta) != duAbs(deltas[j].Delta) {
			return duAbs(deltas[i].Delta) > duAbs(deltas[j].Delta)
		}
		return deltas[i].Path < deltas[j].Path
	})
	if len(deltas) > limit {
		deltas = deltas[:limit]
	}
	return deltas
}

func duAbs(value int64) int64 {
	if value < 0 {
		return -value
	}
	return value
}

// formatDuDirDeltas는 report diff의 상세 줄이다. 한쪽 목록에 없던 디렉터리는 그쪽 값 앞에 ≤를 붙인다.
func formatDuDirDeltas(deltas []duDirDelta) []string {
	pathWidth := 0
	for _, delta := range deltas {
		pathWidth = min(max(pathWidth, liveWidth(delta.Path)), 40)
	}
	lines := make([]string, 0, len(deltas))
	for _, delta := range deltas {
		sign := "+"
		if delta.Delta < 0 {
			sign = "-"
		}
		before, after := formatSizeShort(delta.Before), formatSizeShort(delta.After)
		switch delta.Bound {
		case "before":
			before = "≤" + before
		case "after":
			after = "≤" + after
		}
		path := ansi.Truncate(delta.Path, pathWidth, "…")
		line := fmt.Sprintf("%10s  %s%s → %s", sign+formatSizeShort(uint64(duAbs(delta.Delta))), liveCell(path, pathWidth+2), before, after)
		if delta.Label != "" {
			line += "  " + delta.Label
		}
		lines = append(lines, line)
	}
	return lines
}

// duSnapshotResult는 edc snapshot --du의 결과다. edc du와 같은 탐색과 판정을 쓰고, snapshot의 제한 시간에 걸리면
// 그때까지 센 값을 partial로 남긴다.
func duSnapshotResult(ctx context.Context, path string, timeout time.Duration) Result {
	started := time.Now()
	sources, ok := hostDuSources()
	if !ok {
		return unsupported(duProbeID, T("du.skip.unsupported"))
	}
	result := Result{Probe: duProbeID, StartedAt: started.UTC()}
	options := duOptions{workers: duDefaultWorkers, rows: duPipedRows}
	root, err := duResolveRoot(path)
	var scan duScan
	if err == nil {
		options.root = root
		scan, err = duWalk(ctx, options, sources)
	}
	if err != nil {
		result = duPathFailure(result, path, err)
	} else {
		result = duResult(result, options, scan, timeout, false)
	}
	result.DurationMS = time.Since(started).Milliseconds()
	return result
}

func duPathFailure(result Result, path string, err error) Result {
	result.Status, result.Summary = StatusFail, T("du.error.path", path)
	result.Error = &DiagnosticError{Kind: "path", Message: err.Error()}
	return result
}

func duStatfs(path string) (duUsage, bool) {
	var stat unix.Statfs_t
	if err := unix.Statfs(path, &stat); err != nil {
		return duUsage{}, false
	}
	return duUsage{Size: stat.Blocks * uint64(stat.Bsize), Used: (stat.Blocks - stat.Bfree) * uint64(stat.Bsize)}, true
}

