		}
	}
	start := duDir{node: root, path: options.root}
	if options.workers <= 1 {

func (walker *duWalker) scan(dir duDir, buffer *duBuffer) []duDir {
	walker.scanning.Add(1)
	defer walker.scanning.Add(-1)
	duBeforeRead(dir.path)
	fd, err := unix.Open(dir.path, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	walker.advance()
	if err != nil {
		walker.apply(func() { dir.node.unreadable = walker.unreadableDir(dir.path, err) })
		return nil
	}
	defer unix.Close(fd)
	return walker.scanDarwinFD(dir, buffer, fd)
}

func (walker *duWalker) scanDarwinFD(dir duDir, buffer *duBuffer, fd int) []duDir {
	walker.directories.Add(1)
	var subdirs []duDir
	for {
		if walker.ctx.Err() != nil {
			walker.stopped.Store(true)
			break
		}
		duBeforeRead(dir.path)
		n, err := duDarwinRead(fd, buffer.read)
		walker.advance()
		if err != nil {
			walker.apply(func() { walker.markUnreadable(dir, err) })
			break
		}
		if n == 0 {
			break
		}
		var batch duDarwinBatch
		buffer.entries, batch = walker.readDarwinBatch(dir, buffer.read, n, fd, buffer.entries[:0])
		applied := walker.apply(func() {
			subdirs = walker.addEntries(dir, buffer.entries, subdirs)
			if batch.broken {
				dir.node.unreadable = walker.unreadableDir(dir.path, unix.EIO)
			} else if batch.failed != nil {
				walker.markUnreadable(dir, batch.failed)
			}
		})
		if !applied || batch.broken {
			break
		}
	}

// duDarwinBatch는 bulk 조회 한 번의 오류다. broken이면 남은 기록을 읽을 수 없고, failed는 항목 하나를 읽지 못한 첫 오류다.
type duDarwinBatch struct {
	broken bool
	failed error
}

		scan, err := duWalk(context.Background(), duOptions{root: root, workers: workers, rows: 20}, sources)
		if err != nil {
			t.Fatal(err)
		}
		if scan.root.total != want || (scan.root.total+1023)/1024 != kib || scan.root.count != 1208 || scan.directories != 5 || scan.partial || scan.unreadableCount != 0 {
			t.Fatalf("workers %d: bytes=%d stat=%d du=%d entries=%d dirs=%d partial=%v unreadable=%d", workers, scan.root.total, want, kib, scan.root.count, scan.directories, scan.partial, scan.unreadableCount)
		}
		if scan.filesystem.Whole || scan.notFound != 0 {
			t.Fatalf("APFS accounting: %+v", scan.filesystem)
		}
	}
}

func TestDuDarwinCancellationAndUnreadableDirectory(t *testing.T) {
	root := duDarwinTestTree(t)
	sources, _ := hostDuSources()
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	for _, workers := range []int{1, 4} {
		scan, err := duWalk(ctx, duOptions{root: root, workers: workers, rows: 20}, sources)
		if err != nil {
			t.Fatal(err)
		}
		if !scan.partial || scan.directories != 0 {
			t.Fatalf("workers %d: partial=%v dirs=%d", workers, scan.partial, scan.directories)
		}
	}
	if os.Geteuid() == 0 {
		t.Skip("root can read directories without permissions")
	}
	blocked := filepath.Join(root, "0")
	if err := os.Chmod(blocked, 0); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(blocked, 0o755) })
	scan, err := duWalk(context.Background(), duOptions{root: root, workers: 4, rows: 20}, sources)
	if err != nil {
		t.Fatal(err)
	}
	if scan.unreadableCount != 1 || len(scan.unreadable) != 1 || scan.unreadable[0] != blocked {
		t.Fatalf("unreadable=%d paths=%v", scan.unreadableCount, scan.unreadable)
	}
}

