		t.Fatalf("total %d, want %d", scan.root.total, want)
	}
	if len(scan.mounts) != 1 || scan.mounts[0].Path != filepath.Join(root, "a") || scan.mounts[0].FSType != "xfs" || !scan.mounts[0].Shared {
		t.Fatalf("mounts = %+v", scan.mounts)
	}

