// grepLevelFields는 "2026-10-26 10:00:02,310 ERROR ..." 같은 줄의 level과 그 앞의 시각이다. level이 없거나 들여 쓴 줄은
// 앞 event에 이어지는 줄이라 header가 false다.
func grepLevelFields(line []byte) (string, []byte, bool) {
