func TestGrepNativeCorpusEvaluation(t *testing.T) {
	model, library, vocab := os.Getenv("EDC_TEST_ONNX_MODEL"), os.Getenv("EDC_TEST_ONNX_LIBRARY"), os.Getenv("EDC_TEST_ONNX_VOCAB")
	if os.Getenv("EDC_EVAL_GREP") != "1" || model == "" || library == "" || vocab == "" {
		t.Skip("set EDC_EVAL_GREP=1 and the EDC_TEST_ONNX_* paths")
	}
	raw, err := os.ReadFile("testdata/grep-ask/queries.json")
	if err != nil {
		t.Fatal(err)
	}
	var queries []struct {
		Query string `json:"query"`
		Path  string `json:"path"`
	}
	if err := json.Unmarshal(raw, &queries); err != nil {
		t.Fatal(err)
	}
	if len(queries) < 20 {
		t.Fatal("20 English queries required")
	}
	root, err := filepath.Abs(".")
	if err != nil {
		t.Fatal(err)
	}
	root, err = filepath.EvalSymlinks(root)
	if err != nil {
		t.Fatal(err)
	}
	targets, _, problems := grepCodeTargets([]string{root}, grepOptions{})
	if len(problems) > 0 {
		t.Fatal(problems)
	}
	var chunks []grepAskChunk

for _, path := range targets {
	rel, err := filepath.Rel(root, path)
	if err != nil {
		t.Fatal(err)
	}
	if rel == "grep_ask_eval_test.go" || strings.HasPrefix(filepath.ToSlash(rel), "testdata/grep-ask/") {
		continue
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if len(data) > grepAskMaxFileBytes || bytes.IndexByte(data, 0) >= 0 || !utf8.Valid(data) {
		continue
	}
	fileChunks := grepAskChunks(path, data)
	for i := range fileChunks {
		fileChunks[i].rankPath = filepath.ToSlash(rel)
	}
	chunks = append(chunks, fileChunks...)
}
tokenizer, err := newGrepTokenizer(vocab)
if err != nil {
	t.Fatal(err)
}
engine, err := newGrepONNX(library, model)
if err != nil {
	t.Fatal(err)
}
defer engine.close()
index := &grepSemanticIndex{Vectors: make(map[string][]float32, len(chunks))}
start := time.Now()

type tokenized struct {
	index int
	ids   []int64
}
items := make([]tokenized, len(chunks))
for i, chunk := range chunks {
	text := strings.Join(chunk.lines, "\n")
	if runes := []rune(text); len(runes) > 3000 {
		text = string(runes[:3000])
	}
	items[i] = tokenized{index: i, ids: tokenizer.encode(chunk.rankPath + "\n" + text)}
}
sort.SliceStable(items, func(i, j int) bool { return len(items[i].ids) > len(items[j].ids) })
if os.Getenv("EDC_EVAL_TOKEN_ONLY") == "1" {
	t.Logf("tokenized %d chunks in %s", len(items), time.Since(start).Round(time.Millisecond))
	return
}
for from := 0; from < len(items); from += 32 {
	end := min(from+32, len(items))
	batch := make([][]int64, 0, end-from)
	for _, item := range items[from:end] {
		batch = append(batch, item.ids)
	}
	vectors, err := engine.encode(batch)
	if err != nil {
		t.Fatal(err)
	}
	for i, vector := range vectors {
		index.Vectors[grepSemanticKey(root, chunks[items[from+i].index])] = vector
	}
}
elapsed := time.Since(start)

	hits := 0
	for _, q := range queries[:20] {
		query, err := engine.encode([][]int64{tokenizer.encode(q.Query)})
		if err != nil {
			t.Fatal(err)
		}
		results := grepSemanticScore(root, grepOptions{pattern: q.Query, askLimit: 5}, chunks, index, query[0])
		found := false
		for _, r := range results {
			rel, err := filepath.Rel(root, r.Path)
			if err != nil {
				t.Fatal(err)
			}
			if filepath.ToSlash(filepath.Join("internal/edc", rel)) == q.Path {
				found = true
				break
			}
		}
		if found {
			hits++
		} else {
			t.Logf("MISS %q expected %s", q.Query, q.Path)
		}
	}
	t.Logf("native MiniLM hybrid top-5: %d/20; %d chunks; embedding %s", hits, len(chunks), elapsed.Round(time.Millisecond))
}

func newGrepONNX(libraryPath, modelPath string) (*grepONNX, error) {
	library, err := purego.Dlopen(libraryPath, purego.RTLD_NOW|purego.RTLD_LOCAL)
	if err != nil {
		return nil, err
	}
	o := &grepONNX{library: library}
	fail := func(err error) (*grepONNX, error) { o.close(); return nil, err }
	symbol, err := purego.Dlsym(library, "OrtGetApiBase")
	if err != nil {
		return fail(err)
	}
	var base func() unsafe.Pointer
	purego.RegisterFunc(&base, symbol)
	basePtr := base()
	if basePtr == nil {
		return fail(errors.New("ONNX Runtime API base unavailable"))
	}
	var getAPI func(uint32) unsafe.Pointer
	purego.RegisterFunc(&getAPI, *(*uintptr)(basePtr))
	api := getAPI(23)
	if api == nil {
		return fail(errors.New("ONNX Runtime API 23 unavailable"))
	}
	table := unsafe.Slice((*uintptr)(api), 101)
	// These C API slots are stable for ONNX Runtime API 23 and must match the pinned runtime.
	for _, index := range []int{2, 3, 6, 7, 9, 10, 24, 25, 49, 51, 61, 62, 65, 69, 92, 93, 94, 95, 96, 99, 100} {
		if table[index] == 0 {
			return fail(fmt.Errorf("ONNX Runtime API slot %d unavailable", index))
		}
	}
	var createEnv func(int32, string, *unsafe.Pointer) unsafe.Pointer
	var disableTelemetry func(unsafe.Pointer) unsafe.Pointer

func (o *grepONNX) close() {
	if o.memory != nil && o.releaseMemory != nil {
		o.releaseMemory(o.memory)
	}
	if o.session != nil && o.releaseSession != nil {
		o.releaseSession(o.session)
	}
	if o.options != nil && o.releaseOptions != nil {
		o.releaseOptions(o.options)
	}
	if o.env != nil && o.releaseEnv != nil {
		o.releaseEnv(o.env)
	}
	if o.library != 0 {
		purego.Dlclose(o.library)
	}
}

const (
	// grepBlockSize는 파일을 읽는 단위이고 index의 블록 크기다.
	grepBlockSize = 1 << 20
	// grepLineLimit는 한 줄로 다루는 최대 바이트다. 이보다 긴 줄은 앞부분만 비교한다. view와 같은 상한이다.
	grepLineLimit = 64 << 20
	// grepSampleSize는 pivot 바이트를 고르기 위해 파일에서 읽는 표본 크기다.
	grepSampleSize = 64 << 10
	// grepTailRead는 구간 끝을 지난 뒤 마지막 줄의 나머지를 읽는 단위다. 블록 단위로 읽으면 구간마다 1 MiB를 더 읽는다.
	grepTailRead = 64 << 10
	// grepPivotShare는 pivot으로 쓸 수 있는 바이트의 최대 비율이다. 가장 드문 바이트가 이보다 흔하면 IndexByte로 찍는
	// 후보가 너무 많아 bytes.Index가 빠르다. 측정에서 1.49%인 '4'까지는 pivot이 빨랐다.
	grepPivotShare = 0.015
	// bytes.Index는 needle의 첫 바이트로 후보를 찍다가 실패가 쌓이면 bytealg.Index로 넘어간다. 첫 바이트가 5%보다 흔하면
	// 금방 넘어가 빠르지만, 3~5%에서는 넘어가지 못한 채 후보마다 멈춰 가장 느리다. 그 구간에서는 가장 드문 바이트가 첫
	// 바이트의 0.8배 이하이기만 하면 pivot이 빨랐다. 로그의 status=503(첫 바이트 4.6%, 가장 드문 바이트 1.8%)은
	// 47ms에서 28ms가 되었고, 0.8배를 넘는 =200 은 bytes.Index가 빨랐다.
	grepPivotFirstShare = 0.05
	grepPivotFirstRatio = 0.8
)

// newGrepMatcher는 pattern을 컴파일하고 sample(파일의 일부)의 바이트 빈도로 pivot을 고른다.
func newGrepMatcher(pattern string, useRegex, ignoreCase bool, sample []byte) (*grepMatcher, error) {
	matcher := &grepMatcher{pivot: -1, second: -1}
	switch {
	case !useRegex && !ignoreCase:
		matcher.literal = []byte(pattern)
		matcher.needle = matcher.literal
		matcher.indexNeedle = matcher.literal
	default:
		expr := pattern
		if !useRegex {
			expr = regexp.QuoteMeta(pattern)
		}
		if ignoreCase {
			expr = "(?i)" + expr
		}
		regex, err := regexp.Compile(expr)
		if err != nil {
			return nil, err
		}
		matcher.regex = regex
		prefix, _ := regex.LiteralPrefix()
		matcher.needle = []byte(prefix)
		// 앞에 고정 문자열이 없어도 모든 일치에 들어가는 문자열이 있으면 그것으로 건너뛴다. 없으면 모든 줄에 정규식을 대서,
		// Go 소스 41 MB에 [a-z]+_[a-z]+Test\( 를 찾는 데 869ms가 걸렸고 Test( 로 건너뛰면 7ms였다.
		if parsed, err := syntax.Parse(expr, syntax.Perl); err == nil {
			if required := grepRequiredLiteral(parsed); len(required) > len(matcher.needle) {
				matcher.needle = required
			}
		}
		matcher.indexNeedle = matcher.needle
		if ignoreCase && !useRegex {

			// 대소문자를 무시해도 글자가 아닌 바이트는 그대로다. 그중 가장 긴 구간이 모든 일치에 들어간다.
			matcher.needle = grepLongestNonLetterRun(pattern)
			matcher.indexNeedle = []byte(pattern)
			if grepFoldsInASCII(pattern) {
				matcher.fold = true
				matcher.needle = bytes.ToLower([]byte(pattern))
			}
		}
	}
	matcher.pivot, matcher.second = matcher.choosePivot(sample)
	return matcher, nil
}

// grepFoldsInASCII는 (?i)로 pattern에 맞는 글자가 모두 ASCII인지 본다. 유니코드 대소문자 접기에서 ASCII 글자 중 k와 s만
// ASCII 밖의 글자(K U+212A, ſ U+017F)와 같다. 그런 패턴은 정규식으로 찾아야 결과가 같다.
func grepFoldsInASCII(pattern string) bool {
	if pattern == "" {
		return false
	}
	for index := 0; index < len(pattern); index++ {
		switch char := pattern[index]; {
		case char >= utf8.RuneSelf, char == 'k', char == 'K', char == 's', char == 'S':
			return false
		}
	}
	return true
}

// grepRequiredLiteral은 re에 맞는 모든 문자열에 들어가는 가장 긴 고정 문자열이다. 확실하지 않으면 nil이다. 대소문자를
// 접는 문자열은 바이트로 찾을 수 없으므로 쓰지 않는다.
func grepRequiredLiteral(re *syntax.Regexp) []byte {
	switch re.Op {
	case syntax.OpLiteral:
		// 정규식은 잘못된 UTF-8 바이트를 U+FFFD로 읽어 맞추므로, U+FFFD가 든 문자열을 바이트로 찾으면 그런 줄을 놓친다.
		if re.Flags&syntax.FoldCase != 0 || slices.Contains(re.Rune, utf8.RuneError) {
			return nil
		}
		return []byte(string(re.Rune))
	case syntax.OpCapture, syntax.OpPlus:
		return grepRequiredLiteral(re.Sub[0])
	case syntax.OpRepeat:
		if re.Min >= 1 {
			return grepRequiredLiteral(re.Sub[0])
		}
	case syntax.OpConcat:
		var best []byte
		for _, sub := range re.Sub {
			if literal := grepRequiredLiteral(sub); len(literal) > len(best) {
				best = literal
			}
		}
		return best
	case syntax.OpAlternate:
		// 갈래마다 들어가는 문자열의 공통 부분만 모든 일치에 들어간다.
		common := grepRequiredLiteral(re.Sub[0])
		for _, sub := range re.Sub[1:] {
			if len(common) == 0 {
				return nil
			}
			common = grepLongestCommonRun(common, grepRequiredLiteral(sub))

		}
		return common
	}
	return nil
}

func grepLongestNonLetterRun(pattern string) []byte {
	var best []byte
	start := -1
	for index := 0; index <= len(pattern); index++ {
		if index < len(pattern) && !viewWordByte(pattern[index]) {
			if start < 0 {
				start = index
			}
			continue
		}
		if start >= 0 && index-start > len(best) {
			best = []byte(pattern[start:index])
		}
		start = -1
	}
	return best
}

// grepChoosePivot은 sample에서 가장 드문 needle 바이트의 위치와 두 번째로 드문 위치를 고른다. 가장 드문 바이트도
// grepPivotShare보다 흔하면 -1을 돌려주어 bytes.Index를 쓰게 한다. 결과는 pivot과 무관하게 전체 비교로 정해지므로
// 표본이 파일을 대표하지 않아도 느려질 뿐 틀리지 않는다.
func grepChoosePivot(needle, sample []byte) (int, int) {
	if len(needle) < 2 || len(sample) == 0 {
		return -1, -1
	}
	var histogram [256]int
	for _, char := range sample {
		histogram[char]++
	}
	first := 0
	for index := range needle {
		if histogram[needle[index]] < histogram[needle[first]] {
			first = index
		}
	}
	rare, leading := float64(histogram[needle[first]]), float64(histogram[needle[0]])
	if rare/float64(len(sample)) > grepPivotShare && (leading/float64(len(sample)) > grepPivotFirstShare || rare > leading*grepPivotFirstRatio) {
		return -1, -1
	}
	second := -1
	for index := range needle {
		if index != first && (second < 0 || histogram[needle[index]] < histogram[needle[second]]) {
			second = index
		}
	}
	return first, second
}

// find는 data에서 needle이 시작하는 첫 위치다.
func (matcher *grepMatcher) find(data []byte) int {
	if matcher.fold {
		return matcher.findFold(data)
	}
	if matcher.pivot < 0 {
		return bytes.Index(data, matcher.needle)
	}
	needle := matcher.needle
	position := 0
	for {
		index := bytes.IndexByte(data[position:], needle[matcher.pivot])
		if index < 0 {
			return -1
		}
		at := position + index - matcher.pivot
		if at >= 0 && at+len(needle) <= len(data) && data[at+matcher.second] == needle[matcher.second] && bytes.Equal(data[at:at+len(needle)], needle) {
			return at
		}
		position += index + 1
	}
}

// findFold는 pivot 바이트의 소문자와 대문자를 각각 IndexByte로 찾는다. 두 위치를 기억해 두어, 한쪽이 드물어도 같은
// 구간을 다시 훑지 않는다.
func (matcher *grepMatcher) findFold(data []byte) int {
	needle := matcher.needle
	lower := needle[matcher.pivot]
	upper := grepASCIIUpper(lower)
	indexFrom := func(position int, char byte) int {
		if index := bytes.IndexByte(data[position:], char); index >= 0 {
			return position + index
		}
		return len(data)
	}
	nextLower, nextUpper := -1, -1
	if upper == lower {
		nextUpper = len(data)
	}
	position := 0
	for {
		if nextLower < position {
			nextLower = indexFrom(position, lower)
		}
		if nextUpper < position {
			nextUpper = indexFrom(position, upper)
		}
		index := min(nextLower, nextUpper)
		if index >= len(data) {
			return -1
		}
		if at := index - matcher.pivot; at >= 0 && at+len(needle) <= len(data) && grepEqualASCIIFold(data[at:at+len(needle)], needle) {
			return at
		}
		position = index + 1

// grepEqualASCIIFold는 data를 ASCII 소문자로 바꿔 lower와 비교한다.
func grepEqualASCIIFold(data, lower []byte) bool {
	for index, char := range data {
		if 'A' <= char && char <= 'Z' {
			char += 'a' - 'A'
		}
		if char != lower[index] {
			return false
		}
	}
	return true
}

// match는 line이 패턴에 맞는지 확정한다.
func (matcher *grepMatcher) match(line []byte) bool {
	if matcher.fold {
		return matcher.findFold(line) >= 0
	}
	if matcher.regex != nil {
		return matcher.regex.Match(line)
	}
	return bytes.Contains(line, matcher.literal)
}

// grepScanner는 파일의 한 구간을 훑는다. find는 후보 자리로 건너뛰고(nil이면 줄마다 본다), accept가 줄을 확정한다.
// 블록 크기를 바꿀 수 있어 테스트는 작은 fixture로 블록 경계를 지난다.
type grepScanner struct {
	block     int
	lineLimit int
	find      func([]byte) int
	accept    func([]byte) bool
	// buffers는 scanRange 호출 사이에 다시 쓰는 읽기 버퍼다. --last는 블록마다 scanRange를 부르므로 매번 만들면
	// 블록 수만큼 메모리를 할당한다.
	buffers *grepBuffers
	// prepare는 scanLast가 블록을 읽기 전에 부른다. 앞 줄의 level과 시각을 물려받는 필터가 그 블록 앞의 머리 줄을 찾는 데 쓴다.
	prepare func(file io.ReaderAt, from int64) error
	// verify는 읽은 조각마다 부른다. index 검색은 블록 원문의 checksum을 index와 맞춰 본다.
	verify func(offset int64, chunk []byte) error
}

func newGrepScanner(matcher *grepMatcher, filter *grepFilter) grepScanner {
	scanner := grepScanner{block: grepBlockSize, lineLimit: grepLineLimit, buffers: &grepBuffers{}}
	if filter == nil || !filter.active() {
		scanner.accept = matcher.match
		if len(matcher.needle) != 0 {
			scanner.find = matcher.find
		}
		return scanner
	}
	filter.matcher = matcher
	scanner.accept = func(line []byte) bool { return filter.prefilter(line) && filter.accept(line) }
	scanner.prepare = filter.prime
	if len(matcher.needle) != 0 && !filter.needsEveryLine() {
		scanner.find = matcher.find
	}
	return scanner
}

