type grepSemanticEncoded struct {
	Revision string      `json:"revision"`
	Vectors  [][]float32 `json:"vectors"`
}

func grepSemanticNative(texts []string, progress io.Writer) (grepSemanticEncoded, error) {
	dir, err := grepModelDir()
	if err != nil {
		return grepSemanticEncoded{}, err
	}
	if _, err := os.Stat(dir); err != nil {
		return grepSemanticEncoded{}, fmt.Errorf("%s: %w", T("grep.model.missing"), err)
	}
	unlock, err := grepModelReadLock()
	if err != nil {
		return grepSemanticEncoded{}, err
	}
	defer unlock()
	if err := grepModelCheck(dir); err != nil {
		return grepSemanticEncoded{}, fmt.Errorf("%s: %w", T("grep.model.missing"), err)
	}
	_, _, rt, err := grepModelManifest()
	if err != nil {
		return grepSemanticEncoded{}, err
	}
	tokenizer, err := newGrepTokenizer(filepath.Join(dir, "vocab.txt"))
	if err != nil {
		return grepSemanticEncoded{}, err
	}
	engine, err := newGrepONNX(filepath.Join(dir, rt.libName), filepath.Join(dir, "model.onnx"))
	if err != nil {
		return grepSemanticEncoded{}, fmt.Errorf("%s: %w", T("grep.semantic.backend_error"), err)
	}
	defer engine.close()
	type tokenizedText struct {
		index int
		ids   []int64

	}
	items := make([]tokenizedText, len(texts))
	for i, text := range texts {
		items[i] = tokenizedText{index: i, ids: tokenizer.encode(text)}
	}
	sort.SliceStable(items, func(i, j int) bool { return len(items[i].ids) > len(items[j].ids) })
	vectors := make([][]float32, len(texts))
	lastProgress := time.Now()
	for start := 0; start < len(items); start += 32 {
		end := min(len(items), start+32)
		batch := make([][]int64, 0, end-start)
		for _, item := range items[start:end] {
			batch = append(batch, item.ids)
		}
		encoded, err := engine.encode(batch)
		if err != nil {
			return grepSemanticEncoded{}, fmt.Errorf("%s: %w", T("grep.semantic.backend_error"), err)
		}
		for i, vector := range encoded {
			vectors[items[start+i].index] = vector
		}
		if end < len(items) && time.Since(lastProgress) >= 5*time.Second {
			fmt.Fprintln(progress, T("grep.model.embedding_progress", end, len(items)))
			lastProgress = time.Now()
		}
	}
	return grepSemanticEncoded{Revision: grepMiniLMRevision + ":onnx-" + grepRuntimeVersion + ":wordpiece-v1:chunk-content-v1", Vectors: vectors}, nil
}

func grepSemanticRoot(paths []string) (string, error) {
	if len(paths) != 1 {
		return "", errors.New(T("grep.semantic.one_root"))
	}
	root, err := filepath.Abs(paths[0])
	if err != nil {
		return "", err
	}
	info, err := os.Stat(root)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		return "", errors.New(T("grep.semantic.one_root"))
	}
	return filepath.EvalSymlinks(root)
}

func grepSemanticPath(root string) (string, error) {
	base := grepSemanticCacheRoot
	var err error
	if base == "" {
		base, err = os.UserCacheDir()
		if err != nil {
			return "", err
		}
	}
	sum := sha256.Sum256([]byte(root))
	return filepath.Join(base, "edc", "semantic", hex.EncodeToString(sum[:])+".gob"), nil
}

func grepSemanticKey(root string, chunk grepAskChunk) string {
	absolute, _ := filepath.Abs(chunk.result.Path)
	path, _ := filepath.Rel(root, absolute)
	h := sha256.New()
	fmt.Fprintf(h, "%s\x00", filepath.ToSlash(path))
	io.WriteString(h, strings.Join(chunk.lines, "\n"))
	return hex.EncodeToString(h.Sum(nil))
}

// 벡터는 IEEE 754 half로 저장한다. 측정에서 float32와 검색 순위가 같았고 파일은 3분의 1, 읽기는 6분의 1로 줄었다.
func grepFloat16(x float32) uint16 {
	bits := math.Float32bits(x)
	sign := uint16(bits>>16) & 0x8000
	exponent := int(bits>>23&0xff) - 127 + 15
	mantissa := bits & 0x7fffff
	if exponent >= 31 {
		if bits&0x7fffffff > 0x7f800000 {
			return sign | 0x7e00
		}
		return sign | 0x7c00
	}
	if exponent <= 0 {
		if exponent < -10 {
			return sign
		}
		mantissa |= 0x800000
		shift := uint(14 - exponent)
		half := uint16(mantissa >> shift)
		rest, halfway := mantissa&(1<<shift-1), uint32(1)<<(shift-1)
		if rest > halfway || rest == halfway && half&1 == 1 {
			half++
		}
		return sign | half
	}
	half := sign | uint16(exponent)<<10 | uint16(mantissa>>13)
	if rest := mantissa & 0x1fff; rest > 0x1000 || rest == 0x1000 && half&1 == 1 {
		half++
	}
	return half
}

var grepFloat16Table = sync.OnceValue(func() []float32 {
	table := make([]float32, 1<<16)
	for i := range table {
		h := uint32(i)
		sign, exponent, mantissa := h>>15<<31, h>>10&0x1f, h&0x3ff
		switch exponent {
		case 0:
			table[i] = math.Float32frombits(sign | math.Float32bits(float32(mantissa)/(1<<24)))
		case 31:
			table[i] = math.Float32frombits(sign | 0x7f800000 | mantissa<<13)
		default:
			table[i] = math.Float32frombits(sign | (exponent+112)<<23 | mantissa<<13)
		}
	}
	return table
})

// 형식: magic, body의 SHA-256, body. body는 길이를 앞에 붙인 Root·Model·Revision, 항목 수, 항목(32바이트 key와 half 384개)이다.
func grepSemanticRead(path, root string) (*grepSemanticIndex, error) {
	invalid := errors.New(T("grep.semantic.invalid"))
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, grepSemanticMaxBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) < 36 || len(data) > grepSemanticMaxBytes || string(data[:4]) != grepSemanticMagic {
		return nil, invalid
	}
	body := data[36:]
	if sum := sha256.Sum256(body); !bytes.Equal(data[4:36], sum[:]) {
		return nil, invalid
	}
	index := grepSemanticIndex{Version: grepSemanticVersion}
	for _, field := range []*string{&index.Root, &index.Model, &index.Revision} {
		if len(body) < 2 || len(body) < 2+int(binary.LittleEndian.Uint16(body)) {
			return nil, invalid
		}
		n := int(binary.LittleEndian.Uint16(body))
		*field = string(body[2 : 2+n])
		body = body[2+n:]
	}
	if len(body) < 4 {
		return nil, invalid
	}
	count := int(binary.LittleEndian.Uint32(body))

	body = body[4:]
	const entry = 32 + grepSemanticDimensions*2
	if index.Root != root || index.Model != grepSemanticModel || index.Revision == "" || len(body) != count*entry {
		return nil, invalid
	}
	halves := grepFloat16Table()
	values := make([]float32, count*grepSemanticDimensions)
	index.Vectors = make(map[string][]float32, count)
	for i := 0; i < count; i++ {
		record := body[i*entry : (i+1)*entry]
		vector := values[i*grepSemanticDimensions : (i+1)*grepSemanticDimensions : (i+1)*grepSemanticDimensions]
		for d := range vector {
			x := halves[binary.LittleEndian.Uint16(record[32+d*2:])]
			if math.IsNaN(float64(x)) || math.IsInf(float64(x), 0) {
				return nil, invalid
			}
			vector[d] = x
		}
		index.Vectors[hex.EncodeToString(record[:32])] = vector
	}
	if len(index.Vectors) != count {
		return nil, invalid
	}
	return &index, nil
}

func grepSemanticMarshal(index *grepSemanticIndex) ([]byte, error) {
	keys := make([]string, 0, len(index.Vectors))
	for key := range index.Vectors {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	data := make([]byte, 36, 36+3*2+len(index.Root)+len(index.Model)+len(index.Revision)+4+len(keys)*(32+grepSemanticDimensions*2))
	for _, field := range []string{index.Root, index.Model, index.Revision} {
		if len(field) > math.MaxUint16 {
			return nil, errors.New("semantic index field too long")
		}
		data = binary.LittleEndian.AppendUint16(data, uint16(len(field)))
		data = append(data, field...)
	}
	data = binary.LittleEndian.AppendUint32(data, uint32(len(keys)))
	for _, key := range keys {
		raw, err := hex.DecodeString(key)
		vector := index.Vectors[key]
		if err != nil || len(raw) != 32 || len(vector) != grepSemanticDimensions {
			return nil, fmt.Errorf("invalid semantic index entry %q", key)
		}
		data = append(data, raw...)
		for _, x := range vector {
			data = binary.LittleEndian.AppendUint16(data, grepFloat16(x))
		}
	}
	sum := sha256.Sum256(data[36:])
	copy(data, grepSemanticMagic)
	copy(data[4:], sum[:])
	return data, nil
}

func grepSemanticSave(path string, index *grepSemanticIndex) error {
	data, err := grepSemanticMarshal(index)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return err
	}
	f, err := os.CreateTemp(dir, ".semantic-*")
	if err != nil {
		return err
	}
	name := f.Name()
	defer os.Remove(name)
	if err := f.Chmod(0600); err != nil {
		f.Close()
		return err
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(name, path)
}

func grepSemanticLock(path string) (func(), error) {
	return grepFileLock(path, syscall.LOCK_EX)
}

func grepFileLock(path string, mode int) (func(), error) {
	if err := os.MkdirAll(filepath.Dir(path), 0700); err != nil {
		return nil, err
	}
	file, err := os.OpenFile(path+".lock", os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(file.Fd()), mode); err != nil {
		file.Close()
		return nil, err
	}
	return func() { syscall.Flock(int(file.Fd()), syscall.LOCK_UN); file.Close() }, nil
}

func grepSemanticSync(root string, chunks []grepAskChunk, index *grepSemanticIndex, query string, progress io.Writer) ([]float32, int, bool, error) {
	texts := []string{}
	if query != "" {
		texts = append(texts, query)
	}
	missing := []string{}
	active := map[string]bool{}
	queued := map[string]bool{}
	for _, chunk := range chunks {
		key := grepSemanticKey(root, chunk)
		active[key] = true
		if _, ok := index.Vectors[key]; !ok && !queued[key] {
			queued[key] = true
			absolute, _ := filepath.Abs(chunk.result.Path)
			path, _ := filepath.Rel(root, absolute)
			text := strings.Join(chunk.lines, "\n")
			if runes := []rune(text); len(runes) > 3000 {
				text = string(runes[:3000])
			}
			texts = append(texts, filepath.ToSlash(path)+"\n"+text)
			missing = append(missing, key)
		}
	}
	if len(texts) == 0 {
		texts = append(texts, "initialize")
	}
	encoded, err := grepSemanticEncode(texts, progress)
	if err != nil {
		return nil, 0, false, err
	}
	if encoded.Revision == "" || (index.Revision != "" && index.Revision != encoded.Revision) {
		return nil, 0, false, errors.New(T("grep.semantic.invalid"))

	}
	index.Revision = encoded.Revision
	vectors := encoded.Vectors
	if len(vectors) != len(texts) {
		return nil, 0, false, errors.New("embedding count mismatch")
	}
	changed := len(missing) > 0 || len(index.Vectors) != len(active)
	offset := 0
	var queryVector []float32
	if query != "" {
		queryVector = vectors[0]
		offset = 1
	} else if len(missing) == 0 {
		offset = 1
	}
	for i, key := range missing {
		index.Vectors[key] = vectors[i+offset]
	}
	for key := range index.Vectors {
		if !active[key] {
			delete(index.Vectors, key)
		}
	}
	return queryVector, len(missing), changed, nil
}

func grepSemanticVerify(root string, chunks []grepAskChunk, options grepOptions) error {
	current, _, problems := grepAskCollect([]string{root}, options)
	if len(problems) > 0 {
		return fmt.Errorf("%s: %s", T("grep.semantic.changed"), strings.Join(problems, "; "))
	}
	if len(current) != len(chunks) {
		return errors.New(T("grep.semantic.changed"))
	}
	type snapshotKey struct {
		content    string
		start, end int
	}
	seen := make(map[snapshotKey]int, len(chunks))
	for _, chunk := range chunks {
		seen[snapshotKey{grepSemanticKey(root, chunk), chunk.result.Start, chunk.result.End}]++
	}
	for _, chunk := range current {
		key := snapshotKey{grepSemanticKey(root, chunk), chunk.result.Start, chunk.result.End}
		seen[key]--
		if seen[key] < 0 {
			return errors.New(T("grep.semantic.changed"))
		}
	}
	return nil
}

func grepSemanticRank(paths []string, options grepOptions, chunks []grepAskChunk, stderr io.Writer) ([]grepAskResult, error) {
	root, err := grepSemanticRoot(paths)
	if err != nil {
		return nil, err
	}
	path, err := grepSemanticPath(root)
	if err != nil {
		return nil, err
	}
	if _, err := os.Stat(path); err != nil {
		return nil, fmt.Errorf("%s: %w", T("grep.semantic.init_required"), err)
	}
	unlock, err := grepSemanticLock(path)
	if err != nil {
		return nil, err
	}
	defer unlock()
	index, err := grepSemanticRead(path, root)
	if err != nil {
		return nil, err
	}
	fmt.Fprintln(stderr, T("grep.semantic.loading"))
	query, embedded, changed, err := grepSemanticSync(root, chunks, index, options.pattern, stderr)
	if err != nil {
		return nil, err
	}
	// 벡터는 경로와 내용으로 키를 만든다. 그래서 내용이 바뀐 사이에 벡터가 잘못 짝지어지는 경우는 새로 임베딩한 청크뿐이다.
	if embedded > 0 {
		if err := grepSemanticVerify(root, chunks, options); err != nil {
			return nil, err
		}
	}

	if changed {
		if err := grepSemanticSave(path, index); err != nil {
			return nil, err
		}
	}
	return grepSemanticScore(root, options, chunks, index, query), nil
}

func grepSemanticRankAuto(root string, options grepOptions, chunks []grepAskChunk, stderr io.Writer) ([]grepAskResult, error) {
	candidates, err := grepSemanticPrepareAuto(root, options, chunks, stderr)
	if err != nil {
		return nil, err
	}
	return grepSemanticScoreCandidates(options, candidates), nil
}

func grepSemanticFileIdentity(path string) string {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return filepath.Clean(path)
	}
	canonical, err := filepath.EvalSymlinks(absolute)
	if err != nil {
		return filepath.Clean(absolute)
	}
	return filepath.Clean(canonical)
}

func grepSemanticPrepareAuto(root string, options grepOptions, chunks []grepAskChunk, stderr io.Writer) ([]grepSemanticCandidate, error) {
	path, err := grepSemanticPath(root)
	if err != nil {
		return nil, err
	}
	unlock, err := grepSemanticLock(path)
	if err != nil {
		return nil, err
	}
	defer unlock()
	index, err := grepSemanticRead(path, root)
	if err != nil {
		index = &grepSemanticIndex{Version: grepSemanticVersion, Root: root, Model: grepSemanticModel, Vectors: map[string][]float32{}}
	}
	fmt.Fprintln(stderr, T("grep.semantic.loading"))
	query, embedded, changed, err := grepSemanticSync(root, chunks, index, options.pattern, stderr)
	if err != nil {
		return nil, err
	}
	if embedded > 0 {
		if err := grepSemanticVerify(root, chunks, options); err != nil {
			return nil, err
		}
	}
	if changed {
		if err := grepSemanticSave(path, index); err != nil {
			return nil, err
		}
	}
	candidates := make([]grepSemanticCandidate, 0, len(chunks))
	for _, chunk := range chunks {
		candidates = append(candidates, grepSemanticCandidate{root: root, chunk: chunk, index: index, query: query})

	}
	return candidates, nil
}

func grepSemanticScore(root string, options grepOptions, chunks []grepAskChunk, index *grepSemanticIndex, query []float32) []grepAskResult {
	candidates := make([]grepSemanticCandidate, 0, len(chunks))
	for _, chunk := range chunks {
		candidates = append(candidates, grepSemanticCandidate{root: root, chunk: chunk, index: index, query: query})
	}
	return grepSemanticScoreCandidates(options, candidates)
}

func grepSemanticSourcePrior(query, path string) float64 {
	queryTerms := make(map[string]bool)
	for _, term := range grepAskTokens(query) {
		queryTerms[term] = true
	}
	path = filepath.ToSlash(strings.ToLower(path))
	special := false
	for term := range queryTerms {
		if term == "test" || term == "tests" || term == "testing" || term == "docs" || term == "doc" || term == "readme" || term == "locale" || term == "i18n" || term == "linux" || term == "darwin" || term == "windows" || term == "platform" || term == "testdata" {
			special = true
			break
		}
	}
	if special {
		return 1
	}
	if strings.HasSuffix(path, "_test.go") || strings.Contains(path, "/testdata/") || strings.Contains(path, "/locale/") || filepath.Base(path) == "readme.md" || strings.HasSuffix(path, "_linux.go") || strings.HasSuffix(path, "_darwin.go") || strings.HasSuffix(path, "_windows.go") {
		return 0
	}
	return 1
}

func grepSemanticScoreCandidates(options grepOptions, candidates []grepSemanticCandidate) []grepAskResult {
	type chunkID struct {
		path       string
		start, end int
	}
	chunkIDLess := func(left, right chunkID) bool {
		if left.path != right.path {
			return left.path < right.path
		}
		if left.start != right.start {
			return left.start < right.start
		}
		return left.end < right.end
	}
	chunks := make([]grepAskChunk, 0, len(candidates))
	for _, candidate := range candidates {
		chunks = append(chunks, candidate.chunk)
	}
	keywordResults := grepAskScore(options.pattern, chunks)
	keywordRank := make(map[chunkID]int, len(keywordResults))
	for rank, result := range keywordResults {
		keywordRank[chunkID{result.Path, result.Start, result.End}] = rank + 1
	}
	type scoredChunk struct {
		grepAskResult
		lines    []string
		fileID   string
		rankID   chunkID
		semantic float64
		exact    float64
		source   float64
	}

results := make([]scoredChunk, 0, len(candidates))
for _, candidate := range candidates {
	chunk := candidate.chunk
	vector := candidate.index.Vectors[grepSemanticKey(candidate.root, chunk)]
	semantic := 0.0
	for i, x := range candidate.query {
		if i < len(vector) {
			semantic += float64(x) * float64(vector[i])
		}
	}
	exact := 0.0
	for _, term := range grepAskTokens(options.pattern) {
		if chunk.terms[term] > 0 {
			exact += 1
		}
		for _, pathTerm := range grepAskTokens(chunk.rankPath) {
			if term == pathTerm {
				exact += 0.5
			}
		}
	}
	result := chunk.result
	for _, candidate := range candidates {
		if candidate.chunk.result.Path == chunk.result.Path && candidate.chunk.result.Start == chunk.result.Start && candidate.chunk.result.End == chunk.result.End {
			if candidate.displayPath != "" {
				result.Path = candidate.displayPath
			}
			break
		}
	}
	rankID := chunkID{path: chunk.result.Path, start: chunk.result.Start, end: chunk.result.End}
	results = append(results, scoredChunk{grepAskResult: result, lines: chunk.lines, fileID: grepSemanticFileIdentity(chunk.result.Path), rankID: rankID, semantic: semantic, exact: exact, source: grepSemanticSourcePrior(options.pattern, result.Path)})

}
semanticOrder := append([]scoredChunk(nil), results...)
sort.Slice(semanticOrder, func(i, j int) bool {
	if semanticOrder[i].semantic != semanticOrder[j].semantic {
		return semanticOrder[i].semantic > semanticOrder[j].semantic
	}
	return chunkIDLess(semanticOrder[i].rankID, semanticOrder[j].rankID)
})
semanticRank := make(map[chunkID]int, len(semanticOrder))
for rank, result := range semanticOrder {
	semanticRank[result.rankID] = rank + 1
}
exactOrder := append([]scoredChunk(nil), results...)
sort.Slice(exactOrder, func(i, j int) bool {
	if exactOrder[i].exact != exactOrder[j].exact {
		return exactOrder[i].exact > exactOrder[j].exact
	}
	return chunkIDLess(exactOrder[i].rankID, exactOrder[j].rankID)
})
exactRank := make(map[chunkID]int, len(exactOrder))
for rank, result := range exactOrder {
	if result.exact > 0 {
		exactRank[result.rankID] = rank + 1
	}
}
for i := range results {
	id := results[i].rankID
	score := 0.45 / (60 + float64(semanticRank[id]))
	if rank := keywordRank[id]; rank > 0 {
		score += 0.35 / (60 + float64(rank))
	}
	if rank := exactRank[id]; rank > 0 {

		score += 0.10 / (60 + float64(rank))
	}
	score += 0.20 * results[i].source
	results[i].Score = score
}
sort.Slice(results, func(i, j int) bool {
	if results[i].Score != results[j].Score {
		return results[i].Score > results[j].Score
	}
	if results[i].rankID.path != results[j].rankID.path {
		return results[i].rankID.path < results[j].rankID.path
	}
	if results[i].rankID.start != results[j].rankID.start {
		return results[i].rankID.start < results[j].rankID.start
	}
	return results[i].rankID.end < results[j].rankID.end
})
selected := make([]grepAskResult, 0, min(options.askLimit, len(results)))
type interval struct{ start, end int }
selectedIntervals := map[string][]interval{}
for _, r := range results {
	overlaps := false
	for _, selectedInterval := range selectedIntervals[r.fileID] {
		if r.Start <= selectedInterval.end && selectedInterval.start <= r.End {
			overlaps = true
			break
		}
	}
	if overlaps {
		continue
	}
	terms := make(map[string]bool)

		for _, term := range grepAskTokens(options.pattern) {
			terms[term] = true
		}
		anchor := 0
		for i, line := range r.lines {
			for _, term := range grepAskTokens(line) {
				if terms[term] {
					anchor = i
					break
				}
			}
		}
		start := max(0, anchor-1)
		lines := append([]string(nil), r.lines[start:min(len(r.lines), start+3)]...)
		for i, line := range lines {
			runes := []rune(line)
			if len(runes) > 300 {
				lines[i] = string(runes[:300]) + "…"
			}
		}
		r.Snippet = strings.Join(lines, "\n")
		selected = append(selected, r.grepAskResult)
		selectedIntervals[r.fileID] = append(selectedIntervals[r.fileID], interval{start: r.Start, end: r.End})
		if len(selected) == options.askLimit {
			break
		}
	}
	return selected
}

func grepSemanticLifecycle(args []string, stdout, stderr io.Writer) int {
	return grepSemanticLifecycleWithInput(args, os.Stdin, isTerminal(os.Stdin), stdout, stderr)
}

func grepSemanticLifecycleWithInput(args []string, input io.Reader, terminal bool, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		return 2
	}
	rootArg := "."
	rootSet, yes := false, false
	for _, arg := range args[1:] {
		if arg == "--yes" {
			if yes || args[0] != "--semantic-init" {
				fmt.Fprintln(stderr, T("grep.semantic.usage"))
				return 2
			}
			yes = true
			continue
		}
		if strings.HasPrefix(arg, "-") || rootSet || args[0] == "--model-clear" {
			fmt.Fprintln(stderr, T("grep.semantic.usage"))
			return 2
		}
		rootArg, rootSet = arg, true
	}
	if args[0] == "--model-clear" {
		dir, err := grepModelDir()
		if err != nil {
			fmt.Fprintln(stderr, err)
			return 2
		}
		if _, err := os.Lstat(dir); os.IsNotExist(err) {
			fmt.Fprintln(stdout, T("grep.model.cleared"))
			return 0
		} else if err != nil {
			fmt.Fprintln(stderr, err)

		return 2
	}
	unlock, err := grepModelLock()
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	defer unlock()
	if err := os.RemoveAll(dir); err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	fmt.Fprintln(stdout, T("grep.model.cleared"))
	return 0
}
root, err := grepSemanticRoot([]string{rootArg})
if err != nil {
	fmt.Fprintln(stderr, err)
	return 2
}
path, err := grepSemanticPath(root)
if err != nil {
	fmt.Fprintln(stderr, err)
	return 2
}
if args[0] == "--semantic-files" {
	return grepSemanticFiles(root, path, stdout, stderr)
}
if args[0] == "--semantic-status" {
	dir, modelErr := grepModelDir()
	if modelErr == nil {
		modelErr = grepModelCheck(dir)

	}
	if modelErr != nil {
		fmt.Fprintln(stdout, T("grep.model.status_missing"))
	} else {
		fmt.Fprintln(stdout, T("grep.model.status_ready", dir))
	}
	info, err := os.Stat(path)
	if os.IsNotExist(err) {
		fmt.Fprintln(stderr, T("grep.semantic.init_required"))
		return 1
	}
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	index, err := grepSemanticRead(path, root)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	fmt.Fprintf(stdout, "%s @ %s: %d chunks, %s (%d bytes)\n", index.Model, index.Revision, len(index.Vectors), path, info.Size())
	return 0
}
if args[0] == "--semantic-clear" {
	if _, err := os.Stat(path); os.IsNotExist(err) {
		fmt.Fprintln(stdout, T("grep.semantic.cleared"))
		return 0
	} else if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	unlock, err := grepSemanticLock(path)

	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	defer unlock()
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		fmt.Fprintln(stderr, err)
		return 2
	}
	fmt.Fprintln(stdout, T("grep.semantic.cleared"))
	return 0
}
chunks, skipped, problems := grepAskCollect([]string{root}, grepOptions{})
if len(problems) > 0 {
	for _, problem := range problems {
		fmt.Fprintln(stderr, T("grep.failed", problem))
	}
	return 2
}
if skipped > 0 {
	fmt.Fprintln(stderr, T("grep.ask.skipped", skipped))
}
if err := grepSemanticEnsure(input, terminal, yes, stderr); err != nil {
	if errors.Is(err, errGrepModelCancelled) {
		fmt.Fprintln(stderr, T("grep.model.cancelled"))
		return 4
	}
	fmt.Fprintln(stderr, err)
	return 2
}
unlock, err := grepSemanticLock(path)
if err != nil {

		fmt.Fprintln(stderr, err)
		return 2
	}
	defer unlock()
	index := &grepSemanticIndex{Version: grepSemanticVersion, Root: root, Model: grepSemanticModel, Vectors: map[string][]float32{}}

	fmt.Fprintln(stderr, T("grep.semantic.loading"))
	if _, _, _, err = grepSemanticSync(root, chunks, index, "", stderr); err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	if err = grepSemanticVerify(root, chunks, grepOptions{}); err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	if err = grepSemanticSave(path, index); err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	fmt.Fprintf(stdout, "%s: %d chunks, %s\n", grepSemanticModel, len(chunks), path)
	return 0
}

// grepSemanticFiles는 지금 수집되는 파일마다 index에 든 청크 수와 전체 청크 수를 보여 준다. index에는 경로가 없어 수집을 다시 한다.
func grepSemanticFiles(root, path string, stdout, stderr io.Writer) int {
	if _, err := os.Stat(path); os.IsNotExist(err) {
		fmt.Fprintln(stderr, T("grep.semantic.init_required"))
		return 1
	}
	index, err := grepSemanticRead(path, root)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 2
	}
	chunks, _, problems := grepAskCollect([]string{root}, grepOptions{})
	for _, problem := range problems {
		fmt.Fprintln(stderr, T("grep.failed", problem))
	}
	if len(problems) > 0 {
		return 2
	}
	type fileChunks struct{ indexed, total int }
	files := map[string]*fileChunks{}
	var names []string
	for _, chunk := range chunks {
		file := files[chunk.rankPath]
		if file == nil {
			file = &fileChunks{}
			files[chunk.rankPath] = file
			names = append(names, chunk.rankPath)
		}
		file.total++
		if _, ok := index.Vectors[grepSemanticKey(root, chunk)]; ok {
			file.indexed++
		}

	}
	sort.Strings(names)
	terminal := false
	if file, ok := stdout.(*os.File); ok {
		terminal = isTerminal(file)
	}
	for _, name := range names {
		file := files[name]
		// 탭과 줄바꿈이 든 경로가 줄과 열을 나누지 않도록 Go 문자열로 감싼다.
		if strings.ContainsRune(name, '"') || strings.IndexFunc(name, unicode.IsControl) >= 0 {
			name = strconv.Quote(name)
		}
		if terminal {
			name = viewSanitize(name)
		}
		if _, err := fmt.Fprintf(stdout, "%d/%d\t%s\n", file.indexed, file.total, name); err != nil {
			fmt.Fprintln(stderr, err)
			return 2
		}
	}
	return 0
}

