func printHistoryPruneHelp(output io.Writer) {
	color := helpColor(output)
	width := 80
	if color {
		width = min(width, terminalWidth())
	}
	renderHistoryPruneHelp(output, max(20, width), color)
}

func renderHistoryPruneHelp(output io.Writer, width int, color bool) {
	render := helpRenderer{output: output, width: width, color: color}
	renderHelpHeader(output, "history prune", T("command.history.sub.prune"), width, color)
	render.panel(T("help.usage_label"), func() {
		for _, line := range []string{"edc history prune [--older-than <age>] [options] [<DB>]", "edc history prune --older-than <age> --dry-run [<DB>]", "edc history prune --older-than <age> --yes [--vacuum] [<DB>]"} {
			render.syntax(line)
		}
	})
	render.panel(T("help.examples_label"), func() {
		for _, line := range []string{"edc history prune", "edc history prune --older-than 30d --dry-run", "edc history prune --older-than 90d --command top"} {
			render.syntax(line)
		}
	})
	render.panel(T("help.options_label"), func() {
		render.options([]optionDoc{{"--older-than <age>", "history.option.older_than"}, {"--command <top|snapshot>", "history.option.prune_command"}, {"--dry-run", "history.option.dry_run"}, {"--yes", "history.option.yes"}, {"--vacuum", "history.option.vacuum"}})
	})
	for _, group := range []struct {
		title string
		notes []string
	}{{"interactive_title", []string{"retention", "keys", "period"}}, {"deletion_title", []string{"confirm", "recheck", "vacuum"}}, {"storage_title", []string{"storage"}}} {
		render.panel(T("history.prune_help."+group.title), func() {
			for _, key := range group.notes {
				render.note(T("history.prune_help." + key))
			}
			if group.title == "storage_title" {
				if path, err := defaultHistoryPath(); err == nil {
					render.note(T("history.database_path", "`"+reportIdentityValue(path)+"`"))
				}
			}
		})
	}
}

func TestHistoryPruneHelpGroupsRelevantContentAndFitsWidth(t *testing.T) {
	restore := currentLanguage()
	defer setLanguage(restore)
	for _, language := range []string{"en", "ko", "ja"} {
		setLanguage(language)
		for _, width := range []int{40, 64, 80, 88} {
			var plain, colored strings.Builder
			renderHistoryPruneHelp(&plain, width, false)
			renderHistoryPruneHelp(&colored, width, true)
			plainBody := plain.String()[strings.Index(plain.String(), "\n\n")+2:]
			stripped := ansi.Strip(colored.String())
			coloredBody := stripped[strings.Index(stripped, "\n\n")+2:]
			coloredBody = strings.ReplaceAll(coloredBody, "│ ", "  ")
			var bodyLines []string
			for _, line := range strings.Split(coloredBody, "\n") {
				if strings.HasPrefix(line, "╭─ ") {
					bodyLines = append(bodyLines, strings.TrimSuffix(strings.TrimPrefix(line, "╭─ "), " ───"))
				} else if line != "╰─" {
					bodyLines = append(bodyLines, line)
				}
			}
			if strings.Join(bodyLines, "\n") != plainBody {
				t.Fatalf("plain/color help differs at %s/%d", language, width)
			}
			if strings.Contains(plain.String(), "`") || strings.Contains(plain.String(), "\x1b[") {
				t.Fatal("plain help contains formatting markup")
			}
			for _, line := range strings.Split(colored.String(), "\n") {
				if liveWidth(line) > width {
					t.Fatalf("help line exceeds %s/%d: %q", language, width, line)
				}
			}

			for _, key := range []string{"help.usage_label", "help.options_label", "history.prune_help.interactive_title", "history.prune_help.deletion_title", "history.prune_help.storage_title"} {
				if !strings.Contains(plain.String(), T(key)) {
					t.Fatalf("missing help section %s", key)
				}
			}
			for _, unrelated := range []string{"--probe", "--metric", "--process", "PSI"} {
				if strings.Contains(plain.String(), unrelated) {
					t.Fatalf("prune help contains unrelated option %s", unrelated)
				}
			}
		}
	}
}

