		fmt.Fprintln(os.Stderr, T("history.usage"))
		return 2
	}
	command := args[0]
	if len(args) > 1 && (args[1] == "--help" || args[1] == "-h") {
		if command == "prune" {
			printHistoryPruneHelp(os.Stdout)
