// 샘플 간격이 보존 기간보다 길면 기록 중인 실행의 마지막 샘플도 보존 기간보다 오래되어 지워질 수 있다. 실제 기준은
// 샘플 두 번 사이보다 짧아지지 않는다. 대시보드는 실행 중에 간격을 topMaxInterval까지 늘릴 수 있다.
func TestHistoryRetentionAgeOutlastsTwoSamples(t *testing.T) {
