const (
	// defaultLanguage는 설정이 없을 때 쓰는 언어다.
	defaultLanguage = "en"
	// languageEnv는 config 파일보다 우선한다. 한 번만 다른 언어로 보고 싶을 때 쓴다.
	languageEnv = "EDC_LANG"
)

// catalog는 언어 하나의 메시지 나무다. 키는 점으로 계층을 나눈다.
type catalog struct {
	language string
	tree     map[string]interface{}
	mu       *sync.RWMutex
	files    map[string]*sync.Once
}

var (
	catalogOnce sync.Once
	catalogs    map[string]catalog
	activeLang  = defaultLanguage
)

func loadCatalogs() {
	catalogOnce.Do(func() {
		catalogs = make(map[string]catalog, len(supportedLanguages))
		for _, language := range supportedLanguages {
			paths, err := fs.Glob(localeFiles, "locale/"+language+"/*.yaml")
			if err != nil {
				continue
			}
			files := make(map[string]*sync.Once, len(paths))
			for _, path := range paths {
				files[strings.TrimSuffix(filepath.Base(path), ".yaml")] = new(sync.Once)
			}
			catalogs[language] = catalog{language: language, tree: map[string]interface{}{}, mu: new(sync.RWMutex), files: files}
		}
	})
}

func (c catalog) loadFile(name string) {
	if name == "history" {
		c.loadFile("help")
	}
	once := c.files[name]
	if once == nil {
		return
	}
	once.Do(func() {
		data, err := localeFiles.ReadFile("locale/" + c.language + "/" + name + ".yaml")
		if err != nil {
			return
		}
		var part map[string]interface{}
		if err := yaml.Unmarshal(data, &part); err != nil {
			return
		}
		c.mu.Lock()
		defer c.mu.Unlock()
		mergeTree(c.tree, part)
	})
}

// mergeTree는 나무 둘을 깊이 합친다. 같은 키가 겹치면 나중에 읽은 파일이 이긴다.
func mergeTree(into, from map[string]interface{}) {
	for key, value := range from {
		branch, isBranch := value.(map[string]interface{})
		if !isBranch {
			into[key] = value
			continue
		}
		existing, ok := into[key].(map[string]interface{})
		if !ok {
			existing = map[string]interface{}{}
			into[key] = existing
		}
		mergeTree(existing, branch)
	}
}

// initLanguage는 환경변수와 config 파일을 보고 쓸 언어를 정한다.
// 우선순위는 EDC_LANG, config의 lang, 그리고 기본값 en이다.
func initLanguage() {
	loadCatalogs()
	activeLang = resolveLanguage(os.Getenv(languageEnv), readConfigLanguage())
}

// resolveLanguage는 두 후보에서 쓸 언어를 고른다.
// 환경을 읽지 않는 순수 함수라 test가 사용자의 실제 설정에 기대지 않는다.
func resolveLanguage(fromEnv, fromConfig string) string {
	if language, ok := normalizeLanguage(fromEnv); ok {
		return language
	}
	if language, ok := normalizeLanguage(fromConfig); ok {
		return language
	}
	return defaultLanguage
}

// normalizeLanguage는 ko_KR.UTF-8 같은 값에서 앞의 언어 코드만 본다.
func normalizeLanguage(value string) (string, bool) {
	value = strings.TrimSpace(strings.ToLower(value))
	if value == "" {
		return "", false
	}
	for _, separator := range []string{".", "_", "-"} {
		if index := strings.Index(value, separator); index > 0 {
			value = value[:index]
		}
	}
	for _, language := range supportedLanguages {
		if value == language {
			return language, true
		}
	}
	return "", false
}

func currentLanguage() string {
	loadCatalogs()
	return activeLang
}

// setLanguage는 test가 언어를 바꿔 볼 때 쓴다.
func setLanguage(language string) {
	loadCatalogs()
	if _, ok := catalogs[language]; ok {
		activeLang = language
	}
}

func (c catalog) lookup(key string) (interface{}, bool) {
	section, _, _ := strings.Cut(key, ".")
	switch section {
	case "command":
		c.loadFile("help")
		c.loadFile("history")
	case "help", "option":
		c.loadFile("help")
	default:
		c.loadFile(section)
	}
	if c.mu != nil {
		c.mu.RLock()
		defer c.mu.RUnlock()
	}
	var current interface{} = c.tree
	for _, part := range strings.Split(key, ".") {
		branch, ok := current.(map[string]interface{})
		if !ok {
			return nil, false
		}
		current, ok = branch[part]
		if !ok {
			return nil, false
		}
	}
	return current, true
}

func (c catalog) text(key string) (string, bool) {
	value, ok := c.lookup(key)
	if !ok {
		return "", false
	}
	text, ok := value.(string)
	return text, ok
}

func (c catalog) list(key string) ([]string, bool) {
	value, ok := c.lookup(key)
	if !ok {
		return nil, false
	}
	items, ok := value.([]interface{})
	if !ok {
		return nil, false
	}
	result := make([]string, 0, len(items))
	for _, item := range items {
		text, ok := item.(string)
		if !ok {
			return nil, false
		}
		result = append(result, text)
	}
	return result, true
}

// T는 키의 메시지를 현재 언어로 돌려준다.
// 번역이 없으면 영어로 내려가고, 영어에도 없으면 키를 그대로 보여 준다.
// 키가 화면에 보이면 번역이 빠졌다는 뜻이므로 조용히 넘어가지 않는다.
func T(key string, args ...interface{}) string {
	loadCatalogs()
	text, ok := catalogs[activeLang].text(key)
	if !ok {
		text, ok = catalogs[defaultLanguage].text(key)
	}
	if !ok {
		return key
	}
	if len(args) == 0 {
		return text
	}
	return fmt.Sprintf(text, args...)
}

