// catalogKeys는 언어 하나가 가진 모든 키를 평탄하게 편다.
func catalogKeys(language string) []string {
	loadCatalogs()
	c := catalogs[language]
	var files []string
	for name := range c.files {
		files = append(files, name)
	}
	sort.Strings(files)
	for _, name := range files {
		c.loadFile(name)
	}
	if c.mu != nil {
		c.mu.RLock()
		defer c.mu.RUnlock()
	}
	var keys []string
	var walk func(prefix string, node interface{})
	walk = func(prefix string, node interface{}) {
		branch, ok := node.(map[string]interface{})
		if !ok {
			keys = append(keys, prefix)
			return
		}
		for name, child := range branch {
			next := name
			if prefix != "" {
				next = prefix + "." + name
			}
			walk(next, child)
		}
	}

func configPath() string {
	directory, err := os.UserConfigDir()
	if err != nil && runtime.GOOS != "darwin" {
		return ""
	}
	home, _ := os.UserHomeDir()
	return configPathFor(runtime.GOOS, directory, home, os.Getenv("XDG_CONFIG_HOME"))
}

func configPathFor(platform, userConfigDirectory, home, xdgConfigHome string) string {
	directory := userConfigDirectory
	if platform == "darwin" {
		if filepath.IsAbs(xdgConfigHome) {
			directory = xdgConfigHome
		} else if home != "" {
			directory = filepath.Join(home, ".config")
		} else {
			return ""
		}
	}
	if directory == "" {
		return ""
	}
	return filepath.Join(directory, "edc", "config.toml")
}

// readConfigLanguage는 설정 파일의 lang을 읽는다.
// 파일이 없거나 읽지 못하면 빈 값을 주고, 다음 단계가 기본값을 쓴다.
func readConfigLanguage() string { return readConfigLanguageAt(configPath()) }

// readConfigLanguageAt은 경로를 받아 읽는다.
// os.UserConfigDir은 macOS에서 XDG_CONFIG_HOME을 보지 않으므로,
// test가 환경변수로 격리하려 하면 개발자의 실제 설정을 읽게 된다. 경로를 넘겨 그 문제를 없앤다.
func readConfigLanguageAt(path string) string {
	path = configReadPath(path)
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() || info.Size() > maxConfigBytes {
		return ""
	}
	file, err := os.Open(path)
	if err != nil {
		return ""
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxConfigBytes+1))
	if err != nil || len(data) > maxConfigBytes {
		return ""
	}
	var header struct {
		Lang string `yaml:"lang" toml:"lang"`
	}
	if filepath.Ext(path) == ".toml" {
		if err := toml.Unmarshal(data, &header); err != nil {
			return ""
		}
	} else {
		if err := yaml.Unmarshal(data, &header); err != nil {
			return ""
		}
	}
	return header.Lang
}

// 언어팩이 갈라지면 어떤 언어에서만 키가 보인다. 세 파일이 같은 키를 갖는지 잰다.
