// formatListenTable은 포트를 앞에 두고 그 포트를 잡은 프로세스를 함께 그린다. 이 명령에 사람이 묻는
// 것이 "어느 포트가 열려 있나"이므로 포트가 첫 열이다.
//
// detail은 열을 더 여는 것일 뿐 줄을 늘리거나 줄이지 않는다. -v가 목록 자체를 바꾸면 -v를 준 화면과
// 주지 않은 화면이 다른 사실을 말하게 된다.
//
// note가 있으면 각 행 아래에 명령줄을 note로 칠한 줄로 붙인다. 명령줄은 길이가 process마다 크게 달라 열로
// 두면 표 폭이 가장 긴 명령줄을 따라간다.
func formatListenTable(sockets []listenSocket, detail bool, note func(string) string) string {
	headers := []string{T("observe.listen.column.port"), T("observe.listen.column.proto"), T("observe.listen.column.address"), T("observe.listen.column.scope"), T("observe.listen.column.process")}
	if detail {
		headers = append(headers, T("observe.listen.column.user"), T("observe.listen.column.fd"), T("observe.listen.column.queue"))
	}
	home, _ := os.UserHomeDir()
	rows := make([][]string, 0, len(sockets))
	commands := make([]string, 0, len(sockets))
	for _, socket := range sockets {
		if note != nil {
			commands = append(commands, listenCommandLine(socket, home))
		}
		process := socket.Process
		if socket.PID != "" {
			process += " (" + socket.PID + ")"
		}
		port := strconv.Itoa(socket.Port)
		if socket.Port == 0 {
			// 유닉스 소켓은 포트가 없다. 빈 칸 대신 없음을 그대로 적는다.
			port = "-"
		}
		row := []string{port, socket.Proto, socket.Address, T("observe.listen.scope." + listenBindingScope(socket.Proto, socket.Address)), process}
		if detail {
			row = append(row, listenCell(socket.User), listenCell(socket.FD), listenQueueCell(socket))

// listenMaskArgs는 명령줄의 비밀 값을 가린다. listen 출력은 이슈와 history에 그대로 옮겨지는 일이 많아서
// --redact를 주지 않아도 가린다. 이름에 비밀을 뜻하는 낱말이 든 옵션의 값과 URL의 암호가 대상이다.
func listenMaskArgs(args []string) []string {
	masked := slices.Clone(args)
	for index := range masked {
		masked[index] = listenURLCredential.ReplaceAllString(masked[index], "${1}***@")
	}
	for index := 1; index < len(masked); index++ {
		arg := masked[index]
		hasValue, secret := listenSecretOption(arg)
		if !secret {
			continue
		}
		if hasValue {
			masked[index] = arg[:strings.IndexByte(arg, '=')+1] + "***"
			continue
		}
		// 값이 -로 시작할 수 있어서(base64url 토큰) 다음 인자가 옵션처럼 보여도 가린다. 불리언 옵션 뒤의 옵션을
		// 가리는 쪽이 비밀을 내보내는 쪽보다 낫다. 가린 인자가 값 없는 비밀 옵션이면 --password --token abc123의
		// abc123처럼 그 값이 남으므로 이어서 가린다.
		for index+1 < len(masked) {
			index++
			next := masked[index]
			masked[index] = "***"
			if hasValue, secret := listenSecretOption(next); !secret || hasValue {
				break
			}
		}
	}
	return masked
}

func (request linuxInetDiagRequest) Serialize() []byte {
	data := make([]byte, linuxInetDiagRequestSize)
	data[0], data[1] = request.family, request.protocol
	binary.NativeEndian.PutUint32(data[4:], request.states)
	return data
}

// collectNetnsListenSockets는 pid가 속한 network namespace의 TCP·UDP 대기 소켓을 읽는다. 자기 network namespace를 가진
// container의 소켓은 그 안에만 있어 host에서 덤프하면 보이지 않는다.
func collectNetnsListenSockets(pid int) ([]listenSocket, error) {
	type dump struct {
		sockets []listenSocket
		err     error
	}
	done := make(chan dump, 1)
	go func() {
		// netlink 소켓은 만든 thread의 namespace에 속한다. 읽은 뒤에는 원래 namespace로 되돌린다. 이 goroutine이 main thread에서
		// 돌면 Go runtime은 그 thread를 끝내지 못하고 남겨 두는데, /proc/self/net과 /proc/net은 main thread의 namespace를 보인다.
		// 되돌리지 않으면 process 전체가 그 뒤로 container의 /proc/net을 읽는다. 되돌리지 못했을 때만 UnlockOSThread 없이 끝내
		// runtime이 그 thread를 버리게 한다.
		runtime.LockOSThread()
		original, err := os.Open("/proc/thread-self/ns/net")
		if err != nil {
			runtime.UnlockOSThread()
			done <- dump{err: err}
			return
		}
		defer original.Close()
		namespace, err := os.Open(filepath.Join("/proc", strconv.Itoa(pid), "ns", "net"))
		if err != nil {
			runtime.UnlockOSThread()
			done <- dump{err: err}
			return
		}
		err = unix.Setns(int(namespace.Fd()), unix.CLONE_NEWNET)
		namespace.Close()
		if err != nil {
			runtime.UnlockOSThread()
			done <- dump{err: fmt.Errorf("setns %s: %w", namespace.Name(), err)}

// readLinuxProcessCommand는 /proc/<pid>/cmdline의 argv와 cwd 링크를 읽는다. 커널 thread는 cmdline이 비고, 다른 계정의
// cwd는 root가 아니면 읽을 수 없어 비운다.
func readLinuxProcessCommand(procRoot, pid string) ([]string, string) {
	directory := filepath.Join(procRoot, pid)
	var args []string
	if data, err := os.ReadFile(filepath.Join(directory, "cmdline")); err == nil && len(bytes.Trim(data, "\x00")) != 0 {
		args = strings.Split(strings.TrimRight(string(data), "\x00"), "\x00")
	}
	cwd, _ := os.Readlink(filepath.Join(directory, "cwd"))
	return args, cwd
}

