func writeLogStart(writer io.Writer, started time.Time, options logOptions) error {
	command := options.command
	if options.commandDisplay == "name" {
		command = []string{filepath.Base(command[0])}
	}
	field := ""
	if options.commandDisplay != "none" {
		field = " command=" + asciiJSON(command)
		if key, err := commandKey(options.command); err == nil {
			field += " command_key=" + key + " command_key_version=1"
		}
	}
	field = " command_display=" + options.commandDisplay + field
	cwd, err := os.Getwd()
	if err != nil {
		return err
	}
	_, err = fmt.Fprintf(writer, "=== edc log start time=%s pid=%d cwd=%s stream=%s%s ===\n", started.Format(time.RFC3339Nano), os.Getpid(), asciiJSON(cwd), options.stream, field)
	return err
}

// terminalJSON은 화면 표시용이다. 셸 명령의 <, >, &가 \u003e로 바뀌지 않게 HTML escape만 끈다.
// 제어 문자는 json이 여전히 escape한다. 로그 파일 헤더는 형식을 지키려고 asciiJSON을 그대로 쓴다.
func terminalJSON(value any) string {
	var buffer bytes.Buffer
	encoder := json.NewEncoder(&buffer)
	encoder.SetEscapeHTML(false)
	_ = encoder.Encode(value)
	return asciiEscape(bytes.TrimSuffix(buffer.Bytes(), []byte("\n")))
}

type logHistoryOptions struct {
	Directory, File, Key, Name string
	Exact                      []string
	Failed, Follow             bool
	JSON                       string
	Limit                      int
	// oldestFirst makes a direct read keep the oldest families at its limits.
	// prune needs the old runs; the history needs the new ones.
	oldestFirst   bool
	limitExplicit bool
}

func parseLogHistoryOptions(args []string, output io.Writer) (logHistoryOptions, error) {
	options := logHistoryOptions{Limit: 20}
	set := newFlagSet("log history")
	set.SetOutput(output)
	set.StringVar(&options.Directory, "dir", "", T("cli.log_history.option.dir"))
	set.StringVar(&options.File, "file", "", T("cli.log_history.option.file"))
	seenKey, seenCommand := false, false
	set.Func("key", T("cli.log_history.option.key"), func(value string) error {
		if seenKey || value == "" {
			return errors.New(T("cli.log_history.usage"))
		}
		seenKey = true
		options.Key = value
		return nil
	})
	set.Func("command", T("cli.log_history.option.command"), func(value string) error {
		if seenCommand || value == "" {
			return errors.New(T("cli.log_history.usage"))
		}
		seenCommand = true
		options.Name = value
		return nil
	})
	set.IntVar(&options.Limit, "limit", configuredInt(activeConfig.Defaults.Log.HistoryLimit, logHistoryDefaultLimit), T("cli.log_history.option.limit"))
	set.BoolVar(&options.Failed, "failed", false, T("cli.log_history.option.failed"))
	set.BoolVar(&options.Follow, "follow", false, T("cli.log_history.option.follow"))
	set.StringVar(&options.JSON, "json", "", T("cli.log_history.option.json"))
	if err := set.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return options, err
		}
		return options, flagReported(err)

}
set.Visit(func(f *flag.Flag) {
	if f.Name == "limit" {
		options.limitExplicit = true
	}
})
if options.Directory != "" && options.File != "" || options.Limit < 1 || options.Limit > logHistoryMaxLimit || options.JSON != "" && !options.Follow {
	return options, errors.New(T("cli.log_history.usage"))
}
if set.NArg() > 0 {
	options.Exact = set.Args()
}
if seenKey && seenCommand || options.Exact != nil && (seenKey || seenCommand) {
	return options, errors.New(T("cli.log_history.usage"))
}
if options.Exact != nil {
	key, err := commandKey(options.Exact)
	if err != nil {
		return options, errors.New(T("cli.log_history.usage"))
	}
	options.Key = key
}
options.Key = strings.ToLower(options.Key)
if options.Key != "" {
	if len(options.Key) < 12 || len(options.Key) > 64 {
		return options, errors.New(T("cli.log_history.usage"))
	}
	for _, char := range options.Key {
		if !strings.ContainsRune("0123456789abcdef", char) {
			return options, errors.New(T("cli.log_history.usage"))
		}
	}

	limited := errors.Is(err, errHistoryScanLimit)
	if err != nil && !limited && !(options.Directory == "" && os.IsNotExist(err)) {
		return logHistorySnapshot{}, err
	}
	if options.Directory == "" && activeConfig.Defaults.Log.Output != nil && *activeConfig.Defaults.Log.Output != "" {
		path := *activeConfig.Defaults.Log.Output
		if _, err := os.Lstat(path); err != nil {
			if !os.IsNotExist(err) {
				return logHistorySnapshot{}, err
			}
		} else {
			paths = append(paths, path)
		}
	}
	snapshot := collectLogHistoryOrdered(paths, cache, families, options.oldestFirst)
	if limited {
		snapshot.issue(root, "limit_error")
	}
	snapshot.Notices = notices
	if options.Directory == "" {
		attachLogHistoryArchive(&snapshot, root)
	}
	return snapshot, nil
}

// attachLogHistoryArchive adds the summaries of the trend window. A stats file
// that cannot be read only hides the archived days, with one notice.
func attachLogHistoryArchive(snapshot *logHistorySnapshot, root string) {
	archive, err := loadLogHistoryArchive(root, historyTrendStart(time.Now()))
	if err != nil {
		snapshot.Notices = append(snapshot.Notices, T("cli.log_history.stats_unavailable", reportIdentityValue(firstLine(err.Error()))))
		return
	}
	snapshot.Archive = archive
}

