// historyTint는 색을 쓸 때만 칠한다. code는 richGreen 같은 팔레트 번호다.
func historyTint(text, code string, color bool) string {
	if !color {
		return text
	}
	return richPaint(text, code, false)
}

func historyStrong(text, code string, color bool) string {
	if !color {
		return text
	}
	return richPaint(text, code, true)
}

// historySelect는 고른 줄이다. 색을 쓰면 막대와 chip 바탕으로, 아니면 "▸ "로 표시한다.
func historySelect(cells string, color bool) string {
	if !color {
		return "▸ " + cells
	}
	if !liveRich(color) {
		return "▸ " + cells
	}
	truecolor := richTruecolor()
	base := "\033[1;97;" + richRGBCode(historySelectedBackground, true, truecolor) + "m"
	bar := "\033[" + richFixedColor(richMagenta, truecolor) + "m" + liveSelectedBar + "\033[39m\033[97m"
	gray := "\033[" + richFixedColor(richGray, truecolor) + "m"
	cells = strings.ReplaceAll(cells, gray, "\033[97m")
	return base + bar + " " + strings.ReplaceAll(cells, richReset, richReset+base) + richReset
}

func historyKeyWidths(width int, groups []logHistoryGroup) historyKeyColumns {
	columns := historyKeyColumns{runs: 6, failed: 7}
	if width >= 64 {
		columns.last = 17
