}

// historyResourceLines describes a run's resources for the details view and
// the piped run list.
func historyResourceLines(row logHistoryAttempt, ratios historyRatios) []string {
	resources := row.Resources
	if resources == nil {
		return nil
	}
	ratio := func(parts []string, value float64) []string {
		if text := historyRatioText(value); text != "" {
			parts = append(parts, text)
		}
		return parts
	}
	var lines []string
	if resources.cpu {
		parts := []string{T("cli.log_history.resources.cpu", resources.CPU.Round(time.Millisecond).String())}
		if resources.CPUUser > 0 || resources.CPUSys > 0 {
			parts = append(parts, T("cli.log_history.resources.cpu_split", resources.CPUUser.Round(time.Millisecond).String(), resources.CPUSys.Round(time.Millisecond).String()))
		}
		if !row.Ended.IsZero() && row.Duration > 0 {
			parts = append(parts, T("cli.log_history.resources.average", strconv.FormatFloat(float64(resources.CPU)/float64(row.Duration)*100, 'f', 0, 64)+"%"))
		}
		if resources.Samples > 1 {
			parts = append(parts, T("cli.log_history.resources.peak", strconv.FormatFloat(resources.CPUPeak, 'f', 0, 64)+"%"))
		}
		lines = append(lines, strings.Join(ratio(parts, ratios.cpu), " · "))
	}
	var memory []string
	if resources.Samples > 0 {
		memory = append(memory, T("cli.log_history.resources.memory", formatSizeShort(resources.MemPeak)), T("cli.log_history.resources.average", formatSizeShort(resources.MemAvg)))
	}
	if resources.MaxRSS > 0 {

		memory = append(memory, T("cli.log_history.resources.max_rss", formatSizeShort(resources.MaxRSS)))
	}
	if len(memory) > 0 {
		lines = append(lines, strings.Join(ratio(memory, ratios.memory), " · "))
	}
	if resources.disk {
		lines = append(lines, T("cli.log_history.resources.disk", formatSizeShort(resources.DiskRead), formatSizeShort(resources.DiskWrite)))
	}
	switch {
	case resources.Samples > 0 && resources.Scope == logResourceScopeGroup:
		lines = append(lines, T("cli.log_history.resources.scope_pgrp", resources.Samples))
	case resources.Samples > 0:
		lines = append(lines, T("cli.log_history.resources.scope_"+resources.Scope, resources.Container, resources.Samples))
	}
	return lines
}

func historyCompactSummary(rows []logHistoryAttempt, color bool) []string {
	type context struct{ rows []logHistoryAttempt }
	contexts := map[string]*context{}
	var order []string
	for _, row := range rows {
		if contexts[row.CWD] == nil {
			contexts[row.CWD] = &context{}
			order = append(order, row.CWD)
		}
		contexts[row.CWD].rows = append(contexts[row.CWD].rows, row)
	}
	var lines []string
	for _, cwd := range order {
		var total big.Int
		success, failed, unknown, running := 0, 0, 0, 0
		for _, row := range contexts[cwd].rows {
			if row.Outcome == historyOutcomeSuccess {
				success++
				total.Add(&total, big.NewInt(int64(row.Duration)))
			} else if row.Outcome == historyOutcomeRunning {
				running++
			} else if row.failed() {
				failed++
			} else {
				unknown++
			}
		}
		parts := []string{historyTint(T("cli.log_history.summary_pass", success), richGreen, color)}
		if running > 0 {
			parts = append(parts, historyTint(T("cli.log_history.summary_running", running), richCyan, color))
		}
		if failed > 0 {

			parts = append(parts, historyTint(T("cli.log_history.summary_fail", failed), richRed, color))
		}
		if unknown > 0 {
			parts = append(parts, historyTint(T("cli.log_history.summary_unknown", unknown), richYellow, color))
		}
		if success > 0 {
			mean := time.Duration(new(big.Int).Quo(&total, big.NewInt(int64(success))).Int64())
			parts = append(parts, T("cli.log_history.summary_avg", mean.String()))
		}
		if len(order) > 1 {
			lines = append(lines, historyTint("cwd "+reportIdentityValue(cwd), richGray, color))
		}
		separator := " · "
		if color {
			separator = richDim(separator)
		}
		lines = append(lines, strings.Join(parts, separator))
	}
	return lines
}

// historyTrend sums the runs of a command per local day over the window, from
// the runs still in the logs plus the daily summaries of runs that prune
// deleted. The two never hold the same run, so they add up.
func historyTrend(group logHistoryGroup, now time.Time, color bool) string {
	start := historyTrendStart(now)
	days := make([]logHistoryDay, historyTrendDays)
	slot := func(day string) int {
		at, err := time.ParseInLocation("2006-01-02", day, time.Local)
		if err != nil || at.Before(start) {
			return -1
		}
		index := int(at.Sub(start).Hours()+12) / 24
		if index >= historyTrendDays {
			return -1
		}
		return index
	}
	for _, row := range group.Rows {
		if row.Started.IsZero() || row.Outcome == historyOutcomeRunning {
			continue
		}
		if index := slot(row.Started.Local().Format("2006-01-02")); index >= 0 {
			days[index].add(row)
		}
	}
	for _, archived := range group.Archive {
		if index := slot(archived.Day); index >= 0 {
			day := &days[index]
			day.Runs += archived.Runs
			day.Failed += archived.Failed
			day.Successes += archived.Successes
			day.DurationSum += archived.DurationSum

func scanHistoryRoot(root string) (historyFamilies, error) {
	families := historyFamilies{}
	examined := 0
	err := scanHistoryDirectory(root, true, families, &examined, func(directory string) error {
		return scanHistoryDirectory(directory, false, families, &examined, nil)
	})
	return families, err
}

func openLogIndex(ctx context.Context, path string) (*sql.DB, error) {
	// The index holds command lines, which can carry secrets, so it gets the
	// mode of the logs. SQLite gives the -wal and -shm files the mode of this file.
	if file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600); err == nil {
		file.Close()
	}
	uri := url.URL{Scheme: "file", Path: path}
	query := url.Values{"mode": {"rwc"}, "_pragma": {"busy_timeout(" + strconv.Itoa(logIndexBusyMS) + ")"}}
	uri.RawQuery = query.Encode()
	db, err := sql.Open("sqlite", uri.String())
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(1)
	if err := initializeLogIndex(ctx, db); err != nil {
		db.Close()
		// The index is a cache, so a file from another schema is replaced, not migrated.
		if errors.Is(err, errLogIndexSchema) {
			for _, suffix := range []string{"", "-wal", "-shm"} {
				_ = os.Remove(path + suffix)
			}
			if file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600); err == nil {
				file.Close()
			}
			return openLogIndexFresh(ctx, uri.String())
		}
		return nil, err
	}
	return db, nil
}

// indexTestRoot points the default log directory at a temporary home, so the
// tests never touch the index of the user running them.
func indexTestRoot(t *testing.T) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("XDG_STATE_HOME", filepath.Join(home, "state"))
	root := defaultLogDirectory()
	if root == "" {
		t.Skip("no default log directory on this platform")
	}
	return root
}

func TestLogIndexFallsBackInAReadOnlyDirectory(t *testing.T) {
	if os.Geteuid() == 0 {
		t.Skip("root ignores directory permissions")
	}
	root := indexTestRoot(t)
	writeIndexRun(t, root, "a", time.Now().Add(-time.Hour))
	if err := os.Chmod(root, 0500); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { os.Chmod(root, 0700) })
	var stdout, stderr strings.Builder
	code := runLogWithStreams([]string{"history"}, logStreams{stdin: strings.NewReader(""), stdout: &stdout, stderr: &stderr})
	if code != 0 || !strings.Contains(stdout.String(), "make a") || !strings.Contains(stderr.String(), T("cli.log_history.index_unavailable", "")[:10]) {
		t.Fatalf("code=%d stdout=%q stderr=%q", code, stdout.String(), stderr.String())
	}
}

type logPruneOptions struct {
	history              logHistoryOptions
	olderThan            time.Duration
	dryRun, yes, verbose bool
}

func parseLogPruneOptions(args []string, output io.Writer) (logPruneOptions, error) {
	var options logPruneOptions
	var age string
	set := newFlagSet("log prune")
	set.SetOutput(output)
	set.StringVar(&age, "older-than", "", T("cli.log_prune.option.older_than"))
	set.StringVar(&options.history.Directory, "dir", "", T("cli.log_history.option.dir"))
	set.StringVar(&options.history.File, "file", "", T("cli.log_history.option.file"))
	set.StringVar(&options.history.Name, "command", "", T("cli.log_prune.option.command"))
	set.StringVar(&options.history.Key, "key", "", T("cli.log_history.option.key"))
	set.BoolVar(&options.dryRun, "dry-run", false, T("cli.log_prune.option.dry_run"))
	set.BoolVar(&options.yes, "yes", false, T("cli.log_prune.option.yes"))
	set.BoolVar(&options.verbose, "v", false, T("cli.log_prune.option.verbose"))
	if err := set.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return options, err
		}
		return options, flagReported(err)
	}
	if set.NArg() > 0 || age == "" || options.history.Directory != "" && options.history.File != "" {
		return options, errors.New(T("cli.log_prune.usage"))
	}
	var err error
	options.olderThan, err = parseLogAge(age)
	options.history.Key = strings.ToLower(options.history.Key)
	if strings.Trim(options.history.Key, "0123456789abcdef") != "" {
		return options, errors.New(T("cli.log_prune.usage"))
	}
	return options, err
}

// pruneTargets selects the finished runs that started before the cutoff. A run
// without a command key is selected only when no key or command filter is set.
func pruneTargets(rows []logHistoryAttempt, options logPruneOptions, cutoff time.Time) []logHistoryAttempt {
	var targets []logHistoryAttempt
	for _, row := range rows {
		if row.Outcome == historyOutcomeRunning || row.Started.IsZero() || !row.Started.Before(cutoff) {
			continue
		}
		if options.history.Key != "" && (row.Key == "" || !strings.HasPrefix(row.Key, options.history.Key)) {
			continue
		}
		if options.history.Name != "" && (len(row.Command) == 0 || filepath.Base(row.Command[0]) != options.history.Name) {
			continue
		}
		targets = append(targets, row)
	}
	return targets
}

// pruneSummary groups the runs by command name, as the default directory keeps
// one folder per name, and names the directory once in the first line. -v adds
// every file.
func pruneSummary(plan logHistoryDeletion, defaultRoot string, verbose, dryRun bool) []string {
	var paths []string
	for _, family := range plan.families {
		paths = append(paths, family.path)
	}
	base := pruneBase(paths, defaultRoot)
	header := "cli.log_prune.plan"
	if dryRun {
		header = "cli.log_prune.dry_plan"
	}
	lines := []string{T(header, plan.Runs, plan.Files, formatSizeShort(plan.Bytes), reportIdentityValue(base))}
	if base == filepath.Dir(base) {
		lines[0] = T(header+"_total", plan.Runs, plan.Files, formatSizeShort(plan.Bytes))
	}
	groups := map[string]*pruneGroup{}
	for _, family := range plan.families {
		for index, row := range family.rows {
			name := T("cli.log_history.hidden")
			if len(row.Command) > 0 {
				name = filepath.Base(row.Command[0])
			}
			group := groups[name]
			if group == nil {
				group = &pruneGroup{name: name, keys: map[string]bool{}, directories: map[string]bool{}}
				groups[name] = group
			}
			group.runs++
			// A file belongs to the command of its first run, so the sizes add up to the total.
			if index == 0 {

			group.bytes += family.bytes
		}
		group.directories[filepath.Dir(family.path)] = true
		if row.Key != "" {
			group.keys[row.Key] = true
		}
		if group.first.IsZero() || row.Started.Before(group.first) {
			group.first = row.Started
		}
		if row.Started.After(group.last) {
			group.last = row.Started
		}
	}
}
ordered := make([]*pruneGroup, 0, len(groups))
nameWidth := 0
for _, group := range groups {
	ordered = append(ordered, group)
}
sort.Slice(ordered, func(i, j int) bool {
	if ordered[i].runs != ordered[j].runs {
		return ordered[i].runs > ordered[j].runs
	}
	return ordered[i].name < ordered[j].name
})
shown := ordered[:min(len(ordered), pruneSummaryLimit)]
for _, group := range shown {
	nameWidth = max(nameWidth, min(24, len([]rune(group.name))))
}
for _, group := range shown {
	line := "  " + historyCell(reportIdentityValue(group.name), nameWidth, false) + "  " + historyCell(T("cli.log_prune.runs", group.runs), 10, true) + "  " + pruneRange(group.first, group.last) + "  " + historyCell(formatSizeShort(group.bytes), 9, true) + "  " + pruneLocation(group.directories, base)
	if len(group.keys) > 1 {

			line += "  " + T("cli.log_prune.argument_sets", len(group.keys))
		}
		lines = append(lines, line)
	}
	if hidden := len(ordered) - len(shown); hidden > 0 {
		lines = append(lines, "  "+T("cli.log_prune.more", hidden))
	}
	if plan.Shared+plan.Running > 0 {
		lines = append(lines, T("cli.log_history.delete_kept", plan.Shared, plan.Running))
	}
	if verbose {
		for _, family := range plan.families {
			lines = append(lines, "  "+reportIdentityValue(family.path)+"  "+T("cli.log_prune.runs", family.runs))
		}
	}
	return lines
}

func pruneLocation(directories map[string]bool, base string) string {
	if len(directories) != 1 {
		return T("cli.log_prune.folders", len(directories))
	}
	for directory := range directories {
		relative, err := filepath.Rel(base, directory)
		if err != nil || strings.HasPrefix(relative, "..") || base == filepath.Dir(base) {
			return reportIdentityValue(directory) + "/"
		}
		if relative == "." {
			return "./"
		}
		return reportIdentityValue(relative) + "/"
	}
	return ""
}

func pruneRange(first, last time.Time) string {
	first, last = first.Local(), last.Local()
	switch {
	case first.Equal(last):
		return first.Format("2006-01-02 15:04") + "        "
	case first.Format("2006-01-02") == last.Format("2006-01-02"):
		return first.Format("2006-01-02 15:04") + " – " + last.Format("15:04")
	default:
		return historyCell(first.Format("2006-01-02")+" – "+last.Format("2006-01-02"), 24, false)
	}
}

func runLogPrune(args []string, streams logStreams) int {
	options, err := parseLogPruneOptions(args, streams.stderr)
	if errors.Is(err, flag.ErrHelp) {
		return 0
	}
	if errors.Is(err, errFlagReported) {
		return 2
	}
	if err != nil {
		fmt.Fprintln(streams.stderr, err)
		return 2
	}
	options.history.oldestFirst = true
	snapshot, err := loadLogHistory(options.history, nil)
	if err != nil {
		fmt.Fprintln(streams.stderr, reportIdentityValue(err.Error()))
		return 2
	}
	for _, notice := range snapshot.Notices {
		fmt.Fprintln(streams.stderr, notice)
	}
	code := 0
	for _, issue := range snapshot.Issues {
		fmt.Fprintln(streams.stderr, issue)
		code = 2
	}
	plan := planLogHistoryDeletion(pruneTargets(snapshot.Rows, options, time.Now().Add(-options.olderThan)))
	if plan.Runs == 0 {
		fmt.Fprintln(streams.stdout, T("cli.log_prune.none"))
		if plan.Shared+plan.Running > 0 {
			fmt.Fprintln(streams.stdout, T("cli.log_history.delete_kept", plan.Shared, plan.Running))
		}

	return code
}
for _, line := range pruneSummary(plan, defaultLogDirectory(), options.verbose, options.dryRun) {
	fmt.Fprintln(streams.stdout, line)
}
if options.dryRun {
	fmt.Fprintln(streams.stdout, T("cli.log_prune.dry_note"))
	return code
}
if !options.yes {
	input, inputOK := streams.stdin.(*os.File)
	output, outputOK := streams.stdout.(*os.File)
	if !inputOK || !outputOK || !isTerminal(input) || !isTerminal(output) {
		fmt.Fprintln(streams.stderr, T("cli.log_prune.yes_required"))
		return 2
	}
	fmt.Fprint(streams.stdout, T("cli.log_prune.confirm"))
	answer, _ := bufio.NewReader(input).ReadString('\n')
	if strings.TrimSpace(strings.ToLower(answer)) != "y" {
		return code
	}
}
deleted, err := plan.execute()
// The summary is written for the runs that were really removed, so a log
// that changed and was kept is not counted twice later.
if options.history.Directory == "" && options.history.File == "" {
	if statsErr := saveLogHistoryRollup(defaultLogDirectory(), deleted.deleted); statsErr != nil {
		fmt.Fprintln(streams.stderr, T("cli.log_prune.stats_failed", reportIdentityValue(firstLine(statsErr.Error()))))
	}
}
fmt.Fprintln(streams.stdout, T("cli.log_history.delete_done", deleted.Runs, deleted.Files, formatSizeShort(deleted.Bytes)))
if skipped := deleted.Shared + deleted.Running; skipped > 0 {

		fmt.Fprintln(streams.stdout, T("cli.log_history.delete_skipped", skipped))
	}
	if err != nil {
		fmt.Fprintln(streams.stderr, T("cli.log_history.delete_failed", reportIdentityValue(err.Error())))
		return 2
	}
	return code
}

// logResourceReading is one look at a target. CPU and disk are cumulative so a
// rate can come from two readings; memory is the current total.
type logResourceReading struct {
	cpu                 time.Duration
	memory              uint64
	diskRead, diskWrite uint64
	cpuValid, diskValid bool
	// peak is the kernel's own high-water mark when the target has one.
	peak uint64
}

// logResourceProbe reads the attempt's targets once. The process group is
// always read; a container target appears once docker detection finds it.
type logResourceProbe interface {
	sample(at time.Time)
	finish(resources *logResources, state *os.ProcessState)
}

type logDockerCommand struct {
	kind, container string
	argv            []string
}

// parseLogDockerCommand recognizes `docker run` and `docker exec`. The process
// they start belongs to dockerd, not to edc, so the process group would hold
// only the docker client.
func parseLogDockerCommand(command []string) (logDockerCommand, bool) {
	if len(command) < 2 || filepath.Base(command[0]) != "docker" {
		return logDockerCommand{}, false
	}
	globalValues := map[string]bool{"-H": true, "--host": true, "-c": true, "--context": true, "--config": true, "-l": true, "--log-level": true, "--tlscacert": true, "--tlscert": true, "--tlskey": true}
	args := command[1:]
	for len(args) > 0 && strings.HasPrefix(args[0], "-") {
		if globalValues[args[0]] {
			args = args[1:]
		}
		args = args[1:]
	}
	if len(args) > 0 && args[0] == "container" {
		args = args[1:]
	}
	if len(args) == 0 {
		return logDockerCommand{}, false
	}
	switch args[0] {
	case "run":
		return logDockerCommand{kind: "run"}, true
	case "exec":
	default:
		return logDockerCommand{}, false
	}
	execValues := map[string]bool{"-e": true, "--env": true, "--env-file": true, "-u": true, "--user": true, "-w": true, "--workdir": true, "--detach-keys": true}
	args = args[1:]
	for len(args) > 0 && strings.HasPrefix(args[0], "-") && args[0] != "-" {
		if args[0] == "--" {

			args = args[1:]
			break
		}
		if execValues[args[0]] {
			args = args[1:]
		}
		args = args[1:]
	}
	if len(args) < 2 {
		return logDockerCommand{}, false
	}
	return logDockerCommand{kind: "exec", container: args[0], argv: args[1:]}, true
}

// logCommandLineMatches compares a process argv with the argv given to docker
// exec. The first word may be resolved through PATH inside the container.
func logCommandLineMatches(cmdline, argv []string) bool {
	if len(cmdline) != len(argv) || len(argv) == 0 || filepath.Base(cmdline[0]) != filepath.Base(argv[0]) {
		return false
	}
	return slices.Equal(cmdline[1:], argv[1:])
}

// newLogResourceProbe measures the process group on macOS. Docker Desktop runs
// containers in a VM, so docker run and docker exec stay group measurements.
func newLogResourceProbe(_ []string, pid int, started time.Time) logResourceProbe {
	totals := &logMemberTotals{}
	timebase, err := darwinMachTimebase()
	// Under Rosetta proc_pid_rusage reports kernel ticks that the translated
	// timebase does not describe, so CPU time is left unknown there.
	cpuValid := err == nil && !darwinTranslated()
	return &logGroupProbe{
		group: newLogResourceAggregate(started, true),
		readGroup: func() (logResourceReading, bool) {
			processes, err := unix.SysctlKinfoProcSlice("kern.proc.pgrp", pid)
			if err != nil {
				return logResourceReading{}, false
			}
			members := map[logProcessMember]logResourceReading{}
			for _, process := range processes {
				member := int(process.Proc.P_pid)
				usage, err := readDarwinProcessRusage(member)
				if err != nil {
					continue
				}
				reading := logResourceReading{memory: usage.Footprint, diskRead: usage.DiskRead, diskWrite: usage.DiskWrite, cpuValid: cpuValid, diskValid: true}
				if cpuValid {
					ticks := uint64(usage.UserTime + usage.SystemTime)
					reading.cpu = time.Duration(ticks * uint64(timebase.Numer) / uint64(timebase.Denom))
				}
				members[logProcessMember{pid: member, start: usage.Started}] = reading
			}
			return totals.reading(members), true
		},
	}

// linuxLogMember reads what a member contributes. Memory is RSS plus swap, as in
// top. A process of another user hides its io file unless edc runs as root.
func linuxLogMember(process linuxLogProcess) (logProcessMember, logResourceReading) {
	base := filepath.Join("/proc", strconv.Itoa(process.stat.PID))
	reading := logResourceReading{
		cpu:      time.Duration(process.stat.Ticks) * time.Second / linuxClockTicks,
		memory:   process.stat.RSSPages * uint64(os.Getpagesize()),
		cpuValid: true,
	}
	if data, err := os.ReadFile(filepath.Join(base, "status")); err == nil {
		if swap, ok := parseLinuxProcessSwap(string(data)); ok {
			reading.memory += swap
		}
	}
	if data, err := os.ReadFile(filepath.Join(base, "io")); err == nil {
		if io, ok := parseLinuxProcessIO(string(data)); ok {
			reading.diskRead, reading.diskWrite, reading.diskValid = io.read, io.write, true
		}
	}
	return logProcessMember{pid: process.stat.PID, start: process.stat.StartTicks}, reading
}

func newLogResourceProbe(command []string, pid int, started time.Time) logResourceProbe {
	totals := &logMemberTotals{}
	group := &logGroupProbe{
		group: newLogResourceAggregate(started, true),
		readGroup: func() (logResourceReading, bool) {
			members := linuxLogMembers(readLinuxLogProcesses(listLinuxPIDs()), func(process linuxLogProcess) bool { return process.pgrp == pid })
			return totals.reading(members), true
		},
	}
	docker, ok := parseLogDockerCommand(command)
	if !ok {
		return group
	}
	probe := &linuxDockerProbe{logGroupProbe: group, command: docker, started: started, target: newLogResourceAggregate(started, true)}
	probe.startTicks, probe.startKnown = readLinuxUptimeTicks()
	if docker.kind == "run" {
		probe.known = linuxDockerCgroups()
	}
	return probe
}

// linuxDockerCgroups maps container IDs to their cgroup directories. The systemd
// driver uses docker-<id>.scope; the cgroupfs driver uses docker/<id>.
func linuxDockerCgroups() map[string]string {
	directories := map[string]string{}
	for _, pattern := range []string{filepath.Join(linuxCgroupDefaultMount, "system.slice", "docker-*.scope"), filepath.Join(linuxCgroupDefaultMount, "docker", "*")} {
		matches, _ := filepath.Glob(pattern)
		for _, match := range matches {
			id := strings.TrimSuffix(strings.TrimPrefix(filepath.Base(match), "docker-"), ".scope")
			if validHistoryKey(id) {
				directories[id] = match
			}
		}
	}
	return directories
}

func readLinuxLogCgroup(directory string, withPeak bool) (logResourceReading, bool) {
	memory, err := readLinuxCgroupNumber(filepath.Join(directory, "memory.current"))
	if err != nil {
		return logResourceReading{}, false
	}
	reading := logResourceReading{memory: memory}
	if counters, status := readLinuxCgroupCounters(directory, "cpu.stat", "usage_usec"); status.Status == "available" {
		reading.cpu, reading.cpuValid = time.Duration(counters["usage_usec"])*time.Microsecond, true
	}
	if data, err := os.ReadFile(filepath.Join(directory, "io.stat")); err == nil {
		reading.diskRead, reading.diskWrite, reading.diskValid = sumCgroupIOStat(string(data))
	}
	if withPeak {
		reading.peak, _ = readLinuxCgroupNumber(filepath.Join(directory, "memory.peak"))
	}
	return reading, true
}

func readLinuxUptimeTicks() (uint64, bool) {
	data, err := os.ReadFile("/proc/uptime")
	if err != nil {
		return 0, false
	}
	fields := strings.Fields(string(data))
	if len(fields) == 0 {
		return 0, false
	}
	seconds, err := strconv.ParseFloat(fields[0], 64)
	if err != nil || seconds < 0 {
		return 0, false
	}
	return uint64(seconds * linuxClockTicks), true
}

func readLinuxCgroupNumber(path string) (uint64, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	return strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
}

func (probe *linuxDockerProbe) sampleRun(at time.Time) {
	if probe.ambiguous {
		return
	}
	if probe.dir == "" {
		var fresh []string
		current := linuxDockerCgroups()
		for id := range current {
			if _, seen := probe.known[id]; !seen {
				fresh = append(fresh, id)
			}
		}
		if len(fresh) > 1 {
			probe.ambiguous = true
			return
		}
		if len(fresh) == 0 {
			return
		}
		probe.id, probe.dir = fresh[0], current[fresh[0]]
	}
	// The container starts during the run, so its memory.peak covers only it.
	if reading, ok := readLinuxLogCgroup(probe.dir, true); ok {
		probe.target.add(reading, at)
	}
}

func (probe *linuxDockerProbe) resolveExec() {
	probe.resolved = true
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	output, err := commandOutput(ctx, "docker", "inspect", "--type", "container", "--format", "{{.State.Pid}}|{{.Id}}", "--", probe.command.container)
	if err != nil {
		return
	}
	pidText, id, _ := strings.Cut(output, "|")
	pid, err := strconv.Atoi(pidText)
	if err != nil || pid < 1 || !validHistoryKey(id) {
		return
	}
	path, err := linuxCtrCgroupPath(pid)
	if err != nil {
		return
	}
	data, err := os.ReadFile("/proc/self/mountinfo")
	if err != nil {
		return
	}
	directory, err := resolveLinuxCgroup(path, parseLinuxCgroupMounts(string(data)))
	if err != nil {
		return
	}
	probe.id, probe.dir = id, directory
	probe.whole = newLogResourceAggregate(probe.started, false)
}

