// readDarwinNetworkCounters는 켜진 non-loopback interface마다 kernel 통계를 읽는다.
// NET_RT_IFLIST2의 byte counter는 32비트에서 넘어간 뒤 반올림된 값이라 쓰지 않고 net.link.generic.ifdata를 읽는다.
func readDarwinNetworkCounters() ([]netInterfaceCounters, error) {
	interfaces, err := net.Interfaces()
	if err != nil {
		return nil, err
	}
	var result []netInterfaceCounters
	for _, iface := range interfaces {
		if iface.Flags&net.FlagUp == 0 || iface.Flags&net.FlagLoopback != 0 {
			continue
		}
		data, err := readDarwinInterfaceData(iface.Index)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", iface.Name, err)
		}
		// 목록을 읽은 뒤 interface가 사라지고 index가 재사용되면 다른 interface의 값을 읽게 된다.
		if name := strings.TrimRight(string(data[:16]), "\x00"); name != iface.Name {
			return nil, fmt.Errorf("ifdata %d is %q, want %q", iface.Index, name, iface.Name)
		}
		counters := parseDarwinInterfaceData(data)
		result = append(result, netInterfaceCounters{
			Name: iface.Name, BytesIn: counters.bytesIn, BytesOut: counters.bytesOut, PacketsIn: counters.packetsIn, PacketsOut: counters.packetsOut,
			Errors: counters.errors, Drops: counters.drops,
		})
	}
	return result, nil
}

import (
	"fmt"
	"io"
	"strconv"
	"strings"
)

type networkReading struct {
	Status string  `json:"status"`
	Value  *uint64 `json:"value,omitempty"`
	Text   string  `json:"text,omitempty"`
	Reason string  `json:"reason,omitempty"`
}

type networkHealth struct {
	Supported bool                      `json:"supported"`
	Scope     string                    `json:"scope"`
	Settings  map[string]networkReading `json:"settings,omitempty"`
	Gauges    map[string]networkReading `json:"gauges,omitempty"`
	Counters  map[string]networkReading `json:"counters,omitempty"`
	// NICInterfaces는 interface마다 읽은 장치 쪽 drop이다. Counters의 nic_* 값은 이를 모두 더한 값이고, top --interface는
	// 고른 interface만 다시 더한다.
	NICInterfaces map[string]map[string]networkReading `json:"-"`
}

type networkCounterRate struct {
	Status    string   `json:"status"`
	PerSecond *float64 `json:"per_s,omitempty"`
	Reason    string   `json:"reason,omitempty"`
}

type networkHealthRate struct {
	networkHealth
	Rates map[string]networkCounterRate `json:"rates,omitempty"`
}

func networkNumber(value uint64) networkReading {
	return networkReading{Status: "observed", Value: &value}
}

func networkUnavailable(reason string) networkReading {
	return networkReading{Status: "unavailable", Reason: reason}
}

// sumNetworkNICCounters는 keep에 맞는 interface의 장치 쪽 drop을 counter마다 더한다. 더할 interface 하나라도 읽지 못했으면
// 합은 그 interface의 unavailable이고, 맞는 interface가 없으면 no interface다.
func sumNetworkNICCounters(perInterface map[string]map[string]networkReading, keep func(string) bool) map[string]networkReading {
	type sum struct {
		total   uint64
		counted int
		failure *networkReading
	}
	sums := map[string]*sum{}
	for iface, counters := range perInterface {
		for name, reading := range counters {
			if sums[name] == nil {
				sums[name] = &sum{}
			}
			if !keep(iface) {
				continue
			}
			if reading.Value == nil {
				sums[name].failure = &reading
				continue
			}
			sums[name].total += *reading.Value
			sums[name].counted++
		}
	}
	result := make(map[string]networkReading, len(sums))
	for name, value := range sums {
		switch {
		case value.failure != nil:
			result[name] = *value.failure
		case value.counted == 0:
			result[name] = networkUnavailable("no interface")

		default:
			result[name] = networkNumber(value.total)
		}
	}
	return result
}

func networkReadingText(value networkReading) string {
	if value.Value != nil {
		return fmt.Sprint(*value.Value)
	}
	if value.Text != "" {
		return value.Text
	}
	if value.Status == "" {
		return "unavailable"
	}
	return value.Status
}

func calculateNetworkHealthRate(previous, current *networkHealth, seconds float64) *networkHealthRate {
	if current == nil {
		return nil
	}
	result := &networkHealthRate{networkHealth: *current, Rates: make(map[string]networkCounterRate)}
	// 대시보드는 rate를 수백 행 보관한다. interface마다의 값은 snapshot에서만 쓰므로 rate에 남기지 않는다.
	result.NICInterfaces = nil
	for name, now := range current.Counters {
		rate := networkCounterRate{Status: "unavailable", Reason: "two consecutive observations required"}
		if now.Value == nil {
			rate.Reason = now.Reason
		} else if previous != nil && previous.Scope == current.Scope {
			before := previous.Counters[name]
			if before.Value != nil && seconds > 0 {
				if *now.Value >= *before.Value {
					value := float64(*now.Value-*before.Value) / seconds
					rate.Status, rate.PerSecond, rate.Reason = "observed", &value, ""
				} else {
					rate.Reason = "counter reset"
				}
			}
		}
		result.Rates[name] = rate
	}
	return result
}

// networkTCPMemoryUsage는 TCP가 쓰는 page를 tcp_mem의 상한(세 번째 값)과 비교한다. 상한에 닿으면 커널이 새 버퍼를 거부하고
// 연결을 끊는다. 두 번째 값(pressure)부터는 버퍼를 줄이기 시작한다.
func networkTCPMemoryUsage(health *networkHealth) (float64, bool) {
	if health == nil {
		return 0, false
	}
	pages := health.Gauges["tcp_memory_pages"].Value
	fields := strings.Fields(health.Settings["net.ipv4.tcp_mem"].Text)
	if pages == nil || len(fields) != 3 {
		return 0, false
	}
	limit, ok := parseNetworkUint(fields[2], 10)
	if !ok || limit == 0 {
		return 0, false
	}
	return float64(*pages) / float64(limit) * 100, true
}

func networkTCPMemoryText(health *networkHealth) string {
	if health == nil {
		return "—"
	}
	limit := "—"
	if fields := strings.Fields(health.Settings["net.ipv4.tcp_mem"].Text); len(fields) == 3 {
		limit = fields[2]
	}
	text := networkReadingText(health.Gauges["tcp_memory_pages"]) + "/" + limit + " pages"
	if usage, ok := networkTCPMemoryUsage(health); ok {
		text += fmt.Sprintf(" (%.1f%%)", usage)
	}
	return text
}

func networkConntrackUsage(health *networkHealth) (float64, bool) {
	if health == nil {
		return 0, false
	}
	count, limit := health.Gauges["conntrack_entries"].Value, health.Settings["net.netfilter.nf_conntrack_max"].Value
	if count == nil || limit == nil || *limit == 0 {
		return 0, false
	}
	return float64(*count) / float64(*limit) * 100, true
}

func printInfoNetworkHealth(writer io.Writer, health *networkHealth, color, verbose bool) {
	style := newTextStyle(color)
	fmt.Fprintln(writer)
	style.line(writer, style.heading("Network Limits"))
	if health == nil || !health.Supported {
		style.tree(writer, "└──", style.dim("Unsupported: Linux network limits require Linux"))
		return
	}
	ct := networkReadingText(health.Gauges["conntrack_entries"]) + " / " + networkReadingText(health.Settings["net.netfilter.nf_conntrack_max"])
	if usage, ok := networkConntrackUsage(health); ok {
		// edc top의 conntrack 칸과 같은 기준이다.
		ct += " " + style.level(fmt.Sprintf("(%.1f%%)", usage), topThreshold{warn: 90, danger: 98}.level(usage))
	}
	setting := func(name string) string { return networkReadingText(health.Settings[name]) }
	entry := func(label string, parts ...string) string { return style.kv(label, style.join(" · ", parts...)) }
	lines := []string{
		entry("Conntrack", ct),
		entry("TCP memory", networkTCPMemoryText(health), "orphans="+networkReadingText(health.Gauges["tcp_orphans"])),
		entry("Local ports", setting("net.ipv4.ip_local_port_range"), style.kv("Reserved", setting("net.ipv4.ip_local_reserved_ports"))),
		entry("Listen", "accept="+setting("net.core.somaxconn"), "SYN="+setting("net.ipv4.tcp_max_syn_backlog"), "syncookies="+setting("net.ipv4.tcp_syncookies")),
		entry("Socket buffer max", "receive="+setting("net.core.rmem_max"), "send="+setting("net.core.wmem_max")+" bytes"),
		entry("Receive backlog", setting("net.core.netdev_max_backlog"), "budget="+setting("net.core.netdev_budget"), "budget_us="+setting("net.core.netdev_budget_usecs")),
		entry("Neighbor max", "IPv4="+setting("net.ipv4.neigh.default.gc_thresh3"), "IPv6="+setting("net.ipv6.neigh.default.gc_thresh3")),
		entry("Routing", "forward(v4/v6)="+setting("net.ipv4.ip_forward")+"/"+setting("net.ipv6.conf.all.forwarding"), "rp_filter(all/default)="+setting("net.ipv4.conf.all.rp_filter")+"/"+setting("net.ipv4.conf.default.rp_filter")),
	}
	for index, line := range lines {
		branch := "├──"
		if index == len(lines)-1 {
			branch = "└──"
		}
		style.tree(writer, branch, line)
	}

	if verbose {
		style.line(writer, style.dim(fmt.Sprintf("    Scope: %s; softnet and TCP TIME_WAIT can be host-wide.", health.Scope)))
		for _, name := range networkSettingNames {
			reading := health.Settings[name]
			line := "    " + style.kv(name, networkReadingText(reading))
			if reading.Reason != "" {
				line += style.dim(" (" + infoSingleLine(reading.Reason) + ")")
			}
			style.line(writer, line)
		}
	}
}

func networkRateText(health *networkHealthRate, name string) string {
