	}
	if options.detail != httpDetailOff {
		metrics["hops"] = httpHopMetrics(hops)
	}
	if observedPeer != "" {
		if peerIsProxy {
			summary += ", " + T("observe.probe.proxy_peer_ip", observedPeer)
		} else {
			summary += ", " + T("observe.probe.peer_ip", observedPeer)
