	}
	if redirects > 0 {
		summary += ", " + T("observe.probe.final_request")
	}
	for _, phase := range httpTimingLabels {
		if value, ok := observedTimings[phase.key]; ok {
			summary += fmt.Sprintf(", %s %dms", phase.label, value)
		}
	}
	if redirects > 0 {
		summary += ", " + T("observe.probe.http_redirect", redirects, response.Request.URL.String())
	}
	return withHTTPBodyOutput(Result{Probe: "http.check", Status: status, StartedAt: started.UTC(), DurationMS: total.Milliseconds(), Summary: summary, Metrics: metrics, Error: diagnostic}, saved, bytesRead)
}

func classifyNetworkError(err error) string {
	if err == context.DeadlineExceeded || strings.Contains(strings.ToLower(err.Error()), "timeout") {
		return "timeout"
	}
	var dnsError *net.DNSError
	if errors.As(err, &dnsError) {
		return "dns"
	}
	if strings.Contains(strings.ToLower(err.Error()), "refused") {
		return "connection_refused"
	}
	return "network"
}

// withHTTPHops는 지나온 요청을 결과에 붙인다. 실패한 결과에도 붙여서 몇 번째 redirect에서 멈췄는지 보이게 한다.
func withHTTPHops(result Result, hops []httpHop, options httpCheckOptions) Result {
	if options.detail == httpDetailOff || len(hops) == 0 {
		return result
	}
	if result.Metrics == nil {
		result.Metrics = map[string]interface{}{}
	}
	result.Metrics["hops"] = httpHopMetrics(hops)
	result.Evidence = append(result.Evidence, Evidence{Label: T("observe.http.requests"), Value: formatHTTPHops(hops, httpOutputWidth(options))})
	return result
}

func readLinuxCgroupCounters(directory, file string, required ...string) (map[string]uint64, topLimitStatus) {
	data, err := os.ReadFile(filepath.Join(directory, file))
	if err != nil {
		return nil, linuxLimitError(err, true)
	}
	values := map[string]uint64{}
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if len(fields) != 2 {
			return nil, topLimitStatus{Status: "error", Reason: "invalid " + file + " row"}
		}
		value, err := strconv.ParseUint(fields[1], 10, 64)
		if err != nil {
			return nil, topLimitStatus{Status: "error", Reason: "invalid " + file + " counter"}
		}
		if _, exists := values[fields[0]]; exists {
			return nil, topLimitStatus{Status: "error", Reason: "duplicate " + file + " counter"}
		}
		values[fields[0]] = value
	}
	for _, key := range required {
		if _, ok := values[key]; !ok {
			return nil, topLimitStatus{Status: "unsupported", Reason: file + " does not provide " + key}
		}
	}
	return values, topLimitStatus{Status: "available"}
}

// promptMissingArgs는 빠진 필수 위치 인자를 terminal에서 받아 온다. 지금까지는 인자가 빠지면
// usage만 내고 끝나서 명령을 처음부터 다시 쳐야 했다. 묻는 자리는 그 오류 자리뿐이라,
// 인자를 제대로 준 실행의 흐름은 건드리지 않는다.
//
// terminal이 아니면 아무것도 묻지 않고 false를 돌려준다. caller가 지금과 같은 usage 오류와
// exit code를 유지해야 script의 계약이 깨지지 않는다. option과 flag는 묻지 않는다.
func promptMissingArgs(command string, labels ...string) ([]string, bool) {
	file, ok := terminalInput(os.Stdin)
	if !ok {
		return nil, false
	}
	return promptArgs(bufio.NewReader(file), os.Stdout, command, labels)
}

// promptArgs는 실제 질문이다. terminal 판정과 떼어 두어 검사할 수 있다.
func promptArgs(reader *bufio.Reader, output io.Writer, command string, labels []string) ([]string, bool) {
	return promptArgsWithColor(reader, output, command, labels, promptColor(output))
}

func promptArgsWithColor(reader *bufio.Reader, output io.Writer, command string, labels []string, color bool) ([]string, bool) {
	values := make([]string, 0, len(labels))
	for _, label := range labels {
		// label은 묻는 줄에만 쓴다. 빈 값의 오류 문장은 여기서 버리므로 색이 섞이지 않는다.
		if color {
			label = richBold(label)
		}
		value, err := promptRemoteText(reader, output, label, "")
		// 빈 값과 EOF는 취소다. caller가 usage를 내고 지금과 같은 exit code로 끝낸다.
		if err != nil {
			return nil, false
		}
		values = append(values, value)
	}
	writePromptEcho(output, command+" "+strings.Join(values, " "), color)
	return values, true
}

// promptMissingChoice는 하위 command가 빠졌을 때 terminal에서 고르게 한다. 하위 command도
// 명령에 꼭 필요한 값이라, 값을 제대로 준 실행에는 나타나지 않는다.
// promptMissingSubcommand는 commandDocs의 하위 명령에서 고르게 한다. 명령 이름을 한 번만 받아, 선택기와 설명이
// 서로 다른 명령을 가리킬 수 없다.
func promptMissingSubcommand(name string) (string, bool) {
	return promptMissingChoice("edc "+name, subcommandChoices(name))
}

func promptMissingChoice(command string, choices []string) (string, bool) {
	// 항목이 없는 선택 화면은 Ctrl-C까지 모든 키를 무시해서 터미널이 멈춘다. 고를 것이 없으면 usage로 끝낸다.
	if len(choices) == 0 {
		return "", false
	}
	file, ok := terminalInput(os.Stdin)
	// 선택 화면은 stdout에 그린다. stdout이 파이프나 파일이면 화면이 그쪽으로 가고 입력만 기다리게 된다.
	if !ok || !isTerminal(os.Stdout) {
		return "", false
	}
	// 고를 것이 하나뿐이면 고르는 화면은 의식일 뿐이다. 무엇이 실행되는지는 echo가 알려 준다.
	if len(choices) == 1 {
		promptEcho(os.Stdout, command+" "+choices[0])
		return choices[0], true
	}
	model := newSelectModel("cli.prompt.subcommand_title", "cli.prompt.subcommand_label", subcommandSelectItems(strings.TrimPrefix(command, "edc "), choices))
	value, err := runSelect(file, os.Stdout, model)
	if err != nil {
		return "", false
	}
	promptEcho(os.Stdout, command+" "+value)
	return value, true
}

// promptStatePath는 --state가 빠졌을 때 남아 있는 상태 파일에서 고르게 한다. run id가 박힌
// 경로를 옮겨 적는 대신 고른다. 되돌려야 하는 순간은 대개 급하다.
func promptStatePath(command string, paths []string) (string, bool) {
	if len(paths) == 0 {
		return "", false
	}
	file, ok := terminalInput(os.Stdin)
	if !ok {
		return "", false
	}
	model := newSelectModel("cli.prompt.state_title", "cli.prompt.state_label", selectItemsFromValues(paths))
	value, err := runSelect(file, os.Stdout, model)
	if err != nil {
		return "", false
	}
	promptEcho(os.Stdout, command+" --state "+value)
	return value, true
}

// promptEcho는 받은 값을 채운 명령을 되돌려 준다. 다음부터는 묻지 않고 바로 칠 수 있고,
// 그대로 script에 옮길 수도 있다.
func promptEcho(output io.Writer, command string) {
	writePromptEcho(output, command, promptColor(output))
}

// writePromptEcho는 색을 쓰면 화살표를 회색으로, 그대로 칠 수 있는 명령을 굵은 청록으로 쓴다.
func writePromptEcho(output io.Writer, command string, color bool) {
	if color {
		fmt.Fprintf(output, "%s %s\n\n", richDim("→"), richPaint(command, richCyan, true))
		return
	}
	fmt.Fprintf(output, "→ %s\n\n", command)
}

// promptColor는 묻는 줄과 echo에 색을 써도 되는지다. 색을 쓰는 터미널 파일일 때만 칠한다.
func promptColor(output io.Writer) bool {
	file, ok := output.(*os.File)
	return ok && richEnabled(file)
}

// go test의 stdin은 terminal이 아니다. 인자가 빠진 실행은 지금까지와 같이 usage 오류와
// exit code 2로 끝나야 script의 계약이 깨지지 않는다.
func TestTargetProbeKeepsTheUsageErrorWithoutATerminal(t *testing.T) {
	for _, args := range [][]string{
		{"dns", "lookup"},
		{"tcp", "check"},
		{"tls", "check"},
		{"http", "check"},
		{"net", "ping"},
		{"doctor"},
	} {
		if code := Run(args, "test"); code != 2 {
			t.Fatalf("%v: exit code = %d, want 2", args, code)
		}
	}
}

// 하위 command가 빠진 실행도 terminal이 아니면 지금까지와 같은 usage 오류로 끝나야 한다.
func TestSubcommandGroupsKeepTheUsageErrorWithoutATerminal(t *testing.T) {
	for _, args := range [][]string{
		{"dns"}, {"net"}, {"report"}, {"route"}, {"change"}, {"completion"},
		{"report", "show"}, {"report", "diff"},
		{"tcp"}, {"tls"}, {"http"},
		{"change", "confirm"}, {"change", "rollback"}, {"route", "rollback"},
	} {
		if code := Run(args, "test"); code != 2 {
			t.Fatalf("%v: exit code = %d, want 2", args, code)
		}
	}
}

// resolveQualityTimeout은 defaults.common.timeout을 물려받지 않는다. 예전 setup이 쓴 common 15s가 측정을 매번 자르기 때문이다.
func resolveQualityTimeout() time.Duration {
	return configuredDuration(activeConfig.Defaults.Quality.Timeout, defaultQualityTimeout)
}

func runQualityWith(args []string, version string, newProbe func(server string) func(context.Context) Result) int {
	options := configuredCommon(defaultQualityTimeout)
	options.timeout = resolveQualityTimeout()
	server := configuredString(activeConfig.Defaults.Quality.Server, "")
	flags := probeFlags{
		bind: func(set *flag.FlagSet) {
			set.StringVar(&server, "server", server, T("command.quality.option.server"))
		},
		check: func() error {
			if server == "" {
				return nil
			}
			if err := validateQualityServer(server); err != nil {
				return errors.New(T("cli.error.quality_server", server))
			}
			return nil
		},
	}
	return runSimpleWithOptions(args, version, "quality", qualityProbeID, options, flags, func(ctx context.Context) Result {
		return newProbe(server)(ctx)
	})
}

// qualityProbe는 빈 server를 기본 서버로 본다. macOS에서는 사용자가 바꾼 경우에만 -C를 넘겨 networkQuality의 기본 동작을 지킨다.
func qualityProbe(server string) func(context.Context) Result {
	if runtime.GOOS == "darwin" {
		return func(ctx context.Context) Result { return probeNetworkQuality(ctx, server, runNetworkQuality) }
	}
	configURL := server
	if configURL == "" {
		configURL = defaultQualityServer
	}
	return func(ctx context.Context) Result { return probeNativeQuality(ctx, configURL) }
}

func networkQualityArgs(server string, maxRuntime time.Duration) []string {
	args := []string{"-c"}
	if maxRuntime >= time.Second {
		args = append(args, "-M", strconv.Itoa(int(maxRuntime/time.Second)))
	}
	if server != "" {
		args = append(args, "-C", server)
	}
	return args
}

// networkQualityMaxRuntime은 기한 전에 networkQuality가 스스로 끝내게 한다. 기한에 kill되면 측정값이 하나도 남지 않는다.
func networkQualityMaxRuntime(ctx context.Context) time.Duration {
	deadline, ok := ctx.Deadline()
	if !ok {
		return 0
	}
	return time.Until(deadline) - finalizeReserve
}

func probeNetworkQuality(ctx context.Context, server string, run func(context.Context, []string) ([]byte, error)) Result {
	started := time.Now()
	output, err := run(ctx, networkQualityArgs(server, networkQualityMaxRuntime(ctx)))
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && bytes.Contains(exitErr.Stderr, []byte(networkQualityNoMaxRuntime)) {
		output, err = run(ctx, networkQualityArgs(server, 0))
	}
	if err != nil {
		return resultFromError(qualityProbeID, started, classifyCommandError(ctx, err), err)
	}
	return networkQualityResult(started, output)
}

func networkQualityResult(started time.Time, output []byte) Result {
	var metrics map[string]interface{}
	if err := json.Unmarshal(output, &metrics); err != nil {
		return resultFromError(qualityProbeID, started, "parse", err)
	}
	if metrics == nil {
		metrics = map[string]interface{}{}
	}
	measurement := normalizeNetworkQuality(metrics)
	mergeQualityMetrics(metrics, measurement)
	return qualityResult(started, measurement, metrics)
}

func (e *responsivenessEngine) downloadOnce(ctx context.Context, client *http.Client, url string) error {
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	response, err := client.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if response.StatusCode/100 != 2 {
		return fmt.Errorf("%w: %s", errQualityLoadStatus, response.Status)
	}
	_, err = io.Copy(byteCounter{total: &e.downloadBytes}, response.Body)
	return err
}

func (e *responsivenessEngine) uploadOnce(ctx context.Context, client *http.Client, url string) error {
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, url, zeroReader{ctx: ctx, total: &e.uploadBytes})
	if err != nil {
		return err
	}
	request.ContentLength = -1
	response, err := client.Do(request)
	if err != nil {
		return err
	}
	defer response.Body.Close()
	if _, err := io.Copy(io.Discard, response.Body); err != nil {
		return err
	}
	if response.StatusCode/100 != 2 {
		return fmt.Errorf("%w: %s", errQualityLoadStatus, response.Status)
	}
	return nil
}

