// validateRemoteHost trims and checks one host. index is zero-based and only names the host in an empty-name message.
func validateRemoteHost(host *remoteHost, index int) error {
	host.Name = strings.TrimSpace(host.Name)
	host.Target = strings.TrimSpace(host.Target)
	if host.Name == "" {
		return errors.New(T("remote.error.host_name_empty", index+1))
	}
	if host.Target == "" {
		host.Target = host.Name
	}
	if strings.HasPrefix(host.Target, "-") {
		return errors.New(T("remote.error.host_target_dash", host.Name))
	}
	tags, err := normalizeRemoteTags(host.Tags, fmt.Sprintf("host %q", host.Name))
	if err != nil {
		return err
	}
	host.Tags = tags
	return nil
}

func validateRemoteInventory(inventory *remoteInventory) error {
	if len(inventory.Hosts) == 0 {
		return errors.New(T("remote.error.inventory_no_host"))
	}
	if len(inventory.Hosts) > remoteHostLimit {
		return errors.New(T("remote.error.inventory_host_limit", remoteHostLimit))
	}
	if len(inventory.Groups) == 0 {
		return errors.New(T("remote.error.inventory_no_group"))
	}
	if len(inventory.Groups) > remoteGroupLimit {
		return errors.New(T("remote.error.inventory_group_limit", remoteGroupLimit))
	}
	if inventory.Parallel < 0 || inventory.Parallel > remoteHostLimit {
		return errors.New(T("remote.error.inventory_parallel_range", remoteHostLimit))
	}
	hosts := make(map[string]struct{}, len(inventory.Hosts))
	for index := range inventory.Hosts {
		host := &inventory.Hosts[index]
		if err := validateRemoteHost(host, index); err != nil {
			return err
		}
		if _, exists := hosts[host.Name]; exists {
			return errors.New(T("remote.error.duplicate_host", host.Name))
		}
		hosts[host.Name] = struct{}{}
	}
	for group, members := range inventory.Groups {
		if strings.TrimSpace(group) == "" || len(members) == 0 {
			return errors.New(T("remote.error.group_empty"))
		}
		if remoteReservedGroup(group) {

			return errors.New(T("remote.error.group_reserved", group))
		}
		seen := make(map[string]struct{}, len(members))
		for _, member := range members {
			if _, exists := hosts[member]; !exists {
				return errors.New(T("remote.error.group_unknown_host", group, member))
			}
			if _, exists := seen[member]; exists {
				return errors.New(T("remote.error.group_duplicate_host", group, member))
			}
			seen[member] = struct{}{}
		}
	}
	for group, options := range inventory.Options {
		if _, exists := inventory.Groups[group]; !exists {
			return errors.New(T("remote.error.options_unknown_group", group))
		}
		if options.Parallel < 1 || options.Parallel > remoteHostLimit {
			return errors.New(T("remote.error.group_parallel_range", group, remoteHostLimit))
		}
	}
	return nil
}

func remoteGroupNames(inventory remoteInventory) []string {
	groups := make([]string, 0, len(inventory.Groups))
	for group := range inventory.Groups {
		groups = append(groups, group)
	}
	sort.Strings(groups)
	return groups
}

func remoteParallelForGroup(inventory remoteInventory, group string, override int) int {
	if override > 0 {
		return override
	}
	if options, exists := inventory.Options[group]; exists {
		return options.Parallel
	}
	if inventory.Parallel > 0 {
		return inventory.Parallel
	}
	return 1
}

func loadRemoteRecipe(path string, defaultTimeout time.Duration) (remoteRecipe, error) {
	if defaultTimeout <= 0 || defaultTimeout > remoteMaxTimeout {
		return remoteRecipe{}, errors.New(T("remote.error.default_timeout_range", remoteMaxTimeout))
	}
	var file remoteRecipeFile
	if err := decodeRemoteYAML(path, &file); err != nil {
		return remoteRecipe{}, fmt.Errorf("recipe %q: %w", path, err)
	}
	return buildRemoteRecipe(file, defaultTimeout)
}

// buildRemoteRecipe checks a decoded recipe and turns it into the form that edc remote runs.
func buildRemoteRecipe(file remoteRecipeFile, defaultTimeout time.Duration) (remoteRecipe, error) {
	if strings.TrimSpace(file.Name) == "" {
		return remoteRecipe{}, errors.New(T("remote.error.recipe_name_empty"))
	}
	if len(file.Steps) == 0 || len(file.Steps) > remoteStepLimit {
		return remoteRecipe{}, errors.New(T("remote.error.recipe_step_range", remoteStepLimit))
	}
	recipe := remoteRecipe{Name: strings.TrimSpace(file.Name), Steps: make([]remoteStep, 0, len(file.Steps))}
	seen := make(map[string]struct{}, len(file.Steps))
	for index, value := range file.Steps {
		step := remoteStep{Name: strings.TrimSpace(value.Name), Command: strings.TrimSpace(value.Command), Verify: strings.TrimSpace(value.Verify), Timeout: defaultTimeout}
		if step.Name == "" {
			return remoteRecipe{}, errors.New(T("remote.error.step_name_command_empty", index+1))
		}
		if step.Command != "" && value.Upload != nil {
			return remoteRecipe{}, errors.New(T("remote.error.step_action_once", index+1))
		}
		if value.Upload != nil {
			source := strings.TrimSpace(value.Upload.Source)
			destination := strings.TrimSpace(value.Upload.Destination)
			if source == "" || destination == "" {
				return remoteRecipe{}, errors.New(T("remote.error.upload_path_empty", index+1))
			}
			if strings.HasPrefix(source, "-") {
				return remoteRecipe{}, errors.New(T("remote.error.upload_source_dash", index+1))
			}
			mode, err := normalizeRemoteUploadMode(strings.TrimSpace(value.Upload.Mode))
			if err != nil {
				return remoteRecipe{}, errors.New(T("remote.error.upload_mode_invalid", index+1, value.Upload.Mode))
			}
			step.Upload = &remoteUpload{Source: source, Destination: destination, Mode: mode}

			step.Command = fmt.Sprintf("upload %s → %s", source, destination)
			if mode != "" {
				step.Command += "  mode " + mode
			}
		}
		if step.Command == "" {
			return remoteRecipe{}, errors.New(T("remote.error.step_name_command_empty", index+1))
		}
		if _, exists := seen[step.Name]; exists {
			return remoteRecipe{}, errors.New(T("remote.error.duplicate_step", step.Name))
		}
		seen[step.Name] = struct{}{}
		tags, err := normalizeRemoteTags(value.Tags, fmt.Sprintf("step %q", step.Name))
		if err != nil {
			return remoteRecipe{}, err
		}
		step.Tags = tags
		if value.Timeout != "" {
			duration, err := time.ParseDuration(value.Timeout)
			if err != nil || duration <= 0 || duration > remoteMaxTimeout {
				return remoteRecipe{}, errors.New(T("remote.error.step_timeout_invalid", step.Name, value.Timeout))
			}
			step.Timeout = duration
		}
		recipe.Steps = append(recipe.Steps, step)
	}
	return recipe, nil
}

func normalizeRemoteUploadMode(mode string) (string, error) {
	if mode == "" {
		return "", nil
	}
	if (len(mode) != 3 && len(mode) != 4) || (len(mode) == 4 && mode[0] != '0') {
		return "", errors.New("invalid mode")
	}
	if _, err := strconv.ParseUint(mode, 8, 12); err != nil {
		return "", err
	}
	return mode, nil
}

func normalizeRemoteTags(tags []string, owner string) ([]string, error) {
	if len(tags) > remoteTagLimit {
		return nil, errors.New(T("remote.error.tag_limit", owner, remoteTagLimit))
	}
	normalized := make([]string, 0, len(tags))
	seen := make(map[string]struct{}, len(tags))
	for _, tag := range tags {
		tag = strings.TrimSpace(tag)
		if tag == "" {
			return nil, errors.New(T("remote.error.tag_empty", owner))
		}
		if _, exists := seen[tag]; exists {
			return nil, errors.New(T("remote.error.duplicate_tag", owner, tag))
		}
		seen[tag] = struct{}{}
		normalized = append(normalized, tag)
	}
	return normalized, nil
}

// stepRunsOnHost는 tag가 없는 step을 모든 host에서 실행하고, tag가 있으면 같은 tag를 가진 host에서만 실행한다.
func stepRunsOnHost(step remoteStep, host remoteHost) bool {
	if len(step.Tags) == 0 {
		return true
	}
	for _, tag := range step.Tags {
		for _, hostTag := range host.Tags {
			if tag == hostTag {
				return true
			}
		}
	}
	return false
}

func stepHostNames(step remoteStep, hosts []remoteHost) []string {
	names := make([]string, 0, len(hosts))
	for _, host := range hosts {
		if stepRunsOnHost(step, host) {
			names = append(names, host.Name)
		}
	}
	return names
}

func decodeRemoteYAML(path string, target interface{}) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()
	data, err := io.ReadAll(&io.LimitedReader{R: file, N: remoteConfigLimit + 1})
	if err != nil {
		return err
	}
	if len(data) > remoteConfigLimit {
		return errors.New(T("remote.error.file_too_large", remoteConfigLimit))
	}
	decoder := yaml.NewDecoder(strings.NewReader(string(data)))
	decoder.KnownFields(true)
	if err := decoder.Decode(target); err != nil {
		return err
	}
	var extra interface{}
	if err := decoder.Decode(&extra); err != io.EOF {
		if err == nil {
			return errors.New(T("remote.error.single_document"))
		}
		return err
	}
	return nil
}

func hostsForRemoteGroup(inventory remoteInventory, group string) ([]remoteHost, error) {
	members, exists := inventory.Groups[group]
	if !exists {
		return nil, errors.New(T("remote.error.unknown_group", group))
	}
	selected := make(map[string]struct{}, len(members))
	for _, member := range members {
		selected[member] = struct{}{}
	}
	hosts := make([]remoteHost, 0, len(members))
	for _, host := range inventory.Hosts {
		if _, exists := selected[host.Name]; exists {
			hosts = append(hosts, host)
		}
	}
	return hosts, nil
}

	if len(hosts) != 2 || hosts[0].Name != "first" || hosts[1].Name != "second" {
		t.Fatalf("host order = %#v", hosts)
	}
	if hosts[1].Target != "second" {
		t.Fatalf("default target = %q", hosts[1].Target)
	}
	if got := remoteParallelForGroup(inventory, "daily", 0); got != 3 {
		t.Fatalf("parallel = %d", got)
	}
	if got := remoteParallelForGroup(inventory, "daily", 4); got != 4 {
		t.Fatalf("override parallel = %d", got)
	}
	recipe, err := loadRemoteRecipe(recipePath, time.Minute)
	if err != nil {
		t.Fatal(err)
	}
	if recipe.Steps[0].Timeout != 30*time.Second {
		t.Fatalf("timeout = %s", recipe.Steps[0].Timeout)
	}
}

	recipe, err := loadRemoteRecipe(recipePath, time.Minute)
	if err != nil {
		t.Fatal(err)
	}
	hosts, err := hostsForRemoteGroup(inventory, "daily")
	if err != nil {
		t.Fatal(err)
	}
	want := map[string][]string{"git-kit": {"server", "laptop"}, "brew": {"laptop"}, "apt": {"server"}}
	for _, step := range recipe.Steps {
		got := stepHostNames(step, hosts)
		if strings.Join(got, ",") != strings.Join(want[step.Name], ",") {
			t.Fatalf("step %q hosts = %v, want %v", step.Name, got, want[step.Name])
		}
	}
}

