func (runner sshRemoteRunner) Run(parent context.Context, target, command string, timeout time.Duration, stream io.Writer) remoteCommandResult {
	started := time.Now()
	executable := runner.executable
	if executable == "" {
		executable = "ssh"
	}
	path, err := exec.LookPath(executable)
	if err != nil {
		return remoteCommandResult{ExitCode: -1, Duration: time.Since(started), Err: fmt.Errorf("%s: %w", T("remote.error.ssh_not_found"), err)}
	}
	connectSeconds := int((runner.connectTimeout + time.Second - 1) / time.Second)
	args := []string{"-o", "BatchMode=yes", "-o", fmt.Sprintf("ConnectTimeout=%d", connectSeconds), target, remoteShellCommand(command)}
	return runner.runExecutable(parent, path, args, timeout, stream)
}

func quoteRemotePath(path string) string {
	if path == "~" {
		return path
	}
	if strings.HasPrefix(path, "~/") {
		return "~/" + quoteRemoteShell(strings.TrimPrefix(path, "~/"))
	}
	if strings.HasPrefix(path, "~") {
		slash := strings.IndexByte(path, '/')
		if slash > 1 && remotePathUser(path[1:slash]) {
			return path[:slash+1] + quoteRemoteShell(path[slash+1:])
		}
	}
	return quoteRemoteShell(path)
}

func remoteShellCommand(command string) string {
	inner := "trap - DEBUG 2>/dev/null || true; unset PROMPT_COMMAND; exec 1>&3 2>&4; " + command
	return "exec 3>&1 4>&2; shell=${SHELL:-/bin/sh}; \"$shell\" -ic " + quoteRemoteShell(inner) + " >/dev/null 2>/dev/null"
}

func quoteRemoteShell(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

// remoteCapture는 원격 명령의 표준 출력과 표준 오류를 따로 받은 결과다. 표준 출력을 데이터로 읽는 명령이 쓴다.
type remoteCapture struct {
	Stdout    string
	Stderr    string
	Truncated bool
	ExitCode  int
	TimedOut  bool
	Duration  time.Duration
	Err       error
}

// Capture는 Run과 같은 셸 준비를 거치되 표준 출력과 표준 오류를 섞지 않는다. 표준 출력은 stdoutLimit까지 받고,
// 표준 오류는 원인을 보여 줄 만큼만 받는다.
func (runner sshRemoteRunner) Capture(parent context.Context, target, command string, timeout time.Duration, stdoutLimit int) remoteCapture {
	started := time.Now()
	executable := runner.executable
	if executable == "" {
		executable = "ssh"
	}
	path, err := exec.LookPath(executable)
	if err != nil {
		return remoteCapture{ExitCode: -1, Duration: time.Since(started), Err: fmt.Errorf("%s: %w", T("remote.error.ssh_not_found"), err)}
	}
	connectSeconds := int((runner.connectTimeout + time.Second - 1) / time.Second)
	args := []string{"-o", "BatchMode=yes", "-o", fmt.Sprintf("ConnectTimeout=%d", connectSeconds), target, remoteShellCommand(command)}
	ctx, cancel := context.WithTimeout(parent, timeout)
	defer cancel()
	stdout := &remoteLimitedBuffer{limit: stdoutLimit}
	stderr := &remoteLimitedBuffer{limit: remoteOutputLimit}
	process := exec.CommandContext(ctx, path, args...)
	process.Stdout, process.Stderr = stdout, stderr
	err = process.Run()
	result := remoteCapture{Stdout: stdout.String(), Stderr: stderr.String(), Truncated: stdout.Truncated(), Duration: time.Since(started), Err: err}
	if err == nil {
		return result
	}
	result.ExitCode = -1
	var exitError *exec.ExitError
	if errors.As(err, &exitError) {
		result.ExitCode = exitError.ExitCode()
	}
	result.TimedOut = ctx.Err() == context.DeadlineExceeded
	return result

func TestRemoteExecArgumentsAndOutputLimit(t *testing.T) {
	script := writeRemoteExecutable(t, "#!/bin/sh\nprintf '%s\n' \"$@\"\n")
	runner := sshRemoteRunner{executable: script, connectTimeout: 1500 * time.Millisecond, outputLimit: 256}
	result := runner.Run(context.Background(), "server-alias", "gk update", time.Second, nil)
	if result.Err != nil {
		t.Fatal(result.Err)
	}
	for _, value := range []string{"BatchMode=yes", "ConnectTimeout=2", "server-alias", "${SHELL:-/bin/sh}", " -ic ", "gk update"} {
		if !strings.Contains(result.Output, value) {
			t.Fatalf("output %q does not contain %q", result.Output, value)
		}
	}

	limited := sshRemoteRunner{executable: script, connectTimeout: time.Second, outputLimit: 4}
	result = limited.Run(context.Background(), "server-alias", "gk update", time.Second, nil)
	if result.Output != "-o\nB" || !result.Truncated {
		t.Fatalf("limited result = %#v", result)
	}
}

func TestRemoteShellCommandLoadsStartupAndHidesItsOutput(t *testing.T) {
	shell := writeRemoteExecutable(t, "#!/bin/sh\nprintf 'startup output\n'\nprintf 'startup error\n' >&2\nexec /bin/sh -c \"$2\"\n")
	process := exec.Command("/bin/sh", "-c", remoteShellCommand(`printf '%s\n' "command output with ' quote"`))
	process.Env = append(os.Environ(), "SHELL="+shell)
	output, err := process.CombinedOutput()
	if err != nil {
		t.Fatalf("command failed: %v: %s", err, output)
	}
	if string(output) != "command output with ' quote\n" {
		t.Fatalf("output = %q", output)
	}
}

func TestRemoteExecTimeoutAndMissingExecutable(t *testing.T) {
	script := writeRemoteExecutable(t, "#!/bin/sh\nexec sleep 2\n")
	runner := sshRemoteRunner{executable: script, connectTimeout: time.Second, outputLimit: 64}
	result := runner.Run(context.Background(), "server-alias", "gk update", 20*time.Millisecond, nil)
	if !result.TimedOut || result.Err == nil {
		t.Fatalf("result = %#v", result)
	}

	missing := sshRemoteRunner{executable: filepath.Join(t.TempDir(), "missing-ssh"), connectTimeout: time.Second, outputLimit: 64}
	result = missing.Run(context.Background(), "server-alias", "gk update", time.Second, nil)
	if result.ExitCode != -1 || result.Err == nil || !strings.Contains(result.Err.Error(), "ssh executable") {
		t.Fatalf("result = %#v", result)
	}
}

// remoteYAMLFiles는 탐색 디렉터리의 YAML 파일 경로를 기본 파일 탐색과 같은 순서로 모은다.
func remoteYAMLFiles(cwd, configDir string) []string {
	var paths []string
	seen := make(map[string]struct{})
	for _, directory := range remoteSearchDirectories(cwd, configDir) {
		entries, err := os.ReadDir(directory)
		if err != nil {
			continue
		}
		var names []string
		for _, entry := range entries {
			if entry.IsDir() {
				continue
			}
			if extension := strings.ToLower(filepath.Ext(entry.Name())); extension != ".yaml" && extension != ".yml" {
				continue
			}
			names = append(names, entry.Name())
		}
		sort.Strings(names)
		for _, name := range names {
			path := filepath.Join(directory, name)
			if _, exists := seen[path]; exists {
				continue
			}
			seen[path] = struct{}{}
			paths = append(paths, path)
			if len(paths) >= remoteCandidateLimit {
				return paths
			}
		}
	}

// remoteInventoryCandidates는 실제로 inventory로 읽히는 파일만 남긴다. 읽히지 않는 YAML은 목록에서 뺀다.
func remoteInventoryCandidates(cwd, configDir string) []selectItem {
	var items []selectItem
	for _, path := range remoteYAMLFiles(cwd, configDir) {
		inventory, err := loadRemoteInventory(path)
		if err != nil {
			continue
		}
		items = append(items, selectItem{
			label: T("remote.label.inventory_candidate", remoteDisplayPath(cwd, path), len(inventory.Groups), len(inventory.Hosts)),
			value: path,
		})
	}
	return items
}

// remoteRecipeCandidates는 실제로 recipe로 읽히는 파일만 남긴다.
func remoteRecipeCandidates(cwd, configDir string, defaultTimeout time.Duration) []selectItem {
	var items []selectItem
	for _, path := range remoteYAMLFiles(cwd, configDir) {
		recipe, err := loadRemoteRecipe(path, defaultTimeout)
		if err != nil {
			continue
		}
		items = append(items, selectItem{
			label: T("remote.label.recipe_candidate", remoteDisplayPath(cwd, path), recipe.Name, len(recipe.Steps)),
			value: path,
		})
	}
	return items
}

