func TestRemoteInventoryDiscoveryPrecedence(t *testing.T) {
	cwd := t.TempDir()
	config := t.TempDir()
	writeRemoteFixture(t, filepath.Join(cwd, "inventory.yaml"), "hosts: [{name: cwd, target: cwd}]\ngroups: {all: [cwd]}\n")
