	Recipe:         recipe,
	RecipeLocation: recipeFile,
}, os.Stdin, os.Stdout)
if err != nil {
	fmt.Fprintln(os.Stderr, err)
	return 1
}
if editor.Dirty() || recipe.Dirty() {
	fmt.Fprintln(os.Stderr, T("cli.setup.cancelled"))
	return 4

	}
	if result.Inventory {
		fmt.Fprintln(os.Stdout, T("remotesetup.saved", path))
	}
