func collectResourceSnapshot() (resourceSnapshot, error) {
	snapshot := resourceSnapshot{TakenAt: time.Now(), NetworkHealth: collectNetworkHealth()}
	stat, err := os.ReadFile("/proc/stat")
	if err != nil {
		return snapshot, err
	}
	lines := strings.Split(string(stat), "\n")
	if created, ok := parseLinuxProcessesCreated(string(stat)); ok {
		snapshot.ProcsCreated, snapshot.ProcsCreatedValid, snapshot.ProcsCreatedSource = created, true, "kernel"
	}
	fields := strings.Fields(lines[0])
	if len(fields) < 8 {
		return snapshot, fmt.Errorf("invalid /proc/stat cpu line")
	}
	values := make([]uint64, len(fields)-1)
	for i, field := range fields[1:] {
		values[i], _ = strconv.ParseUint(field, 10, 64)
		snapshot.CPUTotal += values[i]
	}
	snapshot.CPUUser = values[0] + values[1]
	snapshot.CPUSystem = values[2] + values[5] + values[6]
	snapshot.CPUIdle = values[3]
	snapshot.CPUIOWait, snapshot.CPUIOWaitValid = values[4], true
	if len(values) > 7 {
		snapshot.CPUSteal, snapshot.CPUStealValid = values[7], true
	}
	for _, line := range lines[1:] {
		parts := strings.Fields(line)
		if len(parts) == 2 && parts[0] == "procs_blocked" {
			snapshot.ProcsBlocked, snapshot.ProcsBlockedSource = parseUint(parts[1]), topBlockedKernelTasks
			continue
		}

	}
	if network, err := os.ReadFile("/proc/net/dev"); err == nil {
		snapshot.NetInterfaces = parseLinuxNetDev(string(network))
		snapshot.NetHealthValid = len(snapshot.NetInterfaces) > 0
	} else {
		snapshot.NetMissing = true
	}
	if disks, err := os.ReadFile("/proc/diskstats"); err == nil {
		for _, line := range strings.Split(string(disks), "\n") {
			parts := strings.Fields(line)
			if len(parts) < 14 || !isPhysicalLinuxDisk(parts[2]) {
				continue
			}
			snapshot.DiskRead += parseUint(parts[5]) * 512
			snapshot.DiskWrite += parseUint(parts[9]) * 512
			snapshot.DiskOps += parseUint(parts[3]) + parseUint(parts[7])
			snapshot.DiskWaitMS += parseUint(parts[6]) + parseUint(parts[10])
			snapshot.DiskBusyMS += parseUint(parts[12])
			snapshot.DiskQueueMS += parseUint(parts[13])
			snapshot.DiskHealthValid, snapshot.DiskBusyValid = true, true
		}
	} else {
		snapshot.DiskMissing = true
	}
	snapshot.ThrottleMS, snapshot.ThrottleValid = readLinuxPackageThrottle()
	snapshot.TempC, snapshot.TempValid = readLinuxMaxValue("/sys/class/thermal/thermal_zone*/temp", 1000)
	snapshot.GPUBusy, snapshot.GPUValid = readLinuxMaxValue("/sys/class/drm/card*/device/gpu_busy_percent", 1)
	return snapshot, nil
}

// parseLinuxNetDev는 /proc/net/dev에서 loopback을 뺀 interface마다 counter를 읽는다. 이 file은 edc가 있는 network namespace의
// interface만 보인다.
func parseLinuxNetDev(data string) []netInterfaceCounters {
	var interfaces []netInterfaceCounters
	for _, line := range strings.Split(data, "\n") {
		parts := strings.Fields(strings.Replace(line, ":", " ", 1))
		if len(parts) < 17 || parts[0] == "lo" {
			continue
		}
		interfaces = append(interfaces, netInterfaceCounters{
			Name:       parts[0],
			BytesIn:    parseUint(parts[1]),
			PacketsIn:  parseUint(parts[2]),
			Errors:     parseUint(parts[3]) + parseUint(parts[11]),
			Drops:      parseUint(parts[4]) + parseUint(parts[12]),
			BytesOut:   parseUint(parts[9]),
			PacketsOut: parseUint(parts[10]),
		})
	}
	return interfaces
}

func readLinuxPressure(path string, kinds ...string) ([]float64, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	values := make([]float64, len(kinds))
	for index, kind := range kinds {
		value, ok := parsePressureAvg10(string(data), kind)
		if !ok {
			return nil, false
		}
		values[index] = value
	}
	return values, true
}

func collectHostDetails() (hostDetails, error) {
	var details hostDetails
	details.Hostname, _ = os.Hostname()
	details.System = "Linux"
	details.Machine = runtimeMachine()
	if data, err := os.ReadFile("/etc/os-release"); err == nil {
		values := parseKeyValues(string(data))
		details.OS = strings.Trim(values["ID"], "\"")
		details.Version = strings.Trim(values["PRETTY_NAME"], "\"")
	}
	if output, err := exec.Command("uname", "-r").Output(); err == nil {
		details.Release = strings.TrimSpace(string(output))
	}
	if output, err := exec.Command("uname", "-v").Output(); err == nil {
		details.Processor = strings.TrimSpace(string(output))
	}
	if data, err := os.ReadFile("/proc/cpuinfo"); err == nil {
		details.Model = linuxCPUModel(string(data))
	}
	details.Cores = runtime.NumCPU()
	memory, err := readMemInfo()
	if err != nil {
		return details, err
	}
	details.MemoryTotal = memory["MemTotal"]
	details.SwapTotal = memory["SwapTotal"]
	details.SwapUsed = details.SwapTotal - memory["SwapFree"]
	if loads, err := os.ReadFile("/proc/loadavg"); err == nil {
		fmt.Sscan(string(loads), &details.Load[0], &details.Load[1], &details.Load[2])
	}
	if uptime, err := os.ReadFile("/proc/uptime"); err == nil {
		var seconds float64

		fmt.Sscan(string(uptime), &seconds)
		details.Uptime = time.Duration(seconds * float64(time.Second))
	}
	var limits syscall.Rlimit
	if syscall.Getrlimit(syscall.RLIMIT_NOFILE, &limits) == nil {
		details.RLimitSoft, details.RLimitHard = limits.Cur, limits.Max
	}
	return details, nil
}

func readMemInfo() (map[string]uint64, error) {
	data, err := os.ReadFile("/proc/meminfo")
	if err != nil {
		return nil, err
	}
	result := map[string]uint64{}
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		if len(fields) >= 2 {
			result[strings.TrimSuffix(fields[0], ":")] = parseUint(fields[1]) * 1024
		}
	}
	return result, nil
}

// readLinuxPackageThrottle은 x86 CPU package가 열 때문에 속도를 낮춘 누적 ms다. 같은 package의 CPU는 모두 같은 값을 보이므로
// physical_package_id마다 한 번만 더한다. thermal_throttle이 없는 CPU(ARM, VM)는 값이 없다.
func readLinuxPackageThrottle() (uint64, bool) {
	paths, _ := filepath.Glob("/sys/devices/system/cpu/cpu[0-9]*/thermal_throttle/package_throttle_total_time_ms")
	seen := map[string]bool{}
	var total uint64
	for _, path := range paths {
		cpu := filepath.Dir(filepath.Dir(path))
		id, err := os.ReadFile(filepath.Join(cpu, "topology", "physical_package_id"))
		if err != nil || seen[strings.TrimSpace(string(id))] {
			continue
		}
		value, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		seen[strings.TrimSpace(string(id))] = true
		total += parseUint(strings.TrimSpace(string(value)))
	}
	return total, len(seen) > 0
}

// newTopProcessReader는 macOS ps를 쓴다. macOS의 %cpu는 최근 사용률의 감쇠 평균이라 그대로 쓸 수 있다.
func newTopProcessReaderWithRusage(readRusage bool) func() ([]topProcess, bool) {
	var kernel darwinKernelTaskCPU
	return func() ([]topProcess, bool) {
		ctx, cancel := context.WithTimeout(context.Background(), darwinProcessTimeout)
		defer cancel()
		args := []string{"-Ao", "pid=,ppid=,pcpu=,rss=,state=,lstart=,comm="}
		if topFullCommand {
			// -ww는 ps가 출력 폭에 맞춰 argv를 자르지 않게 한다.
			args = []string{"-ww", "-Ao", "pid=,ppid=,pcpu=,rss=,state=,lstart=,args="}
		}
		command := exec.CommandContext(ctx, "/bin/ps", args...)
		// lstart의 요일과 달 이름이 지역 설정을 따르면 시작 시각을 읽을 수 없다.
		command.Env = append(os.Environ(), "LC_ALL=C")
		output, err := command.Output()
		if err != nil {
			return nil, false
		}
		processes := parseTopProcesses(string(output))
		for index := range processes {
			processes[index].CWD = darwinProcessCWD(processes[index].PID)
			threads, err := readDarwinProcessThreads(processes[index].PID)
			if err == nil {
				processes[index].Threads = threads
			}
			// 다른 사용자 소유 process는 root로 실행할 때만 읽는다. 그때는 MemoryValid가 false로 남아 RSS로 대신한다.
			if readRusage {
				if usage, err := darwinProcessRusageReader(processes[index].PID); err == nil {
					processes[index].Memory, processes[index].MemoryValid = usage.Footprint, true
					processes[index].diskSampled, processes[index].diskStarted = true, usage.Started
					processes[index].diskReadBytes, processes[index].diskWriteBytes = usage.DiskRead, usage.DiskWrite
					processes[index].diskSampledAt = darwinProcessNow()

// read는 첫 관측에서 CPU 0을 준다. ps의 %cpu와 달리 누적 시간만 있어 직전 기준이 있어야 rate를 구한다.
// Rosetta에서는 rusage의 tick 단위가 번역된 timebase와 어긋나 CPU를 0으로 둔다.
func (kernel *darwinKernelTaskCPU) read() (topProcess, bool) {
	usage, err := darwinProcessRusageReader(0)
	if err != nil {
		return topProcess{}, false
	}
	now := darwinProcessNow()
	// kernel_task의 resident 크기는 root여도 rusage_info와 proc_taskinfo 모두 0을 준다.
	process := topProcess{PID: 0, Command: "kernel_task", RSSMissing: true, Memory: usage.Footprint, MemoryValid: true}
	process.diskSampled, process.diskStarted, process.diskSampledAt = true, usage.Started, now
	process.diskReadBytes, process.diskWriteBytes = usage.DiskRead, usage.DiskWrite
	if task, err := darwinProcessTaskInfoReader(0); err == nil {
		process.Threads = int(task.Threads)
	}
	ticks := usage.UserTime + usage.SystemTime
	timebase, err := darwinMachTimebase()
	if seconds := now.Sub(kernel.at).Seconds(); err == nil && !darwinTranslated() && !kernel.at.IsZero() && seconds > 0 && ticks >= kernel.ticks {
		process.CPU = timebase.duration(ticks-kernel.ticks).Seconds() / seconds * 100
	}
	kernel.ticks, kernel.at = ticks, now
	return process, true
}

// darwinSpawnTracker는 macOS에 없는 process 생성 counter를 PID로 근사한다. 직전 sample에 없던 PID는 그 사이 fork로
// 배정된 것이므로, 그 가운데 직전 최신 PID에서 가장 먼 거리가 그동안 배정된 PID 수다. 그 사이 만들어졌다 끝난 process만
// 있으면 다음에 살아남은 process가 보일 때 한꺼번에 센다. 첫 sample의 가장 큰 PID는 PID가 한 바퀴 돈 뒤라면 오래된
// process라서, 두 번째 sample에 새로 보인 PID로 최신 PID를 정한 뒤부터 센다.
type darwinSpawnTracker struct {
	mutex    sync.Mutex
	previous map[int32]bool
	newest   int32
	ready    bool
	total    uint64
}

	group.Wait()

	snapshot.NetMissing, snapshot.DiskMissing = !networkOK, !diskOK
	snapshot.NetInterfaces, snapshot.NetHealthValid = network, networkOK
	snapshot.DiskRead, snapshot.DiskWrite = disk.read, disk.write
	snapshot.DiskOps, snapshot.DiskWaitMS, snapshot.DiskHealthValid = disk.operations, disk.waitNS/uint64(time.Millisecond), diskOK
	snapshot.MemoryTotal, snapshot.MemoryUsed = memory.total, memory.used
	snapshot.SwapOutBytes, snapshot.SwapMissing = memory.swapOut, !memory.swapOK
	snapshot.SwapUsed, snapshot.SwapTotal, snapshot.SwapUsageValid = memory.swapUsed, memory.swapTotal, memory.swapUsageOK
	snapshot.Compressor, snapshot.CompressorValid = memory.compressor, memory.compressorOK
	if pids, err := darwinListAllPIDs(); err == nil {
		total, ready := darwinSpawns.observe(pids)
		snapshot.ProcsCreated, snapshot.ProcsCreatedValid, snapshot.ProcsCreatedSource = total, ready, "pid_delta"
	}
	snapshot.Load1 = load
	if pressureErr == nil {
		snapshot.MemoryPressure = pressure
	}
	if thermalErr == nil && thermal >= 0 {
		snapshot.Thermal = topThermal(min(thermal, int(topThermalSleeping)-1) + 1)
	}
	snapshot.GPUBusy, snapshot.GPUValid = gpu, gpuOK
	return snapshot, nil
}

// readDarwinMemory는 top의 PhysMem 대신 즉시 회수 가능한 page를 빼서 Linux MemAvailable과 같은 기준으로 사용량을 구한다.
// top의 used는 캐시와 compressor를 포함해 평상시에도 97% 이상으로 나온다.
func readDarwinMemory() darwinMemory {
	stats, err := readDarwinVMStatistics()
	if err != nil {
		return darwinMemory{}
	}
	pageSize, err := darwinPageSize()
	if err != nil {
		return darwinMemory{}
	}
	memory := darwinMemoryFromStatistics(stats, pageSize, darwinMemoryTotal())
	if swap, err := readDarwinSwapUsage(); err == nil {
		memory.swapUsed, memory.swapTotal, memory.swapUsageOK = swap.Used, swap.Total, true
	}
	return memory
}

func TestCalculateRateSkipsCountersAfterMissingRead(t *testing.T) {
	start := time.Unix(0, 0)
	// 앞 sample은 network를 읽지 못해 counter가 0이고 disk만 읽었다.
	previous := resourceSnapshot{TakenAt: start, NetMissing: true, DiskRead: 1000, DiskWrite: 1000}
	current := resourceSnapshot{TakenAt: start.Add(time.Second), NetInterfaces: []netInterfaceCounters{{Name: "eth0", BytesIn: 5 << 40, BytesOut: 4 << 40, PacketsIn: 1 << 30, PacketsOut: 1 << 30}}, DiskRead: 3000, DiskWrite: 5000}
	rate := calculateRate(previous, current)
	if rate.NetIn != 0 || rate.NetOut != 0 || rate.PacketsIn != 0 || rate.PacketsOut != 0 || rate.NetHealthValid || rate.NetInterfaces != nil {
		t.Fatalf("network rate after a missing read = %#v", rate)
	}
	if rate.DiskRead != 2000 || rate.DiskWrite != 4000 {
		t.Fatalf("disk rate must not depend on the network read: %#v", rate)
	}
	previous.DiskMissing, previous.DiskRead, previous.DiskWrite = true, 0, 0
	if rate := calculateRate(previous, current); rate.DiskRead != 0 || rate.DiskWrite != 0 || rate.DiskHealthValid {
		t.Fatalf("disk rate after a missing read = %#v", rate)
	}
}

func TestCalculateRateIncludesHealthCounters(t *testing.T) {
	start := time.Unix(0, 0)
	previous := resourceSnapshot{TakenAt: start, DiskOps: 10, DiskWaitMS: 100, DiskBusyMS: 500, NetInterfaces: []netInterfaceCounters{{Name: "eth0", Errors: 4, Drops: 2}}, DiskHealthValid: true, DiskBusyValid: true, NetHealthValid: true}
	current := resourceSnapshot{TakenAt: start.Add(2 * time.Second), DiskOps: 30, DiskWaitMS: 500, DiskBusyMS: 1300, NetInterfaces: []netInterfaceCounters{{Name: "eth0", Errors: 10, Drops: 6}}, DiskHealthValid: true, DiskBusyValid: true, NetHealthValid: true}
	rate := calculateRate(previous, current)
	if rate.DiskIOPS != 10 || rate.DiskAwait != 20 || rate.DiskBusy != 40 || rate.NetErrors != 3 || rate.NetDrops != 2 {
		t.Fatalf("health rate = %#v", rate)
	}
	if !rate.DiskHealthValid || !rate.DiskBusyValid || !rate.NetHealthValid {
		t.Fatalf("health validity = %#v", rate)
	}
	// macOS는 busy 시간을 주지 않으므로 IOPS와 await만 계산한다.
	previous.DiskBusyValid, current.DiskBusyValid = false, false
	if rate := calculateRate(previous, current); rate.DiskIOPS != 10 || rate.DiskAwait != 20 || rate.DiskBusy != 0 || rate.DiskBusyValid || !rate.DiskHealthValid {
		t.Fatalf("rate without busy time = %#v", rate)
	}
}

