func writeConfigAtomic(path string, data []byte) error {
	directory := filepath.Dir(path)
	if err := os.MkdirAll(directory, 0o700); err != nil {
		return err
	}
	if err := os.Chmod(directory, 0o700); err != nil {
		return err
	}
	file, err := os.CreateTemp(directory, ".config-*.yaml")
	if err != nil {
		return err
	}
	temporary := file.Name()
	remove := true
	defer func() {
		if remove {
			_ = os.Remove(temporary)
		}
	}()
	if err := file.Chmod(0o600); err != nil {
		file.Close()
		return err
	}
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {

func writeConfigIfUnchanged(path string, data []byte, original configSnapshot) error {
	lock, err := os.OpenFile(path+".lock", os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			if mkdirErr := os.MkdirAll(filepath.Dir(path), 0o700); mkdirErr != nil {
				return mkdirErr
			}
			lock, err = os.OpenFile(path+".lock", os.O_CREATE|os.O_RDWR, 0o600)
		}
		if err != nil {
			return err
		}
	}
	defer lock.Close()
	interrupted, err := lockLogFile(lock, make(chan os.Signal))
	if err != nil {
		return err
	}
	if interrupted != nil {
		return fmt.Errorf("config lock interrupted by %v", interrupted)
	}
	defer unlockLogFile(lock)
	current, err := configFileSnapshot(path)
	if err != nil {
		return err
	}
	if current != original {
		return errConfigChanged
	}
	return writeConfigAtomic(path, data)
}

func TestSetupCreatesConfigWithSecureModes(t *testing.T) {
	root := t.TempDir()
	directory := filepath.Join(root, "edc")
