func readLinuxSvcStats(pids []int) []linuxProcessStat {
	stats := make([]linuxProcessStat, 0, len(pids))
	for _, pid := range pids {
		data, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
		if err != nil {
			continue
		}
		if stat, ok := parseLinuxProcessStat(pid, string(data)); ok {
			stats = append(stats, stat)
		}
	}
	return stats
}

// linuxSvcJournal은 stdout과 stderr를 나눠 받는다. 권한 hint는 stderr에 나오고 기록 줄과 섞이면 안 된다.
func linuxSvcJournal(ctx context.Context, unit string) (string, string, error) {
	path, err := exec.LookPath("journalctl")
	if err != nil {
		return "", "", err
	}
	var stdout, stderr bytes.Buffer
	command := exec.CommandContext(ctx, path, "-u", unit, "-p", "err", "-n", strconv.Itoa(svcJournalLines), "--no-pager", "-o", "short-iso")
	command.Stdout, command.Stderr = &stdout, &stderr
	err = command.Run()
	return stdout.String(), stderr.String(), err
}

// formatListTable은 svc와 ctr 목록 표다. 첫 줄은 머리글이다. 색을 쓰면 머리글은 회색이고 칸은 colors의 색이다.
// 칸 폭은 평문으로 정한 뒤 칠해, 색을 써도 열이 맞는다.
func formatListTable(rows [][]string, colors [][]string, style textStyle) string {
	if style.color {
		// 첫 열이 unit이나 container 이름이라 줄이지 않는다.
		return style.colorTableRows(rows, false, func(row, column int, _, shown string) string {
			if column < len(colors[row+1]) {
				return style.paint(shown, colors[row+1][column])
			}
			return shown
		})
	}
	widths := make([]int, len(rows[0]))
	for _, row := range rows {
		for index, cell := range row {
			widths[index] = max(widths[index], liveWidth(cell))
		}
	}
	var builder strings.Builder
	for _, row := range rows {
		var line strings.Builder
		for index, cell := range row {
			if index == len(row)-1 {
				line.WriteString(cell)
				break
			}
			line.WriteString(liveCell(cell, widths[index]+2))
		}
		builder.WriteString(line.String() + "\n")
	}
	return builder.String()
}

// runSvcList는 unit 없이 부른 edc svc다. 터미널이면 목록에서 골라 상세를 여는 화면을 열고, 아니면 결과 한 줄과 표를 낸다.
