		return runSvcBrowser(sources, options.timeout, all)
	}
	ctx, cancel, deadline := probeContext(options.timeout)
	defer cancel()
	defer deadline()
	items, err := collectSvcList(ctx, sources, all)
	result := evaluateSvcList(items, err)
	if options.jsonPath != "" {
