const (
	// topMemoryGrowthBucket은 memory 최저값을 남기는 구간이다. GC는 구간 안에서 오르내리므로 최저값만 남기면
	// 힙이 늘었다 줄어드는 톱니가 걸러지고, 해제되지 않고 쌓이는 양만 남는다.
	topMemoryGrowthBucket = time.Minute
	// topMemoryGrowthBuckets는 판정에 쓰는 연속 구간 수다. 15분을 채우기 전에는 판정하지 않는다.
	topMemoryGrowthBuckets = 15
	// topMemoryGrowthRisingPairs는 이웃한 구간 최저값 14쌍 중 줄지 않아야 하는 쌍의 수다. 한두 번의 큰 해제는 넘긴다.
	topMemoryGrowthRisingPairs = 12
	// topMemoryGrowthGrowingPairs는 그중 실제로 늘어난 쌍의 수다. 시작할 때 cache를 한 번에 채우고 멈춘 계단은 누수가 아니다.
	topMemoryGrowthGrowingPairs = 7
	// topMemoryGrowthEdge는 처음과 마지막 구간의 최저값을 고를 때 묶는 구간 수다. 한 구간의 튀는 값에 흔들리지 않게 한다.
	topMemoryGrowthEdge = 3
	// topMemoryGrowthMin은 처음과 마지막 최저값 사이에 늘어야 하는 최소량이다. 작은 cache가 몇 MB씩 느는 것은 누수로 보지 않는다.
	topMemoryGrowthMin = 256 << 20
	// topMemoryGrowthDangerHorizon은 이 속도로 남은 memory를 다 쓰는 데 걸리는 시간이 이보다 짧으면 위험으로 보는 한도다.
	topMemoryGrowthDangerHorizon = time.Hour
)

// topMemoryGrowth는 꾸준히 늘어난 process의 증가량이다. Bytes는 처음과 마지막 구간 묶음의 최저값 차이이고,
// Window는 그 두 최저값을 남긴 구간 사이의 시간이다. 15분 창 전체가 아니라 실제로 비교한 간격이라 속도가 맞다.
type topMemoryGrowth struct {
	Bytes  uint64
	Window time.Duration
}

// perSecond는 증가 속도(byte/s)다.
func (growth topMemoryGrowth) perSecond() float64 {
	return float64(growth.Bytes) / growth.Window.Seconds()
}

type topProcessKey struct {
	pid     int
	started time.Time
}

// topMemorySeries는 process 하나의 구간별 최저값이다. 구간 번호를 함께 남겨 빠진 구간을 알아본다.
type topMemorySeries struct {
	buckets  []int64
	minimums []uint64
	cached   *topMemoryGrowth
	checks   int
}

// topMemoryGrowthTracker는 모든 process의 memory를 구간마다 기록해 지금은 작아도 계속 늘어나는 process를 찾는다.
// 크기 순위만으로는 큰 process에 밀려 누수를 늦게 알아챈다.
type topMemoryGrowthTracker struct {
	series map[topProcessKey]*topMemorySeries
	seen   map[topProcessKey]bool
	// start는 처음 기록한 시각이다. 구간 번호를 여기서 지난 시간으로 정해, 시계를 뒤로 돌려도 번호가 거꾸로 가지 않는다.
	// time.Now()의 monotonic 값으로 빼므로 NTP 보정에 흔들리지 않는다.
	start time.Time
}

func newTopMemoryGrowthTracker() *topMemoryGrowthTracker {
	return &topMemoryGrowthTracker{series: map[topProcessKey]*topMemorySeries{}, seen: map[topProcessKey]bool{}}
}

// observe는 processes의 memory를 기록하고, 꾸준히 늘어난 process에 Growth를 채운다. 목록에 없는 process의 기록은 지운다.
func (tracker *topMemoryGrowthTracker) observe(at time.Time, processes []topProcess) {
	if tracker.start.IsZero() {
		tracker.start = at
	}
	bucket := int64(at.Sub(tracker.start) / topMemoryGrowthBucket)
	clear(tracker.seen)
	for index := range processes {
		process := &processes[index]
		key := topProcessKey{pid: process.PID, started: process.Started}
		tracker.seen[key] = true
		series := tracker.series[key]
		if series == nil {
			series = &topMemorySeries{}
			tracker.series[key] = series
		}
		if !series.add(bucket, process.memory()) {
			process.Growth = series.cached
			continue
		}
		series.checks++
		growth, ok := series.growth()
		if ok {
			series.cached = &growth
		} else {
			series.cached = nil
		}
		process.Growth = series.cached
	}
	for key := range tracker.series {
		if !tracker.seen[key] {
			delete(tracker.series, key)

func (series *topMemorySeries) add(bucket int64, memory uint64) bool {
	if last := len(series.buckets) - 1; last >= 0 && series.buckets[last] == bucket {
		if memory >= series.minimums[last] {
			return false
		}
		series.minimums[last] = memory
		return true
	}
	series.buckets = append(series.buckets, bucket)
	series.minimums = append(series.minimums, memory)
	if extra := len(series.buckets) - topMemoryGrowthBuckets; extra > 0 {
		series.buckets, series.minimums = series.buckets[extra:], series.minimums[extra:]
	}
	return true
}

// growth는 최근 구간이 연속으로 다 찼고 최저값이 꾸준히 올랐을 때만 증가량을 돌려준다. 일시정지나 긴 --interval로
// 구간이 비면 그만큼 시간이 길어져 속도를 부풀리므로 판정하지 않는다.
func (series *topMemorySeries) growth() (topMemoryGrowth, bool) {
	if len(series.buckets) < topMemoryGrowthBuckets || series.buckets[len(series.buckets)-1]-series.buckets[0] != topMemoryGrowthBuckets-1 {
		return topMemoryGrowth{}, false
	}
	rising, growing := 0, 0
	for index := 1; index < len(series.minimums); index++ {
		if series.minimums[index] >= series.minimums[index-1] {
			rising++
		}
		if series.minimums[index] > series.minimums[index-1] {
			growing++
		}
	}
	head := series.minimums[:topMemoryGrowthEdge]
	tailStart := len(series.minimums) - topMemoryGrowthEdge
	tail := series.minimums[tailStart:]
	first, last := slices.Min(head), slices.Min(tail)
	if rising < topMemoryGrowthRisingPairs || growing < topMemoryGrowthGrowingPairs || last < first || last-first < topMemoryGrowthMin {
		return topMemoryGrowth{}, false
	}
	from := series.buckets[slices.Index(head, first)]
	to := series.buckets[tailStart+slices.Index(tail, last)]
	return topMemoryGrowth{Bytes: last - first, Window: time.Duration(to-from) * topMemoryGrowthBucket}, true
}

// topMemoryGrowthScore는 위험 한도를 이 속도로 남은 memory를 다 쓰기까지의 시간으로 나눈 값이다. 1 이상이면 위험이다.
// 남은 양을 모르면 경고 단계의 값을 돌려준다.
func topMemoryGrowthScore(growth topMemoryGrowth, memoryTotal uint64, memoryPercent float64) float64 {
	const unknown = 0.5
	if memoryTotal == 0 || growth.perSecond() <= 0 {
		return unknown
	}
	available := float64(memoryTotal) * math.Max(0, 100-memoryPercent) / 100
	return topMemoryGrowthDangerHorizon.Seconds() * growth.perSecond() / math.Max(available, 1)
}

// topFastestGrowing은 가장 많이 늘어난 process다. 늘어난 process가 없으면 false다.
func topFastestGrowing(processes []topProcess) (topProcess, bool) {
	var leading *topProcess
	for index := range processes {
		if growth := processes[index].Growth; growth != nil && (leading == nil || growth.Bytes > leading.Growth.Bytes) {
			leading = &processes[index]
		}
	}
	if leading == nil {
		return topProcess{}, false
	}
	return *leading, true
}

// feedTopMemory는 분마다 세 번 기록한다. 가운데 값은 GC 직전처럼 튀어 오른 값이라 최저값에 들지 않아야 한다.
func feedTopMemory(tracker *topMemoryGrowthTracker, start time.Time, minutes int, memory func(minute int) uint64) topProcess {
	var process topProcess
	for minute := 0; minute < minutes; minute++ {
		for index, spike := range []uint64{0, 500 << 20, 0} {
			process = topProcess{PID: 7, Started: start, Command: "node", Memory: memory(minute) + spike, MemoryValid: true}
			processes := []topProcess{process}
			tracker.observe(start.Add(time.Duration(minute)*time.Minute+time.Duration(index)*10*time.Second), processes)
			process = processes[0]
		}
	}
	return process
}

func TestTopMemoryGrowthFindsASteadyLeakThroughGCSpikes(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	leak := func(minute int) uint64 { return 1<<30 + uint64(minute)*(30<<20) }
	if process := feedTopMemory(newTopMemoryGrowthTracker(), start, topMemoryGrowthBuckets-1, leak); process.Growth != nil {
		t.Fatalf("growth before %d buckets: %+v", topMemoryGrowthBuckets, process.Growth)
	}
	process := feedTopMemory(newTopMemoryGrowthTracker(), start, topMemoryGrowthBuckets, leak)
	// 처음 세 구간의 최저값은 0분, 마지막 세 구간의 최저값은 12분에 남는다. 증가량과 시간이 같은 12분을 가리켜야 속도가 맞다.
	if process.Growth == nil || process.Growth.Bytes != 12*(30<<20) || process.Growth.Window != 12*time.Minute {
		t.Fatalf("growth = %+v, want 360 MiB over 12m", process.Growth)
	}
}

func TestTopMemoryGrowthIgnoresSawtoothStepsAndSmallGrowth(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	cases := map[string]func(minute int) uint64{
		// GC가 매번 같은 바닥으로 돌아온다.
		"sawtooth": func(int) uint64 { return 2 << 30 },
		// 시작할 때 cache를 한 번에 채우고 멈춘다.
		"step": func(minute int) uint64 {
			if minute < 2 {
				return 1 << 30
			}
			return 2 << 30
		},
		// 꾸준히 늘지만 15분에 256 MiB가 안 된다.
		"small": func(minute int) uint64 { return 1<<30 + uint64(minute)*(10<<20) },
		// 늘었다가 크게 해제한다.
		"released": func(minute int) uint64 {
			if minute%3 == 2 {
				return 1 << 30
			}
			return 1<<30 + uint64(minute)*(60<<20)
		},
	}
	for name, memory := range cases {
		if process := feedTopMemory(newTopMemoryGrowthTracker(), start, topMemoryGrowthBuckets, memory); process.Growth != nil {
			t.Errorf("%s must not count as growth: %+v", name, process.Growth)
		}
	}
}

func TestTopMemoryGrowthNeedsContinuousBucketsAndForgetsGoneProcesses(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	tracker := newTopMemoryGrowthTracker()
	for minute := 0; minute <= topMemoryGrowthBuckets; minute++ {
		if minute == 5 {
			// 일시정지로 한 구간을 건너뛴다.
			continue
		}
		processes := []topProcess{{PID: 7, Started: start, Memory: uint64(minute) * (100 << 20), MemoryValid: true}}
		tracker.observe(start.Add(time.Duration(minute)*time.Minute), processes)
		if processes[0].Growth != nil {
			t.Fatalf("minute %d: a gap must stop the verdict until %d buckets refill: %+v", minute, topMemoryGrowthBuckets, processes[0].Growth)
		}
	}
	// 같은 PID라도 시작 시각이 다르면 다른 process다. 이전 기록은 지워진다.
	tracker.observe(start.Add(20*time.Minute), []topProcess{{PID: 7, Started: start.Add(time.Hour)}})
	if len(tracker.series) != 1 {
		t.Fatalf("series = %d, want only the new process", len(tracker.series))
	}
}

func TestTopMemoryGrowthSkipsSameMinuteRecalculation(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	tracker := newTopMemoryGrowthTracker()
	processes := []topProcess{{PID: 7, Started: start, Memory: 1 << 30, MemoryValid: true}}
	tracker.observe(start, processes)
	series := tracker.series[topProcessKey{pid: 7, started: start}]
	checks := series.checks
	tracker.observe(start.Add(10*time.Second), processes)
	if series.checks != checks {
		t.Fatalf("growth checks = %d, want %d", series.checks, checks)
	}
}

func TestTopMemoryGrowthKeepsCachedGrowthAboveSameMinuteMinimum(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	tracker := newTopMemoryGrowthTracker()
	process := feedTopMemory(tracker, start, topMemoryGrowthBuckets, func(minute int) uint64 { return 1<<30 + uint64(minute)*(30<<20) })
	if process.Growth == nil {
		t.Fatal("setup must produce growth")
	}
	series := tracker.series[topProcessKey{pid: 7, started: start}]
	checks, want := series.checks, *process.Growth
	processes := []topProcess{{PID: 7, Started: start, Memory: series.minimums[len(series.minimums)-1] + 1, MemoryValid: true}}
	tracker.observe(start.Add(14*time.Minute+30*time.Second), processes)
	if series.checks != checks || processes[0].Growth == nil || *processes[0].Growth != want {
		t.Fatalf("checks %d, growth %+v, want %+v", series.checks, processes[0].Growth, want)
	}
}

func TestTopMemoryGrowthRecomputesWhenSameMinuteMinimumDrops(t *testing.T) {
	start := time.Unix(1_800_000_000, 0)
	tracker := newTopMemoryGrowthTracker()
	process := feedTopMemory(tracker, start, topMemoryGrowthBuckets, func(minute int) uint64 { return 1<<30 + uint64(minute)*(30<<20) })
	if process.Growth == nil {
		t.Fatal("setup must produce growth")
	}
	series := tracker.series[topProcessKey{pid: 7, started: start}]
	checks := series.checks
	processes := []topProcess{{PID: 7, Started: start, Memory: 1 << 30, MemoryValid: true}}
	tracker.observe(start.Add(14*time.Minute+30*time.Second), processes)
	if series.checks != checks+1 || processes[0].Growth != nil {
		t.Fatalf("checks %d, growth %+v", series.checks, processes[0].Growth)
	}
}

