// topProcessBPFPrerequisites는 kernel이 이 program을 지원하는지 먼저 보고, 그다음 권한을 본다.
func topProcessBPFPrerequisites() error {
	return traceBPFPrerequisites("top --detail", topProcessKernelSupported)
}

func topProcessKernelSupported(spec *btf.Spec) error {
	if err := traceTracepointsAvailable(spec, topBPFTracepoints); err != nil {
		return err
	}
	// tp_btf는 인자 수만큼만 읽을 수 있다. 이 program은 sched_switch의 prev와 next, block_rq_complete의 nr_bytes를 읽는다.
	// sched_switch의 prev_state는 5.15에 없으므로, 없으면 top_switch_legacy가 task의 상태 field를 대신 읽는다.
	for _, required := range []struct {
		tracepoint string
		params     int
	}{{"sched_switch", 4}, {"block_rq_complete", 4}} {
		count, err := tracepointParams(spec, required.tracepoint)
		if err != nil {
			return err
		}
		if count < required.params {
			return fmt.Errorf("kernel tracepoint %s has %d arguments, need %d", required.tracepoint, count-1, required.params-1)
		}
	}
	for _, required := range []struct{ name, member string }{{"task_struct", "signal"}, {"signal_struct", "pids"}, {"pid", "numbers"}, {"pid_namespace", "ns"}, {"request", "__data_len"}} {
		if err := btfStructHasMember(spec, required.name, required.member); err != nil {
			return err
		}
	}
	if legacy, err := topSchedSwitchLegacy(spec); err != nil || !legacy {
		return err
	}
	if btfStructHasMember(spec, "task_struct", "__state") != nil && btfStructHasMember(spec, "task_struct", "state") != nil {
		return errors.New("kernel BTF has no field task_struct.__state")
	}
	return nil
}

// topSchedSwitchLegacy는 sched_switch가 prev_state를 넘기지 않는 kernel인지다. 첫 인자는 tp_btf가 쓰는 void *이고,
// preempt, prev, next 뒤에 prev_state가 오면 인자는 다섯이다.
func topSchedSwitchLegacy(spec *btf.Spec) (bool, error) {
	count, err := tracepointParams(spec, "sched_switch")
	if err != nil {
		return false, err
	}
	return count < 5, nil
}

type topProcessBPF struct {
	objects  topProcessEventsObjects
	links    []link.Link
	watched  map[int]struct{}
	previous map[int]topProbeStats
	at       time.Time
}

// startTopProcessProbe는 감시 pid가 없는 채로 program을 붙인다. 돌려주는 observer로 pid를 정하고, close로 모두 뗀다.
func startTopProcessProbe() (topProbeObserver, func(), error) {
	if err := topProcessBPFPrerequisites(); err != nil {
		return nil, nil, err
	}
	if err := rlimit.RemoveMemlock(); err != nil {
		return nil, nil, fmt.Errorf("remove memlock limit: %w", err)
	}
	namespace, err := pidNamespaceInode()
	if err != nil {
		return nil, nil, err
	}
	spec, err := loadTopProcessEvents()
	if err != nil {
		return nil, nil, fmt.Errorf("load eBPF objects: %w", err)
	}
	var variables topProcessEventsVariableSpecs
	if err := spec.Assign(&variables); err != nil {
		return nil, nil, fmt.Errorf("load eBPF variables: %w", err)
	}
	if err := variables.TargetNsInum.Set(namespace); err != nil {
		return nil, nil, fmt.Errorf("set PID namespace: %w", err)
	}
	kernel, err := btf.LoadKernelSpec()
	if err != nil {
		return nil, nil, fmt.Errorf("read kernel BTF: %w", err)
	}
	legacy, err := topSchedSwitchLegacy(kernel)
	if err != nil {
		return nil, nil, err
	}
	// 고르지 않은 program도 불러오면 verifier가 없는 인자를 읽는다고 거부하므로, 고른 program을 두 이름에 모두 넣는다.

selected := "top_switch"
if legacy {
	selected = "top_switch_legacy"
}
switchSpec := spec.Programs[selected]
if switchSpec == nil {
	return nil, nil, fmt.Errorf("missing eBPF program %s", selected)
}
for _, name := range []string{"top_switch", "top_switch_legacy"} {
	spec.Programs[name] = switchSpec.Copy()
	spec.Programs[name].Name = name
}
tracer := &topProcessBPF{watched: map[int]struct{}{}, previous: map[int]topProbeStats{}}
if err := spec.LoadAndAssign(&tracer.objects, nil); err != nil {
	return nil, nil, fmt.Errorf("load eBPF objects: %w", err)
}
for _, attachment := range []struct {
	name    string
	program *ebpf.Program
}{
	{"sched_wakeup", tracer.objects.TopWakeup}, {"sched_wakeup_new", tracer.objects.TopWakeupNew}, {"sched_switch", tracer.objects.TopSwitch},
	{"sched_process_exit", tracer.objects.TopExit}, {"block_rq_issue", tracer.objects.TopIssue}, {"block_rq_requeue", tracer.objects.TopRequeue},
	{"block_rq_complete", tracer.objects.TopComplete},
} {
	attached, err := link.AttachTracing(link.TracingOptions{Program: attachment.program, AttachType: ebpf.AttachTraceRawTp})
	if err != nil {
		tracer.close()
		return nil, nil, fmt.Errorf("attach tp_btf/%s: %w", attachment.name, err)
	}
	tracer.links = append(tracer.links, attached)
}
return tracer.observe, tracer.close, nil

func (tracer *topProcessBPF) close() {
	closeCaptureLinks(tracer.links)
	tracer.links = nil
	_ = tracer.objects.Close()
}

// observe는 pids만 감시하게 맞추고 pid마다 직전 관측 이후 센 값을 돌려준다. 이번에 새로 감시한 pid는 기준이 없어 다음 관측부터 나온다.
func (tracer *topProcessBPF) observe(pids []int) map[int]topProbeStats {
	now := time.Now()
	window := now.Sub(tracer.at)
	want := make(map[int]struct{}, min(len(pids), topBPFWatchedMax))
	for _, pid := range pids[:min(len(pids), topBPFWatchedMax)] {
		want[pid] = struct{}{}
	}
	observed := make(map[int]topProbeStats, len(tracer.watched))
	waits, waitKeys := tracer.readWaits()
	for pid := range tracer.watched {
		if _, keep := want[pid]; !keep {
			key := uint32(pid)
			_ = tracer.objects.Watched.Delete(key)
			_ = tracer.objects.Stats.Delete(key)
			for _, waitKey := range waitKeys[key] {
				_ = tracer.objects.Waits.Delete(waitKey)
			}
			delete(tracer.watched, pid)
			delete(tracer.previous, pid)
			continue
		}
		cumulative, err := tracer.read(pid, waits[uint32(pid)])
		if err != nil {
			continue
		}
		delta := cumulative.sub(tracer.previous[pid])
		delta.Window, delta.Source, delta.Measured = window, topProbeSourceEBPF, 1
		tracer.previous[pid] = cumulative
		observed[pid] = delta
	}
	for pid := range want {

		if _, ok := tracer.watched[pid]; ok {
			continue
		}
		if err := tracer.objects.Watched.Put(uint32(pid), uint8(1)); err != nil {
			continue
		}
		tracer.watched[pid] = struct{}{}
		tracer.previous[pid] = topProbeStats{RunqHist: &topProbeHist{}, IO: &topProbeIO{}, Waits: map[string]topProbeWait{}}
	}
	tracer.at = now
	return observed
}

// topWaitNoSyscall과 topWaitSyscallCompat은 top_process_bpf.c의 WAIT_NO_SYSCALL과 WAIT_SYSCALL_COMPAT이다.
const (
	topWaitNoSyscall     = 0xFFFF
	topWaitSyscallCompat = 0x8000
)

// readWaits는 대기 map을 한 번 돌아 tgid별 누적 대기와, 감시를 멈출 때 지울 key를 돌려준다. 읽지 못하면 비어 있다.
func (tracer *topProcessBPF) readWaits() (map[uint32]map[string]topProbeWait, map[uint32][]topProcessEventsWaitKey) {
	waits := map[uint32]map[string]topProbeWait{}
	keys := map[uint32][]topProcessEventsWaitKey{}
	var key topProcessEventsWaitKey
	var perCPU []topProcessEventsWaitStats
	iterator := tracer.objects.Waits.Iterate()
	for iterator.Next(&key, &perCPU) {
		name := "-"
		if key.Nr != topWaitNoSyscall {
			name = syscallName(runtime.GOARCH, key.Nr&^topWaitSyscallCompat, key.Nr&topWaitSyscallCompat != 0)
		}
		if waits[key.Tgid] == nil {
			waits[key.Tgid] = map[string]topProbeWait{}
		}
		total := waits[key.Tgid][name]
		for _, cpu := range perCPU {
			total.Count += cpu.Count
			total.SumNS += cpu.SumNs
		}
		waits[key.Tgid][name] = total
		keys[key.Tgid] = append(keys[key.Tgid], key)
	}
	return waits, keys
}

// read는 pid의 누적값을 모든 CPU에 걸쳐 더한다. 아직 이벤트가 없으면 0이다. eBPF는 분포와 I/O를 세므로 0이어도 채운다.
func (tracer *topProcessBPF) read(pid int, waits map[string]topProbeWait) (topProbeStats, error) {
	total := topProbeStats{RunqHist: &topProbeHist{}, IO: &topProbeIO{}, Waits: map[string]topProbeWait{}}
	for name, wait := range waits {
		total.Waits[name] = wait
	}
	var perCPU []topProcessEventsProcessStats
	if err := tracer.objects.Stats.Lookup(uint32(pid), &perCPU); err != nil {
		if errors.Is(err, ebpf.ErrKeyNotExist) {
			return total, nil
		}
		return topProbeStats{}, err
	}
	for _, cpu := range perCPU {
		total.RunqCount += cpu.RunqCount
		total.RunqSumNS += cpu.RunqSumNs
		total.IO.Count += cpu.IoCount
		total.IO.Bytes += cpu.IoBytes
		total.IO.SumNS += cpu.IoSumNs
		for index := range total.RunqHist {
			total.RunqHist[index] += cpu.RunqHist[index]
			total.IO.Hist[index] += cpu.IoHist[index]
		}
	}
	return total, nil
}

func topBTFSpec(t *testing.T, types ...btf.Type) *btf.Spec {
	t.Helper()
	builder, err := btf.NewBuilder(types, nil)
	if err != nil {
		t.Fatal(err)
	}
	raw, err := builder.Marshal(nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	spec, err := btf.LoadSpecFromReader(bytes.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	return spec
}

func topTracepointType(name string, params int) btf.Type {
	void := &btf.Void{}
	proto := &btf.FuncProto{Return: void}
	for range params {
		proto.Params = append(proto.Params, btf.FuncParam{Type: &btf.Int{Name: "long", Size: 8}})
	}
	return &btf.Typedef{Name: "btf_trace_" + name, Type: &btf.Pointer{Target: proto}}
}

func TestTracepointParamsCountsTheFunctionPrototype(t *testing.T) {
	spec := topBTFSpec(t, topTracepointType("sched_switch", 5), topTracepointType("block_rq_complete", 3))
	if got, err := tracepointParams(spec, "sched_switch"); err != nil || got != 5 {
		t.Fatalf("sched_switch = %d, %v", got, err)
	}
	if err := topProcessKernelSupported(spec); err == nil || !strings.Contains(err.Error(), "block_rq_complete has 2 arguments") && !strings.Contains(err.Error(), "no tracepoint") {
		t.Fatalf("a kernel with a short tracepoint or missing tracepoints must be unsupported: %v", err)
	}
	if _, err := tracepointParams(spec, "missing"); err == nil {
		t.Fatal("a missing tracepoint must be an error")
	}
}

// BTF에 같은 이름의 struct가 둘 이상인 kernel(OrbStack 7.0)에서 하나라도 member를 가지면 통과한다.
func TestBTFStructHasMemberAcceptsDuplicateStructs(t *testing.T) {
	u32 := &btf.Int{Name: "u32", Size: 4}
	task := func(fields ...string) *btf.Struct {
		members := make([]btf.Member, len(fields))
		for index, field := range fields {
			members[index] = btf.Member{Name: field, Type: u32, Offset: btf.Bits(32 * index)}
		}
		return &btf.Struct{Name: "task_struct", Size: uint32(4 * len(fields)), Members: members}
	}
	if err := btfStructHasMember(topBTFSpec(t, task("pid"), task("pid", "signal")), "task_struct", "signal"); err != nil {
		t.Fatalf("duplicate task_struct: %v", err)
	}
	if err := btfStructHasMember(topBTFSpec(t, task("pid")), "task_struct", "signal"); err == nil || !strings.Contains(err.Error(), "task_struct.signal") {
		t.Fatalf("missing field: %v", err)
	}
	if err := btfStructHasMember(topBTFSpec(t, u32), "task_struct", "signal"); err == nil || !strings.Contains(err.Error(), "no type task_struct") {
		t.Fatalf("missing type: %v", err)
	}
}

// 5.15의 sched_switch는 prev_state 없이 preempt, prev, next만 넘긴다. 그 kernel은 task 상태 field를 읽는 program으로 지원한다.
func TestTopProcessKernelSupportedAcceptsSchedSwitchWithoutPrevState(t *testing.T) {
	u32 := &btf.Int{Name: "u32", Size: 4}
	structure := func(name string, fields ...string) *btf.Struct {
		members := make([]btf.Member, len(fields))
		for index, field := range fields {
			members[index] = btf.Member{Name: field, Type: u32, Offset: btf.Bits(32 * index)}
		}
		return &btf.Struct{Name: name, Size: uint32(4 * len(fields)), Members: members}
	}
	kernel := func(switchParams int, taskFields ...string) *btf.Spec {
		types := []btf.Type{
			structure("task_struct", append([]string{"signal"}, taskFields...)...), structure("signal_struct", "pids"),
			structure("pid", "numbers"), structure("pid_namespace", "ns"), structure("request", "__data_len"),
		}
		for _, name := range topBPFTracepoints {
			params := 2
			switch name {
			case "sched_switch":
				params = switchParams
			case "block_rq_complete":
				params = 4
			}
			types = append(types, topTracepointType(name, params))
		}
		return topBTFSpec(t, types...)
	}
	if err := topProcessKernelSupported(kernel(4, "__state")); err != nil {
		t.Fatalf("5.15 kernel: %v", err)
	}
	if legacy, err := topSchedSwitchLegacy(kernel(4, "__state")); err != nil || !legacy {
		t.Fatalf("5.15 kernel legacy = %t, %v", legacy, err)

	}
	if err := topProcessKernelSupported(kernel(4)); err == nil || !strings.Contains(err.Error(), "task_struct.__state") {
		t.Fatalf("a kernel without a task state field must be unsupported: %v", err)
	}
	if legacy, err := topSchedSwitchLegacy(kernel(5)); err != nil || legacy {
		t.Fatalf("a kernel with prev_state legacy = %t, %v", legacy, err)
	}
	if err := topProcessKernelSupported(kernel(3, "__state")); err == nil || !strings.Contains(err.Error(), "sched_switch has 2 arguments") {
		t.Fatalf("a kernel without next must be unsupported: %v", err)
	}
}

