model := newTraceScreenModel("redis", tcpTraceOptions{}, make(chan captureEvent), make(chan traceFinishedMsg), nil)
model.width, model.height = 160, 20
model.events = events
paired := 0
for _, row := range traceVisibleScreenRows(model) {
	if row.response >= 0 {
		paired++
		if events[row.primary].Redis.Command != events[row.response].Redis.Command {
			t.Fatalf("row pairs %s with %s", events[row.primary].Redis.Command, events[row.response].Redis.Command)
		}
	}
}
if uint64(paired) != report.Replies {
	t.Fatalf("paired rows = %d, replies %d", paired, report.Replies)

const (
	traceDNSQueryEvent      = "dns_query"
	traceDNSTruncatedEvent  = "dns_truncated"
	traceDNSTCPConnectEvent = "dns_tcp_connect"
	traceDNSTCPFailEvent    = "dns_tcp_fail"
	traceDNSTCPAcceptEvent  = "dns_tcp_accept"
	traceDNSHeaderSize      = 12
	// traceDNSPendingLimit은 응답을 기다리는 질의 수의 상한이다. 응답이 오지 않는 질의가 쌓여도 메모리를 제한한다.
	traceDNSPendingLimit = 65536
	// traceDNSTruncatedLimit은 TCP로 다시 물을 이름을 기억하는 수의 상한이다.
	traceDNSTruncatedLimit = 1024
)

// dnsQueryKey의 remote는 client 쪽이면 DNS 서버, 서버 쪽이면 질의한 client다.
type dnsQueryKey struct {
	server    bool
	localPort string
	remote    string
	id        uint16
}

type dnsPendingQuery struct {
	bootTimeNS uint64
	name       string
	queryType  string
}

// dnsTruncatedKey는 잘린 응답이 오간 process와 상대 host다. client 쪽은 응답을 받은 process와 서버, 서버 쪽은 응답을 보낸
// client다. 그 client가 TCP로 다시 물으면 이 이름을 붙인다. 서버 쪽 accept event는 process를 모를 수 있어 pid를 0으로 둔다.
type dnsTruncatedKey struct {
	pid  uint32
	peer string
}

// dnsQueryTracker는 응답을 같은 로컬 port, 상대, transaction ID의 질의와 짝지어 응답 시간을 잰다. client 쪽은 질의를
// 보낸 때부터 응답을 읽은 때까지, 서버 쪽은 질의를 읽은 때부터 응답을 보낸 때까지다.
// 응답 하나는 같은 key로 다시 보낸 질의까지 모두 답한 것으로 보고, 응답 시간은 처음 보낸 질의부터 잰다.
// server는 tracker가 볼 쪽이다. 다른 쪽 message는 짝도 기억하지 않는다. --side server에서도 client 쪽 레코드는
// kernel에서 오므로, 기록하면 쓰지 않을 질의와 잘린 응답이 map을 채운다.
type dnsQueryTracker struct {
	server    bool
	pending   map[dnsQueryKey][]dnsPendingQuery
	size      int
	truncated map[dnsTruncatedKey]dnsPendingQuery
}

func newDNSQueryTracker(server bool) *dnsQueryTracker {
	return &dnsQueryTracker{server: server, pending: map[dnsQueryKey][]dnsPendingQuery{}, truncated: map[dnsTruncatedKey]dnsPendingQuery{}}
}

func (tracker *dnsQueryTracker) remember(key dnsQueryKey, query dnsPendingQuery) {
	if tracker.size >= traceDNSPendingLimit {
		// 이때 버린 질의의 응답은 응답 시간 없이 보인다.
		clear(tracker.pending)
		tracker.size = 0
	}
	tracker.pending[key] = append(tracker.pending[key], query)
	tracker.size++
}

func (tracker *dnsQueryTracker) event(packet dnsPacket, clockOffset int64) (captureEvent, bool) {
	if len(packet.payload) < traceDNSHeaderSize {
		return captureEvent{}, false
	}
	id := binary.BigEndian.Uint16(packet.payload[0:2])
	flags := binary.BigEndian.Uint16(packet.payload[2:4])
	_, localPort, _ := net.SplitHostPort(packet.source)
	_, remotePort, _ := net.SplitHostPort(packet.destination)
	// client는 port 53으로 질의를 보내고 port 53에서 응답을 받는다. 서버는 로컬 port 53으로 질의를 받고 응답을 보낸다.
	// QR bit와 방향, port가 어느 쪽에도 맞지 않으면 뺀다.
	query := flags&0x8000 == 0
	var server bool
	switch {
	case remotePort == "53" && query == packet.sent:
	case localPort == "53" && query != packet.sent:
		server = true
	default:
		return captureEvent{}, false
	}
	if server != tracker.server {
		return captureEvent{}, false
	}
	event := captureEvent{
		TimestampNS: uint64(int64(packet.bootTimeNS) + clockOffset),
		BootTimeNS:  packet.bootTimeNS,
		Protocol:    "dns",
		PID:         packet.pid,
		Process:     packet.process,
		CgroupID:    packet.cgroupID,
		Source:      packet.source,
		Destination: packet.destination,
		Bytes:       uint64(len(packet.payload)),

}
var message dns.Msg
parsed := message.Unpack(packet.payload) == nil && len(message.Question) > 0
if parsed {
	event.Target = traceDNSName(message.Question[0].Name)
	event.QueryType = dns.Type(message.Question[0].Qtype).String()
}
if server {
	event.Side = traceServerSide
}
// 받은 message만 수신 큐 시각이 있다. client 쪽은 응답을, 서버 쪽은 질의를 받는다.
if !packet.sent && packet.arrivalNS != 0 {
	event.ReadDelayMS = traceSpan(packet.arrivalNS, packet.bootTimeNS)
}
key := dnsQueryKey{server: server, localPort: localPort, remote: packet.destination, id: id}
if query {
	event.Event = traceDNSQueryEvent
	tracker.remember(key, dnsPendingQuery{bootTimeNS: packet.bootTimeNS, name: event.Target, queryType: event.QueryType})
	return event, true
}
// 응답이 BPF가 읽는 1024바이트보다 길면 해석하지 못한다. header의 RCODE와 ANCOUNT로 결과를 정하고, 이름은 질의에서 가져온다.
rcode, answers := int(flags&0xF), int(binary.BigEndian.Uint16(packet.payload[6:8]))
if parsed {
	rcode = message.Rcode
	event.Answers = dnsAnswerAddresses(message)
}
event.Event = traceDNSAnswerEvent(rcode, answers)
if queries := tracker.pending[key]; len(queries) > 0 {
	delete(tracker.pending, key)
	tracker.size -= len(queries)
	event.LatencyMS = traceSpan(queries[0].bootTimeNS, packet.bootTimeNS)
	if !packet.sent && packet.arrivalNS != 0 {

			event.NetworkMS = traceSpan(queries[0].bootTimeNS, packet.arrivalNS)
		}
		event.answered = uint64(len(queries))
		if event.Target == "" {
			event.Target, event.QueryType = queries[0].name, queries[0].queryType
		}
	}
	// TC bit는 응답이 UDP에 다 들어가지 않았다는 뜻이다. client는 같은 서버에 TCP로 다시 묻는다.
	if flags&0x0200 != 0 {
		event.Event = traceDNSTruncatedEvent
		if len(tracker.truncated) >= traceDNSTruncatedLimit {
			clear(tracker.truncated)
		}
		tracker.truncated[tracker.truncatedKey(packet.pid, packet.destination)] = dnsPendingQuery{name: event.Target, queryType: event.QueryType}
	}
	return event, true
}

// tcpEvent는 port 53의 TCP 연결을 DNS event로 바꾼다. client 쪽은 port 53으로 가는 연결과 실패를, 서버 쪽은 로컬 port 53이
// 받은 연결을 본다. TCP로 주고받는 DNS message는 읽지 않는다.
func (tracker *dnsQueryTracker) tcpEvent(event captureEvent) (captureEvent, bool) {
	if traceProtocol(event) != "tcp" {
		return captureEvent{}, false
	}
	name, port := "", 0
	switch {
	case tracker.server && event.Event == "tcp_accept":
		name, port = traceDNSTCPAcceptEvent, traceDNSPort(event.Source)
	case !tracker.server && event.Event == "tcp_connect":
		name, port = traceDNSTCPConnectEvent, traceDNSPort(event.Destination)
	case !tracker.server && event.Event == "tcp_close" && event.OldState == "SYN_SENT":
		name, port = traceDNSTCPFailEvent, traceDNSPort(event.Destination)
	}
	if port != 53 {
		return captureEvent{}, false
	}
	dnsEvent := captureEvent{
		TimestampNS: event.TimestampNS, BootTimeNS: event.BootTimeNS, Event: name, Protocol: "dns", PID: event.PID, Process: event.Process,
		CgroupID: event.CgroupID, Source: event.Source, Destination: event.Destination, Transport: "tcp",
	}
	if tracker.server {
		dnsEvent.Side = traceServerSide
	}
	key := tracker.truncatedKey(event.PID, event.Destination)
	if query, ok := tracker.truncated[key]; ok {
		delete(tracker.truncated, key)
		dnsEvent.Target, dnsEvent.QueryType = query.name, query.queryType
	}
	return dnsEvent, true
}

func (tracker *dnsQueryTracker) truncatedKey(pid uint32, peer string) dnsTruncatedKey {
	if tracker.server {
		pid = 0
	}
	return dnsTruncatedKey{pid: pid, peer: traceDNSHost(peer)}
}

func traceDNSPort(address string) int {
	port, _ := traceAddressPort(address)
	return port
}

func traceDNSHost(address string) string {
	host, _, err := net.SplitHostPort(address)
	if err != nil {
		return address
	}
	return host
}

type dnsTCPStreamKey struct {
	socket uint64
	sent   bool
}

// dnsTCPStreams는 TCP로 주고받은 조각에서 DNS message를 꺼낸다. DNS over TCP는 message 앞에 2바이트 길이를 붙인다.
// 길이와 message를 따로 읽거나 쓰는 program이 많아, 길이만 온 조각은 연결과 방향마다 기억했다가 다음 조각을 message로 본다.
type dnsTCPStreams struct {
	pending map[dnsTCPStreamKey]int
}

func newDNSTCPStreams() *dnsTCPStreams {
	return &dnsTCPStreams{pending: map[dnsTCPStreamKey]int{}}
}

func (streams *dnsTCPStreams) forgetSocket(socket uint64) {
	delete(streams.pending, dnsTCPStreamKey{socket: socket, sent: true})
	delete(streams.pending, dnsTCPStreamKey{socket: socket, sent: false})
}

// messages는 조각 하나에 든 DNS message다. BPF는 조각의 앞 capacity byte만 읽으므로, 잘린 message는 잘린 채로 돌려준다.
// 뒤의 해석이 header로 결과를 읽는다.
func (streams *dnsTCPStreams) messages(key dnsTCPStreamKey, chunk []byte, capacity int) [][]byte {
	if expected, ok := streams.pending[key]; ok {
		delete(streams.pending, key)
		// 앞 조각이 길이였고 이 조각이 그 길이면 message 본문이다. 길이가 맞지 않으면 이 조각을 새로 읽는다.
		if len(chunk) >= traceDNSHeaderSize && (len(chunk) == expected || (len(chunk) == capacity && expected > capacity)) {
			return [][]byte{chunk}
		}
	}
	var messages [][]byte
	for len(chunk) >= 2 {
		length := int(binary.BigEndian.Uint16(chunk[0:2]))
		if len(chunk) == 2 {
			if len(streams.pending) >= dnsTCPStreamLimit {
				clear(streams.pending)
			}
			streams.pending[key] = length
			break
		}
		body := chunk[2:]
		if length < traceDNSHeaderSize || len(body) < traceDNSHeaderSize {
			break
		}
		if len(body) <= length {
			messages = append(messages, body)
			break
		}
		messages = append(messages, body[:length])
		chunk = body[length:]
	}
	return messages

func traceDNSName(name string) string {
	return strings.ToLower(strings.TrimSuffix(name, "."))
}

// traceDNSAnswerEvent는 응답을 RCODE로 이름 붙인다. 주소 없이 성공한 응답은 오류가 아니라서 nodata로 따로 둔다.
func traceDNSAnswerEvent(rcode, answers int) string {
	if rcode == dns.RcodeSuccess && answers == 0 {
		return "dns_nodata"
	}
	if name, ok := dns.RcodeToString[rcode]; ok {
		return "dns_" + strings.ToLower(name)
	}
	return "dns_rcode" + strconv.Itoa(rcode)
}

// traceDNSError는 조회가 실패한 결과다. 잘린 응답과 TCP 연결은 TCP로 다시 묻는 과정이라 오류로 세지 않는다.
func traceDNSError(event string) bool {
	switch event {
	case traceDNSQueryEvent, "dns_noerror", "dns_nodata", traceDNSTruncatedEvent, traceDNSTCPConnectEvent, traceDNSTCPAcceptEvent:
		return false
	}
	return true
}

func dnsAnswerAddresses(message dns.Msg) []string {
	var addresses []string
	for _, answer := range message.Answer {
		var ip net.IP
		switch record := answer.(type) {
		case *dns.A:
			ip = record.A
		case *dns.AAAA:
			ip = record.AAAA
		default:
			continue
		}
		if address, ok := netip.AddrFromSlice(ip); ok {
			addresses = append(addresses, address.Unmap().String())
		}
	}
	return addresses
}

func (counts *traceDNSCounts) observe(event captureEvent) {
	counts.readDelay.observe(event.ReadDelayMS)
	switch event.Event {
	case traceDNSQueryEvent:
		counts.Queries++
		return
	case traceDNSTCPConnectEvent, traceDNSTCPFailEvent, traceDNSTCPAcceptEvent:
		counts.TCPConnections++
		if traceDNSError(event.Event) {
			counts.Errors++
		}
		return
	}
	counts.Answers++
	if traceDNSError(event.Event) {
		counts.Errors++
	}
	counts.answered += event.answered
	counts.latency.observe(event.LatencyMS)
	counts.network.observe(event.NetworkMS)
}

// finished는 보여 줄 값을 채운 복사본이다. 쌓은 값은 그대로 두어 같은 요약을 다시 만들 수 있다. 전체 화면은
// 최근 event만 두므로 질의가 창 밖으로 밀린 응답이 있어 응답 없음을 0 밑으로 내리지 않는다.
func (counts traceDNSCounts) finished() traceDNSCounts {
	counts.Unanswered = counts.Queries - min(counts.Queries, counts.answered)
	counts.LatencyAvgMS, counts.LatencyMaxMS = counts.latency.summary()
	counts.NetworkAvgMS, counts.NetworkMaxMS = counts.network.summary()
	counts.ReadDelayAvgMS, counts.ReadDelayMaxMS = counts.readDelay.summary()
	return counts
}

func traceDNSGroupSummary(counts *traceDNSCounts) *traceDNSCounts {
	if counts == nil {
		return nil
	}
	finished := counts.finished()
	return &finished
}

func traceDNSColumn(value func(counts traceDNSCounts) string) func(traceGroupSummary) string {
	return func(group traceGroupSummary) string {
		if group.DNS == nil {
			return "-"
		}
		return value(*group.DNS)
	}
}

// traceDNSScrollLabels는 스크롤 행의 목적지 칸에 조회한 이름, 레코드 종류, 서버를, event 칸에 결과와 응답 시간을 쓴다.
func traceDNSScrollLabels(event captureEvent) (string, string) {
	name := emptyAs(event.Target, "-")
	if event.QueryType != "" {
		name += " " + event.QueryType
	}
	if event.Destination != "" {
		name += " (" + event.Destination + ")"
	}
	label := event.Event
	if event.LatencyMS != nil {
		label += " " + traceLatency(event.LatencyMS, "ms")
	}
	return name, label
}

type dnsTraceNameKey struct {
	name      string
	queryType string
}

type dnsTraceNameStats struct {
	processes map[string]struct{}
	servers   map[string]struct{}
	addresses map[string]struct{}
	results   map[string]uint64
	counts    traceDNSCounts
}

// dnsTraceSummarizer는 --group-by 없이 끝난 DNS trace를 조회한 이름과 레코드 종류마다 한 행으로 묶는다.
type dnsTraceSummarizer struct {
	names   map[dnsTraceNameKey]*dnsTraceNameStats
	results map[string]uint64
	counts  traceDNSCounts
	side    string
}

func newDNSTraceSummarizer() *dnsTraceSummarizer {
	return &dnsTraceSummarizer{names: map[dnsTraceNameKey]*dnsTraceNameStats{}, results: map[string]uint64{}}
}

func (summarizer *dnsTraceSummarizer) observe(event captureEvent) {
	if event.Side != "" {
		summarizer.side = event.Side
	}
	key := dnsTraceNameKey{name: emptyAs(event.Target, "-"), queryType: event.QueryType}
	stats := summarizer.names[key]
	if stats == nil {
		stats = &dnsTraceNameStats{processes: map[string]struct{}{}, servers: map[string]struct{}{}, addresses: map[string]struct{}{}, results: map[string]uint64{}}
		summarizer.names[key] = stats
	}
	if event.Process != "" {
		stats.processes[event.Process] = struct{}{}
	}
	if event.Destination != "" {
		stats.servers[event.Destination] = struct{}{}
	}
	for _, address := range event.Answers {
		stats.addresses[address] = struct{}{}
	}
	if event.Event != traceDNSQueryEvent {
		result := strings.TrimPrefix(event.Event, "dns_")
		stats.results[result]++
		summarizer.results[result]++
	}
	stats.counts.observe(event)
	summarizer.counts.observe(event)
}

func (summarizer *dnsTraceSummarizer) summarize(summary captureSummary, duration time.Duration) traceReport {
	report := dnsTraceReport{Side: summarizer.side, DurationMS: duration.Milliseconds(), LostEvents: summary.LostEvents, Results: maps.Clone(summarizer.results), traceDNSCounts: summarizer.counts.finished()}
	report.Names = make([]dnsTraceName, 0, len(summarizer.names))
	for key, stats := range summarizer.names {
		report.Names = append(report.Names, dnsTraceName{
			Name: key.name, Type: key.queryType, Processes: slices.Sorted(maps.Keys(stats.processes)), Servers: slices.Sorted(maps.Keys(stats.servers)),
			Addresses: slices.Sorted(maps.Keys(stats.addresses)), Results: maps.Clone(stats.results), traceDNSCounts: stats.counts.finished(),
		})
	}
	sort.Slice(report.Names, func(i, j int) bool {
		left, right := report.Names[i], report.Names[j]
		if left.Queries != right.Queries {
			return left.Queries > right.Queries
		}
		if left.Name != right.Name {
			return left.Name < right.Name
		}
		return left.Type < right.Type
	})
	return report
}

// print는 detail과 상관없이 같다. DNS 요약은 이미 이름과 record 종류마다 한 행이고, 질의마다의 행은 두지 않는다.
func (report dnsTraceReport) print(bool) {
	title := "DNS trace"
	if report.Side == traceServerSide {
		title = "DNS server trace"
	}
	out := os.Stdout
	style := newTraceSummaryStyle(out)
	style.line(out, style.title(title, (time.Duration(report.DurationMS)*time.Millisecond).String()))
	io.WriteString(out, "\n")
	style.fields(out, "", "Queries", fmt.Sprint(report.Queries), "Answers", fmt.Sprint(report.Answers), "Errors", fmt.Sprint(report.Errors), "Unanswered", fmt.Sprint(report.Unanswered), "TCP connections", fmt.Sprint(report.TCPConnections),
		"Latency avg", traceLatency(report.LatencyAvgMS, "ms"), "Latency max", traceLatency(report.LatencyMaxMS, "ms"), "Network avg", traceLatency(report.NetworkAvgMS, "ms"), "Network max", traceLatency(report.NetworkMaxMS, "ms"),
		"Read delay avg", traceLatency(report.ReadDelayAvgMS, "ms"), "Read delay max", traceLatency(report.ReadDelayMaxMS, "ms"), "Lost events", fmt.Sprint(report.LostEvents))
	if len(report.Names) == 0 {
		return
	}
	table := traceTable{titles: []string{"NAME", "TYPE", "QUERIES", "ANSWERS", "RESULTS", "UNANSWERED", "AVG", "MAX", "NET", "READ", "PROCESS"}}
	for _, name := range report.Names {
		table.add(name.Name, emptyAs(name.Type, "-"), fmt.Sprint(name.Queries), fmt.Sprint(name.Answers), traceResultCounts(name.Results), fmt.Sprint(name.Unanswered), traceLatency(name.LatencyAvgMS, "ms"), traceLatency(name.LatencyMaxMS, "ms"), traceLatency(name.NetworkAvgMS, "ms"), traceLatency(name.ReadDelayAvgMS, "ms"), emptyAs(strings.Join(name.Processes, ","), "-"))
	}
	io.WriteString(out, "\n")
	style.writeTable(out, table)
}

// dnsRecordType은 BPF가 DNS 질의와 응답을 넘기는 레코드다. trace dns만 이것을 event로 바꾼다.
// offset은 capture_events_bpf.c의 struct dns_record와 같다.
const (
	dnsRecordType          = 9
	dnsRecordSent          = 1
	dnsRecordTCP           = 1
	dnsRecordPayloadOffset = 100
	// dnsRecordPayloadSize는 BPF가 읽는 message 앞부분의 크기다. capture_events_bpf.c의 DNS_PAYLOAD_SIZE와 같다.
	dnsRecordPayloadSize = 1024
)

const (
	targetSourceCommand       = "command"
	targetSourceDNS           = "dns"
	targetSourceResolverCache = "resolver-cache"
)

type dnsProcessAddress struct {
	pid     uint32
	address netip.Addr
}

type dnsName struct {
	name   string
	source string
}

// dnsNameCache는 DNS 응답과 resolver 캐시에서 본 주소의 이름이다. 프로세스가 직접 조회한 이름을 따로 둔다.
// CDN처럼 한 주소를 여러 이름이 함께 쓰면 주소별 이름은 다른 프로세스의 조회일 수 있다.
type dnsNameCache struct {
	byProcess map[dnsProcessAddress]string
	byAddress map[netip.Addr]dnsName
}

func newDNSNameCache() *dnsNameCache {
	return &dnsNameCache{byProcess: map[dnsProcessAddress]string{}, byAddress: map[netip.Addr]dnsName{}}
}

func (cache *dnsNameCache) rememberAnswer(pid uint32, names map[netip.Addr]string) {
	for address, name := range names {
		key := dnsProcessAddress{pid: pid, address: address}
		if _, ok := cache.byProcess[key]; !ok && len(cache.byProcess) >= dnsNameLimit {
			clear(cache.byProcess)
		}
		cache.byProcess[key] = name
		cache.rememberAddress(address, name, targetSourceDNS)
	}
}

func (cache *dnsNameCache) rememberAddress(address netip.Addr, name, source string) {
	if _, ok := cache.byAddress[address]; !ok && len(cache.byAddress) >= dnsNameLimit {
		clear(cache.byAddress)
	}
	cache.byAddress[address] = dnsName{name: name, source: source}
}

func (cache *dnsNameCache) forProcess(pid uint32, destination string) (string, bool) {
	address, ok := traceDestinationAddress(destination)
	if !ok {
		return "", false
	}
	name, ok := cache.byProcess[dnsProcessAddress{pid: pid, address: address}]
	return name, ok
}

func (cache *dnsNameCache) forAddress(destination string) (dnsName, bool) {
	address, ok := traceDestinationAddress(destination)
	if !ok {
		return dnsName{}, false
	}
	name, ok := cache.byAddress[address]
	return name, ok
}

// traceDestinationAddress는 event의 host:port에서 주소를 꺼낸다. 문자열이 아니라 netip 값으로 비교해야
// 같은 IPv6 주소의 여러 표기(축약, 풀어 쓴 형태, v4-mapped)가 한 주소로 맞는다.
func traceDestinationAddress(destination string) (netip.Addr, bool) {
	host, _, err := net.SplitHostPort(destination)
	if err != nil {
		return netip.Addr{}, false
	}
	address, err := netip.ParseAddr(host)
	if err != nil || address.IsUnspecified() {
		return netip.Addr{}, false
	}
	return address.Unmap(), true
}

func parseDNSRecord(sample []byte) (dnsPacket, bool) {
	if len(sample) < dnsRecordPayloadOffset || binary.LittleEndian.Uint32(sample[8:12]) != dnsRecordType {
		return dnsPacket{}, false
	}
	family := binary.LittleEndian.Uint16(sample[44:46])
	var source, destination [16]byte
	copy(source[:], sample[52:68])
	copy(destination[:], sample[68:84])
	packet := dnsPacket{
		bootTimeNS:  binary.LittleEndian.Uint64(sample[0:8]),
		pid:         binary.LittleEndian.Uint32(sample[12:16]),
		cgroupID:    binary.LittleEndian.Uint64(sample[16:24]),
		arrivalNS:   binary.LittleEndian.Uint64(sample[24:32]),
		socket:      binary.LittleEndian.Uint64(sample[32:40]),
		sent:        sample[46] == dnsRecordSent,
		tcp:         sample[47] == dnsRecordTCP,
		source:      formatCaptureAddress(family, source, binary.LittleEndian.Uint16(sample[48:50])),
		destination: formatCaptureAddress(family, destination, binary.LittleEndian.Uint16(sample[50:52])),
		process:     strings.TrimRight(string(sample[84:100]), "\x00"),
		payload:     sample[dnsRecordPayloadOffset:],
	}
	if size := int(binary.LittleEndian.Uint32(sample[40:44])); size < len(packet.payload) {
		packet.payload = packet.payload[:size]
	}
	return packet, true
}

// dnsAnswerNames는 응답의 A와 AAAA 주소를 질의 이름에 연결한다. CNAME을 거쳐도 프로그램이 물어본 이름이
// 사용자에게 의미가 있다. 잘린 응답은 해석하지 않는다.
func dnsAnswerNames(payload []byte) map[netip.Addr]string {
	var message dns.Msg
	if err := message.Unpack(payload); err != nil || !message.Response || len(message.Question) == 0 {
		return nil
	}
	name := traceDNSName(message.Question[0].Name)
	names := map[netip.Addr]string{}
	for _, answer := range message.Answer {
		var ip net.IP
		switch record := answer.(type) {
		case *dns.A:
			ip = record.A
		case *dns.AAAA:
			ip = record.AAAA
		default:
			continue
		}
		if address, ok := netip.AddrFromSlice(ip); ok {
			names[address.Unmap()] = name
		}
	}
	return names
}

// seedResolverCache는 trace 전에 조회된 이름을 systemd-resolved 캐시에서 채운다. resolvectl이 없거나
// 실패하면 채우지 않는다. 그때는 trace 중에 본 DNS 응답과 명령줄만으로 이름을 정한다.
func seedResolverCache(cache *dnsNameCache) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	output, err := exec.CommandContext(ctx, "resolvectl", "show-cache").Output()
	if err != nil {
		return
	}
	for address, name := range resolverCacheNames(string(output)) {
		cache.rememberAddress(address, name, targetSourceResolverCache)
	}
}

// resolverCacheNames는 "name IN A 1.2.3.4" 형식의 줄을 읽는다. 주소는 CNAME을 거슬러 올라간 첫 이름에
// 연결한다. 여러 이름이 같은 곳을 가리키면 사전순으로 첫 이름을 쓴다.
func resolverCacheNames(output string) map[netip.Addr]string {
	aliases := map[string][]string{}
	owners := map[netip.Addr][]string{}
	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) != 4 || fields[1] != "IN" {
			continue
		}
		name := traceDNSName(fields[0])
		switch fields[2] {
		case "CNAME":
			target := traceDNSName(fields[3])
			aliases[target] = append(aliases[target], name)
		case "A", "AAAA":
			if address, err := netip.ParseAddr(fields[3]); err == nil {
				owners[address.Unmap()] = append(owners[address.Unmap()], name)
			}
		}
	}
	names := map[netip.Addr]string{}
	for address, list := range owners {
		heads := []string{}
		for _, owner := range list {
			heads = append(heads, resolverAliasHeads(owner, aliases, map[string]bool{})...)
		}
		sort.Strings(heads)
		names[address] = heads[0]
	}
	return names

func resolverAliasHeads(name string, aliases map[string][]string, seen map[string]bool) []string {
	if seen[name] {
		return []string{name}
	}
	seen[name] = true
	parents := aliases[name]
	if len(parents) == 0 {
		return []string{name}
	}
	heads := []string{}
	for _, parent := range parents {
		heads = append(heads, resolverAliasHeads(parent, aliases, seen)...)
	}
	return heads
}

// resolveTraceTarget은 target과 그 출처를 정한다. 프로세스가 trace 중에 직접 조회한 이름이 가장 확실하고,
// 명령줄 인자는 파일 이름을 잘못 고를 수 있어 그다음이다. 주소별 이름은 다른 프로세스의 조회일 수 있어 마지막이다.
func resolveTraceTarget(event captureEvent, commandTarget string, names *dnsNameCache) (string, string) {
	if event.PID != 0 {
		if name, ok := names.forProcess(event.PID, event.Destination); ok {
			return name, targetSourceDNS
		}
	}
	if commandTarget != "" && commandTargetFits(commandTarget, event.Destination) {
		return commandTarget, targetSourceCommand
	}
	if name, ok := names.forAddress(event.Destination); ok {
		return name.name, name.source
	}
	return "", ""
}

// commandTargetFits는 명령줄 target이 IP(또는 user@IP)이면 그 주소로 가는 event에만 맞다고 본다. 명령줄 target은
// 프로세스의 모든 event에 붙으므로, IP가 다른 연결에 붙으면 그 연결의 상대를 틀리게 보여 준다. 호스트 이름은
// 주소를 알 수 없어서 그대로 맞다고 본다.
func commandTargetFits(commandTarget, destination string) bool {
	host := commandTarget
	if _, after, ok := strings.Cut(commandTarget, "@"); ok {
		host = after
	}
	target, err := netip.ParseAddr(host)
	if err != nil {
		return true
	}
	address, ok := traceDestinationAddress(destination)
	return ok && address == target.Unmap()
}

func dnsTestPacket(t *testing.T, message *dns.Msg, at uint64, source string) dnsPacket {
	t.Helper()
	payload, err := message.Pack()
	if err != nil {
		t.Fatal(err)
	}
	return dnsPacket{bootTimeNS: at, pid: 10, process: "dig", sent: !message.Response, source: source, destination: "127.0.0.53:53", payload: payload}
}

func dnsTestReply(t *testing.T, question *dns.Msg, rcode int, records ...string) *dns.Msg {
	t.Helper()
	reply := new(dns.Msg)
	reply.SetRcode(question, rcode)
	for _, text := range records {
		record, err := dns.NewRR(text)
		if err != nil {
			t.Fatal(err)
		}
		reply.Answer = append(reply.Answer, record)
	}
	return reply
}

func TestDNSQueryTrackerMatchesAnswersToQueries(t *testing.T) {
	tracker := newDNSQueryTracker(false)
	question := new(dns.Msg)
	question.SetQuestion("Example.COM.", dns.TypeA)
	// 같은 질의를 다시 보낸 뒤 온 응답 하나가 두 질의에 답한다. 응답 시간은 처음 보낸 때부터 잰다.
	for _, at := range []uint64{1_000_000, 3_000_000} {
		event, ok := tracker.event(dnsTestPacket(t, question, at, "127.0.0.1:41000"), 0)
		if !ok || event.Event != traceDNSQueryEvent || event.Target != "example.com" || event.QueryType != "A" || event.Protocol != "dns" {
			t.Fatalf("query event = %#v, %t", event, ok)
		}
	}
	answer, ok := tracker.event(dnsTestPacket(t, dnsTestReply(t, question, dns.RcodeSuccess, "example.com. 60 IN A 203.0.113.10"), 6_500_000, "127.0.0.1:41000"), 0)
	if !ok || answer.Event != "dns_noerror" || answer.LatencyMS == nil || *answer.LatencyMS != 5.5 || answer.answered != 2 || !slices.Equal(answer.Answers, []string{"203.0.113.10"}) {
		t.Fatalf("answer event = %#v, %t", answer, ok)
	}
	if tracker.size != 0 || len(tracker.pending) != 0 {
		t.Fatalf("pending after the answer = %d, %v", tracker.size, tracker.pending)
	}
	// 다른 로컬 port로 온 응답은 짝이 없으므로 응답 시간이 없다.
	other, _ := tracker.event(dnsTestPacket(t, dnsTestReply(t, question, dns.RcodeSuccess, "example.com. 60 IN A 203.0.113.10"), 7_000_000, "127.0.0.1:42000"), 0)
	if other.LatencyMS != nil || other.answered != 0 {
		t.Fatalf("an answer without a query = %#v", other)
	}
}

func TestDNSAnswerEventsNameTheResult(t *testing.T) {
	question := new(dns.Msg)
	question.SetQuestion("example.com.", dns.TypeAAAA)
	for _, test := range []struct {
		rcode   int
		records []string
		want    string
	}{
		{dns.RcodeSuccess, []string{"example.com. 60 IN AAAA 2001:db8::1"}, "dns_noerror"},
		{dns.RcodeSuccess, nil, "dns_nodata"},
		{dns.RcodeNameError, nil, "dns_nxdomain"},
		{dns.RcodeServerFailure, nil, "dns_servfail"},
		{dns.RcodeRefused, nil, "dns_refused"},
	} {
		event, ok := newDNSQueryTracker(false).event(dnsTestPacket(t, dnsTestReply(t, question, test.rcode, test.records...), 1, "127.0.0.1:41000"), 0)
		if !ok || event.Event != test.want {
			t.Fatalf("rcode %d with %d answers = %q, want %q", test.rcode, len(test.records), event.Event, test.want)
		}
		if traceDNSError(event.Event) != (test.want != "dns_noerror" && test.want != "dns_nodata") {
			t.Fatalf("traceDNSError(%q) = %t", event.Event, traceDNSError(event.Event))
		}
	}
}

func TestDNSCutAnswerTakesTheNameFromTheQuery(t *testing.T) {
	tracker := newDNSQueryTracker(false)
	question := new(dns.Msg)
	question.SetQuestion("big.example.com.", dns.TypeA)
	tracker.event(dnsTestPacket(t, question, 1_000_000, "127.0.0.1:41000"), 0)
	packet := dnsTestPacket(t, dnsTestReply(t, question, dns.RcodeSuccess, "big.example.com. 60 IN A 203.0.113.10"), 2_000_000, "127.0.0.1:41000")
	// BPF는 응답을 1024바이트까지만 읽는다. 뒤가 잘린 응답은 header만 믿는다.
	packet.payload = packet.payload[:traceDNSHeaderSize+4]
	event, ok := tracker.event(packet, 0)
	if !ok || event.Event != "dns_noerror" || event.Target != "big.example.com" || event.QueryType != "A" || event.LatencyMS == nil || event.Answers != nil {
		t.Fatalf("cut answer = %#v, %t", event, ok)
	}
	short := packet
	short.payload = short.payload[:traceDNSHeaderSize-1]
	if _, ok := tracker.event(short, 0); ok {
		t.Fatal("a payload shorter than the DNS header made an event")
	}
	// 이 host의 DNS 서버가 port 53 client에게 보낸 응답은 질의 hook에 걸려도 client 쪽 질의가 아니다.
	served := packet
	served.sent = true
	if _, ok := tracker.event(served, 0); ok {
		t.Fatal("an answer sent to port 53 was read as a query")
	}
}

func dnsTestEvents() []captureEvent {
	latency := func(value float64) *float64 { return &value }
	return []captureEvent{
		{Protocol: "dns", Event: traceDNSQueryEvent, Process: "dig", Target: "example.com", QueryType: "A", Destination: "127.0.0.53:53", Bytes: 40},
		{Protocol: "dns", Event: "dns_noerror", Process: "dig", Target: "example.com", QueryType: "A", Destination: "127.0.0.53:53", Answers: []string{"203.0.113.10"}, LatencyMS: latency(2), answered: 1, Bytes: 56},
		{Protocol: "dns", Event: traceDNSQueryEvent, Process: "curl", Target: "missing.invalid", QueryType: "A", Destination: "127.0.0.53:53"},
		{Protocol: "dns", Event: "dns_nxdomain", Process: "curl", Target: "missing.invalid", QueryType: "A", Destination: "127.0.0.53:53", LatencyMS: latency(6), answered: 1},
		{Protocol: "dns", Event: traceDNSQueryEvent, Process: "dig", Target: "example.com", QueryType: "A", Destination: "192.0.2.1:53"},
	}
}

func TestDNSTraceSummaryCountsNamesAndUnansweredQueries(t *testing.T) {
	summarizer := newDNSTraceSummarizer()
	for _, event := range dnsTestEvents() {
		summarizer.observe(event)
	}
	report := summarizer.summarize(captureSummary{LostEvents: 1}, 2*time.Second).(dnsTraceReport)
	if report.Queries != 3 || report.Answers != 2 || report.Errors != 1 || report.Unanswered != 1 || *report.LatencyAvgMS != 4 || *report.LatencyMaxMS != 6 || report.Results["noerror"] != 1 || report.Results["nxdomain"] != 1 {
		t.Fatalf("report totals = %#v", report)
	}
	if len(report.Names) != 2 || report.Names[0].Name != "example.com" || report.Names[0].Queries != 2 || report.Names[0].Unanswered != 1 || !slices.Equal(report.Names[0].Servers, []string{"127.0.0.53:53", "192.0.2.1:53"}) || !slices.Equal(report.Names[0].Addresses, []string{"203.0.113.10"}) {
		t.Fatalf("report names = %#v", report.Names)
	}
	data, err := json.Marshal(report)
	if err != nil {
		t.Fatal(err)
	}
	for _, field := range []string{`"queries":3`, `"unanswered":1`, `"latency_avg_ms":4`, `"results":{"noerror":1,"nxdomain":1}`, `"lost_events":1`} {
		if !strings.Contains(string(data), field) {
			t.Fatalf("report JSON %s does not contain %s", data, field)
		}
	}
	if again := summarizer.summarize(captureSummary{LostEvents: 1}, 2*time.Second); again.(dnsTraceReport).Unanswered != 1 {
		t.Fatal("a second summary changed the counts")
	}
}

func TestDNSGroupsCountQueriesAndKeepTCPGroupsUnchanged(t *testing.T) {
	report := summarizeTraceGroups("dns", traceGroupByTarget, dnsTestEvents(), captureSummary{}, time.Second, "", "")
	if len(report.Groups) != 2 || report.Groups[0].Group != "example.com" || report.Groups[0].DNS == nil || report.Groups[0].DNS.Queries != 2 || report.Groups[0].DNS.Unanswered != 1 || report.Groups[1].DNS.Errors != 1 {
		t.Fatalf("dns groups = %#v", report.Groups)
	}
	// event 보기는 질의와 응답을 다른 행에 둔다. 답을 받은 질의는 dns_query 행에서 응답 없음으로 세지 않는다.
	events := summarizeTraceGroups("dns", traceGroupByEvent, dnsTestEvents(), captureSummary{}, time.Second, "", "")
	for _, group := range events.Groups {
		if want := map[string]uint64{traceDNSQueryEvent: 1}[group.Group]; group.DNS.Unanswered != want {
			t.Fatalf("event view %s unanswered = %d, want %d", group.Group, group.DNS.Unanswered, want)
		}
	}
	for _, group := range summarizeTraceGroups("dns", traceGroupBySource, dnsTestEvents(), captureSummary{}, time.Second, "", "").Groups {
