func runTraceExec(args []string) int {
	options := execTraceOptions{}
	set := newFlagSet("trace exec")
	set.SetOutput(os.Stderr)
	set.DurationVar(&options.duration, "duration", 0, T("command.trace.option.duration"))
	set.StringVar(&options.process, "process", "", T("command.trace.option.process"))
	set.StringVar(&options.containerRef, "container", "", T("command.trace.option.container"))
	set.StringVar(&options.groupBy, "group-by", "", "process, parent, cgroup, or event")
	set.StringVar(&options.signals, "signal", "", T("command.trace.option.signal"))
	set.BoolVar(&options.raw, "raw", false, T("command.trace.option.raw"))
	set.StringVar(&options.jsonPath, "json", "", T("option.json"))
	set.BoolVar(&options.detail, "detail", false, T("command.trace.option.detail"))
	set.BoolVar(&options.detail, "d", false, T("command.trace.option.detail"))
	if err := set.Parse(args); err != nil {
		return 2
	}
	if set.NArg() != 0 || options.duration < 0 || options.duration > maxCaptureDuration || (options.raw && options.jsonPath != "") {
		fmt.Fprintln(os.Stderr, T("cli.usage", "edc trace exec [--duration 15s] [--process name] [--signal names|all|none] [--group-by process|parent|cgroup|event] [--raw | --json <path>]"))
		return 2
	}
	switch options.groupBy {
	case "", traceGroupByProcess, execGroupByParent, execGroupByCgroup, traceGroupByEvent:
	default:
		fmt.Fprintln(os.Stderr, "trace exec --group-by must be process, parent, cgroup, or event")
		return 2
	}
	mask, err := parseExecSignals(options.signals)
	if err != nil {
		fmt.Fprintln(os.Stderr, "trace exec --signal:", err)
		return 2
	}
	options.signalMask = mask

func execPrintable(value []byte) string {
	var out strings.Builder
	for _, b := range value {
		if b < 0x20 || b == 0x7f {
			fmt.Fprintf(&out, `\x%02x`, b)
			continue
		}
		out.WriteByte(b)
	}
	return out.String()
}

func (aggregator *execAggregator) report(duration time.Duration, summary execSummary) execReport {
	report := execReport{DurationMS: duration.Milliseconds(), GroupBy: aggregator.groupBy, ShortLifetimeMS: execShortLifetime.Milliseconds(), Summary: summary, Rows: []execReportOutputRow{}, Signals: []execSignalRow{}, OOMs: append([]execEvent{}, aggregator.ooms...)}
	if report.DurationMS < 1 {
		report.DurationMS = 1
	}
	for _, row := range aggregator.rows {
		output := execReportOutputRow{Group: row.Group, Execs: row.Execs, Exits: row.Exits, NonZeroExits: row.NonZeroExits, Signaled: row.Signaled, ShortLived: row.ShortLived, OOMKilled: row.OOMKilled}
		if len(row.lifetimes) > 0 {
			var total, maximum float64
			for _, value := range row.lifetimes {
				total += value
				if value > maximum {
					maximum = value
				}
			}
			average := total / float64(len(row.lifetimes))
			output.AvgLifetimeMS, output.MaxLifetimeMS = &average, &maximum
		}
		report.Rows = append(report.Rows, output)
	}
	sort.Slice(report.Rows, func(i, j int) bool {
		left, right := report.Rows[i], report.Rows[j]
		if left.Execs+left.Exits != right.Execs+right.Exits {
			return left.Execs+left.Exits > right.Execs+right.Exits
		}
		return left.Group < right.Group
	})
	for _, signal := range aggregator.signals {
		report.Signals = append(report.Signals, *signal)
	}
	sort.Slice(report.Signals, func(i, j int) bool {
		left, right := report.Signals[i], report.Signals[j]

		}
		if len(report.Signals) > 0 {
			lines = append(lines, "", traceColumnTitles(fmt.Sprintf("%-10s %-20s %-20s %-18s %6s", "SIGNAL", "SENDER", "TARGET", "RESULT", "COUNT"), width, color))
			sort.SliceStable(report.Signals, func(i, j int) bool { return report.Signals[i].Count > report.Signals[j].Count })
			for _, row := range report.Signals {
				lines = append(lines, fmt.Sprintf("%-10s %-20s %-20s %-18s %6d", row.Signal, row.Sender, row.Target, row.Result, row.Count))
			}
		}
	} else {
		lines = append(lines, traceColumnTitles("TIME          EVENT   PID      PROCESS           DETAIL", width, color))
		for index, event := range m.matching() {
			prefix := " "
			if m.selected == index {
				prefix = liveSelectedBar
			}
			line := fmt.Sprintf("%s%s  %-6s  %-7d  %-16s  %s", prefix, execScreenTime(event), event.Event, event.PID, event.Process, execEventDetail(event))
			switch {
			case !color:
			case m.selected == index:
				line = traceSelectedEvent(traceFit(line, width), width, true)
			default:
				line = traceTexts([]traceText{{text: prefix}, traceLabelSpan(execScreenTime(event)), {text: "  "}, {text: fmt.Sprintf("%-6s", event.Event), color: execEventSeverity(event)},
					{text: fmt.Sprintf("  %-7d  %-16s  %s", event.PID, event.Process, execEventDetail(event))}}, width, true)
			}
			lines = append(lines, line)
		}
	}
	view := liveFrame(strings.Join(lines, "\n")+"\n", m.height)
	view.AltScreen = true
	return view
}

