}

func http2PayloadHeader(event captureEvent, fields []hpack.HeaderField) []byte {
	path := event.Path
	for _, field := range fields {
		if field.Name == ":path" {
			path = field.Value
			break
		}
	}
	line := traceEscapeHTTPHeader(event.Method) + " " + traceEscapeHTTPHeader(path) + " HTTP/2\r\n"
	if event.Status != 0 {
		line = "HTTP/2 " + strconv.Itoa(event.Status) + "\r\n"
	}
	var header strings.Builder
	header.WriteString(line)
	for _, field := range fields {
		name := traceEscapeHTTPHeader(field.Name)
		if name == ":authority" {
			name = "Host"
		} else if strings.HasPrefix(name, ":") {
			continue
		}
		header.WriteString(name)
		header.WriteString(": ")
		header.WriteString(traceEscapeHTTPHeader(field.Value))
		header.WriteString("\r\n")
	}
	header.WriteString("\r\n")
	return []byte(header.String())
}

func traceEscapeHTTPHeader(value string) string {
	var escaped strings.Builder
	for _, character := range []byte(value) {
		if character < 0x20 || character == 0x7f {
			fmt.Fprintf(&escaped, "\\x%02x", character)
		} else {
			escaped.WriteByte(character)
		}
	}
	return escaped.String()
}

// compareHTTP2Payloads는 시작 순서다. 한 레코드로 연 stream은 시각이 같으므로 stream id로 정하고, 같은 stream이면 요청이 먼저다.
func (tracker *httpTracker) compareHTTP2Payloads(a, b http2PayloadKey) int {
	first, second := tracker.h2Payload[a].event, tracker.h2Payload[b].event
	return cmp.Or(cmp.Compare(first.BootTimeNS, second.BootTimeNS), cmp.Compare(a.socket, b.socket), cmp.Compare(a.stream, b.stream), cmp.Compare(first.Status, second.Status))
}

// tlsVector는 앞에 size byte 길이가 붙은 값을 떼어 내고 나머지를 돌려준다.
func tlsVector(data []byte, size int) ([]byte, []byte, bool) {
	if len(data) < size {
		return nil, nil, false
	}
	length := 0
	for _, value := range data[:size] {
		length = length<<8 | int(value)
	}
	data = data[size:]
	if len(data) < length {
		return nil, nil, false
	}
	return data[:length], data[length:], true
}

// parseHTTPRequest는 요청 줄과 Host header를 읽는다. 요청 줄이 "METHOD target HTTP/1.x"가 아니면 HTTP가 아니다.
func parseHTTPRequest(payload []byte) (string, string, string, bool) {
	line, rest, ok := bytes.Cut(payload, []byte("\r\n"))
	if !ok {
		return "", "", "", false
	}
	fields := strings.Split(string(line), " ")
	if len(fields) != 3 || !slices.Contains(traceHTTPMethods, fields[0]) || (fields[2] != "HTTP/1.1" && fields[2] != "HTTP/1.0") || fields[1] == "" {
		return "", "", "", false
	}
	host := ""
	for _, header := range bytes.Split(rest, []byte("\r\n")) {
		name, value, ok := bytes.Cut(header, []byte(":"))
		if ok && strings.EqualFold(string(name), "host") {
			host = strings.ToLower(strings.TrimSpace(string(value)))
			break
		}
	}
	return fields[0], fields[1], host, true
}

// parseHTTPStatus는 "HTTP/1.x NNN" 상태 줄의 코드를 읽는다.
func parseHTTPStatus(payload []byte) (int, bool) {
	if len(payload) < 12 || (!bytes.HasPrefix(payload, []byte("HTTP/1.1 ")) && !bytes.HasPrefix(payload, []byte("HTTP/1.0 "))) {
		return 0, false
	}
	status, err := strconv.Atoi(string(payload[9:12]))
	if err != nil || status < 100 || status > 599 || (len(payload) > 12 && payload[12] != ' ' && payload[12] != '\r') {
		return 0, false
	}
	return status, true
}

