// traceWrapLineUpTo는 traceWrapLine과 같지만 limit줄을 채우면 멈춘다. cut은 줄의 나머지를 나누지 않았는지다. 한 줄
// JSON 본문은 1MiB까지 길어서, 화면을 그릴 때마다 끝까지 나누면 event를 따라가지 못한다.
func traceWrapLineUpTo(line string, width, limit int) ([]string, bool) {
	if width <= 0 {
		return []string{line}, false
	}
	var parts []string
	var current strings.Builder
	used := 0
	for index, r := range line {
		cell := 1
		if r >= utf8.RuneSelf {
			if r == utf8.RuneError {
				cell = lipgloss.Width(string(r))
			} else {
				cell = lipgloss.Width(line[index : index+utf8.RuneLen(r)])
			}
		}
		if used+cell > width && used > 0 {
			parts = append(parts, current.String())
			if len(parts) == limit {
				return parts, true
			}
			current.Reset()
			used = 0
		}
		current.WriteRune(r)
		used += cell
	}
	return append(parts, current.String()), false
}

func runTraceShow(args []string) int {
	options := traceShowOptions{}
	set := newFlagSet("trace show")
	set.SetOutput(os.Stderr)
	set.StringVar(&options.groupBy, "group-by", "", T("command.trace.option.group_by"))
	set.StringVar(&options.process, "process", "", T("command.trace.option.process"))
	set.StringVar(&options.destination, "destination", "", T("command.trace.option.destination"))
	set.StringVar(&options.jsonPath, "json", "", T("option.json"))
	set.BoolVar(&options.detail, "detail", false, T("command.trace.option.detail"))
	set.BoolVar(&options.detail, "d", false, T("command.trace.option.detail"))
	if err := parseReordered(set, args); err != nil {
		return 2
	}
	usage := T("cli.usage", "edc trace show <raw.jsonl> [--group-by view] [--process name] [--destination host:port] [-d] [--json <path>]")
	if set.NArg() != 1 {
		fmt.Fprintln(os.Stderr, usage)
		return 2
	}
	path := set.Arg(0)
	var reader io.Reader = os.Stdin
	if path != "-" {
		handle, err := os.Open(path)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 2
