// liveFrame은 화면 줄 수를 유지한 View를 만든다.
//
// bubbletea v2.0.9의 inline renderer는 두 가지 제약이 있다.
// View가 줄어들면 줄어든 만큼 이전 화면이 위쪽에 남고, content가 줄바꿈으로 끝나지 않으면 마지막 줄이 지워진다.
// 그래서 model은 가장 컸던 높이를 알려 주고, 여기서 빈 줄로 채우며 줄바꿈으로 끝맺는다.
func liveFrame(content string, height int) tea.View {
	if content != "" && !strings.HasSuffix(content, "\n") {
		content += "\n"
	}
	for liveLineCount(content) < height {
		content += "\n"
	}
	return tea.NewView(content)
}

func (model aiModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch value := msg.(type) {
	case aiClockMsg:
		model.now = time.Time(value)
		return model, aiClock()
	case aiPollMsg:
		model.providers, model.lastResets, model.logErr, model.polled = value.providers, value.lastResets, value.logErr, true
		model.claudeInterval, model.stateErr = value.claudeInterval, value.stateErr
		return model, model.pollCmd(model.poll)
	case aiScanMsg:
		model.usage, model.scanned = aiUsageSnapshot(value), true
		return model, model.scanCmd(aiScanInterval)
	case aiSessionFeedMsg:
		model.sessions, model.sessionsHaveEvents, model.sessionsErr, model.sessionsRead = value.sessions, value.hasEvents, value.err, true
		return model, model.sessionsCmd(aiScanInterval)
	case tea.WindowSizeMsg:
		model.width, model.height = value.Width, value.Height
		model.back = min(model.back, model.maxBack())
	case tea.KeyPressMsg:
		switch value.String() {
		case "q", "esc", "ctrl+c":
			return model, tea.Quit
		}
		return model.updateKey(value.String()), nil
	}
	return model, nil
}

func (model aiModel) statusLine(width int) string {
	switch {
	case model.logErr != nil:
		return richPaint(topDashboardFitWidth(T("observe.ai.error.reset_log", model.logErr), width), richRed, false)
	case model.stateErr != nil:
		return richPaint(topDashboardFitWidth(T("observe.ai.error.state", model.stateErr), width), richRed, false)
	case model.usage.Err != "":
		return richPaint(topDashboardFitWidth("scan error · "+model.usage.Err, width), richRed, false)
	}
	return topDashboardFitWidth(aiRowSizeHint(model.rowSize)+liveKeyHints("  row size · ↑↓ history · End live · q quit", true), width)
}

// withSessionPane은 표 오른쪽에 세션 영역을 붙인다. 맨 아래 상태 줄은 화면 폭 전체를 쓰므로 붙이지 않는다.
func (model aiModel) withSessionPane(lines []string, width int) []string {
	paneWidth := width - aiBoxWidth - aiPaneGap
	if model.sessionFeed == nil || paneWidth < aiPaneMinWidth || len(lines) < 2 {
		return lines
	}
	body := len(lines) - 1
	pane := model.sessionPane(paneWidth, body)
	for index := range body {
		left := ansi.Truncate(lines[index], aiBoxWidth, "")
		right := ""
		if index < len(pane) {
			right = ansi.Truncate(pane[index], paneWidth, "")
		}
		lines[index] = padRight(left, aiBoxWidth) + richDim(" │ ") + right
	}
	return lines
}

