func historyListReviewData(db *sql.DB, options historyOptions, now time.Time) (historyReviewData, error) {
	query, values := historyQuery("list", options)
	rows, err := db.Query(query, values...)
	if err != nil {
		return historyReviewData{}, err
	}
	defer rows.Close()
	data := historyReviewData{summary: T("history.list_browser.summary"), empty: T("history.list_browser.empty")}
	if !options.from.IsZero() || !options.to.IsZero() || options.run != "" {
		data.summary += " · " + T("history.list_browser.active_range", historyHistoryRangeLabel(options))
	}
	for rows.Next() {
		var payload, status string
		var ended sql.NullInt64
		var samples int
		if err := rows.Scan(&payload, &ended, &status, &samples); err != nil {
			return historyReviewData{}, err
		}
		var run historyRun
		if err := json.Unmarshal([]byte(payload), &run); err != nil {
			return historyReviewData{}, err
		}
		run.Status, run.SampleCount = status, samples
		if ended.Valid {
			at := time.Unix(0, ended.Int64)
			run.EndedAt = &at
		}
		endedText, duration := "—", "—"
		if run.EndedAt != nil {
			endedText = run.EndedAt.Local().Format("2006-01-02 15:04:05 MST")
			duration = historyShortDuration(run.EndedAt.Sub(run.StartedAt))
		}

func historyHistoryRangeLabel(options historyOptions) string {
	parts := []string{}
	if options.run != "" {
		parts = append(parts, options.run)
	}
	if !options.from.IsZero() {
		parts = append(parts, options.from.Local().Format(time.DateTime)+" →")
	}
	if !options.to.IsZero() {
		parts = append(parts, options.to.Local().Format(time.DateTime))
	}
	return strings.Join(parts, " ")
}

