func historyPruneReviewData(plan historyPrunePlan, options historyPruneOptions, now time.Time) historyReviewData {
	data := historyReviewData{plan: plan, pruneOptions: options, summary: T("history.review.prune_range", now.Add(-options.olderThan).Local().Format(time.DateTime), len(plan.runs), plan.samples), empty: T("history.prune.none")}
	data.summary = T("history.review.age_current", historyPruneAgeLabel(options.olderThan)) + " · " + data.summary
	if options.vacuum {
		data.summary += " · VACUUM"
	}
	for _, entry := range plan.entries {
		run := entry.run
		ended := "—"
		if run.EndedAt != nil {
			ended = run.EndedAt.Local().Format(time.DateTime)
		}
		data.entries = append(data.entries, historyReviewEntry{id: run.ID,
			cells:   []string{run.Command + " " + run.ID, entry.lastActivity.Local().Format(time.DateTime), fmt.Sprint(entry.samples), run.Hostname, run.Status},
			details: []string{historyTerminalText(run.Command) + " · " + historyTerminalText(run.ID), historyTerminalText(run.Hostname), "", "started  " + run.StartedAt.Local().Format(time.DateTime), "ended  " + ended, "last active  " + entry.lastActivity.Local().Format(time.DateTime), "status  " + historyTerminalText(run.Status), fmt.Sprintf("samples/results  %d", entry.samples), "", T("history.review.prune_details")}})
	}
	return data
}

func selectedHistoryPrunePlan(plan historyPrunePlan, selected []string) historyPrunePlan {
	ids := map[string]bool{}
	for _, id := range selected {
		ids[id] = true
	}
	var chosen historyPrunePlan
	for _, entry := range plan.entries {
		if ids[entry.run.ID] {
			chosen.add(entry)
		}
	}
	return chosen
}

func newHistoryPruneBrowser(path string, options historyPruneOptions, plan historyPrunePlan, now time.Time) historyReviewBrowser {
	columns := []historyReviewColumn{{"RUN", 0, 0}, {"LAST ACTIVE", 19, 0}, {"SAMPLES", 8, 72}, {"HOST", 22, 112}, {"STATUS", 12, 144}}
	model := newHistoryReviewBrowser(T("history.review.prune_title"), path, columns, historyPruneReviewData(plan, options, now))
	model.prune, model.dryRun, model.pruneOptions = true, options.dryRun, options
	for _, entry := range plan.entries {
		model.checked[entry.run.ID] = true
	}
	model.resize()
	return model
}

func runHistoryPruneBrowser(input, output *os.File, db *sql.DB, path string, options historyPruneOptions, plan historyPrunePlan) (historyPrunePlan, historyPruneOptions, bool, error) {
	model := newHistoryPruneBrowser(path, options, plan, time.Now())
	model.loadPrune = func(options historyPruneOptions) (historyReviewData, error) {
		now := time.Now()
		plan, err := planHistoryPrune(db, options, now)
		if err != nil {
			return historyReviewData{}, err
		}
		return historyPruneReviewData(plan, options, now), nil
	}
	result, err := tea.NewProgram(model, tea.WithInput(input), tea.WithOutput(output)).Run()
	if err != nil {
		return historyPrunePlan{}, options, false, err
	}
	final := result.(historyReviewBrowser)
	return selectedHistoryPrunePlan(final.data.plan, final.selectedIDs()), final.data.pruneOptions, final.confirmed && !options.dryRun, nil
}

type historyPruneAgePicker struct {
	selected  int
	input     bool
	text, err string
}

func historyPruneAgeLabel(age time.Duration) string {
	switch {
	case age%(24*time.Hour) == 0:
		return fmt.Sprintf("%dd", age/(24*time.Hour))
	case age%time.Hour == 0:
		return fmt.Sprintf("%dh", age/time.Hour)
	case age%time.Minute == 0:
		return fmt.Sprintf("%dm", age/time.Minute)
	default:
		return age.String()
	}
}

func pruneAgeInputText(text string) string {
	var runes []rune
	for _, r := range text {
		if !unicode.IsControl(r) && len(runes) < 64 {
			runes = append(runes, r)
		}
	}
	return string(runes)
}

func (model *historyReviewBrowser) openPruneAgePicker() {
	picker := &historyPruneAgePicker{selected: len(historyPruneAges), text: historyPruneAgeLabel(model.pruneOptions.olderThan)}
	for i, age := range historyPruneAges {
		if age == model.pruneOptions.olderThan {
			picker.selected = i
			break
		}
	}
	model.agePicker = picker
}

func (model historyReviewBrowser) applyPruneAge(age time.Duration) (tea.Model, tea.Cmd) {
	if model.loadPrune == nil {
		return model, nil
	}
	model.pruneOptions.olderThan = age
	model.seq++
	model.agePicker = nil
	model.expanded, model.confirm, model.selected = false, false, 0
	model.checked = map[string]bool{}
	model.data = historyReviewData{summary: T("history.review.age_loading", historyPruneAgeLabel(age)), empty: T("history.review.age_loading", historyPruneAgeLabel(age)), pruneOptions: model.pruneOptions}
	model.notice = ""
	model.resize()
	return model, model.reload()
}

func (model historyReviewBrowser) updatePruneAge(key tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	picker := model.agePicker
	if key.String() == "ctrl+c" {
		return model, tea.Quit
	}
	if key.String() == "esc" {
		model.agePicker = nil
		return model, nil
	}
	if picker.input {
		switch key.String() {
		case "enter":
			age, err := parseLogAge(strings.TrimSpace(picker.text))
			if err != nil || age <= 0 {
				picker.err = T("history.review.age_invalid")
				return model, nil
			}
			return model.applyPruneAge(age)
		case "backspace", "ctrl+h":
			runes := []rune(picker.text)
			if len(runes) > 0 {
				picker.text = string(runes[:len(runes)-1])
			}
		case "ctrl+u":
			picker.text = ""
		default:
			picker.text = pruneAgeInputText(picker.text + key.Text)
		}
		picker.err = ""
		return model, nil
	}
	switch key.String() {

func (model historyReviewBrowser) pruneAgeView() tea.View {
	if model.width < 40 || model.height < 10 {
		view := tea.NewView(ansi.Truncate(T("cli.log_history.small"), max(1, model.width), "…"))
		view.AltScreen = true
		return view
	}
	picker := model.agePicker
	lines := []string{historyStrong(T("history.review.age_title"), richCyan, model.color), historyTint(T("history.review.age_current", historyPruneAgeLabel(model.pruneOptions.olderThan)), richGray, model.color), ""}
	key := "history.review.age_help"
	var body []string
	selected := picker.selected
	if picker.input {
		key = "history.review.age_input_help"
		body = []string{T("history.review.age_custom"), "", historyStrong(historyTerminalText(picker.text)+"█", richCyan, model.color)}
		if picker.err != "" {
			body = append(body, "", historyTint(picker.err, richYellow, model.color))
		}
		selected = 0
	} else {
		for i, age := range historyPruneAges {
			text := T("history.review.age_option", historyPruneAgeLabel(age))
			if i == picker.selected {
				text = historySelect(text, model.color)
			} else {
				text = "  " + text
			}
			body = append(body, text)
		}
		text := T("history.review.age_custom")
		if picker.selected == len(historyPruneAges) {
			text = historySelect(text, model.color)
		} else {

			text = "  " + text
		}
		body = append(body, text)
	}
	footer := historyReviewKeyHints(T(key), model.width, model.color)
	available := max(1, model.height-len(lines)-len(footer))
	start := max(0, selected-available+1)
	end := min(len(body), start+available)
	lines = append(lines, body[start:end]...)
	for len(lines)+len(footer) < model.height {
		lines = append(lines, "")
	}
	lines = append(lines, footer...)
	for i := range lines {
		lines[i] = ansi.Truncate(lines[i], model.width, "…")
	}
	view := tea.NewView(strings.Join(lines[:min(len(lines), model.height)], "\n"))
	view.AltScreen = true
	return view
}

