	}
	return line
}

// truncateLine은 줄이 접혀 화면 높이가 늘어나지 않게 자른다.
func truncateLine(line string, width int) string {
	if width <= 0 {
		return line
	}
	trimmed := strings.TrimRight(line, "\n")
	if liveWidth(trimmed) <= width {
		return line
	}
	// "…"까지 폭 안에 드는 가장 긴 앞부분을 찾는다. 앞부분의 폭은 길어질수록 줄지 않으므로 이분 탐색한다. 한 글자씩
	// 줄이며 폭을 다시 재면 4KiB 줄 하나에 200ms가 넘게 걸려, 화면을 그릴 때마다 키 입력이 밀렸다.
	runes := []rune(trimmed)
	low, high := 0, len(runes)
	for low < high {
		middle := (low + high + 1) / 2
		if liveWidth(string(runes[:middle]))+1 <= width {
			low = middle
		} else {
			high = middle - 1
		}
	}
	return string(runes[:low]) + "…\n"
}

// runProbeLive는 probe 하나를 한 줄로 보여 준다. probeLiveDelay 안에 끝나면 화면 없이 결과만 출력한다.
func runProbeLive(ctx context.Context, cancel context.CancelFunc, probeID, target string, options commonOptions, version string, started time.Time, targetInfo map[string]interface{}, probe func(context.Context) Result) int {
	progress := &probeProgress{}
	finished := make(chan Result, 1)
	go func() { finished <- probe(withProbeObserver(ctx, progress.observe)) }()
	select {
	case result := <-finished:
		return emit(options, buildReport(version, started, targetInfo, []Result{result}, options.redact))
	case <-time.After(probeLiveDelay):
	}
	model := newProbeModel(probeID, target, progress.snapshot(), true, options.redact, cancel)
	live, err := startLiveProgram(model, cancel, tea.WithInput(os.Stdin), tea.WithOutput(os.Stdout))
	if err != nil {
		fmt.Fprintln(os.Stderr, T("observe.live.start_failed", err))
		return emit(options, buildReport(version, started, targetInfo, []Result{<-finished}, options.redact))
	}
	if latest := progress.attach(live); latest != "" {
		live.send(probeLogMsg{line: latest})
	}
	result := <-finished
	// finish가 Run을 끝내면 onExit이 cancel을 부르므로, 사용자 취소 여부는 그 전에 읽는다.
	cancelled := ctx.Err() != nil
	if _, err := live.finish(probeResultMsg{result: result}); err != nil {
		fmt.Fprintln(os.Stderr, T("observe.live.exit_error", err))
	}
	report := buildReport(version, started, targetInfo, []Result{result}, options.redact)
	printResultTail(os.Stdout, report.Results, options.verbose, true)
	if cancelled {
		fmt.Fprintln(os.Stderr, errProbeCancelled)
		return 4
	}
	return exitCode(report.Results)

// 화면 줄 수가 변하면 잔상이 남으므로 진행 표시는 항상 한 줄이어야 한다.
func TestProbeModelStaysOnOneLine(t *testing.T) {
	model := newProbeModel("net.trace", "example.com", "", false, false, nil)
	model, _ = probeAfter(t, model, tea.WindowSizeMsg{Width: 200, Height: 40})
	for _, line := range []string{" 1  hop one", " 2  hop two", " 3  hop three"} {
		model, _ = probeAfter(t, model, probeLogMsg{line: line})
	}
	view := model.View().Content
	if strings.Count(view, "\n") != 1 {
		t.Fatalf("view must stay on one line: %q", view)
	}
	if !strings.Contains(view, " 3  hop three") || strings.Contains(view, "hop one") {
		t.Fatalf("view must show the latest line only: %q", view)
	}
}

func TestCommandOutputStreamsWithObserver(t *testing.T) {
	if _, err := exec.LookPath("printf"); err != nil {
		t.Skip("printf is not available")
	}
	var lines []string
	ctx := withProbeObserver(context.Background(), func(line string) { lines = append(lines, line) })
	output, err := commandOutput(ctx, "printf", "one\ntwo\n")
	if err != nil {
		t.Fatal(err)
	}
	if output != "one\ntwo" {
		t.Fatalf("output = %q", output)
	}
	if strings.Join(lines, "|") != "one|two" {
		t.Fatalf("streamed lines = %#v", lines)
	}
	// observer가 없으면 예전처럼 모아서 돌려준다.
	plain, err := commandOutput(context.Background(), "printf", "one\ntwo\n")
	if err != nil || plain != "one\ntwo" {
		t.Fatalf("plain output = %q, %v", plain, err)
	}
}

