// fit은 제목과 키 안내의 줄마다 화면 폭에 맞춰 자른다. 넘치는 줄은 renderer가 다음 줄로 넘겨 본문을 밀어낸다.
func (model viewerModel) fit(text string) string {
	if model.width <= 0 {
		return text
	}
	lines := strings.Split(text, "\n")
	for index, line := range lines {
		lines[index] = ansi.Truncate(line, model.width, "…")
	}
	return strings.Join(lines, "\n")
}

// fit은 제목과 안내 줄을 화면 폭에 맞춰 자른다. 폭을 아직 모르면 그대로 둔다.
func (model reportPairModel) fit(text string) string {
	if model.width <= 0 {
		return text
	}
	return ansi.Truncate(text, model.width, "…")
}

