// loadDetail은 edc svc -v <unit>과 같은 결과를 만든다. CPU를 두 번 재고 journal을 읽어 시간이 걸리므로 화면 밖에서 돈다.
func (model svcBrowser) loadDetail(unit string, seq int) tea.Cmd {
	sources, timeout, color := model.sources, model.timeout, model.color
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), timeout)
		defer cancel()
		var buffer strings.Builder
		printTerminalWithColor(&buffer, evaluateSvc(collectSvcFacts(ctx, unit, sources)), true, color)
		return svcDetailMsg{seq: seq, lines: strings.Split(strings.TrimRight(buffer.String(), "\n"), "\n")}
	}
}

// svcBrowserRow는 표의 한 줄이다. 고른 줄은 색을 쓰면 막대와 chip 바탕을 화면 폭까지 칠하고, 아니면 "› "로 표시한다.
func svcBrowserRow(line string, selected, color bool, width int) string {
	switch {
	case !selected:
		return "  " + line
	case !color:
		return "› " + line
	}
	line = liveSelectedBar + " " + line
	return liveSelected(line+strings.Repeat(" ", max(0, width-liveWidth(line))), true)
}

// 언어팩의 키 안내는 묶음마다 키로 시작해야 키가 청록으로 칠해진다. 새 키 이름이 생기면 liveHintKeys에 더한다.
func TestLocaleKeyHintsStartWithKnownKeys(t *testing.T) {
	restore := currentLanguage()
	defer setLanguage(restore)
	hints := []string{"ui.confirm.help", "cli.report.pick_help", "cli.report.viewer_help", "cli.log_history.list_help", "cli.log_history.detail_help", "cli.log_history.expanded_help"}
	for _, language := range []string{"en", "ko", "ja"} {
		setLanguage(language)
		texts := []string{}
		for _, key := range hints {
			texts = append(texts, T(key))
		}
		for _, key := range []string{selectGroupTitle, selectInventoryTitle, selectRecipeTitle} {
			_, rest, _ := strings.Cut(T(key), "   ")
			texts = append(texts, rest)
		}
		for _, text := range texts {
			for _, group := range liveHintSeparator.Split(text, -1) {
				if group = strings.TrimSpace(group); group == "" {
					continue
				}
				if key, _, _ := strings.Cut(group, " "); !liveHintKey(key) {
					t.Errorf("%s: %q starts with %q, not a key", language, text, key)
				}
			}
		}
	}
}

// runTopDashboard는 alt screen 대시보드를 실행한다. 종료하면 화면이 원래대로 돌아온다.
func runTopDashboard(interval time.Duration, version string, filter topProcessFilter, interfaces topInterfaceFilter, recordPath string, recorder *topRecorder, split []topView, layout topLayout, autoRecord bool) int {
	model, err := newTopDashboardModel(interval, version, filter, interfaces)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	model = model.withProcessFilter(filter).withSplit(split).withLayout(layout)
	model.recordPath = recordPath
	if autoRecord {
		model.autoRecord = &topAutoRecord{}
	}
	if recorder != nil {
		model.attachRecorder(recorder)
	}
	final, err := tea.NewProgram(model, tea.WithInput(os.Stdin), tea.WithOutput(os.Stdout)).Run()
	if final, ok := final.(topModel); ok {
		final.closeAI()
		if final.recorder != nil {
			status := "finished"
			if err != nil || final.recordingErr != nil {
				status = "error"
			}
			if closeErr := final.recorder.Close(status); closeErr != nil {
				fmt.Fprintln(os.Stderr, T("history.error.write", closeErr))
				return 1
			}
		}
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1

	}
	if final.(topModel).recordingErr != nil {
		fmt.Fprintln(os.Stderr, T("history.error.write", final.(topModel).recordingErr))
		return 1
	}
	return 0
}

// newTopDashboardModel은 대시보드와 edc top setup 미리보기가 함께 쓰는 모델이다. host 정보와 첫 표본을 읽고
// interface 선택과 process 수집기를 연결한다. 보기, 박스, 패널은 부르는 쪽이 정한다.
func newTopDashboardModel(interval time.Duration, version string, filter topProcessFilter, interfaces topInterfaceFilter) (topModel, error) {
	details, err := collectHostDetails()
	if err != nil {
		return topModel{}, errors.New(T("observe.top.error.host", err))
	}
	// interface 선택은 수집 직후에 적용한다. 기록, 표, 상세가 모두 같은 snapshot에서 나오므로 따로 맞추지 않아도 된다.
	// 수집은 tea.Cmd goroutine에서 돌고 i는 Update에서 바꾸므로 lock으로 건넨다.
	var selection sync.Mutex
	current := interfaces
	selected := func(sample func() (resourceSnapshot, error)) func() (resourceSnapshot, error) {
		return func() (resourceSnapshot, error) {
			snapshot, err := sample()
			selection.Lock()
			filter := current
			selection.Unlock()
			return filter.apply(snapshot, topInterfacePhysical), err
		}
	}
	sample := selected(sampleTopDashboard)
	if filter.active() {
		sample = selected(sampleTopDashboardNow)
	}
	first, err := sample()
	if err != nil {
		return topModel{}, errors.New(T("observe.top.error.resource", err))
	}
	model := newTopModel(details, first, interval, selected(sampleTopDashboard))
	model.sampleNow, model.setFilter, model.setScanIO = selected(sampleTopDashboardNow), processSampler.setFilter, processSampler.setScanIO
	model.version, model.interfaces = version, interfaces
	model.setInterfaces = func(filter topInterfaceFilter) {

// sampleTopDashboard는 snapshot에 process 목록을 붙인다. 표와 JSON 출력은 process를 쓰지 않으므로
// collectResourceSnapshot이 아니라 대시보드에서만 process를 수집한다.
func sampleTopDashboard() (resourceSnapshot, error) {
	snapshot, err := collectResourceSnapshot()
	snapshot.Processes, snapshot.ProcessTotal, snapshot.ProcessesValid, snapshot.ProcessesAt = processSampler.latestWithTotalAt()
	fillProcsBlocked(&snapshot)
	return snapshot, err
}

// fillProcsBlocked는 kernel이 멈춘 작업 수를 주지 않는 host에서 process 목록의 멈춘 process 수를 쓴다.
// Linux의 procs_blocked는 thread를 세지만 이 값은 process를 센다.
func fillProcsBlocked(snapshot *resourceSnapshot) {
	if !snapshot.ProcsBlockedSource.known() && snapshot.ProcessTotal.BlockedValid {
		snapshot.ProcsBlocked, snapshot.ProcsBlockedSource = uint64(snapshot.ProcessTotal.Blocked), topBlockedProcessList
	}
}

// sampleTopDashboardNow는 필터를 건 대시보드가 쓴다. process 보기는 행마다 그 시점의 값이 필요하므로, 배경 갱신이
// 끝난 직전 목록을 다시 쓰지 않고 지금 읽는다. tick의 tea.Cmd 안에서 돌아 /proc을 읽는 동안 화면은 멈추지 않는다.
func sampleTopDashboardNow() (resourceSnapshot, error) {
	snapshot, err := collectResourceSnapshot()
	snapshot.Processes, snapshot.ProcessTotal, snapshot.ProcessesValid, snapshot.ProcessesAt = processSampler.refreshNowAt()
	fillProcsBlocked(&snapshot)
	return snapshot, err
}

