const (
	// topSignalMinWidth는 all 보기에 칸을 더할 때 signal에 남기는 최소 폭이다. "node 185% +2"와 "await 65ms +1"이 들어간다.
	topSignalMinWidth = 13
	// topSignalWideWidth는 all 보기가 남는 폭을 칸에 나눌 때 signal에 남기는 폭이다. 경고 하나와 +N이 들어간다.
	topSignalWideWidth = 16
	// topPeakWindow는 h 패널이 지표별 최고치를 찾는 구간이다.
	topPeakWindow = time.Minute
	// topSelectionColumn은 행에서 "15:04:05" 바로 뒤 공백 자리다. 선택 표시가 시각을 가리지 않는다.
	topSelectionColumn = 8
	// topFooterProcessWidth는 아래 영역 오른쪽 process 후보 칸의 폭이다. 이름 칸이 쌓을 때와 같은 28칸이 된다.
	topFooterProcessWidth = 63
	topFooterGap          = 2
	// topFooterDockWidth부터 process 후보를 오른쪽에 둔다. 왼쪽 패널은 80열에 맞춰 줄을 나눠 두었으므로 왼쪽에 80열이 남아야 한다.
	topFooterDockWidth = topTableWidth + topFooterGap + topFooterProcessWidth
	// topTallHeight부터 process 패널이 후보를 topProcessLimit개까지 보인다. 두 줄을 더 써도 history가 28행 남는다.
	topTallHeight = 40
	// topProcessNameWidth는 상세 패널의 process 이름 폭이다. 세 개가 80열 한 줄에 들어간다.
	topProcessNameWidth = 10
	// topInterfaceRows는 network 상세가 보이는 interface 수다. 아래 칸은 좁고 그 뒤에 limit와 설정 줄이 이어진다.
	topInterfaceRows = 5
	// topStatusInterfaceWidth는 상태 줄에 보이는 --interface 값의 폭이다. "net physical"은 줄지 않고, 긴 목록도 80열에서 키 안내를
	// 밀어내지 않는다.
	topStatusInterfaceWidth = 8
	// topSignalProcessNameWidth는 signal 열의 process 이름 폭이다.
	topSignalProcessNameWidth = 4
	// topProcessSignalCPU는 process 하나가 signal에 오르는 CPU%다. core 하나가 100%다.
	topProcessSignalCPU = 80
	// topProcessIOMinWidth는 후보 줄에 READ·WRITE 칸을 붙이는 최소 폭이다.
	topProcessIOMinWidth = 60
	// topProcessStateWidth는 STATE 칸의 폭이다. 가장 긴 이름인 iowait와 zombie가 들어간다.
	topProcessStateWidth = 6
	// topProcessColumnsWidth는 후보 줄에서 이름 칸을 뺀 표시·PID·STATE·CPU%·MEM 칸과 사이 공백의 폭이다.

	topProcessColumnsWidth = 26 + topProcessStateWidth
	// topProcessIOColumnsWidth는 READ·WRITE 두 칸과 앞 공백의 폭이다. 63칸 후보 패널에서 이름 칸이 17칸 남는다.
	topProcessIOColumnsWidth = 14
	// topProcessRSSColumnWidth는 MEM 뒤에 붙는 RSS 칸과 앞 공백의 폭이다.
	topProcessRSSColumnWidth = 7
	// topProcessRSSMinNameWidth는 RSS 칸을 붙인 뒤에도 남겨야 하는 이름 칸 폭이다. 이보다 좁아지면 MEM만 보인다.
	topProcessRSSMinNameWidth = 16
	// topBlockedSignalMin은 iowait이 높을 때 blocked가 signal에 오르는 D state 작업 수다. 4 core host의 core 수와 같다.
	topBlockedSignalMin = 4
	// topBlockedSignalDanger는 blocked 경고의 순위를 다른 경고와 맞추는 기준 작업 수다.
	topBlockedSignalDanger = 16
	// topCoreBarLimit는 CPU 보기 막대에 그리는 최대 core 수다.
	topCoreBarLimit = 24
	// topHotCoreWarn은 hot core 칸에 경고를 주는 사용률이다. core 하나가 포화해도 core가 여럿이면
	// host 전체는 여유가 있으므로 host의 cpu 임계치보다 늦게 켜고 위험 단계를 두지 않는다.
	topHotCoreWarn = 90
)

// topProcessIOThreshold는 후보의 READ·WRITE 칸에 색을 입히는 byte/s다. 디스크가 한가할 때 작은 값에 색이
// 들지 않도록 host 처리량 대비 비율이 아니라 절대값으로 정한다.
var topProcessIOThreshold = topThreshold{warn: 10 << 20, danger: 50 << 20}

// topDashboardRow는 포맷 문자열 대신 측정값을 보존한다. 같은 시점을 다른 렌즈로
// 다시 그릴 수 있고, 선택한 과거 행의 상세도 최신 값과 섞이지 않는다.
type topDashboardRow struct {
	at             time.Time
	rate           resourceRate
	processes      []topProcess
	processTotal   topProcessTotal
	processesValid bool
	// filter는 이 행을 수집할 때 걸린 필터다. 실행 중에 필터를 바꾸면 그 전 행은 지금 필터의 값이 아니다.
	filter string
}

	recordNotice  bool
	// autoRecord는 --auto-record를 켰을 때만 있다.
	autoRecord *topAutoRecord
	// split은 박스로 보일 보기 목록이고, 비어 있으면 전체다. boxed는 박스 안에서 그리는 표임을 나타낸다.
	split []topView
	boxed bool
	// compact는 박스가 optional 칸을 빼고 그리는지다.
	compact bool
	// startView는 --view나 defaults.top.view로 고른 처음 보기다. 비어 있으면 split 유무를 따른다.
	startView topView
	// panels는 아래 왼쪽 칸에 늘 보일 패널이다. panelsSet이 false이면 기존 배치를 쓴다.
	panels    []topPanel
	panelsSet bool
	// hiddenPanels는 높이가 모자라 숨긴 패널이다. 그리는 동안만 채워 안내 줄에 알린다.
	hiddenPanels []topPanel
	// processSort는 defaults.top.process_sort로 고른 process 패널 기본 순위다. 비어 있으면 보기를 따른다.
	processSort topView
	// columnGroups는 --columns와 defaults.top.columns로 고른 all 보기의 열 그룹이다. 비어 있으면 다섯 그룹 전부다.
	columnGroups []topColumnGroup
	// aiOn은 AI 패널이 켜졌는지다. openAI는 처음 켤 때 수집기를 연다.
	aiOn        bool
	openAI      func() (topAISource, error)
	aiSource    topAISource
	aiProviders []aiProvider
	aiPolled    bool
	aiPolling   bool
	// aiTokens는 all 보기에 ai 열 그룹이 있는지다. 있을 때만 Claude와 Codex 대화 기록을 읽는다.
	aiTokens   bool
	aiScanning bool
	aiSeconds  map[string]map[int64][]aiStampedUsage
	aiFailed   map[string]bool
}

type topRecordingErrorMsg struct {
	err    error
	source *topRecorder
}

// topSampleMsg는 tick마다 수집한 snapshot이다. seq가 다르면 interval이 바뀐 뒤의 낡은 tick이다.
type topSampleMsg struct {
	seq      int
	snapshot resourceSnapshot
	err      error
}

func newTopModel(details hostDetails, first resourceSnapshot, interval time.Duration, sample func() (resourceSnapshot, error)) topModel {
	limits := newTopLimits(details.Cores, true)
	limits.memoryTotal = details.MemoryTotal
	return topModel{details: details, limits: limits, interval: interval, previous: first, view: topViewAll, follow: true, sample: sample, events: &topEventLog{},
		listInterfaces: topListInterfaces, interfacePhysical: topInterfacePhysical, physicalSupported: topPhysicalSupported}
}

// withProcessFilter는 필터를 건다. 필터를 건 사용자는 그 process를 보려는 것이므로 host 지표 대신 process 묶음 보기로 연다.
func (model topModel) withProcessFilter(filter topProcessFilter) topModel {
	model.processFilter = filter
	if filter.active() {
		model.view = topViewProcess
	}
	return model
}

func (model topModel) Init() tea.Cmd {
	var ai tea.Cmd
	if model.aiOn || model.aiTokens {
		ai = func() tea.Msg { return topAIStartMsg{} }
	}
	return tea.Batch(model.tick(), model.recordFailure, ai)
}

func (model topModel) tick() tea.Cmd {
	seq, sample := model.seq, model.sample
	model.syncScanIO()
	if model.processFilter.active() && model.sampleNow != nil {
		sample = model.sampleNow
	}
	return tea.Tick(model.interval, func(time.Time) tea.Msg {
		snapshot, err := sample()
		return topSampleMsg{seq: seq, snapshot: snapshot, err: err}
	})
}

func (model topModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch value := msg.(type) {
	case topRecordingErrorMsg:
		if value.source != nil && value.source != model.recorder {
			return model, nil
		}
		model.recordingErr = value.err
		return model, tea.Quit
	case topSampleMsg:
		if value.seq != model.seq {
			return model, nil
		}
		if value.err != nil {
			// 일시적인 수집 실패는 화면을 닫지 않는다. 마지막 유효 row를 유지하고 다음 tick에서 복구한다.
			model.lastErr = value.err
			if model.paused {
				return model, nil
			}
			return model, model.tick()
		}
		model.lastErr = nil
		if model.baseline {
			// 재개 직후에는 새 기준점만 세운다. 멈춘 시간 전체를 한 행의 평균 rate로 보이지 않는다.
			model.previous, model.baseline = value.snapshot, false
			return model, model.tick()
		}
		rate := calculateRate(model.previous, value.snapshot)
		if seconds := value.snapshot.TakenAt.Sub(model.previous.TakenAt).Seconds(); seconds > 0 {
			model.interfaceRates = calculateNetInterfaceRates(model.previous.allNetInterfaces(), value.snapshot.allNetInterfaces(), seconds)
		}
		var sample historyTopSample
		if model.record != nil || model.autoRecord != nil {

		sample = newHistoryTopSample(model.details, model.previous, value.snapshot, rate, model.processFilter.String())
	}
	if model.record != nil && !model.previous.TakenAt.Before(model.recordFrom) {
		if err := model.record(sample); err != nil {
			model.recordingErr = err
			return model, tea.Quit
		}
		model.recordCount++
		if model.recordNotice {
			model.notice, model.recordNotice = "", false
		}
	}
	var autoCmd tea.Cmd
	model, autoCmd = model.observeAutoRecord(sample, rate)
	if model.recordingErr != nil {
		return model, tea.Quit
	}
	before := len(model.rows) + 1
	model.rows = appendTopDashboardRow(model.rows, topDashboardRow{at: value.snapshot.TakenAt, rate: rate, processes: value.snapshot.Processes, processTotal: value.snapshot.ProcessTotal, processesValid: value.snapshot.ProcessesValid, filter: model.processFilter.String()})
	model = model.recordEvents(model.rows[len(model.rows)-1])
	model.previous = value.snapshot
	if model.follow {
		model.selected = len(model.rows) - 1
	} else {
		// history 한도에서 앞 row가 잘리면 번호를 같이 당겨야 고른 시점이 그대로 남는다.
		model.selected = max(0, model.selected-(before-len(model.rows)))
	}
	if model.paused {
		return model, autoCmd
	}
	return model, tea.Batch(model.tick(), autoCmd)
case topAIStartMsg:

		if model.aiOn || model.aiTokens {
			return model.startAI()
		}
		return model, nil
	case topAIPollMsg:
		return model.updateAIPoll(aiPollResult(value))
	case topAIScanMsg:
		return model.updateAIScan(aiUsageSnapshot(value))
	case tea.WindowSizeMsg:
		model.width, model.height = value.Width, value.Height
		return model, nil
	case tea.KeyPressMsg:
		return model.updateKey(value)
	}
	return model, nil
}

func (model topModel) updateKey(key tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if model.input {
		return model.updateInput(key)
	}
	if model.picker != nil {
		return model.updatePicker(key)
	}
	model.notice, model.recordNotice = "", false
	if model.help {
		switch key.String() {
		case "?", "esc":
			model.help = false
		case "q", "ctrl+c":
			return model, tea.Quit
		case "up", "k":
			model.helpOffset = max(0, model.helpOffset-1)
		case "down", "j":
			model.helpOffset = min(max(0, len(model.helpLines())-max(1, model.height-2)), model.helpOffset+1)
		case "pgdown":
			model.helpOffset = min(max(0, len(model.helpLines())-max(1, model.height-2)), model.helpOffset+max(1, model.height-2))
		case "pgup":
			model.helpOffset = max(0, model.helpOffset-max(1, model.height-2))
		}
		return model, nil
	}
	if model.eventsOpen {
		switch key.String() {
		case "e", "esc":
			model.eventsOpen = false
		case "q", "ctrl+c":
			return model, tea.Quit
		case "up", "k":

case "a":
	return model.toggleAI()
case "?":
	model.help = true
	model.helpOffset = 0
case "tab":
	model.processFocus = !model.processFocus
	model.processSelected = 0
	if model.processFocus {
		model.follow, model.peaks, model.detail = false, false, false
	}
case "f":
	return model.followSignal()
case "e":
	model.eventsOpen, model.eventSelected = true, 0
case "[":
	model = model.stepEvent(-1)
case "]":
	model = model.stepEvent(1)
case "i":
	return model.openInterfacePicker()
case "/":
	model.input, model.inputText = true, model.processFilter.String()
	if model.inputText == "" {
		if candidates := model.candidates(); len(candidates) > 0 {
			model.inputText = topFilterSeed(candidates[min(model.processSelected, len(candidates)-1)].Command)
		}
	}
case "esc":
	return model.back()
case "enter":
	model.detail = !model.detail

	if model.detail {
		model.peaks = false
	}
case "h":
	model.peaks = !model.peaks
	if model.peaks {
		model.detail = false
	}
case "up", "k":
	if model.selected > 0 {
		model.selected--
		model.follow = false
	}
case "down", "j":
	if model.selected < len(model.rows)-1 {
		model.selected++
		model.follow = model.selected == len(model.rows)-1
	}
case "pgup":
	if model.selected > 0 {
		model.selected = max(0, model.selected-model.bodyLines())
		model.follow = false
	}
case "pgdown":
	if model.selected < len(model.rows)-1 {
		model.selected = min(len(model.rows)-1, model.selected+model.bodyLines())
		model.follow = model.selected == len(model.rows)-1
	}
case "end", "g":
	model.processFocus = false
	if len(model.rows) > 0 {
		model.selected, model.follow = len(model.rows)-1, true

		}
	}
	if key.String() == "1" || key.String() == "c" || key.String() == "m" || key.String() == "d" || key.String() == "n" || key.String() == "s" || key.String() == "v" || key.String() == "o" {
		model.processSelected = 0
		// 이미 예약한 표본도 새 순위로 읽게 바로 알린다. tick에서만 알리면 한 interval 동안 앞 순위의 후보가 남는다.
		model.syncScanIO()
	}
	return model, nil
}

func (model topModel) syncScanIO() {
	if model.setScanIO != nil {
		model.setScanIO(model.panelRank() == topViewDisk || slices.Contains(model.footerPanels(), topPanelDisk))
	}
}

// homeView는 Esc가 돌아가는 처음 보기다. process 필터가 있으면 그 process 보기, --split으로 시작했으면 박스 화면이다.
func (model topModel) homeView() topView {
	if model.processFilter.active() {
		return topViewProcess
	}
	if model.startView == topViewSplit || (model.startView == "" && len(model.split) > 0) {
		if len(model.splitViews()) > 0 {
			return topViewSplit
		}
	} else if model.startView != "" {
		return model.startView
	}
	return topViewAll
}

// canGoBack은 Esc로 되돌릴 것이 있는지다. 있으면 상태 줄에 Esc back을 보인다.
func (model topModel) canGoBack() bool {
	return model.detail || model.peaks || !model.follow || model.panelSort != "" || model.view != model.homeView() || model.processFilter.active()
}

// back은 Esc 한 번에 한 단계만 되돌린다. 아래 패널, 과거 행 선택, o로 고른 정렬, 처음 보기, process 필터 순서라서 Esc를 몇 번 누르면
// 처음 화면으로 돌아온다. 보기 키를 몰라도 돌아올 수 있게 한다.
func (model topModel) back() (tea.Model, tea.Cmd) {
	switch {
	case model.detail || model.peaks:
		model.detail, model.peaks = false, false
	case !model.follow:
		if len(model.rows) > 0 {
			model.selected = len(model.rows) - 1
		}
		model.follow = true
	case model.panelSort != "":
		model.panelSort, model.processSelected = "", 0
		model.syncScanIO()
	case model.view != model.homeView():
		if home := model.homeView(); home == topViewSplit {
			model = model.enterSplit()
		} else {
			model.view = home
		}
		model.processSelected = 0
		model.syncScanIO()
	case model.processFilter.active():
		model.notice = "process filter cleared"
		return model.applyFilter(topProcessFilter{}, "")
	}
	return model, nil
}

func (model topModel) followSignal() (tea.Model, tea.Cmd) {
	if model.processFilter.active() {
		model.view, model.panelSort = topViewProcess, ""
		model.syncScanIO()
		return model, nil
	}
	row, ok := model.selectedRow()
	if !ok || !row.processesValid {
		model.notice = "f: waiting for a sample"
		return model, nil
	}
	items := topDashboardSignalItems(row.rate, row.processes, row.processTotal.Groups, row.processesValid, model.limits)
	if len(items) > 0 && items[0].view != topViewProcess && model.view != items[0].view {
		model.view, model.panelSort, model.processSelected = items[0].view, "", 0
		model.syncScanIO()
		model.notice = fmt.Sprintf("f: %s → %s view · f again selects a candidate", items[0].text, items[0].view)
		return model, nil
	}
	if len(row.processes) == 0 {
		model.notice = "f: no process in this sample"
		return model, nil
	}
	model.processFocus, model.follow, model.detail, model.peaks = true, false, false, false
	model.processSelected = 0
	model.notice = "process candidates · ↑↓ select · Enter focus · Esc back"
	return model, nil
}

func (model topModel) focusProcess() (tea.Model, tea.Cmd) {
	candidates := model.candidates()
	if len(candidates) == 0 {
		model.notice = "no candidate in this sample · / filter"
		return model, nil
	}
	process := candidates[min(model.processSelected, len(candidates)-1)]
	filter, err := parseTopProcessFilter(strconv.Itoa(process.PID))
	if err != nil {
		model.notice = "f: " + err.Error()
		return model, nil
	}
	name := topProcessName(process.Command, topProcessNameWidth)
	model.notice = fmt.Sprintf("focus pid %d %s · / edits · Esc clears", process.PID, name)
	return model.applyFilter(filter, name)
}

// updateInput은 /로 연 필터 입력을 받는다. Enter는 적용하고, Esc는 바꾸지 않고 닫는다. 빈 값을 적용하면 필터를 지운다.
func (model topModel) updateInput(key tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch key.String() {
	case "ctrl+c":
		return model, tea.Quit
	case "esc":
		model.input = false
	case "enter":
		model.input = false
		filter, err := parseTopProcessFilter(model.inputText)
		if err != nil {
			model.notice = T("observe.top.process_invalid")
			return model, nil
		}
		return model.applyFilter(filter, "")
	case "backspace":
		if runes := []rune(model.inputText); len(runes) > 0 {
			model.inputText = string(runes[:len(runes)-1])
		}
	default:
		if key.Text != "" {
			model.inputText += key.Text
		}
	}
	return model, nil
}

// applyInterfaces는 실행 중에 net 값에 더할 interface를 바꾼다. 잘못된 값이나 없는 이름은 안내만 하고 선택을 그대로 둔다.
// 전환 전 snapshot과 다음 snapshot은 다른 interface를 담으므로, 다음 sample은 기준점만 세우고 행을 만들지 않는다.
func (model topModel) applyInterfaces(text string) (tea.Model, tea.Cmd) {
	filter, err := parseTopInterfaceFilter(text)
	if err != nil {
		model.notice = T("observe.top.interface_invalid", err)
		return model, nil
	}
	if filter.physical && !model.physicalSupported {
		model.notice = T("observe.top.interface_physical_unsupported")
		filter = filter.withoutPhysical()
	}
	if filter.active() && model.listInterfaces != nil {
		list, err := model.listInterfaces()
		if err != nil {
			model.notice = err.Error()
			return model, nil
		}
		present := topInterfaceNames(list)
		if missing := filter.missingNames(present); len(missing) > 0 {
			model.notice = T("observe.top.interface_missing", strings.Join(missing, ", "))
			return model, nil
		}
		if !filter.matchesAny(present, model.interfacePhysical) {
			model.notice = T("observe.top.interface_none_notice", filter)
		}
	}
	if filter.String() == model.interfaces.String() {
		return model, nil
	}
	model.interfaces = filter
	if model.setInterfaces != nil {

		model.setInterfaces(filter)
	}
	model.baseline = true
	model.seq++
	if model.paused {
		return model, nil
	}
	return model, model.tick()
}

// applyFilter는 실행 중에 필터를 바꾼다. 순번을 올려 이전 필터로 수집 중인 표본을 버리고, 필터가 있으면 process 보기로 연다.
func (model topModel) applyFilter(filter topProcessFilter, name string) (tea.Model, tea.Cmd) {
	model.processFocus, model.processSelected = false, 0
	model.follow = true
	model.processFilter, model.focusName = filter, name
	if model.setFilter != nil {
		model.setFilter(filter)
	}
	model.view, model.panelSort = topViewAll, ""
	if filter.active() {
		model.view = topViewProcess
	}
	model.seq++
	if model.paused {
		return model, nil
	}
	return model, model.tick()
}

func (model topModel) withInterval(interval time.Duration) (tea.Model, tea.Cmd) {
	if interval == model.interval {
		return model, nil
	}
	// 낡은 tick이 새 간격을 덮어쓰지 않게 순번을 올린다.
	model.interval, model.seq = interval, model.seq+1
	if model.paused {
		return model, nil
	}
	return model, model.tick()
}

// nextTopInterval은 ladder에서 한 칸 옮긴다. CLI로 받은 값이 ladder에 없으면 가장 가까운 자리에 끼워 넣는다.
func nextTopInterval(current time.Duration, step int) time.Duration {
	ladder := append([]time.Duration{}, topIntervalLadder...)
	index := sort.Search(len(ladder), func(i int) bool { return ladder[i] >= current })
	if index == len(ladder) || ladder[index] != current {
		ladder = append(ladder, current)
		sort.Slice(ladder, func(i, j int) bool { return ladder[i] < ladder[j] })
		index = sort.Search(len(ladder), func(i int) bool { return ladder[i] >= current })
	}
	return ladder[min(max(index+step, 0), len(ladder)-1)]
}

func appendTopDashboardRow(rows []topDashboardRow, row topDashboardRow) []topDashboardRow {
	rows = append(rows, row)
	if len(rows) > topDashboardHistory {
		rows = rows[len(rows)-topDashboardHistory:]
	}
	return rows
}

func (model topModel) selectedRow() (topDashboardRow, bool) {
	if model.selected < 0 || model.selected >= len(model.rows) {
		return topDashboardRow{}, false
	}
	return model.rows[model.selected], true
}

// bodyLines는 표 본문에 쓸 수 있는 줄 수다. View와 PgUp·PgDn이 같은 값을 써서 한 화면씩 넘긴다.
func (model topModel) bodyLines() int {
	if model.view == topViewSplit {
		return model.splitBodyLines()
	}
	headers := len(model.tableHeader())
	return max(1, model.height-1-len(model.processBanner())-headers-len(model.footerLines()))
}

func (model topModel) View() tea.View {
	view := model.dashboardView()
	if model.picker != nil && !(model.width > 0 && (model.width < 24 || model.height < 8)) {
		view.Content = overlayTopBox(view.Content, model.picker.lines(model.interfaceRates, model.displayWidth(), model.height, model.limits.color), model.displayWidth(), model.limits.color)
	}
	return view
}

func (model topModel) dashboardView() tea.View {
	if model.width > 0 && (model.width < 24 || model.height < 8) {
		view := tea.NewView(ansi.Truncate("terminal too small · q quit", model.displayWidth(), "") + "\n" + ansi.Truncate("resize to at least 24×8", model.displayWidth(), ""))
		view.AltScreen = true
		return view
	}
	lines := append([]string{model.dashboardTitle()}, model.processBanner()...)
	if model.help {
		lines = []string{topHeading(topDashboardFitWidth("Help · ↑↓ scroll · ?/Esc back · q quit", model.displayWidth()), model.limits.color)}
		help := model.helpLines()
		start := min(model.helpOffset, max(0, len(help)-1))
		end := min(len(help), start+max(1, model.height-2))
		lines = append(lines, help[start:end]...)
		view := tea.NewView(strings.Join(lines, "\n"))
		view.AltScreen = true
		return view
	}
	if model.eventsOpen {
		lines = []string{topHeading(topDashboardFitWidth("Events · ↑↓ select · Enter jump to its start · e/Esc back · q quit", model.displayWidth()), model.limits.color)}
		lines = append(lines, model.eventListLines()...)
		for index := range lines {
			lines[index] = ansi.Truncate(lines[index], model.displayWidth(), "")
		}
		view := tea.NewView(strings.Join(lines, "\n"))
		view.AltScreen = true
		return view
	}
	model.statusCache = map[string][]string{}
	if model.view == topViewSplit {
		return model.splitView()
	}
	for _, header := range model.tableHeader() {

	lines = append(lines, topDim(header, model.limits.color))
}
footer := model.footerLines()
bodyLines := model.bodyLines()
start := max(0, len(model.rows)-bodyLines)
if !model.follow && len(model.rows) > bodyLines {
	start = min(model.selected, len(model.rows)-bodyLines)
}
starts := model.eventStarts()
for index := start; index < len(model.rows) && index < start+bodyLines; index++ {
	line := model.tableRow(model.currentFilterRow(model.rows[index]))
	selected := index == model.selected && !model.follow
	// 고른 행은 같은 칸에 >를 쓰므로 이벤트 표시를 넣지 않는다.
	if level, ok := starts[model.rows[index].at.UnixNano()]; ok && !selected {
		line = line[:topSelectionColumn] + topTint("!", level, model.limits.color) + line[topSelectionColumn+1:]
	}
	if selected {
		line = line[:topSelectionColumn] + ">" + line[topSelectionColumn+1:]
	}
	line = topRules(line, model.limits.color)
	if selected && !model.processFocus && model.limits.color {
		line = topHighlight(line, model.displayWidth())
	}
	lines = append(lines, line)
}
lines = append(model.padToFooter(lines, footer), footer...)
for index := range lines {
	lines[index] = ansi.Truncate(lines[index], model.displayWidth(), "")
}
view := tea.NewView(strings.Join(lines, "\n"))
view.AltScreen = true
return view

// panelLines는 detail이나 peaks 패널이다. renderer는 넘치는 줄을 접지 않고 자르므로
// 패널을 여러 줄로 나눠 80열에서도 끝까지 보이게 한다.
func (model topModel) panelLines() []string {
	lines := append(model.infoLines(), model.candidateLines()...)
	if model.height > 0 {
		available := max(0, model.height-2-len(model.processBanner())-len(model.tableHeader())-len(model.statusLines()))
		if len(lines) > available {
			lines = lines[:available]
		}
	}
	for index, line := range lines {
		lines[index] = topDashboardFitWidth(line, model.displayWidth())
	}
	return lines
}

// infoLines는 process 후보 위에 보이는 detail, peaks, network 패널과 수집 실패 줄이다.
// panelLinesWithEvents는 좁은 아래 영역에서 process 목록을 후보 칸 폭으로 줄이고 남는 오른쪽에 이벤트를 둔다.
func (model topModel) panelLinesWithEvents() []string {
	right := model
	right.width = topFooterProcessWidth
	candidates := right.candidateLines()
	events := model.eventLines(model.displayWidth()-topFooterProcessWidth-topFooterGap, max(topEventMinLines, len(candidates)))
	lines := model.infoLines()
	for index := 0; index < max(len(candidates), len(events)); index++ {
		var candidate, event string
		if index < len(candidates) {
			candidate = candidates[index]
		}
		if index < len(events) {
			event = events[index]
		}
		lines = append(lines, topDashboardFitWidth(candidate, topFooterProcessWidth)+strings.Repeat(" ", topFooterGap)+event)
	}
	if model.height > 0 {
		available := max(0, model.height-2-len(model.processBanner())-len(model.tableHeader())-len(model.statusLines()))
		lines = lines[:min(len(lines), available)]
	}
	for index, line := range lines {
		lines[index] = topDashboardFitWidth(line, model.displayWidth())
	}
	return lines
}

func (model topModel) infoLines() []string {
	lines := model.panelInfoLines()
	if len(lines) > 0 {
		lines[0] = topLead(lines[0], model.limits.color)
	}
	if model.lastErr != nil {
		lines = append(lines, model.sampleErrorLine())
	}
	return lines
}

func (model topModel) sampleErrorLine() string {
	return topTint(fmt.Sprintf("sample failed · last success %s · %s", model.previous.TakenAt.Format("15:04:05"), model.lastErr), topLevelDanger, model.limits.color)
}

// panelInfoLines는 detail, peaks, network 패널이다. 첫 줄이 패널 제목이다.
func (model topModel) panelInfoLines() []string {
	var lines []string
	switch {
	case model.detail:
		lines = model.detailLines()
	case model.peaks:
		lines = model.peakLines()
	case model.view == topViewNetwork && model.previous.NetworkHealth != nil:
		if row, ok := model.selectedRow(); ok {
			lines = append([]string{"network " + row.at.Format("15:04:05") + " · current namespace · Enter interfaces and settings · i select"}, networkHealthLines(row.rate.NetworkHealth)...)
		}
	}
	return lines
}

// footerLines는 표 아래 영역이다. 넓은 화면에서는 process 후보를 오른쪽에, 패널과 안내를 왼쪽에 둬 줄을 아낀다.
// 필터가 있으면 process 줄에 I/O와 limit 줄이 붙어 길어지므로 위아래로 쌓는다.
// footerLines는 표 아래 영역이다. 이벤트 칸이 없는 폭에서는 진행 중인 이벤트 한 줄을 맨 위에 둔다.
func (model topModel) footerLines() []string {
	if ticker := model.eventTicker(); ticker != "" {
		return append([]string{ticker}, model.footerPanelLines()...)
	}
	return model.footerPanelLines()
}

func (model topModel) footerPanelLines() []string {
	if model.customFooter() {
		return model.customFooterLines()
	}
	if model.displayWidth() < topFooterDockWidth || model.processFilter.active() {
		if model.eventsInFooter() {
			return append(model.panelLinesWithEvents(), model.statusLines()...)
		}
		return append(model.panelLines(), model.statusLines()...)
	}
	processWidth := model.footerProcessWidth()
	leftWidth := model.displayWidth() - topFooterGap - processWidth
	left, right := model, model
	left.width, right.width = leftWidth, processWidth
	info, status, candidates := left.infoLines(), left.statusLines(), right.candidateLines()
	if model.height > 0 {
		available := max(len(status), model.height-2-len(model.processBanner())-len(model.tableHeader()))
		info = info[:min(len(info), available-len(status))]
		candidates = candidates[:min(len(candidates), available)]
	}
	// 상세나 최고치 패널이 없으면 왼쪽 빈자리에 이벤트를 둔다. 줄 수는 오른쪽 process 목록에 맞춘다.
	if len(info) == 0 && model.eventsInFooter() {
		info = model.eventLines(leftWidth, max(topEventMinLines, len(candidates)-len(status)))
	}
	rows := max(len(info)+len(status), len(candidates))
	lines := make([]string, rows)
	for index := range lines {
		var leftLine, rightLine string
		if index < len(info) {
			leftLine = info[index]
		}
		// 안내는 왼쪽 칸의 맨 아래에 둬 화면 마지막 줄에 머문다.

		if offset := index - (rows - len(status)); offset >= 0 {
			leftLine = status[offset]
		}
		if index < len(candidates) {
			rightLine = candidates[index]
		}
		lines[index] = topDashboardFitWidth(leftLine, leftWidth) + strings.Repeat(" ", topFooterGap) + topDashboardFitWidth(rightLine, processWidth)
	}
	return lines
}

// footerProcessWidth는 오른쪽에 붙인 process 후보 칸의 폭이다. 왼쪽에 80열이 남을 때만 RSS 칸만큼 넓힌다.
func (model topModel) footerProcessWidth() int {
	if model.displayWidth() >= topFooterDockWidth+topProcessRSSColumnWidth {
		return topFooterProcessWidth + topProcessRSSColumnWidth
	}
	return topFooterProcessWidth
}

// padToFooter는 아래 영역이 화면 맨 아래에 오도록 빈 줄을 채운다. 시작 직후 행이 적어도 안내 줄이 움직이지 않는다.
func (model topModel) padToFooter(lines, footer []string) []string {
	for model.height > 0 && len(lines)+len(footer) < model.height {
		lines = append(lines, "")
	}
	return lines
}

func (model topModel) dashboardTitle() string {
	state := "live"
	if !model.follow {
		state = "history"
	}
	if model.lastErr != nil {
		state += " · sample error"
	}
	color := model.limits.color
	badge := model.recordingBadge()
	if model.displayWidth() < topTableWidth {
		head := "edc top · " + string(model.view) + " · "
		if badge != "" {
			head += strings.TrimSpace(badge) + " · "
		}
		return topDashboardFitWidth(topHeading(head+state, color), model.displayWidth())
	}
	// 왼쪽은 host 정보, 오른쪽은 보기와 상태다. priority 0은 항상 보이고, 나머지는 폭이 허락하는 만큼
	// OS, memory, edc 버전, CPU 모델 순서로 더한다. 자리는 slice 순서를 따르므로 상태가 바뀌어도 host 정보가 움직이지 않는다.
	type titlePart struct {
		text     string
		priority int
		// paint는 색을 쓸 때 이 조각을 그린다. 비면 회색이다.
		paint func(string) string
	}
	version := ""
	if model.version != "" {
		version = "edc " + model.version
	}
	host := func(text string) string { return richPaint(text, richMagenta, true) }
	view := func(text string) string {
		name, _ := strings.CutPrefix(text, "view ")

	return richDim("view ") + richBold(name)
}
leftParts := []titlePart{
	{model.details.Hostname, 0, host},
	{topHostOS(model.details), 1, nil},
	{model.details.Model, 4, nil},
	{fmt.Sprintf("%d cores", model.details.Cores), 0, nil},
	{topMemorySize(model.details.MemoryTotal), 2, nil},
}
// "all latest"를 버전으로 읽는 일이 없게 보기 이름 앞에 view를 붙인다. 필터는 바로 아래 배너가 보인다.
rightParts := []titlePart{{"view " + string(model.view), 0, view}, {badge, 0, model.paintRecordingBadge}, {state, 0, model.titleState}, {version, 3, nil}}
// join은 폭을 재는 평문을, paintJoin은 같은 조각을 색으로 그린다. 폭은 언제나 평문으로 잰다.
join := func(parts []titlePart, priority int) string {
	texts := []string{}
	for _, part := range parts {
		if part.priority <= priority && part.text != "" {
			texts = append(texts, part.text)
		}
	}
	return strings.Join(texts, " · ")
}
paintJoin := func(parts []titlePart, priority int) string {
	if !color {
		return join(parts, priority)
	}
	// 이웃한 회색 조각과 구분점은 한 번에 칠해 escape 수를 줄인다.
	var painted, gray strings.Builder
	first := true
	for _, part := range parts {
		if part.priority > priority || part.text == "" {
			continue
		}

		if !first {
			gray.WriteString(" · ")
		}
		first = false
		if part.paint == nil {
			gray.WriteString(part.text)
			continue
		}
		painted.WriteString(richDim(gray.String()) + part.paint(part.text))
		gray.Reset()
	}
	return painted.String() + richDim(gray.String())
}
// 상태를 표 오른쪽 끝에 맞춘다. all 보기의 표는 terminal 폭을 쓰고, 다른 보기의 표는 80열이다.
width := topTableWidth
if model.view == topViewAll {
	width = max(topTableWidth, model.width)
}
// 두 부분 사이에 최소 두 칸을 둔다. 한 칸이면 이어진 문장처럼 읽힌다.
const gap = 2
title := ""
for priority := 0; priority <= 4; priority++ {
	left, right := "🐰 "+join(leftParts, priority), join(rightParts, priority)+" 🐰"
	space := width - topDisplayWidth(left) - topDisplayWidth(right)
	if space < gap {
		break
	}
	title = "🐰 " + paintJoin(leftParts, priority) + strings.Repeat(" ", space) + paintJoin(rightParts, priority) + " 🐰"
}
if title == "" {
	// host 이름이 길어 양쪽으로 뗄 수 없으면 한 줄로 잇는다. 넘치는 부분은 renderer가 자른다.
	separator := " · "

		if color {
			separator = richDim(separator)
		}
		title = "🐰 " + paintJoin(leftParts, 0) + separator + paintJoin(rightParts, 0) + " 🐰"
	}
	return title
}

// recordingBadge는 기록 중일 때 제목 오른쪽에 두는 배지의 평문이다. 아래 줄의 w rec chip만으로는 기록 중인지
// 한눈에 보이지 않았다. 색을 쓰면 richBadge가 앞뒤에 한 칸씩 붙이므로 폭을 맞추려고 평문에도 넣는다.
func (model topModel) recordingBadge() string {
	if model.record == nil {
		return ""
	}
	text := "● REC"
	if model.paused {
		text = "❚❚ REC"
	}
	if !model.limits.color {
		return "[" + text + "]"
	}
	return " " + text + " "
}

// paintRecordingBadge는 기록 중이면 빨강, 일시 정지면 노랑 바탕으로 그린다.
func (model topModel) paintRecordingBadge(text string) string {
	color := richRed
	if model.paused {
		color = richYellow
	}
	return richBadge(strings.TrimSpace(text), color)
}

// titleState는 제목의 live, history 상태다. live는 초록, history는 노랑, 수집 실패는 빨강이다.
func (model topModel) titleState(text string) string {
	state, failure, failed := strings.Cut(text, " · ")
	color := richGreen
	if state != "live" {
		color = richYellow
	}
	painted := richPaint(state, color, false)
	if failed {
		painted += richDim(" · ") + richPaint(failure, richRed, false)
	}
	return painted
}

// topHostOS는 제목에 쓸 OS 이름이다. Linux의 Version은 os-release의 PRETTY_NAME이라 배포판 이름을 이미 담고 있다.
func topHostOS(details hostDetails) string {
	if details.System == "Linux" && details.Version != "" {
		return details.Version
	}
	return strings.TrimSpace(details.OS + " " + details.Version)
}

func topMemorySize(total uint64) string {
	if total == 0 {
		return ""
	}
	return formatBytes(total)
}

// currentFilterRow는 지금 필터와 다른 필터로 수집한 행의 process 값을 비운다. 초점을 바꾸기 전 행이 새 필터의 값처럼 보이지 않는다.
func (model topModel) currentFilterRow(row topDashboardRow) topDashboardRow {
	if row.filter != model.processFilter.String() {
		row.processesValid = false
	}
	return row
}

func (model topModel) detailLines() []string {
	row, ok := model.selectedRow()
	row = model.currentFilterRow(row)
	if !ok {
		return []string{"detail · waiting for a sample"}
	}
	rate := row.rate
	if model.view == topViewNetwork {
		// limit 줄은 Enter 없이도 n 보기 패널에 있으므로 맨 뒤에 둔다. 24행 화면에서는 아래 칸이 잘리는데, interface와 설정은
		// 이 상세에만 있다.
		lines := append([]string{"network detail " + row.at.Format("15:04:05")}, topInterfaceLines(rate, model.interfaces)...)
		return append(append(lines, networkSettingLines(rate.NetworkHealth)...), networkHealthLines(rate.NetworkHealth)...)
	}
	lines := []string{
		fmt.Sprintf("detail %s · load %.1f · cpu %.1f/%.1f%% · iowait %.1f%% · mem %.1f%%", row.at.Format("15:04:05"), rate.Load1, rate.CPUUser, rate.CPUSystem, rate.CPUIOWait, rate.MemoryPercent),
		fmt.Sprintf("  %s · %s · %s", topDiskDetail(rate), topNetworkDetail(rate), topPressureDetail(rate)),
	}
	if !model.processFilter.active() {
		return append(lines, "  "+topProcessDetail(row.processes, row.processesValid, model.limits.color))
	}
	for index, line := range topMatchDetail(row.processes, row.processTotal, row.processesValid, model.limits.color) {
		if index == 0 {
			line = "  " + line
		}
		lines = append(lines, line)
	}
	if row.processesValid {
		lines = append(lines, topProcessLimitLines(row.processes)...)
	}
	return lines
}

// peakLines는 지표마다 따로 최고치를 찾는다. 단위가 다른 값을 더해 한 행을 고르면 load 급등이 memory에 가려진다.
func (model topModel) peakLines() []string {
	if len(model.rows) == 0 {
		return []string{"peaks 60s · waiting for a sample"}
	}
	last := model.rows[len(model.rows)-1]
	if model.view == topViewNetwork && last.rate.NetworkHealth != nil {
		return model.networkPeakLines(last)
	}
	load, cpu, iowait, memory := last, last, last, last
	for _, row := range model.rows {
		if last.at.Sub(row.at) > topPeakWindow {
			continue
		}
		if row.rate.Load1 > load.rate.Load1 {
			load = row
		}
		if row.rate.CPUUser+row.rate.CPUSystem > cpu.rate.CPUUser+cpu.rate.CPUSystem {
			cpu = row
		}
		if row.rate.CPUIOWait > iowait.rate.CPUIOWait {
			iowait = row
		}
		if row.rate.MemoryPercent > memory.rate.MemoryPercent {
			memory = row
		}
	}
	return []string{
		fmt.Sprintf("peaks 60s · load %.1f at %s · cpu %.1f%% at %s", load.rate.Load1, load.at.Format("15:04:05"), cpu.rate.CPUUser+cpu.rate.CPUSystem, cpu.at.Format("15:04:05")),
		fmt.Sprintf("          · iowait %.1f%% at %s · mem %.1f%% at %s", iowait.rate.CPUIOWait, iowait.at.Format("15:04:05"), memory.rate.MemoryPercent, memory.at.Format("15:04:05")),
	}
}

func (model topModel) statusLines() []string {
	key := fmt.Sprintf("%d:%s", model.displayWidth(), model.hiddenText())
	if model.statusCache != nil {
		if lines, ok := model.statusCache[key]; ok {
			return lines
		}
	}
	lines := model.renderStatusLines()
	if model.statusCache != nil {
		model.statusCache[key] = lines
	}
	return lines
}

func (model topModel) renderStatusLines() []string {
	state := "interval " + model.interval.String()
	if model.interfaces.active() {
		// 긴 목록이 80열에서 키 안내를 밀어내지 않게 줄인다. 전체 값은 n 보기 상세 머리줄에 있다.
		state = "net " + ansi.Truncate(model.interfaces.String(), topStatusInterfaceWidth, "…") + " · " + state
	}
	if model.record != nil {
		state = fmt.Sprintf("REC · %d samples · %s", model.recordCount, state)
		if model.autoRecord != nil && model.autoRecord.trigger != "" {
			state = "auto " + model.autoRecord.trigger + " · " + state
		}
	}
	if hidden := model.hiddenText(); hidden != "" {
		state = hidden + " · " + state
	}
	if model.paused {
		state = T("observe.top.paused") + " · " + state
	} else if !model.follow {
		state = fmt.Sprintf("history · %d new · %s", max(0, len(model.rows)-1-model.selected), state)
	}
	var keys topKeyHints
	if model.processFilter.active() {
		keys = topKeyHints{{key: "1", label: "host"}, {key: "f", label: "proc"}, model.sortHint(), {key: "/", label: "edit"}, {key: "Esc", label: "back"}, {key: "?", label: "help"}}
	} else {
		keys = topKeyHints{
			{key: "c", label: "cpu", on: model.view == topViewCPU}, {key: "m", label: "mem", on: model.view == topViewMemory},
			{key: "d", label: "disk", on: model.view == topViewDisk}, {key: "n", label: "net", on: model.view == topViewNetwork},
			model.sortHint(), {key: "f", label: "candidates"}, {key: "/", label: "filter"}, {key: "?", label: "help"},
		}
	}
	// a는 켰을 때만 켜진 항목으로 보인다. 늘 두면 80열에서 / filter와 ? help가 잘린다. 끈 상태의 a는 ? 도움말에 있다.
	if model.aiOn {

	keys = append(topKeyHints{{key: "a", label: "ai", on: true}}, keys...)
}
if model.interfaces.active() {
	// net 표시가 붙으면 80열에서 / filter까지 잘린다. ? help는 아래 줄에도 있고, o는 ? 도움말에 있으며 고른 뒤에는
	// 패널 제목의 (o)로 보이므로 둘을 뺀다.
	kept := topKeyHints{}
	for _, hint := range keys {
		if hint.key != "?" && hint.key != "o" {
			kept = append(kept, hint)
		}
	}
	keys = kept
}
color := model.limits.color
views := topStatusLine{plain: state + " · " + keys.render(" ", false), styled: topDim(state+" · ", color) + keys.render(" ", color)}
// 두 줄을 합칠 때는 ? help를 아래 줄에만 둔다.
joinedKeys := keys
if last := len(keys) - 1; keys[last].key == "?" {
	joinedKeys = keys[:last]
}
joinedViews := topStatusLine{plain: state + " · " + joinedKeys.render(" ", false), styled: topDim(state+" · ", color) + joinedKeys.render(" ", color)}
switch {
case model.input:
	views = topDimStatusLine("process filter: "+model.inputText+"█ · Enter apply · Esc cancel", color)
	joinedViews = views
case model.notice != "":
	views = topDimStatusLine(model.notice, color)
	joinedViews = views
}
// PgUp/Dn을 넣어도 80열에서 끝의 +/-가 잘리지 않게 구분 공백을 두 칸으로 맞췄다.
actionHints := topKeyHints{{key: "↑↓", label: "history"}, {key: "Tab", label: "processes"}, {key: "Enter", label: "detail"}, {key: "End", label: "live"}}
if model.canGoBack() {

	actionHints = append(actionHints, topKeyHint{key: "Esc", label: "back"})
}
actionHints = append(actionHints, topKeyHint{key: "?", label: "help"}, topKeyHint{key: "q", label: "quit"})
if model.processFocus {
	actionHints = topKeyHints{{key: "↑↓", label: "select"}, {key: "Enter", label: "focus PID"}, {key: "Tab/Esc", label: "history"}, {key: "End", label: "live"}, {key: "?", label: "help"}, {key: "q", label: "quit"}}
}
actionHints = append(topKeyHints{{key: "w", label: "rec", on: model.record != nil}}, actionHints...)
actions := topStatusLine{plain: actionHints.render(" ", false), styled: actionHints.render(" ", color)}
if model.displayWidth() < 70 {
	narrowViews := state + " · / filter · ? help · q quit"
	narrowActions := "w rec · Tab processes · ↑↓ history · End live"
	if model.canGoBack() {
		narrowActions += " · Esc back"
	}
	if model.processFocus {
		narrowActions = "↑↓ select · Enter focus · Esc back"
	}
	if model.input {
		narrowViews = "filter: " + model.inputText + "█"
		narrowActions = "Enter apply · Esc cancel"
	} else if model.notice != "" {
		narrowViews = model.notice
	}
	views, actions = topDimStatusLine(narrowViews, color), topDimStatusLine(narrowActions, color)
	joinedViews = topDimStatusLine(strings.TrimSuffix(narrowViews, " ? help"), color)
}
if model.displayWidth() < 40 && !model.input && model.notice == "" {
	views = topDimStatusLine(model.interval.String()+" · ? help · q quit", color)
	joinedViews = topDimStatusLine(model.interval.String()+" · ? help · q quit", color)
	tiny := "↑↓ history · Tab procs"
	if model.processFocus {
		tiny = "↑↓ pick · Enter · Esc"

		}
		actions = topDimStatusLine(tiny, color)
	}
	// 두 줄이 한 폭에 들어가면 합쳐 표가 한 줄 더 보이게 한다. 폭은 색이 없는 문자열로 잰다.
	if ansi.StringWidth(joinedViews.plain+"  ·  "+actions.plain) <= model.displayWidth() {
		return []string{topFitStatusLine(joinedViews.styled+topDim("  ·  ", color)+actions.styled, model.displayWidth(), color)}
	}
	return []string{topFitStatusLine(views.styled, model.displayWidth(), color), topFitStatusLine(actions.styled, model.displayWidth(), color)}
}

// topKeyHint는 안내 줄의 키 하나다. on은 지금 켜진 보기나 정렬이다.
type topKeyHint struct {
	key, label string
	on         bool
}

// render는 키를 굵은 청록색으로, 설명을 회색으로 쓴다. 다른 화면의 liveKeyHints와 같은 색이다. 켜진 항목은 선택 행과 같은 바탕으로 칠해 지금 상태를 보인다.
// 색이 없으면 글자만 남으므로 정렬 기준은 label에 적는다.
func (hints topKeyHints) render(sep string, color bool) string {
	parts := make([]string, 0, len(hints))
	for _, hint := range hints {
		text := hint.key + " " + hint.label
		switch {
		case !color:
		case hint.on:
			text = topBannerStyle() + text + richReset
		default:
			text = richPaint(hint.key, richCyan, true) + richDim(" "+hint.label)
		}
		parts = append(parts, text)
	}
	return strings.Join(parts, topDim(sep, color))
}

// sortHint는 o 안내다. o로 고른 기준이 있으면 sort:MEM처럼 기준을 붙여 켜진 항목으로 보인다.
func (model topModel) sortHint() topKeyHint {
	if model.panelSort == "" {
		return topKeyHint{key: "o", label: "sort"}
	}
	return topKeyHint{key: "o", label: "sort:" + topRankName(model.panelSort), on: true}
}

// topRankName은 패널 순위의 이름이다. 안내 줄의 sort:MEM과 패널 제목의 MEM rank가 같은 이름을 쓴다.
func topRankName(rank topView) string {
	switch rank {
	case topViewMemory:
		return "MEM"
	case topViewDisk:
		return "I/O"
	}
	return "CPU"
}

func topDimStatusLine(text string, color bool) topStatusLine {
	return topStatusLine{plain: text, styled: topDim(text, color)}
}

// topFitStatusLine은 줄을 폭에 맞춘다. 잘린 자리에서 색이 다음 줄로 번지지 않게 끝에서 닫는다.
func topFitStatusLine(styled string, width int, color bool) string {
	line := topDashboardFitWidth(styled, width)
	if color {
		line += richReset
	}
	return line
}

func (model topModel) displayWidth() int {
	if model.width <= 0 {
		return topTableWidth
	}
	return model.width
}

// panelRank은 process 패널의 정렬 기준이다. o로 고른 기준이 없으면 보기를 따르고, 메모리와 디스크 보기 밖에서는 CPU 순이다.
func (model topModel) panelRank() topView {
	view := model.view
	if model.panelSort != "" {
		view = model.panelSort
	} else if model.processSort != "" {
		view = model.processSort
	}
	switch view {
	case topViewMemory, topViewDisk:
		return view
	}
	return topViewCPU
}

// nextTopPanelSort는 o를 누를 때의 다음 정렬 기준이다. 마지막 다음은 다시 보기를 따른다.
func nextTopPanelSort(current topView) topView {
	switch current {
	case "":
		return topViewCPU
	case topViewCPU:
		return topViewMemory
	case topViewMemory:
		return topViewDisk
	}
	return ""
}

func (model topModel) candidates() []topProcess {
	row, ok := model.selectedRow()
	row = model.currentFilterRow(row)
	if !ok || !row.processesValid {
		return nil
	}
	return topRankedProcesses(row.processes, model.panelRank())[:min(topProcessLimit, len(row.processes))]
}

// topRankedProcesses는 process를 순위 기준으로 줄 세운 복사본이다. 후보 목록과 자원 패널이 함께 쓴다.
func topRankedProcesses(source []topProcess, rank topView) []topProcess {
	processes := append([]topProcess(nil), source...)
	switch rank {
	case topViewMemory:
		// signal이 가리키는 가장 많이 늘어난 process 하나만 크기와 상관없이 앞에 둔다. 다섯 줄로 자를 때 그 줄이 빠지면
		// 안 된다. 늘어나는 process를 모두 앞에 두면 같은 일을 하는 worker 여럿이 가장 큰 process를 밀어낸다.
		sort.SliceStable(processes, func(i, j int) bool { return processes[i].memory() > processes[j].memory() })
		if growing, ok := topFastestGrowing(processes); ok {
			index := slices.IndexFunc(processes, func(process topProcess) bool { return process.PID == growing.PID })
			processes = append([]topProcess{growing}, slices.Delete(processes, index, index+1)...)
		}
	case topViewDisk:
		// 디스크 대기는 CPU를 쓰지 않으므로 I/O가 큰 process를 앞에 둔다. I/O를 읽지 못했거나 같으면
		// I/O를 기다리며 멈춘 process를 CPU 순위보다 앞에 둔다.
		sort.SliceStable(processes, func(i, j int) bool {
			if before, after := topProcessIOTotal(processes[i]), topProcessIOTotal(processes[j]); before != after {
				return before > after
			}
			return processes[i].State == topProcessStateBlocked && processes[j].State != topProcessStateBlocked
		})
	}
	return processes
}

// showsProcessIO는 후보 줄 끝에 읽기·쓰기 rate를 붙일지다. 필터를 걸었거나 디스크 보기이면 읽지 못한 값도 —로 보이고,
// 그 밖의 보기에서는 값을 구한 process가 있을 때만 붙인다.
func (model topModel) showsProcessIO(processes []topProcess) bool {
	if model.displayWidth() < topProcessIOMinWidth {
		return false
	}
	if model.processFilter.active() || model.panelRank() == topViewDisk {
		return true
	}
	for _, process := range processes {
		if process.DiskValid {
			return true
		}
	}
	return false
}

// topProcessStateNames는 /proc/<pid>/stat의 state 문자를 읽을 수 있는 이름으로 바꾼다. D는 커널이 disk sleep이라 부르지만
// 디스크 외의 I/O에서도 생기므로 iowait로 쓴다.
var topProcessStateNames = map[string]string{
	"R": "run", "S": "sleep", "D": "iowait", "Z": "zombie", "T": "stop", "t": "trace", "I": "idle", "X": "dead", "P": "park",
}

// topProcessStateName은 STATE 칸의 이름이다. 표에 없는 문자는 그대로 보이고, 모르면 빈 칸이다.
func topProcessStateName(state string) string {
	if name, ok := topProcessStateNames[state]; ok {
		return name
	}
	return topPrintableText(state)
}

// topProcessIOCell은 READ·WRITE 한 칸이다. 폭을 먼저 맞춘 뒤 색을 입혀 열이 어긋나지 않는다.
func topProcessIOCell(valid bool, value float64, color bool) string {
	text := topFitCell(topOptionalRate(valid, value), 6, false)
	if !valid {
		return text
	}
	return topTint(text, topProcessIOThreshold.level(value), color)
}

// topProcessGroupDetail은 묶음 이름 뒤 괄호에 넣는 process 수와 I/O를 기다리는 수다. 이름에 수를 붙여 쓰면
// gm×163처럼 다른 process 이름으로 읽혀 괄호 안에 단어와 함께 적는다.
func topProcessGroupDetail(group topProcessGroup) string {
	detail := fmt.Sprintf("%d procs", group.Count)
	if group.Blocked > 0 {
		detail += fmt.Sprintf(", %d %s", group.Blocked, topProcessStateName(topProcessStateBlocked))
	}
	return detail
}

// topProcessGroupLabel은 후보 목록의 묶음 이름 칸이다. 폭이 모자라면 I/O 대기 수를 빼고, 그래도 모자라면 이름을 줄인다.
func topProcessGroupLabel(group topProcessGroup, width int) string {
	if group.Place != "" {
		group.Name += " · " + group.Place
	}
	name := topProcessName(group.Name, width)
	count := fmt.Sprintf(" (%d procs)", group.Count)
	for _, suffix := range []string{" (" + topProcessGroupDetail(group) + ")", count} {
		if ansi.StringWidth(name+suffix) <= width {
			return name + suffix
		}
	}
	return topProcessName(group.Name, max(1, width-len(count))) + count
}

// topProcessGroupLine은 묶음 한 줄이다. 고를 수 없는 줄이라 PID 칸과 표시를 비운다.
// CPU 합이 process 경고 기준을 넘으면 그 칸을 위험 색으로 칠한다.
func topProcessGroupLine(group topProcessGroup, nameWidth int, showRSS, showIO, color bool) string {
	name := topProcessGroupLabel(group, nameWidth)
	cpu := fmt.Sprintf("%6.1f%%", group.CPU)
	if group.CPU >= topProcessSignalCPU {
		cpu = topTint(cpu, topLevelDanger, color)
	}
	line := fmt.Sprintf("  %7s %s %s %s %s", "", topFitCell(name, nameWidth, true), strings.Repeat(" ", topProcessStateWidth), cpu, topProcessMemoryCell(formatProcessGroupMemory(group.Memory), group.MemoryEstimated, color))
	if showRSS {
		line += fmt.Sprintf(" %6s", formatProcessGroupMemory(group.RSS))
	}
	if showIO {
		line += " " + topProcessIOCell(group.DiskValid, group.DiskRead, color) + " " + topProcessIOCell(group.DiskValid, group.DiskWrite, color)
	}
	return line
}

// topViewProcessGroups는 보기의 순위 기준에 맞는 묶음이다. 디스크는 I/O, 메모리는 memory, 나머지는 CPU 합 순이다.
func topViewProcessGroups(groups []topProcessGroup, view topView) []topProcessGroup {
	switch view {
	case topViewDisk:
		return topProcessGroupsByIO(groups)
	case topViewMemory:
		return topProcessGroupsByMemory(groups)
	}
	return topProcessGroupsByCPU(groups)
}

// topProcessMemoryCell은 MEM 칸이다. Memory를 읽지 못해 RSS로 대신한 값은 흐리게 보여 측정값과 구분한다.
func topProcessMemoryCell(text string, estimated, color bool) string {
	cell := fmt.Sprintf("%6s", text)
	if estimated {
		return topDim(cell, color)
	}
	return cell
}

// formatProcessGroupMemory는 묶음의 memory 합이다. 공유 page를 process마다 셀 수 있어 실제 사용량의 상한이라 ≤를 붙인다.
func formatProcessGroupMemory(bytes uint64) string {
	const mib = 1024 * 1024
	switch {
	case bytes >= 1024*mib:
		return fmt.Sprintf("≤%.1fG", float64(bytes)/(1024*mib))
	case bytes >= 10*mib:
		return fmt.Sprintf("≤%.0fM", float64(bytes)/mib)
	}
	return fmt.Sprintf("≤%.1fM", float64(bytes)/mib)
}

func (model topModel) candidateLines() []string {
	row, ok := model.selectedRow()
	row = model.currentFilterRow(row)
	if !ok || !row.processesValid {
		return []string{topHeading("processes · waiting for a sample with this filter", model.limits.color)}
	}
	state := "live"
	if !model.follow {
		state = "history"
	}
	title := topRankName(model.panelRank())
	chosen := ""
	if model.panelSort != "" {
		chosen = " (o)"
	}
	lines := []string{topHeading(fmt.Sprintf("processes · %s rank%s · %s %s · Tab select", title, chosen, state, row.at.Format("15:04:05")), model.limits.color)}
	processes := model.candidates()
	if len(processes) == 0 {
		return append(lines, "no match · / edit filter · Esc clear")
	}
	showIO := model.showsProcessIO(processes)
	nameRoom := model.displayWidth() - topProcessColumnsWidth - 10
	if showIO {
		nameRoom = model.displayWidth() - topProcessColumnsWidth - topProcessIOColumnsWidth
	}
	// RSS 칸은 I/O 칸이 붙어도 들어갈 때만 둔다. I/O 값은 refresh마다 생겼다 없어져서, 그에 따라 정하면 열 구성이 바뀐다.
	rssRoom := model.displayWidth() - topProcessColumnsWidth - topProcessIOColumnsWidth - topProcessRSSColumnWidth
	showRSS := model.displayWidth() >= 40 && rssRoom >= topProcessRSSMinNameWidth
	if showRSS {
		nameRoom -= topProcessRSSColumnWidth
	}
	nameWidth := max(4, min(28, nameRoom))

if model.displayWidth() < 40 {
	nameWidth = max(3, model.displayWidth()-18)
}
room := model.height - 2 - len(model.processBanner()) - len(model.tableHeader()) - len(model.statusLines())
if room >= 3 {
	// PID는 Linux에서 7자리(기본 pid_max 4194304)까지 가므로 일곱 칸을 둔다.
	header := fmt.Sprintf("  %7s %s %s %7s %6s", "PID", topFitCell("COMMAND", nameWidth, true), topFitCell("STATE", topProcessStateWidth, true), "CPU%", "MEM")
	if showRSS {
		header += fmt.Sprintf(" %6s", "RSS")
	}
	if showIO {
		header += fmt.Sprintf(" %6s %6s", "READ", "WRITE")
	}
	if model.displayWidth() < 40 {
		// 좁은 화면은 값 하나만 둔다. I/O 순위에도 CPU를 보이므로 MEM 순위만 MEM이다.
		value := "CPU"
		if model.panelRank() == topViewMemory {
			value = "MEM"
		}
		header = fmt.Sprintf("  %7s %s %6s", "PID", topFitCell("COMMAND", nameWidth, true), value)
	}
	lines = append(lines, topDim(header, model.limits.color))
}
if model.displayWidth() >= 40 && !model.processFilter.active() {
	groups := topViewProcessGroups(row.processTotal.Groups, model.panelRank())
	// 묶음이 process 줄을 모두 밀어내지 않도록 process 한 줄은 남긴다.
	groups = groups[:min(len(groups), max(0, room-len(lines)-1))]
	for _, group := range groups {
		lines = append(lines, topProcessGroupLine(group, nameWidth, showRSS, showIO, model.limits.color))
	}
}
count := min(3, len(processes))

if model.processFocus || model.height >= topTallHeight {
	count = min(topProcessLimit, len(processes))
}
count = min(count, max(1, room-len(lines)))
start := 0
if model.processFocus {
	start = max(0, model.processSelected-count+1)
}
for index := start; index < min(start+count, len(processes)); index++ {
	process := processes[index]
	selected := model.processFocus && index == model.processSelected
	marker := " "
	if selected {
		marker = ">"
	}
	// 고른 줄은 칸 색 없이 바탕 하나로 칠해 한 덩어리로 읽힌다.
	color := model.limits.color && !selected
	state := topFitCell(topProcessStateName(process.State), topProcessStateWidth, true)
	if process.State == topProcessStateBlocked {
		state = topTint(state, topLevelWarn, color)
	}
	memory := topProcessMemoryCell(formatProcessRSS(process.memory()), !process.MemoryValid, color)
	// 꾸준히 늘어나는 process는 크기와 상관없이 칸을 칠해 signal이 가리키는 줄을 찾게 한다. RSS로 대신한 값은
	// 정확한 footprint로 오해하지 않게 흐린 색을 그대로 둔다.
	if growth := process.Growth; growth != nil && process.MemoryValid {
		memory = topTint(memory, topSignalItem{score: topMemoryGrowthScore(*growth, model.limits.memoryTotal, row.rate.MemoryPercent)}.level(), color)
	}
	line := fmt.Sprintf("%s %7d %s %s %6.1f%% %s", marker, process.PID, topFitCell(topProcessName(process.Command, nameWidth), nameWidth, true), state, process.CPU, memory)
	if showRSS {
		line += fmt.Sprintf(" %6s", formatProcessRSS(process.RSS))
	}
	if model.displayWidth() < 40 {

			value := fmt.Sprintf("%6s", fmt.Sprintf("%.1f%%", process.CPU))
			if model.panelRank() == topViewMemory {
				value = memory
			}
			line = fmt.Sprintf("%s %7d %s %6s", marker, process.PID, topFitCell(topProcessName(process.Command, nameWidth), nameWidth, true), value)
		}
		if showIO {
			line += " " + topProcessIOCell(process.DiskValid, process.DiskRead, color) + " " + topProcessIOCell(process.DiskValid, process.DiskWrite, color)
		}
		if selected && model.limits.color {
			line = topHighlight(line, model.displayWidth())
		}
		lines = append(lines, line)
	}
	if model.processFocus || model.processFilter.active() {
		process := processes[min(model.processSelected, len(processes)-1)]
		if process.DiskStatus != "" {
			lines = append(lines, "I/O · "+process.DiskStatus)
		}
		if model.processFilter.active() && !model.detail {
			lines = append(lines, topProcessLimitLines([]topProcess{process})...)
		}
	}
	return lines
}

		wrapped = append(wrapped, strings.Split(ansi.Wrap(line, model.displayWidth(), ""), "\n")...)
	}
	return wrapped
}

func (model topModel) tableColumns() ([]topColumn, []int) {
	columns := topViewColumns(model.view)
	var kept []topColumn
	var indexes []int
	used := topSelectionColumn + 2
	dropped := false
	for index, column := range columns {
		if model.view == topViewProcess && model.displayWidth() < 56 && column.title == "thr" {
			continue
		}
		if !column.host.shown(model.details.System) {
			continue
		}
		if model.boxed && model.splitHidden(column.title) {
			continue
		}
		if cores := len(model.previous.Cores); column.title == "cores" && cores > 0 {
			// 막대는 core마다 한 칸이다. details.Cores는 CPU affinity를 따라 /proc/stat의 core 수보다 작을 수 있어 막대가 그리는 수를 쓴다.
			column.width = min(topCoreBarLimit, max(len(column.title), cores))
		}
		if model.view == topViewProcess && !model.probeEnabled && (column.title == "runq ms" || column.title == "io ms") {
			continue
		}
		if column.optional && (dropped || model.compact) {
			continue
		}
		needed, reserve := column.width+1, 0
		if column.optional && !model.boxed {
			reserve = topSignalMinWidth
		}
		if column.width > 0 && used+needed+reserve > model.displayWidth() {
			dropped = dropped || !column.optional

			continue
		}
		kept, indexes = append(kept, column), append(indexes, index)
		used += needed
	}
	return kept, indexes
}

func (model topModel) tableHeader() []string {
	if model.view == topViewAll && model.displayWidth() >= topTableWidth {
		columns, signalWidth := model.hostLayout()
		titles := make([]topCell, len(columns))
		for index, column := range columns {
			titles[index] = topPlainCell(column.title)
		}
		return []string{formatTopAllGroupHeader(columns, signalWidth), formatTopAllLine("", columns, titles, "", signalWidth, false)}
	}
	if model.view == topViewAll {
		return []string{model.compactRow(topDashboardRow{}, true)}
	}
	columns, _ := model.tableColumns()
	titles := make([]topCell, len(columns))
	for index, column := range columns {
		titles[index] = topPlainCell(column.title)
	}
	return []string{formatTopColumnsWidth("time", columns, titles, false, model.displayWidth())}
}

func (model topModel) tableRow(row topDashboardRow) string {
	if model.view == topViewAll {
		if model.displayWidth() < topTableWidth {
			return model.compactRow(row, false)
		}
		columns, signalWidth := model.hostLayout()
		cells := make([]topCell, len(columns))
		tokens := model.aiTokensBetween(model.previousRowAt(row.at), row.at)
		for index, column := range columns {
			if column.tokens != nil {
				cells[index] = topPlainCell(column.tokens(tokens))
				continue
			}
			cells[index] = topPlainCell(column.cell(row.rate))
			if column.level != nil {
				cells[index].level = column.level(model.limits, row.rate)
			}
		}
		signals := topDashboardSignalItems(row.rate, row.processes, row.processTotal.Groups, row.processesValid, model.limits)
		return formatTopAllLine(row.at.Format("15:04:05"), columns, cells, formatTopSignalsWidth(signals, signalWidth), signalWidth, model.limits.color)
	}
	columns, indexes := model.tableColumns()
	signal := topDashboardSignal(row.rate, row.processes, row.processTotal.Groups, row.processesValid, model.limits)
	cells := topViewCells(row.rate, model.view, signal, model.limits)
	if model.view == topViewProcess {
		cells = topProcessViewCells(row)
	}
	kept := make([]topCell, len(indexes))
	for index, source := range indexes {
		kept[index] = cells[source]
	}
	return formatTopColumnsWidth(row.at.Format("15:04:05"), columns, kept, model.limits.color, model.displayWidth())

func (model topModel) hostLayout() ([]topAllColumn, int) {
	columns, signalWidth := topAllLayoutOf(model.displayWidth(), topAllGroupColumns(model.columnGroups))
	if model.details.System != "darwin" {
		return columns, signalWidth
	}
	kept := make([]topAllColumn, 0, len(columns))
	for _, column := range columns {
		if column.host.shown(model.details.System) {
			kept = append(kept, column)
		}
	}
	spare := max(0, model.displayWidth()-topAllLineWidth(kept)-signalWidth)
	for index := range kept {
		extra := spare*(index+1)/len(kept) - spare*index/len(kept)
		kept[index].width += extra
		kept[index].indent += extra
	}
	return kept, signalWidth
}

func (model topModel) compactRow(row topDashboardRow, header bool) string {
	columns := []topColumn{{title: "cpu%", width: 5}, {title: "mem%", width: 5}, {title: "load", width: 5}, {title: "signal", left: true}}
	cells := []topCell{topValueCell("%.1f", row.rate.CPUUser+row.rate.CPUSystem, model.limits.cpu), topValueCell("%.1f", row.rate.MemoryPercent, model.limits.memory), topValueCell("%.1f", row.rate.Load1, model.limits.load), topPlainCell(topDashboardSignal(row.rate, row.processes, row.processTotal.Groups, row.processesValid, model.limits))}
	if model.displayWidth() < 32 {
		columns = append(columns[:2], columns[3])
		cells = append(cells[:2], cells[3])
	}
	at := row.at.Format("15:04:05")
	if header {
		at = "time"
		for index, column := range columns {
			cells[index] = topPlainCell(column.title)
		}
	}
	return formatTopColumnsWidth(at, columns, cells, model.limits.color && !header, model.displayWidth())
}

