// latestReleaseTag는 releases/latest가 돌려주는 redirect의 Location에서 tag를 읽는다.
// redirect를 따라가지 않으므로 release 페이지 본문은 받지 않는다.
func latestReleaseTag(ctx context.Context, releasesURL, version string) (string, error) {
	latestURL := releasesURL + "/latest"
	request, err := http.NewRequestWithContext(ctx, http.MethodHead, latestURL, nil)
	if err != nil {
		return "", fmt.Errorf("%s: %w", T("cli.update.request_failed"), err)
	}
	request.Header.Set("User-Agent", "edc/"+version)
	client := &http.Client{CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	response, err := client.Do(request)
	if err != nil {
		return "", fmt.Errorf("%s: %w", T("cli.update.fetch_failed", latestURL), err)
	}
	response.Body.Close()
	location, err := response.Location()
	if err != nil {
		return "", errors.New(T("cli.update.http_status", latestURL, response.StatusCode))
	}
	_, tag, found := strings.Cut(location.Path, "/releases/tag/")
	if !found || tag == "" || strings.Contains(tag, "/") {
		return "", errors.New(T("cli.update.no_tag"))
	}
	return tag, nil
}

func fetch(ctx context.Context, url, version string) ([]byte, error) {
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", T("cli.update.request_failed"), err)
	}
	request.Header.Set("User-Agent", "edc/"+version)

	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", T("cli.update.fetch_failed", url), err)
	}
	defer response.Body.Close()

	if response.StatusCode != http.StatusOK {
		return nil, errors.New(T("cli.update.http_status", url, response.StatusCode))
	}
	body, err := io.ReadAll(io.LimitReader(response.Body, maxUpdateAsset+1))
	if err != nil {
		return nil, fmt.Errorf("%s: %w", T("cli.update.response_read_failed"), err)
	}
	if int64(len(body)) > maxUpdateAsset {
		return nil, errors.New(T("cli.update.asset_too_large", int64(maxUpdateAsset)))
	}
	return body, nil
}

// updateSudo는 설치 디렉터리에 쓸 수 없을 때 파일 교체에 쓸 sudo다. install.sh처럼 교체만 sudo로 하고, 내려받기와
// checksum 확인은 사용자 권한으로 한다. sudo가 proxy 환경 변수를 지워도 내려받기는 그대로 된다. root이거나 신뢰하는 경로에
// sudo가 없으면 쓸 수 없다는 오류를 돌려준다.
func updateSudo(dir string, writeErr error) (string, error) {
	if captureGeteuid() == 0 {
		return "", errors.New(T("cli.update.not_writable", dir, writeErr))
	}
	sudo, ok := captureFirstExecutable(captureSudoPaths)
	if !ok {
		return "", errors.New(T("cli.update.sudo_missing", dir, strings.Join(captureSudoPaths, ", ")))
	}
	return sudo, nil
}

// confirmUpdate는 terminal에서는 확인 화면을, 그 외에는 Y/n 입력을 쓴다. 기본은 업데이트(예)다.
func confirmUpdate(input *os.File, output *os.File, detail string) bool {
	if term.IsTerminal(int(input.Fd())) {
		answer, err := runConfirmModel(input, output, newDetailedConfirmModel(detail, T("cli.update.confirm"), true))
		return err == nil && answer
	}
	fmt.Fprint(output, detail)
	return confirm(input, output, T("cli.update.prompt"), true)
}

// latestReleaseTag는 redirect를 따라가지 않는다. 따라가면 tag 페이지 경로가 403을 돌려 test가 실패한다.
func TestLatestReleaseTagReadsRedirect(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		switch request.URL.Path {
		case "/tagged/latest":
			http.Redirect(writer, request, "/x-mesh/edc/releases/tag/v1.2.3", http.StatusFound)
		case "/untagged/latest":
			http.Redirect(writer, request, "/x-mesh/edc/releases", http.StatusFound)
		default:
			writer.WriteHeader(http.StatusForbidden)
		}
	}))
	defer server.Close()
	ctx := context.Background()
	if tag, err := latestReleaseTag(ctx, server.URL+"/tagged", "test"); err != nil || tag != "v1.2.3" {
		t.Fatalf("tag = %q, err = %v", tag, err)
	}
	if _, err := latestReleaseTag(ctx, server.URL+"/untagged", "test"); err == nil || err.Error() != T("cli.update.no_tag") {
		t.Fatalf("redirect without a tag returned %v", err)
	}
	if _, err := latestReleaseTag(ctx, server.URL+"/blocked", "test"); err == nil || !strings.Contains(err.Error(), "403") {
		t.Fatalf("a response without redirect returned %v", err)
	}
}

// viewPassthrough는 화면 없이 원문을 낸다. lines가 -1이면 전부, 아니면 마지막 lines줄이다. follow면 파일 끝에서 기다리며
// 새로 쓰인 바이트를 낸다. 파일이 바뀐 것은 stdout 원문에 섞지 않고 stderr에 알린다.
func viewPassthrough(stdout, stderr io.Writer, path string, lines int, follow bool) error {
	if path == "" {
		if lines < 0 {
			_, err := io.Copy(stdout, os.Stdin)
			return err
		}
		tail, truncated, err := viewTailReader(os.Stdin, lines)
		for _, line := range tail {
			if _, writeErr := stdout.Write(line); writeErr != nil {
				return writeErr
			}
		}
		if truncated > 0 {
			fmt.Fprintln(stderr, T("view.truncated_lines", truncated, formatSizeShort(uint64(viewTailLineLimit))))
		}
		return err
	}
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	info, err := file.Stat()
	if err != nil {
		file.Close()
		return err
	}
	if info.IsDir() {
		file.Close()
		return fmt.Errorf("%s: %w", path, syscall.EISDIR)
	}

		fmt.Fprintln(os.Stderr, T("view.failed", err))
		return 1
	}
	// 회전된 .gz는 다 쓰인 뒤에 만들어지므로 따라가지 않는다. 끝에서 거꾸로 읽을 수 없어 화면을 열기 전에 끝까지 푼다.
	initialLines := keep
	if lines == 0 {
		initialLines = 0
	}
	raw, readErr := viewReadGzipTail(reader, initialLines)
	reader.Close()
	file.Close()
	model.ingest(raw, time.Now(), false)
	model.changed = info.ModTime()
	model.ended = true
	// 잘린 .gz도 읽은 줄은 보여 주되, 온전한 로그로 믿지 않도록 오류를 함께 표시한다.
	model.err = readErr
	start = func(*tea.Program) {}
} else {
	file, err := os.Open(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, T("view.failed", err))
		return 1
	}
	info, err := file.Stat()
	if err == nil && info.IsDir() {
		err = fmt.Errorf("%s: %w", path, syscall.EISDIR)
	}
	// -n 0은 빈 화면에서 시작해 새 줄만 받는다.
	initialLines := keep
	if lines == 0 {
		initialLines = 0
	}

		var initial []byte
		if err == nil {
			initial, err = viewReadInitial(file, info.Size(), initialLines, viewScreenReadLimit)
		}
		if err != nil {
			file.Close()
			fmt.Fprintln(os.Stderr, T("view.failed", err))
			return 1
		}
		var raw []string
		raw, model.pending = viewSplitLines(nil, initial)
		model.ingest(raw, time.Now(), false)
		model.changed = info.ModTime()
		start = func(program *tea.Program) {
			go followViewFile(ctx, path, file, info.Size(), func(event viewFollowEvent) bool {
				if ctx.Err() != nil {
					return false
				}
				program.Send(viewDataMsg{event: event})
				return ctx.Err() == nil
			})
		}
	}
	program := tea.NewProgram(model, tea.WithOutput(os.Stdout))
	start(program)
	if _, err := program.Run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	return 0
}

