// viewParseAccess는 nginx와 Apache의 common, combined 형식이다.
// 203.0.113.9 - - [26/Oct/2026:10:00:00 +0900] "GET /api HTTP/1.1" 200 512 "-" "curl/8.0"
// 요청을 따옴표 없이 적고 user agent 뒤에 요청 본문과 처리 시간을 붙이는 nginx 변형도 읽는다. JSON-RPC 노드 앞의 nginx가 이렇게 적는다.
// 127.0.0.1 127.0.0.1  [28/Aug/2026:10:54:19 +0900] POST /api/v3 HTTP/1.1 400 106  "curl/7.81.0"  {"method":"icx_sendTransaction"} HTTP/1.1 0.005
func viewParseAccess(text string, line *viewLine) bool {
	client, rest, found := strings.Cut(text, " ")
	if !found || client == "" {
		return false
	}
	open := strings.IndexByte(rest, '[')
	if open < 0 {
		return false
	}
	closing := strings.IndexByte(rest[open:], ']')
	if closing < 0 {
		return false
	}
	timeText := rest[open+1 : open+closing]
	rest = strings.TrimLeft(rest[open+closing+1:], " ")
	var request string
	quotedRequest := strings.HasPrefix(rest, "\"")
	if quotedRequest {
		end := strings.IndexByte(rest[1:], '"')
		if end < 0 {
			return false
		}
		request = rest[1 : end+1]
		rest = strings.TrimLeft(rest[end+2:], " ")
	} else if request, rest = viewBareRequest(rest); request == "" {
		return false
	}
	statusText, rest, _ := strings.Cut(rest, " ")

			line.fields = append(line.fields, viewField{"rpc method", line.rpc})
		}
		rest = rest[strings.LastIndexByte(rest, '}')+1:]
	} else if len(quoted) > 0 {
		rest = rest[strings.LastIndexByte(rest, '"')+1:]
	}
	// 줄 끝의 소수는 nginx의 $request_time이다.
	if tokens := strings.Fields(rest); len(tokens) > 0 {
		if last := tokens[len(tokens)-1]; strings.ContainsRune(last, '.') && viewDigits(strings.ReplaceAll(last, ".", "")) {
			line.fields = append(line.fields, viewField{"request time", last})
		}
	}
	return true
}

// viewBareRequest는 따옴표 없는 "POST /api/v3 HTTP/1.1"이다. method는 대문자 낱말이고 세 번째 token은 HTTP/로 시작해야 한다.
// 요청과 그 뒤를 돌려주고, 아니면 빈 요청이다.
func viewBareRequest(rest string) (string, string) {
	method, after, ok := strings.Cut(rest, " ")
	if !ok || method == "" || method != strings.ToUpper(method) || !viewLettersOnly(method) {
		return "", rest
	}
	target, after, ok := strings.Cut(after, " ")
	if !ok || target == "" {
		return "", rest
	}
	protocol, after, _ := strings.Cut(after, " ")
	if !strings.HasPrefix(protocol, "HTTP/") {
		return "", rest
	}
	return method + " " + target + " " + protocol, strings.TrimLeft(after, " ")
}

var (
	viewJSONTimeKeys    = []string{"time", "ts", "timestamp", "@timestamp", "date", "t"}
	viewJSONLevelKeys   = []string{"level", "lvl", "severity", "log.level", "loglevel", "levelname"}
	viewJSONMessageKeys = []string{"msg", "message", "event", "text"}
	viewJSONStatusKeys  = []string{"status", "status_code", "statusCode", "http.status_code"}
)

// viewFollowEvent는 따라가는 동안 생긴 일이다. data는 새로 쓰인 바이트이고, reset은 파일이 바뀐 까닭이다.
type viewFollowEvent struct {
	data  []byte
	reset string
	err   error
}

// viewReadTail은 offset 앞의 마지막 viewTailCheck 바이트다. 따라가기를 시작할 때 한 번 읽는다.
func viewReadTail(file io.ReaderAt, offset int64) []byte {
	if offset <= 0 {
		return nil
	}
	start := offset - viewTailCheck
	if start < 0 {
		start = 0
	}
	tail := make([]byte, offset-start)
	count, err := file.ReadAt(tail, start)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil
	}
	return tail[:count]
}

// viewSplitLines는 따라가며 받은 바이트를 줄로 나눈다. 줄바꿈으로 끝나지 않은 나머지는 pending으로 돌려주어 다음 바이트와 잇는다.
func viewSplitLines(pending, data []byte) ([]string, []byte) {
	data = append(pending, data...)
	var lines []string
	for {
		index := bytes.IndexByte(data, '\n')
		if index < 0 {
			break
		}
		lines = append(lines, string(bytes.TrimSuffix(data[:index], []byte("\r"))))
		data = data[index+1:]
	}
	return lines, bytes.Clone(data)
}

// viewReadInitial은 화면을 열 때 보여 줄 마지막 lines줄이다. 파일 끝의 limit바이트 안에서만 찾고, 그 창이 줄 중간에서
// 시작하면 잘린 첫 조각을 버린다.
func viewReadInitial(file io.ReaderAt, size int64, lines int, limit int64) ([]byte, error) {
	if lines <= 0 || size == 0 {
		return nil, nil
	}
	base := size - limit
	if base < 0 {
		base = 0
	}
	offset, err := viewTailOffset(io.NewSectionReader(file, base, size-base), size-base, lines)
	// 크기를 잰 뒤 파일이 잘렸다. 빈 화면에서 시작하면 따라가면서 truncate를 알아채고 처음부터 읽는다.
	if errors.Is(err, io.EOF) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	data := make([]byte, size-base-offset)
	count, err := file.ReadAt(data, base+offset)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, err
	}
	data = data[:count]
	if base > 0 && offset == 0 && !viewLineStartsAt(file, base) {
		if newline := bytes.IndexByte(data, '\n'); newline >= 0 && newline < len(data)-1 {
			data = data[newline+1:]
		}
	}
	return data, nil
}

func viewLineStartsAt(file io.ReaderAt, offset int64) bool {
	previous := make([]byte, 1)
	_, err := file.ReadAt(previous, offset-1)
	return err == nil && previous[0] == '\n'
}

// viewReadGzipTail은 .gz를 처음부터 풀어 마지막 lines줄을 돌려준다. 남기지 않을 줄은 파싱하지 않으므로 시간 대부분이
// 압축 해제에 든다. 끝까지 읽지 못하면(잘린 .gz 등) 그때까지의 마지막 줄과 함께 오류를 돌려준다.
func viewReadGzipTail(reader *fastgzip.Reader, lines int) ([]string, error) {
	tail, _, err := viewTailReader(reader, lines)
	raw := make([]string, 0, len(tail))
	for _, line := range tail {
		raw = append(raw, string(bytes.TrimSuffix(bytes.TrimSuffix(line, []byte("\n")), []byte("\r"))))
	}
	return raw, err
}

func (stats *viewStats) remove(line viewLine) {
	if line.marker || line.cont {
		return
	}
	stats.apply(line, -1)
	// 오래된 줄부터 빠지므로, 가장 최근 오류가 빠졌다면 남은 오류가 없다.
	if stats.failures == 0 {
		stats.lastError = viewLine{}
	}
}

func readViewFixture(t *testing.T, name string) []string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", "view", name))
	if err != nil {
		t.Fatal(err)
	}
	return strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
}

// 줄바꿈이 없는 큰 파일을 열어도 limit보다 많이 읽지 않는다. 창이 줄 중간에서 시작하면 그 조각은 버린다.
func TestViewReadInitialStaysWithinLimit(t *testing.T) {
	content := strings.Repeat("z", 5000) + "\nlast\n"
	reader := strings.NewReader(content)
	data, err := viewReadInitial(reader, int64(len(content)), viewKeepLines, 1024)
	if err != nil {
		t.Fatal(err)
	}
	if string(data) != "last\n" {
		t.Fatalf("read %d bytes: %q", len(data), data[:min(len(data), 40)])
	}
	data, err = viewReadInitial(reader, int64(len(content)), 0, 1024)
	if err != nil || len(data) != 0 {
		t.Fatalf("-n 0 reads nothing: %q %v", data, err)
	}
	noNewline := strings.Repeat("q", 5000)
	data, _ = viewReadInitial(strings.NewReader(noNewline), int64(len(noNewline)), viewKeepLines, 1024)
	if len(data) > 1024 {
		t.Fatalf("a file without newlines read %d bytes", len(data))
	}
}

func (file *viewShrinkingFile) ReadAt(buffer []byte, offset int64) (int, error) {
	file.reads++
	content := file.after
	if file.reads == 1 {
		content = file.before
	}
	return strings.NewReader(content).ReadAt(buffer, offset)
}

func TestViewReadInitialUsesOnlyBytesRead(t *testing.T) {
	file := &viewShrinkingFile{before: "aaaa\nbbbb\n", after: "aaaa\n"}
	data, err := viewReadInitial(file, int64(len(file.before)), viewKeepLines, viewScreenReadLimit)
	if err != nil || string(data) != "aaaa\n" {
		t.Fatalf("read %q %v", data, err)
	}
	// 크기를 잰 뒤 비어 버린 파일은 오류가 아니라 빈 화면이다. 따라가면서 truncate로 알아챈다.
	data, err = viewReadInitial(&viewShrinkingFile{after: ""}, 10, viewKeepLines, viewScreenReadLimit)
	if err != nil || len(data) != 0 {
		t.Fatalf("emptied file: %q %v", data, err)
	}
}

func runWatch(args []string) int {
	if len(args) == 0 {
		choice, ok := promptMissingSubcommand("watch")
		if !ok {
			printCommandHelp(os.Stderr, "watch")
			return 2
		}
		args = []string{choice}
	}
	if helpRequested(args) {
		if args[0] == "http" || args[0] == "fs" {
			printWatchSubcommandHelp(os.Stdout, args[0])
		} else {
			printCommandHelp(os.Stdout, "watch")
		}
		return 0
	}
	switch args[0] {
	case "fs":
		return runFSWatch(args[1:])
	case "http":
		return runHTTPWatch(args[1:])
	default:
		return runHTTPWatch(args)
	}
}

func runHTTPWatch(args []string) int {
	options := configuredCommon(15 * time.Second)
	set := newFlagSet("watch http")
	set.SetOutput(os.Stderr)
	bindCommon(set, &options)
	intervalText := "1"
	set.StringVar(&intervalText, "i", intervalText, T("command.watch.option.interval"))
	set.StringVar(&intervalText, "interval", intervalText, T("command.watch.option.interval"))
	duration := set.Duration("duration", 0, T("command.watch.option.duration"))
	expectStatus := set.Int("expect-status", configuredInt(activeConfig.Defaults.HTTP.ExpectStatus, 0), T("command.http.option.expect_status"))
	if err := set.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}
	if set.NArg() != 1 {
		fmt.Fprintln(os.Stderr, T("cli.usage", "edc watch http [-i seconds] [--duration 1m] [options] <host|URL>"))
		return 2
	}
	interval, err := parseObserveInterval(intervalText)
	if err != nil || *duration < 0 || (*expectStatus != 0 && (*expectStatus < 100 || *expectStatus > 599)) {
		if err == nil {
			err = fmt.Errorf("%s", T("observe.watch.options_invalid"))
		}
		fmt.Fprintln(os.Stderr, err)
		return 2
	}
	_, _, rawURL, err := normalizeTarget(set.Arg(0))
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 2

	}
	writer, closeOutput, err := openObserveStream(options.jsonPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 2
	}
	defer closeOutput()
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	if *duration > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, *duration)
		defer cancel()
	}
	return streamWatch(ctx, writer, interval, options.timeout, options.jsonPath != "", options.redact, func(ctx context.Context) Result {
		return probeHTTPWithOptions(ctx, rawURL, httpCheckOptions{expectStatus: *expectStatus})
	})
}

