// 시끄러운 디렉터리를 알리는 기준이다. 처음 정한 값이고 실제 사용에서 조정한다.
const (
	// fsWatchNoisyWindow 동안 한 디렉터리에서 fsWatchNoisyEvents건 이상, 그리고 그 동안 전체의 fsWatchNoisyShare 이상이 나오면 알린다.
	fsWatchNoisyWindow = 10 * time.Second
	fsWatchNoisyEvents = 30
	fsWatchNoisyShare  = 0.5
	// fsWatchNoisyLimit은 한 번 실행에서 알리는 디렉터리의 수다. 같은 디렉터리는 한 번만 알린다.
	fsWatchNoisyLimit = 3
	// fsWatchNoisyQueueMax는 창 안에서 기억하는 이벤트의 수다. 초당 수만 건이 쏟아져도 메모리가 늘지 않게 오래된 것부터 버린다.
	// 이 수를 넘는 속도에서는 점유율이 10초가 아니라 가장 최근 이만큼의 이벤트 중 비율이 된다. 몰리는 곳을 찾는 데는 그 편이 맞다.
	fsWatchNoisyQueueMax = 100000
)

type fsWatchNoisyEvent struct {
	directory string
	at        time.Time
}

// fsWatchNoisy는 이벤트가 한 디렉터리에 몰리는지 본다. 몰리면 그 디렉터리를 --exclude로 빼는 방법을 알린다. 한 goroutine에서만 쓴다.
type fsWatchNoisy struct {
	queue  []fsWatchNoisyEvent
	counts map[string]int
	hinted map[string]bool
}

// fsWatchNoisyHint는 알릴 디렉터리와 그것을 빼는 --exclude 패턴이다.
type fsWatchNoisyHint struct {
	Directory string
	Events    int
	Pattern   string
}

// add는 감시 루트 기준 경로의 이벤트 하나를 센다. 알릴 때가 되면 그 내용을, 아니면 nil을 돌려준다.
func (noisy *fsWatchNoisy) add(eventPath string, now time.Time) *fsWatchNoisyHint {
	directory := path.Dir(filepath.ToSlash(eventPath))
	noisy.queue = append(noisy.queue, fsWatchNoisyEvent{directory: directory, at: now})
	noisy.counts[directory]++
	for len(noisy.queue) > 0 && (len(noisy.queue) > fsWatchNoisyQueueMax || now.Sub(noisy.queue[0].at) >= fsWatchNoisyWindow) {
		oldest := noisy.queue[0]
		noisy.queue = noisy.queue[1:]
		if noisy.counts[oldest.directory]--; noisy.counts[oldest.directory] <= 0 {
			delete(noisy.counts, oldest.directory)
		}
	}
	count := noisy.counts[directory]
	if count < fsWatchNoisyEvents || float64(count) < fsWatchNoisyShare*float64(len(noisy.queue)) {
		return nil
	}
	if noisy.hinted[directory] || len(noisy.hinted) >= fsWatchNoisyLimit || !fsWatchNoisyExcludable(directory) {
		return nil
	}
	noisy.hinted[directory] = true
	return &fsWatchNoisyHint{Directory: directory, Events: count, Pattern: directory + "/**"}
}

// fsWatchShellQuote는 셸에 그대로 붙여 넣을 수 있게 작은따옴표로 감싼다.
func fsWatchShellQuote(text string) string {
	return "'" + strings.ReplaceAll(text, "'", `'\''`) + "'"
}

// feed는 한 디렉터리에 같은 시각으로 count건을 넣고 처음 나온 알림을 돌려준다.
func feedNoisy(noisy *fsWatchNoisy, directory string, count int, at time.Time) *fsWatchNoisyHint {
	var first *fsWatchNoisyHint
	for index := range count {
		if hint := noisy.add(fmt.Sprintf("%s/file%d", directory, index), at); hint != nil && first == nil {
			first = hint
		}
	}
	return first
}

func TestFSWatchNoisyHintsWhenOneDirectoryDominates(t *testing.T) {
	noisy := newFSWatchNoisy()
	start := time.Date(2026, 10, 22, 17, 27, 0, 0, time.UTC)
	if hint := feedNoisy(noisy, "root/.aic/log-checkpoints", fsWatchNoisyEvents-1, start); hint != nil {
		t.Fatalf("a hint came before the threshold: %+v", hint)
	}
	hint := noisy.add("root/.aic/log-checkpoints/last", start)
	if hint == nil || hint.Directory != "root/.aic/log-checkpoints" || hint.Events != fsWatchNoisyEvents || hint.Pattern != "root/.aic/log-checkpoints/**" {
		t.Fatalf("hint = %+v", hint)
	}
	// 같은 디렉터리는 한 번만 알린다.
	if again := feedNoisy(noisy, "root/.aic/log-checkpoints", 100, start.Add(time.Second)); again != nil {
		t.Fatalf("the same directory was hinted twice: %+v", again)
	}
	// 알린 패턴은 그 디렉터리의 이벤트를 실제로 뺀다.
	if !fsWatchExcluded([]string{hint.Pattern}, "root/.aic/log-checkpoints/file_syslog.checkpoint") {
		t.Errorf("the pattern %q does not exclude a file in the directory", hint.Pattern)
	}
	if fsWatchExcluded([]string{hint.Pattern}, "root/.aic/other/file") {
		t.Errorf("the pattern %q excludes a file in another directory", hint.Pattern)
	}
}

func TestFSWatchNoisyNeedsAShareOfTheEvents(t *testing.T) {
	noisy := newFSWatchNoisy()
	start := time.Date(2026, 10, 22, 17, 27, 0, 0, time.UTC)
	// 여러 디렉터리가 번갈아 고르게 시끄러우면 어느 하나를 빼라고 하지 않는다. 디렉터리마다 기준의 두 배를 넣는다.
	directories := []string{"a", "b", "c", "d"}
	for index := range fsWatchNoisyEvents * 2 * len(directories) {
		directory := directories[index%len(directories)]
		if hint := noisy.add(fmt.Sprintf("%s/file%d", directory, index), start); hint != nil {
			t.Fatalf("an even spread made a hint: %+v", hint)
		}
	}
	// 한 곳이 절반 이상을 차지하면 알린다.
	if hint := feedNoisy(noisy, "e", fsWatchNoisyEvents*8, start); hint == nil || hint.Directory != "e" {
		t.Fatalf("a dominant directory was not hinted: %+v", hint)
	}
}

