func loadFSWatchConfig(filename string) (fsWatchConfig, error) {
	var config fsWatchConfig
	file, err := os.Open(filename)
	if err != nil {
		return config, err
	}
	defer file.Close()
	if info, err := file.Stat(); err != nil {
		return config, err
	} else if info.Size() > 1<<20 {
		return config, errors.New(T("watchfs.single_document"))
	}
	decoder := yaml.NewDecoder(io.LimitReader(file, 1<<20))
	decoder.KnownFields(true)
	if err := decoder.Decode(&config); err != nil {
		return config, err
	}
	var extra interface{}
	if err := decoder.Decode(&extra); err != io.EOF {
		return config, errors.New(T("watchfs.single_document"))
	}
	if len(config.Rules) == 0 {
		return config, errors.New(T("watchfs.rules_required"))
	}
	return config, nil
}

func fsWatchEvents(value string) ([]string, error) {
	var events []string
	seen := map[string]bool{}
	for _, event := range strings.Split(value, ",") {
		event = strings.TrimSpace(event)
		switch event {
		case "create", "modify", "remove", "rename":
		default:
			return nil, errors.New(T("watchfs.invalid_event", event))
		}
		if !seen[event] {
			events = append(events, event)
			seen[event] = true
		}
	}
	return events, nil
}

func fsWatchPathsEqual(first, second string) bool {
	if first == "" || second == "" || second == "-" {
		return false
	}
	firstAbs, firstErr := filepath.Abs(first)
	secondAbs, secondErr := filepath.Abs(second)
	if firstErr == nil && secondErr == nil && firstAbs == secondAbs {
		return true
	}
	firstInfo, firstErr := os.Stat(first)
	secondInfo, secondErr := os.Stat(second)
	return firstErr == nil && secondErr == nil && os.SameFile(firstInfo, secondInfo)
}

// fsWatchBuffered는 source의 이벤트를 limit까지 메모리에 모아 두는 source를 돌려준다. 감시 루프가 출력에 막혀 있는 동안에도
// 드라이버에서 계속 받아 커널 큐가 넘치지 않게 한다. 다 차면 새 이벤트를 버리고, 처음 버릴 때와 resume까지 빠져 다시 받기
// 시작할 때 각각 한 번 알리고, 버린 수를 loss에 더한다. 오류 채널과 driver는 그대로 넘긴다.
func fsWatchBuffered(source fsWatchSource, limit, resume int, loss *fsWatchLoss) fsWatchSource {
	out := make(chan fsWatchEvent, fsWatchQueueHandoff)
	done, finished := make(chan struct{}), make(chan struct{})
	go func() {
		defer close(finished)
		defer close(out)
		var queue []fsWatchEvent
		dropped, dropping := 0, false
		// 버리는 중에 감시가 끝나도 버린 수는 알린다.
		defer func() {
			if dropped > 0 {
				fmt.Fprintln(fsWatchNotice, T("watchfs.queue_dropped", dropped))
				loss.drop(dropped)
			}
		}()
		pop := func() {
			// 버린 뒤 이어서 잡은 메모리를 놓게 비운 칸은 지우고, 다 비면 배열도 놓는다.
			queue[0] = fsWatchEvent{}
			queue = queue[1:]
			if len(queue) == 0 {
				queue = nil
			}
			if dropping && len(queue) <= resume {
				dropping = false
				fmt.Fprintln(fsWatchNotice, T("watchfs.queue_dropped", dropped))
				loss.drop(dropped)
				dropped = 0
			}
		}

in := source.events
for {
	// 감시 루프가 받을 수 있으면 먼저 넘긴다. 큐에는 감시 루프가 막혀 있는 동안의 이벤트만 남는다.
	for len(queue) > 0 {
		select {
		case out <- queue[0]:
			pop()
			continue
		default:
		}
		break
	}
	// 소스가 끝나고 큐도 비었으면 끝낸다. 여기서 확인하지 않으면 아래 select에서 close만 기다린다.
	if in == nil && len(queue) == 0 {
		break
	}
	var send chan<- fsWatchEvent
	var first fsWatchEvent
	if len(queue) > 0 {
		send, first = out, queue[0]
	}
	select {
	case <-done:
		return
	case event, ok := <-in:
		if !ok {
			in = nil
			continue
		}
		if dropping || len(queue) >= limit {
			if !dropping {
				dropping = true

						fmt.Fprintln(fsWatchNotice, T("watchfs.queue_full", limit))
					}
					dropped++
					continue
				}
				queue = append(queue, event)
			case send <- first:
				pop()
			}
		}
	}()
	var once sync.Once
	return fsWatchSource{events: out, errors: source.errors, driver: source.driver, driverReason: source.driverReason, close: func() {
		once.Do(func() {
			source.close()
			close(done)
			<-finished
		})
	}}
}

func (notice *fsWatchTestNotice) Write(data []byte) (int, error) {
	notice.mutex.Lock()
	defer notice.mutex.Unlock()
	return notice.buffer.Write(data)
}

func fsWatchTestReceive(t *testing.T, events <-chan fsWatchEvent) (fsWatchEvent, bool) {
	t.Helper()
	select {
	case event, ok := <-events:
		return event, ok
	case <-time.After(2 * time.Second):
		t.Fatal("no event within 2s")
	}
	return fsWatchEvent{}, false
}

func TestFSWatchBufferedQueueDropsWhenFullAndResumesAfterDraining(t *testing.T) {
	var notice fsWatchTestNotice
	previous := fsWatchNotice.swap(&notice)
	defer fsWatchNotice.swap(previous)
	in := make(chan fsWatchEvent)
	var closeOnce sync.Once
	failures := make(chan error, 1)
	inner := fsWatchSource{events: in, errors: failures, driver: "test", driverReason: "reason", close: func() { closeOnce.Do(func() { close(in) }) }}
	var loss fsWatchLoss
	source := fsWatchBuffered(inner, 4, 2, &loss)
	defer source.close()
	if source.driver != "test" || source.driverReason != "reason" || source.errors != failures {
		t.Fatalf("source = %+v", source)
	}
	// 넘기는 채널이 차고 큐도 찬 뒤의 이벤트는 버린다. 버리기 시작할 때 한 번 알린다.
	kept := fsWatchQueueHandoff + 4
	for index := 0; index < kept+3; index++ {
		in <- fsWatchEvent{Event: "modify", Path: fmt.Sprint(index)}
	}
	notice.wait(t, T("watchfs.queue_full", 4))
	if strings.Count(notice.String(), T("watchfs.queue_full", 4)) != 1 {
		t.Fatalf("queue_full notice repeated: %q", notice.String())
	}
	// 둔 이벤트는 순서대로 나오고, 큐가 절반까지 빠지면 버린 수를 알린다.
	for index := 0; index < kept; index++ {
		event, ok := fsWatchTestReceive(t, source.events)
		if !ok || event.Path != fmt.Sprint(index) {
			t.Fatalf("event %d = %+v %v", index, event, ok)
		}
	}
	notice.wait(t, T("watchfs.queue_dropped", 3))
	if _, dropped, _ := loss.counts(); dropped != 3 {

		t.Fatalf("dropped = %d, want 3", dropped)
	}
	// 다시 받기 시작한 뒤의 이벤트는 그대로 지나간다.
	in <- fsWatchEvent{Event: "create", Path: "after"}
	if event, ok := fsWatchTestReceive(t, source.events); !ok || event.Path != "after" {
		t.Fatalf("event after resume = %+v %v", event, ok)
	}
	if strings.Count(notice.String(), T("watchfs.queue_full", 4)) != 1 {
		t.Fatalf("unexpected notice after resume: %q", notice.String())
	}
	// 닫으면 안쪽 source를 닫고 넘기는 채널도 닫힌다.
	source.close()
	if _, ok := fsWatchTestReceive(t, source.events); ok {
		t.Fatal("events still open after close")
	}
}

func TestFSWatchBufferedQueueReportsTheDropCountWhenClosedWhileDropping(t *testing.T) {
	var notice fsWatchTestNotice
	previous := fsWatchNotice.swap(&notice)
	defer fsWatchNotice.swap(previous)
	in := make(chan fsWatchEvent)
	inner := fsWatchSource{events: in, errors: make(chan error, 1), close: func() {}}
	var loss fsWatchLoss
	source := fsWatchBuffered(inner, 2, 1, &loss)
	for index := 0; index < fsWatchQueueHandoff+2+5; index++ {
		in <- fsWatchEvent{Event: "modify", Path: fmt.Sprint(index)}
	}
	notice.wait(t, T("watchfs.queue_full", 2))
	// 버리는 중에 닫혀도 버린 수를 알리고 loss에 더한다. close는 goroutine이 끝난 뒤 돌아오므로 바로 셀 수 있다.
	source.close()
	notice.wait(t, T("watchfs.queue_dropped", 5))
	if _, dropped, _ := loss.counts(); dropped != 5 {
		t.Fatalf("dropped = %d, want 5", dropped)
	}
}

func TestFSWatchBufferedQueueDrainsWhenTheSourceCloses(t *testing.T) {
	var notice fsWatchTestNotice
	previous := fsWatchNotice.swap(&notice)
	defer fsWatchNotice.swap(previous)
	in := make(chan fsWatchEvent)
	inner := fsWatchSource{events: in, errors: make(chan error, 1), close: func() {}}
	source := fsWatchBuffered(inner, 2, 1, nil)
	defer source.close()
	for index := 0; index < fsWatchQueueHandoff+2; index++ {
		in <- fsWatchEvent{Event: "modify", Path: fmt.Sprint(index)}
	}
	// 소스가 끝나도 둔 이벤트를 모두 넘긴 뒤에 채널을 닫는다.
	close(in)
	for index := 0; index < fsWatchQueueHandoff+2; index++ {
		if event, ok := fsWatchTestReceive(t, source.events); !ok || event.Path != fmt.Sprint(index) {
			t.Fatalf("event %d = %+v %v", index, event, ok)
		}
	}
	if _, ok := fsWatchTestReceive(t, source.events); ok {
		t.Fatal("events still open after the source closed")
	}
	if notice.String() != "" {
		t.Fatalf("unexpected notice %q", notice.String())
	}
}

func fsWatchRepeatSignature(record fsWatchRecord) string {
	return record.Event + "\x00" + record.Path + "\x00" + record.Origin + "\x00" + record.Process + "\x00" + strconv.FormatBool(record.IsDir)
}

// rowsOf는 기록 한 줄이 터미널에서 차지하는 줄 수다. 긴 경로는 줄이 넘어가므로 폭으로 나눈다. 폭을 모르면 0이다.
func (repeater *fsWatchRepeater) rowsOf(record fsWatchRecord) int {
	columns := repeater.width()
	if columns <= 0 {
		return 0
	}
	var line bytes.Buffer
	if err := writeFSWatchRecord(&line, record, false, repeater.style); err != nil {
		return 0
	}
	width := ansi.StringWidth(strings.TrimSuffix(line.String(), "\n"))
	return max(1, (width+columns-1)/columns)
}

func repeatRecord(kind, path, origin string, at time.Time, count int) fsWatchRecord {
	return fsWatchRecord{Type: "event", Time: at, Event: kind, Path: path, Origin: origin, Count: count}
}

func TestFSWatchRepeaterCountsTheRowsOfALongLine(t *testing.T) {
	start := time.Date(2026, 10, 22, 17, 27, 0, 0, time.UTC)
	long := "root/" + strings.Repeat("directory/", 12) + "file"
	repeater := newFSWatchRepeater(func() int { return 40 }, textStyle{})
	line := repeatRecord("create", long, "", start, 0)
	repeater.next(line)
	wantRows := repeater.rows
	if wantRows < 3 {
		t.Fatalf("a long line takes %d rows at width 40", wantRows)
	}
	// 고쳐 쓸 때는 화면에 있는 줄의 줄 수를 쓴다. ×N이 붙어 길어져도 이미 그려진 줄 수다.
	if _, rows := repeater.next(repeatRecord("create", long, "", start.Add(time.Second), 0)); rows != wantRows {
		t.Errorf("replace rows = %d, want %d", rows, wantRows)
	}
	// 폭을 모르면 고쳐 쓰지 않는다.
	unknown := newFSWatchRepeater(func() int { return 0 }, textStyle{})
	unknown.next(line)
	if _, rows := unknown.next(repeatRecord("create", long, "", start.Add(time.Second), 0)); rows != 0 {
		t.Error("folded without a terminal width")
	}
}

