// 터미널처럼 상태줄이 맨 아래에 있을 때 화면에 남는 줄을 본다. 같은 저장이 이어지면 한 줄이 ×N으로 바뀌고, 안내가 끼면 새 줄이 된다.
func TestFSWatchStreamFoldsRepeatsOnAScreenAndKeepsTheHint(t *testing.T) {
	previous := currentLanguage()
	defer setLanguage(previous)
	setLanguage("en")
	ctx, cancel := context.WithCancel(context.Background())
	events := make(chan fsWatchEvent, 256)
	out := &fsSmartSyncBuffer{}
	status := newFSWatchStatus(out, func() int { return 120 }, time.Now, []string{"modify"}, false)
	options := fsWatchOptions{root: ".", events: []string{"modify"}, match: "**", smart: true, status: status}
	options.notice = func(text string) { fmt.Fprintln(status.through(out), fsWatchHintLine(textStyle{}, text)) }
	done := make(chan int, 1)
	go func() {
		code, _ := streamFSWatch(ctx, out, fsWatchSource{events: events, errors: make(chan error)}, options, nil)
		done <- code
	}()
	burst := func(path string, count int) {
		for range count {
			events <- fsWatchEvent{Time: time.Now(), Event: "modify", Path: path}
		}
		time.Sleep(fsWatchSmartWindow + 120*time.Millisecond)
	}
	// 한 파일이 네 번 이어서 바뀐다. 줄 하나가 ×N으로 바뀐다.
	for range 4 {
		burst("quiet/a.txt", 1)
	}
	screen := fsRepeatScreen(out.String())
	var eventLines []string
	for _, line := range screen {
		if strings.Contains(line, "MODIFY") {
			eventLines = append(eventLines, line)
		}

	}
	if len(eventLines) != 1 || !strings.HasSuffix(eventLines[0], `MODIFY   "quiet/a.txt"  ×4`) {
		t.Fatalf("4 identical saves left %d lines: %q", len(eventLines), screen)
	}
	// 다른 파일이 끼면 새 줄이다.
	burst("quiet/b.txt", 1)
	burst("quiet/a.txt", 1)
	// 한 디렉터리에 이벤트가 몰려 안내가 나오면, 안내 줄이 지워지지 않고 그 뒤의 줄은 새로 시작한다.
	burst("noisy/app.log", 10)
	burst("noisy/app.log", 25)
	burst("noisy/app.log", 5)
	screen = fsRepeatScreen(out.String())
	cancel()
	select {
	case <-done:
	case <-time.After(3 * time.Second):
		t.Fatal("stop timed out")
	}
	var want []string
	for _, line := range screen {
		switch {
		case strings.Contains(line, "MODIFY"):
			want = append(want, line[strings.Index(line, "MODIFY"):])
		case strings.HasPrefix(line, "hint:"):
			want = append(want, "HINT")
		}
	}
	expected := []string{`MODIFY   "quiet/a.txt"  ×4`, `MODIFY   "quiet/b.txt"`, `MODIFY   "quiet/a.txt"`, `MODIFY   "noisy/app.log"  ×10`, "HINT", `MODIFY   "noisy/app.log"  ×30`}
	if strings.Join(want, "\n") != strings.Join(expected, "\n") {
		t.Fatalf("screen lines:\n%s\nwant:\n%s\nfull screen: %q", strings.Join(want, "\n"), strings.Join(expected, "\n"), screen)
	}
}

type fsWatchSmartEntry struct {
	kind   string
	path   string
	isDir  bool
	origin string
	count  int
	time   time.Time
	hidden bool
	// pid는 이름을 아는 마지막 이벤트를 일으킨 process의 번호이고, processes는 이 줄에 든 이벤트를 일으킨 서로 다른 process의 이름을
	// 처음 나온 순서로 모은 것이다. 이름을 모르는 이벤트는 아무것도 바꾸지 않는다.
	pid       int
	processes []string
	// known은 이름이 fsWatchSmartScanNames개를 넘은 뒤에만 쓰는 조회용 집합이다. 적을 때는 슬라이스를 훑는 쪽이 싸다.
	known map[string]struct{}
}

func (entry *fsWatchSmartEntry) setProcess(event fsWatchEvent) {
	if event.Process == "" {
		return
	}
	entry.pid = event.PID
	entry.addProcess(event.Process)
}

func (smart *fsWatchSmart) entry(event fsWatchEvent, kind string) *fsWatchSmartEntry {
	entry := &fsWatchSmartEntry{kind: kind, path: event.Path, isDir: event.IsDir, count: 1, time: event.Time}
	entry.setProcess(event)
	smart.entries = append(smart.entries, entry)
	smart.byPath[event.Path] = entry
	return entry
}

// add는 이벤트 하나를 모은다. now는 창을 여는 시각이다.
func (smart *fsWatchSmart) add(event fsWatchEvent, now time.Time) {
	if !smart.pending() {
		smart.opened = now
	}
	renamed := smart.renamed
	smart.renamed = nil
	entry := smart.byPath[event.Path]
	switch event.Event {
	case "create":
		// 바로 앞 rename의 도착점이면 그 이름을 출처로 적고, 옛 이름의 줄은 낸다고 하지 않는다.
		if renamed != nil && renamed.isDir == event.IsDir && renamed.path != event.Path {
			renamed.hidden = true
			delete(smart.byPath, renamed.path)
			created := smart.entry(event, "create")
			created.origin = renamed.path
			// 이름이 바뀐 줄은 옛 이름 줄의 동작이 이어진 것이므로, 거기에 든 process도 함께 보인다. 도착점 이벤트의 process가 뒤에 온다.
			inherited := created.processes
			created.processes, created.known = nil, nil
			for _, name := range renamed.processes {
				created.addProcess(name)
			}
			for _, name := range inherited {
				created.addProcess(name)
			}
			if created.pid == 0 {
				created.pid = renamed.pid
			}
			return
		}
		switch {
		case entry != nil && entry.kind == "remove":

			entry.setProcess(event)
			smart.renamed = entry
			return
		}
		smart.renamed = smart.entry(event, "rename")
	default:
		smart.entry(event, event.Event)
	}
}

// record는 줄 하나의 기록이다.
func (entry *fsWatchSmartEntry) record() fsWatchRecord {
	record := fsWatchRecord{Type: "event", Time: entry.time, Event: entry.kind, Path: entry.path, IsDir: entry.isDir, PID: entry.pid, Process: fsWatchProcessNames(entry.processes)}
	if entry.kind == "modify" && entry.count > 1 {
		record.Count = entry.count
	}
	if entry.origin != "" {
		record.Origin = fsWatchSmartOrigin(entry.origin, entry.path)
	}
	return record
}

// fsWatchSmartGroup은 한 디렉터리에서 같은 종류로 묶인 줄들이다. first는 묶음이 나갈 자리를 정하는 첫 줄이다.
type fsWatchSmartGroup struct {
	directory string
	kind      string
	first     *fsWatchSmartEntry
	count     int
	time      time.Time
	pid       int
	processes []string
	known     map[string]struct{}
}

// record는 묶음의 한 줄이다. 경로는 디렉터리 뒤에 ...을 붙이고, Count는 묶인 항목의 수다.
func (group *fsWatchSmartGroup) record() fsWatchRecord {
	return fsWatchRecord{Type: "event", Time: group.time, Event: group.kind, Path: fsWatchSmartGroupPath(group.directory), Count: group.count, PID: group.pid, Process: fsWatchProcessNames(group.processes)}
}

// add는 offsetMS가 지난 시각의 이벤트 하나를 넣는다.
func (clock *fsSmartClock) add(kind, path string, offsetMS int, dir ...bool) {
	at := clock.start.Add(time.Duration(offsetMS) * time.Millisecond)
	clock.smart.add(fsWatchEvent{Time: at, Event: kind, Path: path, IsDir: len(dir) > 0 && dir[0]}, at)
}

func smartLine(record fsWatchRecord) string {
	line := record.Event + " " + record.Path
	if record.Count > 0 {
		line += " x" + strconv.Itoa(record.Count)
	}
	if record.Origin != "" {
		line += " <- " + record.Origin
	}
	return line
}

func TestFSWatchSmartMergesAnAtomicSaveIntoTheFinalName(t *testing.T) {
	// 사용자가 붙여 넣은 실제 출력이다. 임시 파일에 쓰고 이름을 바꿔 교체한다.
	clock := newFSSmartClock()
	dir := "root/.aic/log-checkpoints/"
	clock.add("create", dir+"file_syslog.tmp", 683)
	clock.add("modify", dir+"file_syslog.tmp", 683)
	clock.add("rename", dir+"file_syslog.tmp", 688)
	clock.add("create", dir+"file_syslog.checkpoint", 688)
	records := clock.flush()
	if got := smartLines(records); !equalLines(got, "create "+dir+"file_syslog.checkpoint <- file_syslog.tmp") {
		t.Fatalf("lines = %v", got)
	}
	if !records[0].Time.Equal(clock.start.Add(688 * time.Millisecond)) {
		t.Errorf("time = %s, want the time of the last event", records[0].Time)
	}
}

func TestFSWatchSmartPairsARenameOnlyWithTheCreateRightAfterIt(t *testing.T) {
	for _, test := range []struct {
		name string
		feed func(*fsSmartClock)
		want []string
	}{
		{"same directory shows the name only", func(c *fsSmartClock) { c.add("rename", "docs/a.txt", 0); c.add("create", "docs/b.txt", 1) }, []string{"create docs/b.txt <- a.txt"}},
		{"another directory shows the path", func(c *fsSmartClock) { c.add("rename", "in/a.txt", 0); c.add("create", "out/a.txt", 1) }, []string{"create out/a.txt <- in/a.txt"}},
		{"an event between them breaks the pair", func(c *fsSmartClock) {
			c.add("rename", "a.txt", 0)
			c.add("modify", "x.txt", 1)
			c.add("create", "b.txt", 2)
		}, []string{"rename a.txt", "modify x.txt", "create b.txt"}},
		{"a file is not paired with a directory", func(c *fsSmartClock) { c.add("rename", "a.txt", 0); c.add("create", "dir", 1, true) }, []string{"rename a.txt", "create dir"}},
		{"a directory moves as a directory", func(c *fsSmartClock) { c.add("rename", "old", 0, true); c.add("create", "new", 1, true) }, []string{"create new <- old"}},
		{"only the first create is the destination", func(c *fsSmartClock) {
			c.add("rename", "a.txt", 0)
			c.add("create", "b.txt", 1)
			c.add("create", "c.txt", 2)
		}, []string{"create b.txt <- a.txt", "create c.txt"}},
	} {
		clock := newFSSmartClock()
		test.feed(clock)
		if got := smartLines(clock.flush()); !equalLines(got, test.want...) {
			t.Errorf("%s: lines = %v, want %v", test.name, got, test.want)
		}
	}
}

func TestFSWatchSmartEnabledFollowsTheOutputAndTheFlags(t *testing.T) {
	for _, test := range []struct {
