// reader는 적게 읽은 뒤 다음 read까지 기다린다. 그동안 생겼다 지워진 트리는 커널이 디렉터리 이벤트를 합쳐 보낸다.
func TestFSWatchFanotifyReportsATreeRemovedBeforeItWasRead(t *testing.T) {
	fsWatchSkipUnavailableDriver(t, fsWatchDriverFanotify)
