var once sync.Once
driver := "fsnotify"
if runtime.GOOS == "linux" {
	driver = fsWatchDriverInotify
}
return fsWatchSource{events: events, errors: failures, driver: driver, close: func() {
	once.Do(func() { close(done); watcher.Close(); <-finished })
}}, nil

func newFSWatchSource(options fsWatchOptions) (fsWatchSource, error) {
	if options.driver != "" && options.driver != fsWatchDriverAuto {
		return fsWatchSource{}, errors.New(T("watchfs.driver_unsupported", options.driver))
	}
	return newFSNotifyWatchSource(options)
}

func (notice *fsWatchNoticeWriter) Write(data []byte) (int, error) {
	notice.mutex.Lock()
	defer notice.mutex.Unlock()
	return notice.target.Write(data)
}

type fsWatchStatusWriter struct {
	status *fsWatchStatus
	target io.Writer
}

// replaceLast는 바로 앞에 쓴 기록 줄을 지우고 그 자리에 data를 쓴다. rows는 그 줄이 차지한 화면 줄 수다. 상태줄을 지운 뒤 커서를
// 그만큼 올려 지우고 쓰며, 쓴 뒤에 상태줄을 다시 그린다.
func (status *fsWatchStatus) replaceLast(rows int, data []byte) error {
	status.mutex.Lock()
	defer status.mutex.Unlock()
	status.clear()
	if _, err := fmt.Fprintf(status.out, "\x1b[%dA\r\x1b[J", rows); err != nil {
		return err
	}
	if _, err := status.out.Write(data); err != nil {
		return err
	}
	status.draw()
	return nil
}

func (status *fsWatchStatus) draw() {
	if status.closed {
		return
	}
	// 마지막 열에 쓰면 일부 터미널이 줄을 넘기므로 한 칸을 비운다.
	line := ansi.Truncate(status.line(max(1, status.width()-1)), max(1, status.width()-1), "…")
	if status.color {
		io.WriteString(status.out, richDim(line))
	} else {
		// NO_COLOR에서도 상태줄은 흐리게(SGR 2) 그려 기록 줄과 구분한다. 색이 아니라 글자 속성이다.
		io.WriteString(status.out, richSGR(line, "2"))
	}
	status.shown = true
}

