		t.Fatalf("timeout=%+v", record)
	}
	time.Sleep(250 * time.Millisecond)
	if _, err := os.Stat(filepath.Join(root, "leaked.txt")); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("timed-out descendant survived")
	}
}

