		t.Fatal("failure stopped watching")
	}
	sink.wait(t, "action_result")
	cancel()
	select {
	case code := <-done:
		if code != 1 {
			t.Fatalf("failure exit=%d", code)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("stop timed out")
	}
}

